window.MP_CATALOG = {"version":"1.53385169a7","site":"https://rainman016.github.io/motion-prompt-zh/","repo":"https://github.com/rainman016/motion-prompt-zh","count":144,"packs":[{"pack":"motion","order":1,"title":{"ja":"モーショングラフィックスの動き","en":"Motion graphics moves","zh-Hans":"动态图形基础"},"langs":["en","ja","zh-Hans"],"categories":[{"slug":"entrances-text","ja":"登場・文字の演出","en":"Entrances & text","zh-Hans":"入场与文字"},{"slug":"motion-polish","ja":"動きの味付け","en":"Motion polish","zh-Hans":"运动润饰"},{"slug":"transitions-highlights","ja":"切り替え・見せ場","en":"Transitions & highlights","zh-Hans":"转场与强调"}],"count":24,"first":"001","last":"024","width":539,"height":208,"cycle":4.7,"fonts":[],"scalable":false},{"pack":"camera","order":2,"title":{"ja":"カメラワークと切り替え","en":"Camera moves & transitions","zh-Hans":"镜头运动与剪辑"},"langs":["en","ja","zh-Hans"],"categories":[{"slug":"camera-movement","ja":"カメラの動き","en":"Camera Movement","zh-Hans":"镜头运动"},{"slug":"shooting-style-time","ja":"撮り方・時間の演出","en":"Shooting Style & Time","zh-Hans":"拍摄风格与时间"},{"slug":"transitions","ja":"切り替え（トランジション）","en":"Transitions","zh-Hans":"剪辑与转场"}],"count":24,"first":"025","last":"048","width":539,"height":208,"cycle":9.4,"fonts":[],"scalable":false},{"pack":"ui","order":3,"title":{"ja":"UIパーツの名前","en":"UI component names","zh-Hans":"UI 组件"},"langs":["en","ja","zh-Hans"],"categories":[{"slug":"open-overlay","ja":"開く・重なるパーツ","en":"Opening & overlays","zh-Hans":"弹出与覆盖"},{"slug":"select-switch","ja":"選ぶ・切り替えるパーツ","en":"Choosing & switching","zh-Hans":"选择与切换"},{"slug":"navigate-status","ja":"案内する・状態を伝えるパーツ","en":"Navigation & status","zh-Hans":"导航与状态"}],"count":24,"first":"049","last":"072","width":542,"height":191,"cycle":4.5,"fonts":[],"scalable":true},{"pack":"lp","order":4,"title":{"ja":"LP・Webサイトの演出","en":"Landing page & web effects","zh-Hans":"落地页与网页动效"},"langs":["en","ja","zh-Hans"],"categories":[{"slug":"scroll","ja":"スクロールで起きる演出","en":"Scroll effects","zh-Hans":"滚动效果"},{"slug":"hover-click","ja":"マウス・クリックへの反応","en":"Hover & click interactions","zh-Hans":"悬停与点击交互"},{"slug":"loading-loops","ja":"読み込み・移動・動き続ける演出","en":"Loading, navigation & ambient loops","zh-Hans":"加载、导航与循环动效"}],"count":24,"first":"073","last":"096","width":539,"height":208,"cycle":4.8,"fonts":[],"scalable":true},{"pack":"photo","order":5,"title":{"ja":"写真の表現・光と画風","en":"Photo looks, lighting & styles","zh-Hans":"摄影光线与风格"},"langs":["en","ja","zh-Hans"],"categories":[{"slug":"lighting","ja":"光の当て方・時間帯","en":"Lighting & time of day","zh-Hans":"布光与时段"},{"slug":"lens-camera","ja":"レンズ・カメラの効果","en":"Lens & camera effects","zh-Hans":"镜头与相机效果"},{"slug":"tone-finish","ja":"仕上げ・画風","en":"Tones & finishing looks","zh-Hans":"色调与后期风格"}],"count":24,"first":"097","last":"120","width":539,"height":208,"cycle":5,"fonts":[],"scalable":true},{"pack":"motion2","order":6,"title":{"ja":"モーショングラフィックスの演出 第2弾","en":"Motion graphics moves, part 2","zh-Hans":"动态图形进阶"},"langs":["en","ja","zh-Hans"],"categories":[{"slug":"techniques","ja":"動きのテクニック","en":"Motion techniques","zh-Hans":"运动技法"},{"slug":"text-shapes","ja":"文字・図形の演出","en":"Text & shapes","zh-Hans":"文字与图形"},{"slug":"transitions-highlights","ja":"切り替え・見せ場","en":"Transitions & highlights","zh-Hans":"转场与强调"}],"count":24,"first":"121","last":"144","width":539,"height":208,"cycle":4.7,"fonts":[],"scalable":false}],"elements":[{"id":"001","pack":"motion","no":"01","slug":"pop-in","category":"entrances-text","width":539,"height":208,"cycle":4.7,"name":{"ja":"ポップイン","en":"Pop-in","zh-Hans":"弹性弹入"},"meaning":{"ja":"ポンと弾んで現れる","en":"Pops into view with a small bounce","zh-Hans":"带轻微回弹地出现"},"ask":{"ja":"ロゴをポップインで出して。0.4秒で、行き過ぎは少しだけ。","en":"Bring the logo in with a pop-in, about 0.4 s, with a slight overshoot.","zh-Hans":"让标志以弹性弹入方式出现，约 0.4 秒，稍微超出目标尺寸再回落。"},"summary":{"ja":"アプリのアイコンがポンと弾んで現れ、通知バッジが遅れてポンと出る。","en":"An app icon pops in with a bounce, then a notification badge pops in a moment later.","zh-Hans":"应用图标弹跳入场，随后通知角标稍晚弹出。"},"spec":{"ja":["2.35秒で1回（1周期4.7秒に2回。1回目はコーラル地に星、2回目は青地にハート）","アイコン: 116pxの角丸四角（角丸30）。0.28秒から拡大率 0→1 をばねで出す: 1 − e^(−6.5t)·cos(15t)（最大およそ1.26まで行き過ぎる）","同時に傾き −0.35rad（約−20°）→ 0 をばね（1 − e^(−6t)·cos(11t)）で戻す","通知バッジ: 半径25の黄色い丸に「1」。アイコン右上（+52, −52）に 0.62秒から ばね 1 − e^(−7t)·cos(17t) で出す","退場: 1.86〜2.12秒。拡大率に (1 − backIn(s=2.2)) を掛ける（少しふくらんでから 0 へ縮む）","床の影: 横62×縦8の楕円をアイコンの拡大率（0〜1に制限）に合わせて伸縮"],"en":["One pop per 2.35 s (twice per 4.7 s cycle: a star on coral first, then a heart on blue).","Icon: 116 px rounded square (radius 30). From 0.28 s, scale 0→1 with a spring: 1 − e^(−6.5t)·cos(15t), peaking at about 1.26.","At the same time, rotation −0.35 rad (about −20°) → 0 with a spring: 1 − e^(−6t)·cos(11t).","Badge: yellow circle, radius 25, with \"1\", at the icon's top-right (+52, −52). Starts at 0.62 s with spring 1 − e^(−7t)·cos(17t).","Exit: 1.86–2.12 s. Scale is multiplied by (1 − backIn, s = 2.2), so it swells slightly and then shrinks to 0.","Floor shadow: 62 × 8 ellipse that scales with the icon (clamped to 0–1)."],"zh-Hans":["每 2.35 秒弹入一次；每个 4.7 秒周期两次，先是珊瑚色底的星形，再是蓝底的心形。","图标为 116 px 圆角方形，圆角半径 30。从 0.28 秒起按弹簧公式 1 − e^(−6.5t)·cos(15t) 将缩放从 0→1，峰值约 1.26。","同时按弹簧公式 1 − e^(−6t)·cos(11t)，将旋转角度从 −0.35 rad（约 −20°）恢复到 0。","角标为半径 25、写有“1”的黄色圆，位于图标右上方（+52, −52）；从 0.62 秒起按弹簧公式 1 − e^(−7t)·cos(17t) 出现。","退场为 1.86–2.12 秒；缩放乘以 (1 − backIn, s = 2.2)，先稍微膨胀，再缩至 0。","地面阴影为 62 × 8 的椭圆，随图标缩放，缩放值限制在 0–1。"]},"use":{"ja":"アイコン・ボタン・バッジなど、小さな要素を軽く目立たせて出したいとき。","en":"Use it to bring in a small element such as an icon, button or badge with a light accent.","zh-Hans":"适合图标、按钮、角标等小元素，以轻快的动效吸引注意。"},"tags":["pop","pop-in","spring","bounce","scale","icon","badge","entrance"],"aliases":{"zh-Hans":["弹入","弹出","弹性"]}},{"id":"002","pack":"motion","no":"02","slug":"stagger","category":"entrances-text","width":539,"height":208,"cycle":4.7,"name":{"ja":"スタガー","en":"Stagger","zh-Hans":"交错入场"},"meaning":{"ja":"少しずつ時間をずらして順に出す","en":"Items appear one after another, slightly offset in time","zh-Hans":"多个元素依次出现，时间略有错开"},"ask":{"ja":"5枚のカードをスタガーで出して。左から0.08秒ずつずらして。","en":"Bring in the five cards with a stagger, 0.08 s apart, left to right.","zh-Hans":"让五张卡片交错入场，从左到右每张间隔 0.08 秒。"},"summary":{"ja":"グラフの棒が、少しずつ時間をずらして左から順に立ち上がる。","en":"Chart bars rise one after another from the left, each slightly delayed.","zh-Hans":"图表的柱条从左到右依次升起，每根略有延迟。"},"spec":{"ja":["2.35秒で1回。棒7本（幅44・間隔20・高さ 52, 84, 68, 112, 92, 136, 158）。色は青・コーラル・黄・ミントの順で繰り返す","i本目（0始まり）は 0.15 + 0.12×i 秒に開始。0.5秒かけて高さ 0→100% を backOut（s=2.6）で伸ばす（底辺固定・行き過ぎてから戻る）","棒の上の白い点（半径6.5・棒の上端から16px上）: 棒の開始から 0.34秒遅れて ばね 1 − e^(−7t)·cos(16t) で出す","退場: 棒は 1.78 + 0.045×i 秒から0.26秒で easeIn（3乗）で縮む。点は 1.70 + 0.045×i 秒から0.2秒で先に消える"],"en":["One pass per 2.35 s. Seven bars (width 44, gap 20, heights 52, 84, 68, 112, 92, 136, 158), coloured blue, coral, yellow, mint in rotation.","Bar i (0-based) starts at 0.15 + 0.12·i s and grows from 0 to full height in 0.5 s with backOut (s = 2.6), anchored at the baseline, overshooting and settling.","White dot (radius 6.5, 16 px above the bar top): starts 0.34 s after its bar with spring 1 − e^(−7t)·cos(16t).","Exit: bars shrink with cubic ease-in over 0.26 s starting at 1.78 + 0.045·i s; dots vanish first, over 0.2 s from 1.70 + 0.045·i s."],"zh-Hans":["每 2.35 秒一轮。七根柱条，宽 44、间隔 20、高度为 52, 84, 68, 112, 92, 136, 158，依次循环使用蓝、珊瑚、黄、薄荷色。","柱条 i（从 0 计数）于 0.15 + 0.12·i 秒开始，使用 backOut（s = 2.6）在 0.5 秒内从 0 长到完整高度；底边固定，先超出再回落。","白点半径 6.5，位于柱顶上方 16 px；比对应柱条晚 0.34 秒，按弹簧公式 1 − e^(−7t)·cos(16t) 出现。","退场：柱条从 1.78 + 0.045·i 秒起，以三次缓入在 0.26 秒内缩回；白点先从 1.70 + 0.045·i 秒起，在 0.2 秒内消失。"]},"use":{"ja":"リスト・グラフ・カードなど、複数の要素を順番に出して視線を流したいとき。","en":"Use it to bring in several items (list rows, chart bars, cards) in sequence and lead the eye across them.","zh-Hans":"适合列表行、图表柱条、卡片等成组元素，按顺序引导视线。"},"tags":["stagger","sequence","delay","cascade","bar-chart","list","entrance"],"aliases":{"zh-Hans":["交错","错峰","依次入场"]}},{"id":"003","pack":"motion","no":"03","slug":"burst","category":"entrances-text","width":539,"height":208,"cycle":4.7,"name":{"ja":"バースト","en":"Burst","zh-Hans":"放射迸发"},"meaning":{"ja":"登場に合わせて線や粒が弾ける","en":"Lines and dots burst outward as something appears","zh-Hans":"元素出现时，线条和圆点向外迸发"},"ask":{"ja":"ハートが出る瞬間に、まわりへバーストを入れて。短い線を8本、0.3秒で消す。","en":"Add a burst around the heart the moment it appears: 8 short lines that fade in 0.3 s.","zh-Hans":"心形出现的瞬间加一圈放射迸发：八根短线，在 0.3 秒内淡出。"},"summary":{"ja":"「いいね」のハートが点くと同時に、まわりに輪・線・粒が弾ける。","en":"A like heart fills in, and a ring, lines and dots burst outward at the same moment.","zh-Hans":"点赞心形被填满的同时，圆环、线条和圆点向外迸发。"},"spec":{"ja":["2.35秒で1回。ハート（サイズ46・線幅7の輪郭）が中央にある","予備動作: 0.3〜0.5秒で拡大率 1→0.7（easeInOut 2乗）","0.5秒に発火: ハートをコーラルで塗り、拡大率 0.7→1 を ばね 1 − e^(−6.5t)·cos(16t) で戻す","輪: 黄色。半径 44→90、線幅 16→0 を0.6秒で easeOut（5乗）","放射の線10本（黄・ミント交互、線幅9）: 先端の半径 64→130（縦は0.82倍）。長さ36を発火後0.22〜0.7秒で0へ","粒10個（コーラル・青交互、半径 8→4.8）: 半径 58→150（横1.45倍・縦0.78倍の楕円状）。発火後0.3〜0.72秒でフェードアウト。塗りは 1.92〜2.2秒で消える"],"en":["One burst per 2.35 s. A heart (size 46, 7 px outline) sits in the centre.","Anticipation: 0.3–0.5 s, scale 1→0.7 (quadratic ease-in-out).","Trigger at 0.5 s: the heart fills with coral and scale returns 0.7→1 with spring 1 − e^(−6.5t)·cos(16t).","Ring: yellow, radius 44→90 while line width goes 16→0, over 0.6 s with quintic ease-out.","10 radial lines (yellow/mint alternating, width 9): outer end radius 64→130 (y scaled 0.82); length 36 shrinks to 0 between 0.22 and 0.7 s after the trigger.","10 dots (coral/blue alternating, radius 8→4.8): radius 58→150 on an ellipse (x ×1.45, y ×0.78), fading out 0.3–0.72 s after the trigger. The heart fill fades at 1.92–2.2 s."],"zh-Hans":["每 2.35 秒迸发一次。中心为尺寸 46、轮廓线宽 7 px 的心形。","预备动作：0.3–0.5 秒，缩放 1→0.7，采用二次缓入缓出。","0.5 秒触发：心形填充珊瑚色，按弹簧公式 1 − e^(−6.5t)·cos(16t) 将缩放从 0.7→1。","黄色圆环的半径从 44→90，线宽从 16→0，持续 0.6 秒，采用五次缓出。","10 根放射线，黄与薄荷色交替，线宽 9；外端半径 64→130，纵向乘以 0.82；长度 36 在触发后 0.22 至 0.7 秒间缩至 0。","10 个圆点，珊瑚与蓝色交替，半径 8→4.8；沿椭圆向外运动，半径 58→150，横向 ×1.45、纵向 ×0.78；触发后 0.3–0.72 秒淡出。心形填充于 1.92–2.2 秒淡出。"]},"use":{"ja":"いいね・達成・正解など、押した瞬間や決まった瞬間を強調したいとき。","en":"Use it to mark the instant something is triggered or achieved, such as a like, a success or a correct answer.","zh-Hans":"适合强调点赞、成功、答对等触发或达成的瞬间。"},"tags":["burst","explosion","radial","like","heart","celebrate","accent","sparkle"]},{"id":"004","pack":"motion","no":"04","slug":"line-draw","category":"entrances-text","width":539,"height":208,"cycle":4.7,"name":{"ja":"ラインドロー","en":"Line draw","zh-Hans":"路径描边"},"meaning":{"ja":"線が描かれるように伸びる","en":"A line extends as if it were being drawn","zh-Hans":"线条像被画出来一样逐渐延伸"},"ask":{"ja":"グラフの折れ線を、ラインドローで左から描いて。1.2秒かけて。","en":"Reveal the chart line with a line draw from the left, over 1.2 s.","zh-Hans":"让图表折线从左侧开始路径描边，用 1.2 秒画完。"},"summary":{"ja":"グラフの線が描かれるように伸び、消えるときは後ろから追いかけて消える。","en":"A chart line draws itself on, and is later erased from its starting end.","zh-Hans":"图表曲线逐渐被描绘出来，随后从起点一侧逐渐擦除。"},"spec":{"ja":["4.7秒で1回。線の見える範囲（始点側の割合〜終点側の割合）を動かして描く（トリムパス）","軸（L字・線幅6）: 0.08〜0.7秒で描く。折れ線（ミント・線幅11・7点を通るなめらかな曲線・端は丸）: 0.4〜1.95秒で描く。どちらも easeInOut（3乗）","描いている間、先端に黄色い丸（半径12、中心に白の半径5）を付ける","矢じり: 1.9〜2.2秒に backOut（s=2.5）で開く（羽の長さ26・開き20）","山の1点を囲む丸（コーラル・半径26・線幅7）: 2.2〜2.8秒に真上から時計回りに描く","消去: 丸 3.5〜4.0秒、折れ線 3.65〜4.45秒、軸 3.85〜4.55秒。いずれも始点側から縮めて消す。矢じりは 4.3〜4.45秒で消す"],"en":["One pass per 4.7 s. Drawn as a trim path: animate the visible range (start fraction to end fraction) of each stroke.","Axes (L shape, width 6) draw at 0.08–0.7 s; the line (mint, width 11, a smooth curve through 7 points, round caps) draws at 0.4–1.95 s. Both use cubic ease-in-out.","While drawing, a yellow dot (radius 12, white centre radius 5) rides the leading tip.","Arrowhead: opens at 1.9–2.2 s with backOut (s = 2.5); wings 26 long, 20 wide.","A coral circle (radius 26, width 7) is drawn around one peak at 2.2–2.8 s, clockwise from the top.","Erase: circle 3.5–4.0 s, line 3.65–4.45 s, axes 3.85–4.55 s, each shrinking from its starting end. The arrowhead fades at 4.3–4.45 s."],"zh-Hans":["每 4.7 秒一轮。采用修剪路径（Trim Path），对每条描边的可见范围起止比例做动画。","坐标轴为 L 形，线宽 6，于 0.08–0.7 秒绘制；曲线为薄荷色，线宽 11，经过 7 个点的平滑曲线，圆形端点，于 0.4–1.95 秒绘制；两者均采用三次缓入缓出。","绘制过程中，半径 12、白色内芯半径 5 的黄色圆点沿线头运动。","箭头于 1.9–2.2 秒以 backOut（s = 2.5）展开，箭翼长 26、宽 20。","珊瑚色圆圈半径 26、线宽 7，于 2.2–2.8 秒从顶部顺时针画出，圈住一个峰值点。","擦除：圆圈 3.5–4.0 秒、曲线 3.65–4.45 秒、坐标轴 3.85–4.55 秒，均从起点缩短直至消失；箭头于 4.3–4.45 秒淡出。"]},"use":{"ja":"グラフ・経路・下線・囲み線など、線そのものを見せ場にしたいとき。","en":"Use it when the stroke itself is the point: charts, routes, underlines, hand-drawn circles.","zh-Hans":"适合突出线条本身，如图表、路线、下划线和手绘圈线。"},"tags":["line-draw","trim-path","stroke","draw-on","chart","path","write-on"]},{"id":"005","pack":"motion","no":"05","slug":"mask-reveal","category":"entrances-text","width":539,"height":208,"cycle":4.7,"name":{"ja":"マスクリビール","en":"Mask reveal","zh-Hans":"遮罩揭示"},"meaning":{"ja":"見えない枠の中から文字がせり上がる","en":"Text rises into view from behind an invisible edge","zh-Hans":"文字从不可见的边缘后方升起"},"ask":{"ja":"タイトルをマスクリビールで下からせり上げて。0.6秒、行ごとに少しずらして。","en":"Bring the title in with a mask reveal from below, 0.6 s, each line slightly after the one before.","zh-Hans":"标题从下方以遮罩揭示方式升起，持续 0.6 秒，各行略微错开。"},"summary":{"ja":"1本の線を境に、見えない枠の向こうから見出しがせり上がる。","en":"Headline text slides out from behind an invisible edge marked by a single line.","zh-Hans":"标题从一条分隔线所标记的不可见边缘后方滑出。"},"spec":{"ja":["2.35秒で1回。境目の線（コーラル・380×6・y=124）: 0.1〜0.5秒で中央から左右へ伸ばす（easeInOut 3乗）。2.05〜2.3秒で縮めて消す","上の文字（太字98px・白）: 線より上だけ見える切り抜き（y=8〜119）の中で、120px下から定位置へ。0.35〜1.0秒・easeOut（5乗）","下の文字（32px・黄）: 線より下だけ見える切り抜き（y=129〜181）の中で、60px上から定位置へ。0.55〜1.15秒・easeOut（5乗）","退場: 上の文字は 1.7〜2.05秒に上へ150px（backIn s=1.2・いったん少し下がる）。下の文字は 1.75〜2.05秒に下へ70px（easeIn 3乗）","文字の透明度は変えない。切り抜きの外に出ると見えなくなるだけ"],"en":["One pass per 2.35 s. Divider line (coral, 380 × 6, y = 124): grows from the centre at 0.1–0.5 s (cubic ease-in-out), shrinks away at 2.05–2.3 s.","Top text (bold 98 px, white): clipped to the area above the line (y 8–119); moves up into place from 120 px below at 0.35–1.0 s, quintic ease-out.","Bottom text (32 px, yellow): clipped to the area below the line (y 129–181); moves down into place from 60 px above at 0.55–1.15 s, quintic ease-out.","Exit: top text moves 150 px up at 1.7–2.05 s (backIn, s = 1.2, dipping slightly first); bottom text moves 70 px down at 1.75–2.05 s (cubic ease-in).","Opacity never changes; the text is hidden only by leaving the clip area."],"zh-Hans":["每 2.35 秒一轮。珊瑚色分隔线为 380 × 6，y = 124；在 0.1–0.5 秒从中心向两侧伸长，采用三次缓入缓出，于 2.05–2.3 秒缩回消失。","上方文字为 98 px 白色粗体，裁剪到线条上方区域（y 8–119）；在 0.35–1.0 秒从下方 120 px 处上移到位，采用五次缓出。","下方文字为 32 px 黄色，裁剪到线条下方区域（y 129–181）；在 0.55–1.15 秒从上方 60 px 处下移到位，采用五次缓出。","退场：上方文字在 1.7–2.05 秒上移 150 px，采用 backIn（s = 1.2），先轻微下沉；下方文字在 1.75–2.05 秒下移 70 px，采用三次缓入。","不改变透明度；文字只在离开裁剪区域后被隐藏。"]},"use":{"ja":"タイトルや見出しを、落ち着いた印象で出したいとき。","en":"Use it for titles and headings that should appear in a clean, composed way.","zh-Hans":"适合简洁、沉稳的标题和大字入场。"},"tags":["mask","reveal","clip","wipe","title","text","slide-up","headline"],"aliases":{"zh-Hans":["遮罩","蒙版","文字揭示"]}},{"id":"006","pack":"motion","no":"06","slug":"typewriter","category":"entrances-text","width":539,"height":208,"cycle":4.7,"name":{"ja":"タイプライター","en":"Typewriter","zh-Hans":"打字机效果"},"meaning":{"ja":"1文字ずつ打たれるように出る","en":"Text appears one character at a time, as if typed","zh-Hans":"文字像键盘输入一样逐字出现"},"ask":{"ja":"この一文をタイプライターで出して。1文字0.05秒、末尾にカーソルを付けて。","en":"Show this sentence with a typewriter effect, 0.05 s per character, with a cursor at the end.","zh-Hans":"这句话用打字机效果呈现，每字 0.05 秒，末尾加光标。"},"summary":{"ja":"入力欄に1文字ずつ打たれ、打ち終わると送信ボタンが点いて押される。","en":"Text is typed into an input field one character at a time, then the send button lights up and is pressed.","zh-Hans":"输入框内逐字输入，完成后发送按钮亮起并被按下。"},"spec":{"ja":["4.7秒で1回。白い入力欄（471×92・角丸30）に9文字を、0.3秒から0.24秒おきに1文字ずつ出す（2.46秒で打ち終わり）","出た文字は拡大率 1.35→1 に落ち着く: 1 + 0.35·e^(−16t)","カーソル（コーラル・5×44）: 最後の文字の右。打っている間は点灯、それ以外は0.94秒周期（0.5秒点灯）で点滅","送信ボタン（半径30）: 灰色 → 2.58秒から青の丸を ばね 1 − e^(−6.5t)·cos(15t) で出す","押下: 2.96〜3.21秒にボタンを最大20%縮める（sin の山）。3.13〜3.41秒に文字が上へ70px動きながら消える","文字が半分消えた時点（約3.27秒）でカーソルは先頭に戻り、3.51〜3.81秒にボタンの青が消える"],"en":["One pass per 4.7 s. Nine characters appear in a white input field (471 × 92, radius 30), one every 0.24 s starting at 0.3 s (typing ends at 2.46 s).","Each new character settles from scale 1.35 to 1: 1 + 0.35·e^(−16t).","Cursor (coral, 5 × 44) sits after the last character: solid while typing, otherwise blinking with a 0.94 s period (on for 0.5 s).","Send button (radius 30): grey, then a blue disc appears from 2.58 s with spring 1 − e^(−6.5t)·cos(15t).","Press: the button shrinks by up to 20% at 2.96–3.21 s (half sine). At 3.13–3.41 s the text moves 70 px up while fading out.","The cursor returns to the start once the text is half faded (about 3.27 s); at 3.51–3.81 s the blue fades."],"zh-Hans":["每 4.7 秒一轮。在 471 × 92、圆角半径 30 的白色输入框内，从 0.3 秒开始每 0.24 秒出现一个字符，共九个字符，于 2.46 秒输入完成。","每个新字符从缩放 1.35 回落至 1，公式为 1 + 0.35·e^(−16t)。","光标为珊瑚色，5 × 44，位于最后一个字符之后；输入时常亮，其余时间以 0.94 秒为周期闪烁，每次亮 0.5 秒。","发送按钮半径 30，初始为灰色；从 2.58 秒起按弹簧公式 1 − e^(−6.5t)·cos(15t) 显现蓝色圆面。","按下：2.96–3.21 秒内，按钮按半个正弦波最多缩小 20%；3.13–3.41 秒文字上移 70 px 并淡出。","文字淡出一半时，约 3.27 秒，光标返回起点；3.51–3.81 秒按钮的蓝色淡出。"]},"use":{"ja":"プロンプト入力・検索・チャットなど、文字を打つ操作を見せたいとき。","en":"Use it to show someone typing: a prompt, a search query, a chat message.","zh-Hans":"适合表现提示词、搜索词、聊天消息等文字输入过程。"},"tags":["typewriter","typing","text","cursor","input","prompt","chat","type-on"]},{"id":"007","pack":"motion","no":"07","slug":"count-up","category":"entrances-text","width":539,"height":208,"cycle":4.7,"name":{"ja":"カウントアップ","en":"Count-up","zh-Hans":"数字递增"},"meaning":{"ja":"数字が勢いよく増えていく","en":"A number runs up quickly to its final value","zh-Hans":"数字快速增长，最终停在目标值"},"ask":{"ja":"数字を0から1,280までカウントアップさせて。1.5秒で、最後はゆっくり止めて。","en":"Count the figure up from 0 to 1,280 in 1.5 s, slowing down at the end.","zh-Hans":"数字从 0 递增到 1,280，用 1.5 秒完成，接近终点时减速。"},"summary":{"ja":"数字が勢いよく増えて、最後にピタッと決まる。","en":"A number races upward and locks onto its final value.","zh-Hans":"数字快速上升，最后准确停在目标值。"},"spec":{"ja":["4.7秒で1回。0.1〜0.4秒でフェードイン、4.0〜4.4秒でフェードアウト","数字（太字104px）: 0.45〜2.9秒で 0→2,480。値 = 目標 × (1 − (1 − p)^4) を四捨五入（最初は速く、最後はゆっくり）","桁区切りのカンマ付き。各桁は同じ幅で右そろえ（数字が変わっても横に揺れない）","2.9秒に確定: 色を白→黄に変え、拡大率を 1 + 0.07·e^(−7t)·cos(15t) で小さく弾ませる","左の上向き矢印（ミントの丸・半径34）: 0.35秒から ばね 1 − e^(−7t)·cos(14t)。数えている間は上下に 6px × (1 − p)^3 × sin(30u) で震える","下のバー（330×12・青→ミントのグラデーション）: 値 ÷ 目標 の割合で伸びる"],"en":["One pass per 4.7 s. Fades in at 0.1–0.4 s and out at 4.0–4.4 s.","Number (bold 104 px): 0→2,480 over 0.45–2.9 s. Value = round(target × (1 − (1 − p)^4)): fast at first, slow at the end.","Thousands separator included. Every digit has the same width and the number is right-aligned, so it does not jitter sideways.","Lands at 2.9 s: colour switches white→yellow and scale does a small bounce, 1 + 0.07·e^(−7t)·cos(15t).","Up-arrow chip on the left (mint circle, radius 34): appears from 0.35 s with spring 1 − e^(−7t)·cos(14t); while counting it shakes vertically by 6 px × (1 − p)^3 × sin(30u).","Bar below (330 × 12, blue→mint gradient): fills in proportion to value ÷ target."],"zh-Hans":["每 4.7 秒一轮，在 0.1–0.4 秒淡入，在 4.0–4.4 秒淡出。","数字为 104 px 粗体，在 0.45–2.9 秒从 0→2,480；值 = round(target × (1 − (1 − p)^4))，先快后慢。","使用千位分隔符；数字等宽并右对齐，避免数值变化时横向抖动。","2.9 秒到达目标：从白色切换为黄色，缩放按 1 + 0.07·e^(−7t)·cos(15t) 轻微回弹。","左侧向上箭头标记为半径 34 的薄荷色圆，从 0.35 秒起按弹簧公式 1 − e^(−7t)·cos(14t) 出现；计数时按 6 px × (1 − p)^3 × sin(30u) 上下抖动。","下方进度条为 330 × 12，蓝到薄荷色渐变，按当前值 ÷ 目标值的比例填充。"]},"use":{"ja":"売上・人数・達成率など、数字の大きさや伸びを印象づけたいとき。","en":"Use it to make a figure feel big or growing: revenue, user counts, completion rates.","zh-Hans":"适合强调收入、用户数、完成率等数据的规模和增长。"},"tags":["count-up","counter","number","odometer","stats","kpi","progress"]},{"id":"008","pack":"motion","no":"08","slug":"kinetic-typography","category":"entrances-text","width":539,"height":208,"cycle":4.7,"name":{"ja":"キネティックタイポグラフィ","en":"Kinetic typography","zh-Hans":"动态字体编排"},"meaning":{"ja":"言葉に合わせて文字が動き回る","en":"Words move, scale and turn in time with what is said","zh-Hans":"文字随语义和节奏移动、缩放、旋转"},"ask":{"ja":"このナレーションをキネティックタイポグラフィにして。強調する語は大きく、拍に合わせて出して。","en":"Turn this narration into kinetic typography: make the stressed words larger and land them on the beat.","zh-Hans":"把这段旁白做成动态字体编排，重读词放大，并在节拍上落定。"},"summary":{"ja":"言葉の意味に合わせて文字が動く（のびる／はねる／まわる／ドン！）。","en":"Words move the way they mean: one stretches, one bounces, one spins, one slams down.","zh-Hans":"词语按含义运动：拉伸、弹跳、旋转，最后猛然砸下。"},"spec":{"ja":["4語を1.175秒ずつ（太字88px）。各語は最後の0.2秒でフェードアウトしながら上へ46px（easeIn 3乗）","のびる（青）: 横の拡大率 0.3→1 を ばね 1 − e^(−4.2t)·cos(12t) で。縦は 1/√(横) で少し縮める","はねる（黄）: 1文字ずつ0.1秒ずらす。高さ 78px × |sin(πt/0.4)| × e^(−2.6t) で弾む。接地の瞬間は縦に最大16%つぶす","まわる（ミント）: 1文字ずつ0.12秒ずらす。0.62秒で −360°→0° を backOut（s=1.3）。拡大率 0→1 を0.25秒で easeOut（3乗）","ドン!（コーラル・100px・斜体風に傾ける）: 0.02〜0.2秒で拡大率 3.4→1（easeIn 3乗）で叩きつける","着地後: 横揺れ 10px × e^(−9t) × sin(38t)、縦つぶれ 20% × e^(−11t)、放射の線8本を0.4秒"],"en":["Four words, 1.175 s each (bold 88 px). Each exits in its last 0.2 s, fading out while moving 46 px up (cubic ease-in).","Stretch (blue): horizontal scale 0.3→1 with spring 1 − e^(−4.2t)·cos(12t); vertical scale is 1/√(horizontal).","Bounce (yellow): characters staggered by 0.1 s; height 78 px × |sin(πt/0.4)| × e^(−2.6t); squashed vertically by up to 16% at each contact.","Spin (mint): characters staggered by 0.12 s; rotation −360°→0° over 0.62 s with backOut (s = 1.3); scale 0→1 over 0.25 s, cubic ease-out.","Slam (coral, 100 px, slanted): scale 3.4→1 at 0.02–0.2 s with cubic ease-in.","After impact: horizontal shake 10 px × e^(−9t) × sin(38t), vertical squash 20% × e^(−11t), and 8 radial lines for 0.4 s."],"zh-Hans":["四个词各持续 1.175 秒，字体为 88 px 粗体；每个词在最后 0.2 秒内上移 46 px 并淡出，采用三次缓入。","Stretch（蓝色）：水平缩放 0.3→1，采用弹簧公式 1 − e^(−4.2t)·cos(12t)；纵向缩放为 1/√(水平缩放)。","Bounce（黄色）：字符交错 0.1 秒；弹跳高度为 78 px × |sin(πt/0.4)| × e^(−2.6t)；每次触地时纵向最多压扁 16%。","Spin（薄荷色）：字符交错 0.12 秒；用 backOut（s = 1.3）在 0.62 秒内从 −360° 转到 0°；缩放用三次缓出在 0.25 秒内从 0→1。","Slam（珊瑚色、100 px、倾斜）：在 0.02–0.2 秒以三次缓入从缩放 3.4→1。","撞击后水平抖动 10 px × e^(−9t) × sin(38t)，纵向压扁 20% × e^(−11t)，并显示8 根放射线，持续 0.4 秒。"]},"use":{"ja":"ナレーションや歌詞のキーワードを、意味ごと印象に残したいとき。","en":"Use it to make key words from narration or lyrics memorable through how they move.","zh-Hans":"适合用运动方式强化旁白或歌词中的关键词。"},"tags":["kinetic-typography","text","typography","lyric","word","bounce","spin","slam"]},{"id":"009","pack":"motion","no":"09","slug":"easing","category":"motion-polish","width":539,"height":208,"cycle":4.7,"name":{"ja":"イージング","en":"Easing","zh-Hans":"缓动"},"meaning":{"ja":"緩急をつけて気持ちよく動かす","en":"Motion speeds up and slows down instead of moving at one speed","zh-Hans":"运动有加速与减速，而非始终匀速"},"ask":{"ja":"この移動にイージングをかけて。イーズアウトで、止まり際をゆっくりに。","en":"Add easing to this move: ease-out, slowing down as it stops.","zh-Hans":"给这段运动加缓动，用 ease-out，在停止前逐渐减速。"},"summary":{"ja":"同じ距離を同じ時間で動く2つの四角。上は一定の速さ、下は緩急あり。","en":"Two squares cover the same distance in the same time: the top one at constant speed, the bottom one eased.","zh-Hans":"两个方块在相同时间内走过相同距离，上方匀速，下方采用缓动。"},"spec":{"ja":["4.7秒で1往復。62pxの四角（角丸16）2つが横に316px動く。行き 0.2〜1.75秒（1.55秒）、0.8秒止まり、戻り 2.55〜4.1秒","上（一定）: 直線的に動く（linear）。形も色も変えない","下（緩急）: cubic-bezier(.86, 0, .14, 1)。ゆっくり出て、中盤で一気に速くなり、ゆっくり止まる","下は速さに比例して横に最大1.5倍のび、縦は0.8倍まで縮む（速さを3.6で割り 0〜1 に制限した値を使う）","下の後ろに速度線3本（最長150px×0.8〜1.25倍）と、0.035秒ずつ遅れた残像4枚","レールには等しい時間間隔での位置を12個の点で表示（上は等間隔、下は両端に詰まる）"],"en":["One round trip per 4.7 s. Two 62 px squares (radius 16) travel 316 px horizontally: out at 0.2–1.75 s (1.55 s), hold 0.8 s, back at 2.55–4.1 s.","Top (constant): linear motion; shape and colour never change.","Bottom (eased): cubic-bezier(.86, 0, .14, 1). Slow start, very fast middle, slow stop.","The bottom square stretches horizontally up to 1.5× and flattens to 0.8× in proportion to speed (speed ÷ 3.6, clamped to 0–1).","Behind it: 3 speed lines (up to 150 px × 0.8–1.25) and 4 ghost copies lagging 0.035 s each.","Each rail shows 12 dots marking positions at equal time intervals (evenly spaced on top, bunched at both ends below)."],"zh-Hans":["每 4.7 秒往返一轮。两个边长 62 px、圆角半径 16 的方块水平移动 316 px；去程 0.2–1.75 秒，耗时 1.55 秒，停留 0.8 秒，回程 2.55–4.1 秒。","上方方块匀速运动，形状和颜色始终不变。","下方使用 cubic-bezier(.86, 0, .14, 1)，起步慢、中间很快、停止前减速。","下方方块随速度水平最多拉伸至 1.5×，纵向压至 0.8×；强度为速度 ÷ 3.6，并限制在 0–1。","其后有3 条速度线，长度最多 150 px × 0.8–1.25；另有4 个残影，每个延迟 0.035 秒。","每条轨道用12 个点标记等时间间隔的位置，上方均匀分布，下方集中在两端。"]},"use":{"ja":"移動・拡大・回転など、あらゆる動きに緩急を付けて機械的に見えないようにしたいとき。","en":"Use it on any move, scale or rotation so the motion accelerates and decelerates instead of looking mechanical.","zh-Hans":"适合位移、缩放和旋转，使运动有自然的加减速。"},"tags":["easing","ease-in-out","cubic-bezier","linear","timing","curve","acceleration"]},{"id":"010","pack":"motion","no":"10","slug":"overshoot","category":"motion-polish","width":539,"height":208,"cycle":4.7,"name":{"ja":"オーバーシュート","en":"Overshoot","zh-Hans":"过冲回弹"},"meaning":{"ja":"行き過ぎてから戻って止まる","en":"Goes a little past the target, then settles back","zh-Hans":"先超过目标位置，再回落稳定"},"ask":{"ja":"メーターの針をオーバーシュートさせて。目標を1割ほど越えてから戻して。","en":"Give the gauge needle an overshoot: about 10% past the target, then back.","zh-Hans":"仪表指针加过冲，超过目标约 10% 后再回落。"},"summary":{"ja":"メーターの針が、目標を行き過ぎてから戻って止まる。","en":"A gauge needle swings past its target, comes back and settles.","zh-Hans":"仪表指针越过目标，回摆后逐渐稳定。"},"spec":{"ja":["4.7秒で1回。半円のメーター（半径128・線幅26）。目標は全体の0.7（左端から126°）","0.25秒に開始: 値 = 0.7 × (1 − e^(−4.6t)·cos(10.5t))。約0.3秒後に目標を約25%行き過ぎ、揺れながら目標に落ち着く","行き過ぎた分（目標より先の弧）はコーラルで塗る。目標の位置に黄色の印","弧の塗りは青→ミントのグラデーション。針は白・線幅9","戻り: 3.7秒から 値 = 0.7 × e^(−7.5t)·cos(8.5t) で 0 へ（0 をわずかに下回ってから止まる）"],"en":["One pass per 4.7 s. Semicircular gauge (radius 128, stroke 26). Target is 0.7 of the sweep (126° from the left end).","Starts at 0.25 s: value = 0.7 × (1 − e^(−4.6t)·cos(10.5t)). About 0.3 s later it is roughly 25% past the target, then it oscillates and settles on the target.","The part beyond the target is drawn in coral. A yellow tick marks the target.","The filled arc is a blue→mint gradient; the needle is white, width 9.","Return: from 3.7 s, value = 0.7 × e^(−7.5t)·cos(8.5t) back to 0 (dipping slightly below 0 before it stops)."],"zh-Hans":["每 4.7 秒一轮。半圆仪表半径 128、描边 26；目标为总量程的 0.7，即从左端起 126°。","从 0.25 秒开始，值 = 0.7 × (1 − e^(−4.6t)·cos(10.5t))；约 0.3 秒后超过目标约 25%，随后振荡并稳定在目标值。","超过目标的弧段为珊瑚色，目标处有黄色刻度。","填充圆弧为蓝到薄荷色渐变；指针为白色，线宽 9。","复位：从 3.7 秒起，值 = 0.7 × e^(−7.5t)·cos(8.5t)，回到 0，停止前略低于 0。"]},"use":{"ja":"要素が到着する動きに勢いと弾力を出したいとき。","en":"Use it to give an arriving element energy and a springy feel.","zh-Hans":"适合为到位动作增加能量和弹性感。"},"tags":["overshoot","spring","bounce","settle","elastic","gauge","meter","needle"],"aliases":{"zh-Hans":["过冲","弹性"]}},{"id":"011","pack":"motion","no":"11","slug":"squash-and-stretch","category":"motion-polish","width":539,"height":208,"cycle":4.7,"name":{"ja":"スクワッシュ＆ストレッチ","en":"Squash & stretch","zh-Hans":"挤压与拉伸"},"meaning":{"ja":"つぶれて伸びて弾力を出す","en":"Squashes and stretches so that it feels elastic","zh-Hans":"通过压扁和拉长表现弹性"},"ask":{"ja":"ボールの着地にスクワッシュ＆ストレッチを入れて。つぶれは弱めに。","en":"Add squash and stretch when the ball lands; keep the squash subtle.","zh-Hans":"球落地时加挤压与拉伸，压扁幅度轻一些。"},"summary":{"ja":"弾むキャラクターが、着地でつぶれ、飛ぶときに伸びる。","en":"A bouncing character squashes on landing and stretches as it takes off.","zh-Hans":"弹跳角色落地时压扁，起跳时拉长。"},"spec":{"ja":["半径37の丸いキャラクター。1.175秒で1回弾み（4.7秒で4回）、高さ92pxの放物線。左右には ±150px をsin波で1周期かけて往復","接地中（各バウンドの最初と最後の10%）: 縦の拡大率 0.52（着地の瞬間）⇄ 1.28（離れる瞬間）を2乗カーブで","空中: 縦の拡大率 = 1 + 0.28 × s^3。s は頂点からの時間のずれ（頂点で0、離れる瞬間と着く瞬間で1）（速いところで伸びる）","横の拡大率は常に 1 ÷ 縦（体積を保つ）。変形の基準は足元","影は高さに応じて小さく・細く。着地のたびに左右へ黄色い短い線が飛ぶ（1バウンドの約18%の間）"],"en":["A round character, radius 37. One bounce per 1.175 s (four per 4.7 s), a 92 px parabola. It drifts ±150 px sideways on a sine wave over the cycle.","On the ground (first and last 10% of each bounce): vertical scale goes between 0.52 (moment of impact) and 1.28 (moment of leaving) on a quadratic curve.","In the air: vertical scale = 1 + 0.28 × s^3, where s is the time offset from the apex (0 at the apex, 1 at take-off and touchdown), so it is stretched where it moves fast.","Horizontal scale is always 1 ÷ vertical (volume is preserved). The transform is anchored at the feet.","The shadow gets smaller and thinner with height. Short yellow lines flick out left and right at each landing (for about 18% of a bounce)."],"zh-Hans":["圆形角色半径 37，每 1.175 秒弹跳一次，每个 4.7 秒周期四次，抛物线高度 92 px；整个周期内按正弦波横向漂移 ±150 px。","触地阶段为每次弹跳的前后各 10%；纵向缩放按二次曲线在 0.52（撞击时）到 1.28（离地时）之间变化。","空中纵向缩放 = 1 + 0.28 × s^3；s 是偏离顶点的时间比例，顶点为 0、起跳和落地为 1，因此速度快时更长。","水平缩放始终为 1 ÷ 纵向缩放，保持面积；变换锚点设在脚底。","阴影随高度增加变小变薄；每次落地时左右闪出黄色短线，约占单次弹跳时长的 18%。"]},"use":{"ja":"キャラクターやロゴの動きに、重さとやわらかさを出したいとき。","en":"Use it to give a character or logo weight and softness.","zh-Hans":"适合为角色或标志赋予重量感与柔软感。"},"tags":["squash","stretch","squash-and-stretch","bounce","character","ball","animation-principle"],"aliases":{"zh-Hans":["挤压拉伸","弹性"]}},{"id":"012","pack":"motion","no":"12","slug":"shape-morph","category":"motion-polish","width":539,"height":208,"cycle":4.7,"name":{"ja":"モーフィング","en":"Shape morph","zh-Hans":"形状变形"},"meaning":{"ja":"形が別の形に変わる","en":"One shape turns smoothly into another","zh-Hans":"一个形状平滑过渡为另一个形状"},"ask":{"ja":"丸を星にモーフィングさせて。0.8秒で、途中で色も青から黄へ。","en":"Morph the circle into a star in 0.8 s, changing the color from blue to yellow on the way.","zh-Hans":"用 0.8 秒把圆形变成星形，同时颜色从蓝色变成黄色。"},"summary":{"ja":"丸 → 四角 → 星 → ハートと、形と色がなめらかに変わる。","en":"A shape changes smoothly from circle to square to star to heart, with its colour.","zh-Hans":"形状连同颜色一起，从圆形变为方形、星形、心形，再回到圆形。"},"spec":{"ja":["4つの形を1.175秒ずつ（丸 → 角を丸く落とした四角 → 星 → ハート → 丸に戻る）。基準の半径64","各区間は前半で止まり、最後の0.62〜0.04秒前（0.58秒間）で次の形へ変形","形は輪郭上の240点で持ち、同じ番号の点どうしを直線補間する。進み具合は backOut（s=1.6）で少し行き過ぎる","色: 青 → コーラル → 黄 → ミント。easeInOut（2乗）で混ぜる","変形中は拡大率を 1 + 0.07 × sin(π × 進み具合) でふくらませる","下に4つの点。今の形の点が大きく色付きになる"],"en":["Four shapes, 1.175 s each: circle → square with rounded-off corners → star → heart → back to circle. Base radius 64.","Each segment holds first, then morphs to the next shape between 0.62 s and 0.04 s before its end (0.58 s).","Every outline is stored as 240 points; points with the same index are linearly interpolated. Progress uses backOut (s = 1.6), so it overshoots slightly.","Colour: blue → coral → yellow → mint, blended with quadratic ease-in-out.","During the morph the scale swells by 1 + 0.07 × sin(π × progress).","Four dots below; the dot for the current shape is larger and coloured."],"zh-Hans":["四种形状各占 1.175 秒：圆形→圆角方形→星形→心形→圆形，基准半径 64。","每段先停留，再从段末前 0.62 秒到段末前 0.04 秒变形，持续 0.58 秒。","每个轮廓存为 240 个点，相同索引的点做线性插值；进度使用 backOut（s = 1.6），带轻微过冲。","颜色按蓝→珊瑚→黄→薄荷色变化，采用二次缓入缓出混合。","变形期间缩放为 1 + 0.07 × sin(π × progress)，略微膨胀。","下方有四个指示点，当前形状对应的点更大并着色。"]},"use":{"ja":"アイコンやロゴを別の形へ、切らずにつなげて変えたいとき。","en":"Use it to turn one icon or logo into another without a cut.","zh-Hans":"适合图标或标志之间的连续变换，无需硬切。"},"tags":["morph","morphing","shape","path","interpolate","transform","icon"]},{"id":"013","pack":"motion","no":"13","slug":"liquid-motion","category":"motion-polish","width":539,"height":208,"cycle":4.7,"name":{"ja":"リキッドモーション","en":"Liquid motion","zh-Hans":"液态运动"},"meaning":{"ja":"液体のようにぬるっと動く","en":"Shapes move and merge like liquid","zh-Hans":"形状像液体一样运动并融合"},"ask":{"ja":"ロゴの登場をリキッドモーションにして。しずくが集まってロゴの形になるように。","en":"Make the logo entrance a liquid motion: drops gather and form the shape.","zh-Hans":"标志用液态运动入场，让液滴聚拢成形。"},"summary":{"ja":"しずくが伸びて、ちぎれて、ぬるっと1つにまとまる。","en":"A blob stretches out, breaks into drops and merges back into one.","zh-Hans":"液团拉长、分裂成液滴，然后重新融合。"},"spec":{"ja":["先頭の丸（半径44）: 0.35〜1.45秒で右へ300px、cubic-bezier(.7, 0, .2, 1)。移動中は sin の山で34px浮く。2.7〜3.8秒で同じ動きで戻る","後ろに7つの丸が0.065秒ずつ遅れて同じ経路を追う。半径は44→15へ小さく、上下に±6px揺れる","止まっている間も、まわりで小さな丸3つ（半径15・13・11）が距離34〜64pxを1周期に2回出入りする","つながる質感: 丸を白で描く → 9pxぼかす → 透明度をしきい値（112〜144の間だけなだらか）で切る → 残った形に色を塗る","色はミント → 青 → 紫（#7C5CFF）の斜めグラデーション。先頭に白い楕円のハイライト"],"en":["Lead circle (radius 44): moves 300 px right at 0.35–1.45 s with cubic-bezier(.7, 0, .2, 1), rising 34 px on a sine arc while moving; returns the same way at 2.7–3.8 s.","Seven circles follow the same path, each 0.065 s later, radius tapering 44→15, wobbling ±6 px vertically.","Even while it rests, three small circles (radius 15, 13, 11) move in and out between 34 and 64 px from it, twice per cycle.","Merged look: draw the circles in white → blur 9 px → threshold the alpha (soft only between 112 and 144) → fill what remains with colour.","Fill is a diagonal gradient mint → blue → violet (#7C5CFF), with a white elliptical highlight on the lead circle."],"zh-Hans":["主圆半径 44，在 0.35–1.45 秒向右移动 300 px，曲线为 cubic-bezier(.7, 0, .2, 1)，同时按正弦弧线上升 34 px；2.7–3.8 秒沿同样方式返回。","七个圆沿相同路径跟随，各延迟 0.065 秒，半径从 44→15 递减，纵向摆动 ±6 px。","静止时仍有三个小圆，半径 15, 13, 11，在距主圆 34 到 64 px 处进出，每周期两次。","融合效果：白色画圆→模糊 9 px→对透明度做阈值处理，仅在 112 到 144 之间平滑过渡→为剩余区域着色。","填充为薄荷→蓝→紫（#7C5CFF）的斜向渐变，主圆上有白色椭圆高光。"]},"use":{"ja":"有機的でやわらかい印象を出したいとき。ロゴ・背景・切り替えのつなぎに。","en":"Use it for an organic, soft look in logos, backgrounds and connecting moves.","zh-Hans":"适合有机、柔和的标志、背景和衔接动效。"},"tags":["liquid","blob","goo","gooey","metaball","fluid","organic","drip"]},{"id":"014","pack":"motion","no":"14","slug":"motion-trail","category":"motion-polish","width":539,"height":208,"cycle":4.7,"name":{"ja":"モーショントレイル","en":"Motion trail","zh-Hans":"运动拖尾"},"meaning":{"ja":"動いた跡に残像が尾を引く","en":"A fading trail follows a moving object","zh-Hans":"移动物体身后留下逐渐消失的轨迹"},"ask":{"ja":"飛んでいく丸にモーショントレイルを付けて。残像は5個、後ろほど薄く。","en":"Add a motion trail to the flying circle: five copies that fade out behind it.","zh-Hans":"给飞行圆球加运动拖尾，身后五个副本逐渐淡出。"},"summary":{"ja":"8の字に動く丸の跡に、残像が尾を引く。","en":"A ball moving in a figure eight leaves a fading trail of copies behind it.","zh-Hans":"圆球沿八字轨迹运动，身后留下逐渐变淡的残影。"},"spec":{"ja":["丸（コーラル・半径25、中心に白の半径11）が8の字を4.7秒で1周: x = 196·sin(a)、y = 62·sin(2a)。a は一定の速さで進む","残像15個: 0.105rad（約0.079秒）ずつ過去の位置に置く","残像の半径は 22→6、透明度は 0.9 × (1 − i/15) + 0.05 で古いほど薄く小さい","残像の色は新しい順にコーラル → 黄 → 青","古い残像から先に描き、本体を最後に重ねる"],"en":["A ball (coral, radius 25, white centre radius 11) traces a figure eight once per 4.7 s: x = 196·sin(a), y = 62·sin(2a), with a advancing at constant speed.","15 copies, each placed 0.105 rad (about 0.079 s) further back along the path.","Copy radius goes 22→6 and opacity is 0.9 × (1 − i/15) + 0.05, so older copies are smaller and fainter.","Copy colour runs coral → yellow → blue from newest to oldest.","Draw the oldest copy first and the ball itself last."],"zh-Hans":["珊瑚色球半径 25、白色内芯半径 11，每 4.7 秒走完一次八字：x = 196·sin(a)，y = 62·sin(2a)，a 匀速增加。","15 个残影，每个沿路径后退 0.105 rad，约 0.079 秒。","残影半径从 22→6，透明度为 0.9 × (1 − i/15) + 0.05；越早的残影越小越淡。","残影颜色从新到旧依次为珊瑚→黄→蓝。","先绘制最旧残影，最后绘制球体本身。"]},"use":{"ja":"速さや軌道を見せたいとき。飛ぶ物・カーソル・光の点に。","en":"Use it to show speed or a path: flying objects, cursors, points of light.","zh-Hans":"适合表现速度或路径，如飞行物、光点和光标。"},"tags":["trail","motion-trail","echo","afterimage","ghost","path","speed"],"aliases":{"zh-Hans":["残影","拖影"]}},{"id":"015","pack":"motion","no":"15","slug":"particles","category":"motion-polish","width":539,"height":208,"cycle":4.7,"name":{"ja":"パーティクル","en":"Particles","zh-Hans":"粒子喷发"},"meaning":{"ja":"粒が飛び散る","en":"Many small pieces fly out and scatter","zh-Hans":"大量小颗粒飞出并散开"},"ask":{"ja":"達成の瞬間に、下からパーティクルを噴き上げて。4色で、1.5秒で落ちきるように。","en":"At the moment of success, shoot particles up from the bottom: four colors, all fallen within 1.5 s.","zh-Hans":"成功时从底部向上喷出四色粒子，在 1.5 秒内全部落下。"},"summary":{"ja":"粒が下の口から次々と噴き出して、飛び散って落ちる。","en":"Particles keep shooting up from an emitter, spread out and fall.","zh-Hans":"粒子从发射器持续向上喷出，散开后落下。"},"spec":{"ja":["粒84個。下中央（横の中央・下端から20px上）から出る","初速: 横 ±190px/秒、上向き 250〜400px/秒。重力 470px/秒²（放物線）","各粒は 2.35秒 または 約1.57秒 の周期で繰り返し、開始のずれは乱数（シード固定なので毎回同じ絵になる）","寿命は最長1.5秒。出た直後0.06秒でフェードイン、寿命の最後30%でフェードアウト。拡大率 1.15→0.7","形は丸・四角・三角（大きさ5〜11px）、色は青・コーラル・黄・ミント。最大 ±4.5rad/秒で回転"],"en":["84 particles, emitted from the bottom centre (horizontal centre, 20 px above the bottom edge).","Initial velocity: ±190 px/s horizontally, 250–400 px/s upward. Gravity 470 px/s² (parabolic paths).","Each particle repeats with a period of 2.35 s or about 1.57 s, with a random start offset (fixed seed, so every run looks the same).","Lifetime up to 1.5 s: fade in over the first 0.06 s, fade out over the last 30%. Scale 1.15→0.7.","Shapes are circles, squares and triangles (size 5–11 px) in blue, coral, yellow and mint, spinning at up to ±4.5 rad/s."],"zh-Hans":["84 个粒子，从底部中心发射，水平居中、距底边 20 px。","初速度：水平 ±190 px/s，向上 250–400 px/s；重力 470 px/s²，轨迹为抛物线。","每个粒子以 2.35 秒或约 1.57 秒为周期重复，初始时间随机错开；固定随机种子，保证每次结果一致。","生命周期最长 1.5 秒，前 0.06 秒淡入，最后 30% 淡出；缩放 1.15→0.7。","形状为圆、方、三角，尺寸 5–11 px；颜色为蓝、珊瑚、黄、薄荷色，旋转速度最高 ±4.5 rad/s。"]},"use":{"ja":"お祝い・達成・にぎやかさを足したいとき。紙吹雪や火花の代わりに。","en":"Use it to add celebration or liveliness, in place of confetti or sparks.","zh-Hans":"适合用彩纸或火花般的粒子增添庆祝氛围与活力。"},"tags":["particles","confetti","emitter","fountain","gravity","celebration","sparks"]},{"id":"016","pack":"motion","no":"16","slug":"parallax","category":"motion-polish","width":539,"height":208,"cycle":4.7,"name":{"ja":"パララックス","en":"Parallax","zh-Hans":"视差运动"},"meaning":{"ja":"手前と奥をずらして動かし奥行きを出す","en":"Near and far layers move at different speeds to show depth","zh-Hans":"远近图层以不同速度移动，形成空间深度"},"ask":{"ja":"この風景を3層に分けて、パララックスで横に流して。手前ほど速く。","en":"Split this landscape into three layers and scroll them with parallax, nearer layers faster.","zh-Hans":"把风景分成三层做视差滚动，越近的图层移动越快。"},"summary":{"ja":"横に動く景色。手前ほど大きく、奥ほど小さく動いて、奥行きが出る。","en":"A landscape pans sideways; near layers move more and far layers move less, creating depth.","zh-Hans":"风景横向平移，近层位移较大、远层较小，形成纵深。"},"spec":{"ja":["カメラの横移動: ±108px を sin波で4.7秒に1往復","各層は 移動量 × 係数 だけ逆向きにずらす。係数は奥から: 星 0.05、月 0.1、遠い山 0.28、中間の山 0.6、手前の丘と木 1.25、いちばん手前の暗い丸 2.1","奥の層ほど暗く背景に近い色、手前ほど明るい色。いちばん手前は暗い影として画面下に大きく置く","各層は画面の左右に200px以上はみ出して描き、端が見えないようにする"],"en":["Camera pan: ±108 px on a sine wave, one round trip per 4.7 s.","Each layer is offset by pan × factor in the opposite direction. Factors from back to front: stars 0.05, moon 0.1, far ridge 0.28, middle ridge 0.6, front hill and trees 1.25, nearest dark shapes 2.1.","Far layers use darker colours close to the background, nearer layers brighter ones; the nearest layer is a large dark silhouette along the bottom.","Every layer is drawn at least 200 px beyond both sides of the frame so its ends never show."],"zh-Hans":["镜头按正弦波水平往返 ±108 px，每 4.7 秒一轮。","每层反向偏移量为镜头位移 × 系数；由远到近为星星 0.05、月亮 0.1、远山 0.28、中景山脊 0.6、前景山丘与树 1.25、最近的深色形状 2.1。","远层使用接近背景的暗色，近层更明亮；最近层是沿底部延伸的大块深色剪影。","各层在画面左右两侧均至少延伸 200 px，防止露出边缘。"]},"use":{"ja":"平面の絵や写真に奥行きを出したいとき。背景・風景・スクロール表現に。","en":"Use it to give flat artwork or photos depth: backgrounds, landscapes, scrolling scenes.","zh-Hans":"适合让平面插画或照片产生空间感，如背景、风景和滚动场景。"},"tags":["parallax","depth","layers","pan","2.5d","background","landscape"]},{"id":"017","pack":"motion","no":"17","slug":"mask-transition","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"マスクトランジション","en":"Mask transition","zh-Hans":"遮罩转场"},"meaning":{"ja":"形の中から次の画面が現れる","en":"The next scene appears inside a growing shape","zh-Hans":"下一场景从扩张的形状内部显现"},"ask":{"ja":"次の場面へはマスクトランジションで。中央の丸が0.7秒で広がって切り替わるように。","en":"Go to the next scene with a mask transition: a circle grows from the center in 0.7 s.","zh-Hans":"用遮罩转场切换场景，让圆形从中心扩张，持续 0.7 秒。"},"summary":{"ja":"丸や星の形の「窓」が広がり、その中に次の画面が見える。","en":"A circle- or star-shaped window grows, showing the next scene inside it.","zh-Hans":"圆形或星形窗口不断扩大，显露其内部的下一场景。"},"spec":{"ja":["昼の画面 → 夜の画面 → 昼の画面を2.35秒ずつ。各区間の 0.45〜1.6秒（1.15秒）で切り替え、easeInOut（3乗）","今の画面の上に、形で切り抜いた次の画面を重ねる。形を広げて画面全体を覆ったら完了","昼→夜: 丸。太陽の中心（112, 104）から半径 0→470","夜→昼: 5角の星。月の中心（427, 104）から外側の半径 0→1150、同時に1.2rad（約69°）回す","広がっている間、形のふちに白い線（線幅7）を付ける"],"en":["Day scene → night scene → day scene, 2.35 s each. The change runs at 0.45–1.6 s of each half (1.15 s), cubic ease-in-out.","The next scene is drawn on top of the current one, clipped to a shape; the shape grows until it covers the frame.","Day→night: a circle from the sun's centre (112, 104), radius 0→470.","Night→day: a five-point star from the moon's centre (427, 104), outer radius 0→1150, rotating 1.2 rad (about 69°) as it grows.","While it grows, the edge of the shape has a white outline (width 7)."],"zh-Hans":["日景→夜景→日景，各占 2.35 秒；每半段的 0.45–1.6 秒执行转场，持续 1.15 秒，采用三次缓入缓出。","下一场景绘制在当前场景上方，并裁剪到形状内部；形状不断放大直至覆盖画面。","日转夜：以太阳中心 (112, 104) 为圆心，圆半径 0→470。","夜转日：以月亮中心 (427, 104) 为中心，五角星外半径 0→1150，同时旋转 1.2 rad，约 69°。","扩张时形状边缘带线宽 7 的白色轮廓。"]},"use":{"ja":"画面の中の物（太陽・ロゴ・ボタン）を起点に、次の場面へ切り替えたいとき。","en":"Use it to change scenes starting from an object in the frame, such as a sun, logo or button.","zh-Hans":"适合从画面中的太阳、标志或按钮等对象发起场景切换。"},"tags":["mask","transition","iris","wipe","shape-wipe","reveal","scene-change"],"aliases":{"zh-Hans":["遮罩","蒙版","圆形转场"]}},{"id":"018","pack":"motion","no":"18","slug":"shape-transition","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"シェイプトランジション","en":"Shape transition","zh-Hans":"图形转场"},"meaning":{"ja":"図形が画面を覆って切り替わる","en":"Shapes cover the screen and uncover the next scene","zh-Hans":"图形覆盖画面后离开，显露下一场景"},"ask":{"ja":"場面の切り替えはシェイプトランジションで。4色の斜めの帯が左から覆うように。","en":"Change scenes with a shape transition: four diagonal color bands sweep in from the left.","zh-Hans":"用图形转场切换场景，四条斜向彩带从左侧扫入覆盖画面。"},"summary":{"ja":"色のついた帯が画面を覆い隠し、抜けると次の画面になっている。","en":"Coloured bands sweep across and cover the frame; when they leave, the next scene is there.","zh-Hans":"彩色条带扫过并遮住画面，离开时露出下一场景。"},"spec":{"ja":["昼 → 夜 → 昼を2.35秒ずつ。横長の帯4本（高さ52・青、コーラル、黄、ミント）。帯の左右の端は80px斜め","覆う: 0.38〜1.0秒。各帯の先端が画面の端から反対の端まで進む。帯ごとに全体の14%ずつ遅らせ、1本あたり全体の58%の長さで easeInOut（3乗）","1.0秒（全部覆った瞬間）に下の画面を次の画面へ差し替える","抜ける: 1.12〜1.75秒。各帯の後ろの端が同じ遅れ・同じカーブで追いかけ、次の画面が現れる","向き: 昼→夜は左から右、夜→昼は左右反転"],"en":["Day → night → day, 2.35 s each. Four horizontal bands (height 52; blue, coral, yellow, mint) whose ends are slanted by 80 px.","Cover: 0.38–1.0 s. Each band's leading edge travels from one side of the frame to the other. Bands are delayed by 14% of the phase each, and each uses cubic ease-in-out over 58% of the phase.","At 1.0 s, when everything is covered, the scene underneath is swapped for the next one.","Uncover: 1.12–1.75 s. Each band's trailing edge follows with the same delays and curve, exposing the next scene.","Direction: left to right for day→night, mirrored for night→day."],"zh-Hans":["日景→夜景→日景，各占 2.35 秒；四条横带高 52，依次为蓝、珊瑚、黄、薄荷色，两端倾斜量 80 px。","覆盖阶段为 0.38–1.0 秒，各带前缘从画面一侧移到另一侧；每条延迟为阶段时长的 14%，每条以三次缓入缓出占用阶段时长的 58%。","1.0 秒完全遮住画面时，将底层场景替换为下一场景。","揭开阶段为 1.12–1.75 秒，各带后缘按相同延迟和曲线跟进，显露下一场景。","日转夜为从左向右，夜转日左右镜像。"]},"use":{"ja":"ブランドカラーの図形で場面を切り替えたいとき。章の区切りや話題の転換に。","en":"Use it to change scenes with shapes in brand colours: chapter breaks, topic changes.","zh-Hans":"适合用品牌色图形连接章节或切换话题。"},"tags":["shape-transition","transition","wipe","bands","stripes","cover","scene-change"]},{"id":"019","pack":"motion","no":"19","slug":"liquid-transition","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"リキッドトランジション","en":"Liquid transition","zh-Hans":"液态转场"},"meaning":{"ja":"液体が流れ込んで切り替わる","en":"Liquid flows in and replaces the scene","zh-Hans":"液体流入并替换当前场景"},"ask":{"ja":"ここはリキッドトランジションで。上から青いインクが垂れて画面を満たすように。","en":"Use a liquid transition here: blue ink drips down from the top and fills the frame.","zh-Hans":"这里用液态转场，蓝色墨水从顶部滴落并铺满画面。"},"summary":{"ja":"ペンキのような液体が上から垂れて流れ込み、次の画面になる。","en":"Paint-like liquid drips down from the top and fills the frame, becoming the next scene.","zh-Hans":"油漆般的液体从顶部滴入，逐渐填满画面并变为下一场景。"},"spec":{"ja":["昼 → 夜 → 昼を2.35秒ずつ。液体は2層。どちらも上から下へ、easeInOut（2乗）","1層目（単色。昼→夜は青、夜→昼はコーラル）: 0.35〜1.5秒。2層目（次の画面そのものを液体の形で切り抜く）: 0.7〜1.8秒","液面は y = −110 から 画面下端+130 まで下がる。ふちは2つのsin波（振幅13pxと8px）で波打ち、波の大きさは途中で最大になる","しずく7本（太さ30〜54px・先端は丸）を液面から垂らす。長さは 基準30〜110px × (0.25 + 0.9 × 波の強さ) で、途中で最大になる","つながる質感: 形を白で描く → 7pxぼかす → 透明度をしきい値で切る → 色（または次の画面）を塗る"],"en":["Day → night → day, 2.35 s each. Two liquid layers, both moving top to bottom with quadratic ease-in-out.","Layer 1 (flat colour: blue for day→night, coral for night→day): 0.35–1.5 s. Layer 2 (the next scene itself, clipped to the liquid shape): 0.7–1.8 s.","The liquid front moves from y = −110 to 130 px below the bottom edge. Its edge waves with two sine waves (amplitudes 13 px and 8 px), strongest midway.","Seven drips (30–54 px wide, round tips) hang from the front; length = base 30–110 px × (0.25 + 0.9 × wave strength), greatest midway.","Merged look: draw the shape in white → blur 7 px → threshold the alpha → fill with the colour (or the next scene)."],"zh-Hans":["日景→夜景→日景，各占 2.35 秒；两层液体均由上向下，采用二次缓入缓出。","第 1 层为纯色，日转夜用蓝色、夜转日用珊瑚色，时间 0.35–1.5 秒；第 2 层把下一场景裁剪为液体形状，时间 0.7–1.8 秒。","液面从 y = −110 移至底边下方 130 px；边缘叠加振幅为 13 px 和 8 px 的两条正弦波，中途最强。","七条末端圆润、宽 30–54 px 的液滴从液面垂下，长度 = 基准 30–110 px × (0.25 + 0.9 × 波动强度)，中途最长。","融合效果：白色画形状→模糊 7 px→对透明度做阈值处理→填充颜色或下一场景。"]},"use":{"ja":"やわらかく有機的に場面を切り替えたいとき。食品・美容・クリエイティブ系の映像に。","en":"Use it for a soft, organic scene change, for example in food, beauty or creative videos.","zh-Hans":"适合食品、美妆、创意视频等柔和、有机的场景切换。"},"tags":["liquid","transition","drip","paint","goo","fluid","wipe","scene-change"]},{"id":"020","pack":"motion","no":"20","slug":"zoom-through","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"ズームスルー","en":"Zoom through","zh-Hans":"穿越放大转场"},"meaning":{"ja":"物の中へ突き抜けて次へ","en":"Zooms into an object and passes through it into the next scene","zh-Hans":"放大进入物体内部，并穿越到下一场景"},"ask":{"ja":"ロゴの「O」の穴へズームスルーして、次の場面へ。0.6秒で、加速しながら。","en":"Zoom through the hole of the \"O\" in the logo into the next scene, 0.6 s, accelerating.","zh-Hans":"加速穿过标志中“O”的孔洞进入下一场景，持续 0.6 秒。"},"summary":{"ja":"文字の「O」の穴へ突っ込んで、その先の画面へ抜ける。","en":"The camera pushes into the hole of a letter O and comes out in the next scene.","zh-Hans":"镜头推进字母 O 的孔洞，再从孔洞中穿出进入下一场景。"},"spec":{"ja":["画面X（黄地に ZOOM）→ 画面Y（青地に GO!）→ 画面X を2.35秒ずつ","今の画面を「O」の穴の中心（半径24.5）を基準に拡大する。最大倍率は穴が画面全体を覆う値の1.08倍（約14倍）","倍率 = 最大倍率^p（指数で拡大。速さが一定に見える）","p = 0.8 × easeIn（3乗・0.25〜1.2秒）+ 0.2 × easeOut（3乗・1.2〜1.65秒）。加速して突っ込み、最後に減速","穴の中には次の画面を 1/最大倍率 に縮めて置く。拡大が終わるとちょうど等倍になり、そのまま次の画面に切り替わる"],"en":["Scene X (ZOOM on yellow) → scene Y (GO! on blue) → scene X, 2.35 s each.","The current scene is scaled around the centre of an O's hole (radius 24.5). Maximum scale is 1.08× the value at which the hole covers the whole frame (about 14×).","Scale = maxScale^p (exponential zoom, which reads as constant speed).","p = 0.8 × cubic ease-in (0.25–1.2 s) + 0.2 × cubic ease-out (1.2–1.65 s): accelerate in, slow down at the end.","Inside the hole the next scene is placed at 1/maxScale. When the zoom ends it is exactly at full size, and the view switches to the next scene."],"zh-Hans":["场景 X 为黄底 ZOOM，场景 Y 为蓝底 GO!，依次 X→Y→X，各占 2.35 秒。","以 O 的孔洞中心为缩放中心，孔半径 24.5；最大倍率为孔洞覆盖整幅画面所需倍率的 1.08×，约 14×。","缩放倍率 = maxScale^p，采用指数放大，使视觉速度保持均匀。","p = 0.8 × 三次缓入（0.25–1.2 秒）+ 0.2 × 三次缓出（1.2–1.65 秒），先加速推进，最后减速。","下一场景以 1/maxScale 缩小后放在孔内；放大结束时恰好恢复原尺寸，直接切换到下一场景。"]},"use":{"ja":"ロゴや文字の中へ入り込んで、勢いよく次の場面へ進みたいとき。","en":"Use it to dive into a logo or letter and move to the next scene with momentum.","zh-Hans":"适合钻入标志或文字，以强烈动势推进到下一场景。"},"tags":["zoom","zoom-through","transition","push-in","scale","tunnel","scene-change"]},{"id":"021","pack":"motion","no":"21","slug":"flip","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"フリップ","en":"Flip","zh-Hans":"卡片翻转"},"meaning":{"ja":"カードのように裏返る","en":"Turns over like a card to show the other side","zh-Hans":"像卡片一样翻到另一面"},"ask":{"ja":"料金カードをフリップで裏返して、裏に詳細を出して。0.5秒で。","en":"Flip the pricing card to show the details on its back, in 0.5 s.","zh-Hans":"价格卡片用 0.5 秒翻转，显示背面的详情。"},"summary":{"ja":"カードが縦の軸で回って裏返り、裏の面が出る。","en":"A card turns over around its vertical axis and shows its other side.","zh-Hans":"卡片绕竖直轴翻转，显露另一面。"},"spec":{"ja":["カード（300×156・角丸22）。表（青・Q）⇄ 裏（黄・A）を2.35秒ずつ","0.45〜1.5秒（1.05秒）で180°回す。backOut（s=1.5）で180°を少し行き過ぎてから戻る","カードの幅 = 元の幅 × |cos θ|。90°を越えたところで面の絵を差し替える","遠近感: カードを縦に細く切り、左右で高さを最大±20% × sin θ 変える（奥が低く、手前が高い）","回転中は sin の山で8%拡大し6px浮かせる。面に暗い色を透明度 0.34 × |sin θ| で重ねる。床に楕円の影"],"en":["A card (300 × 156, radius 22). Front (blue, Q) ⇄ back (yellow, A), 2.35 s each.","Rotates 180° at 0.45–1.5 s (1.05 s) with backOut (s = 1.5), going slightly past 180° and coming back.","Card width = original width × |cos θ|. The face artwork is swapped as it passes 90°.","Perspective: the card is drawn in thin vertical slices whose height varies by up to ±20% × sin θ from one side to the other (far side shorter, near side taller).","During the turn it scales up 8% and lifts 6 px on a sine curve; a dark overlay with opacity 0.34 × |sin θ| shades the face. An elliptical shadow sits on the floor."],"zh-Hans":["卡片为 300 × 156、圆角半径 22；正面为蓝色 Q，背面为黄色 A，往返各占 2.35 秒。","在 0.45–1.5 秒内旋转 180°，持续 1.05 秒；使用 backOut（s = 1.5），略超过 180° 后回落。","卡片宽度 = 原宽度 × |cos θ|，越过 90° 时替换正反面图案。","透视：将卡片切成细竖条绘制，左右高度变化最多 ±20% × sin θ，远侧较矮、近侧较高。","旋转时按正弦曲线放大 8% 并抬升 6 px；面上叠加透明度为 0.34 × |sin θ| 的暗色，地面放椭圆阴影。"]},"use":{"ja":"問いと答え、ビフォーとアフターなど、表と裏の関係にある2つを見せたいとき。","en":"Use it for two things that are sides of one another: question and answer, before and after.","zh-Hans":"适合问答、前后对比等具有正反对应关系的内容。"},"tags":["flip","card","3d","rotate","turn","reveal","question-answer"]},{"id":"022","pack":"motion","no":"22","slug":"light-sweep","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"ライトスイープ","en":"Light sweep","zh-Hans":"扫光"},"meaning":{"ja":"光が表面を横切る","en":"A band of light crosses a surface","zh-Hans":"一束光带掠过物体表面"},"ask":{"ja":"ロゴが止まったあとに、ライトスイープを1回。左上から右下へ、弱めに。","en":"After the logo settles, add one light sweep from top-left to bottom-right, subtle.","zh-Hans":"标志停稳后加一次轻微扫光，从左上向右下掠过。"},"summary":{"ja":"ロゴの表面を、光の帯が斜めに横切る。","en":"A band of light crosses the surface of a logo badge at an angle.","zh-Hans":"光带斜向掠过标志徽章的表面。"},"spec":{"ja":["2.35秒で1回。バッジ（400×112・角丸28・青のグラデーション）の形で切り抜いた中だけ光を描く","光の帯: 幅116pxの白いグラデーション（中央の透明度0.72、両端0）＋ 78px離れた幅12pxの細い帯（透明度0.5）。0.42rad（約24°）傾ける","0.45〜1.5秒でバッジの左130px外から右130px外まで（660px）進む。easeInOut（2乗）","きらめき: 1.38〜1.98秒、右上の角に4角の星。大きさ 30 × sin(πq) × (1 + 0.2(1 − q))、0.9rad回す","バッジ自体は動かさない"],"en":["One sweep per 2.35 s. The light is drawn only inside a clip of the badge (400 × 112, radius 28, blue gradient).","Light band: a 116 px wide white gradient (opacity 0.72 in the middle, 0 at the edges) plus a thin 12 px band (opacity 0.5) 78 px away, rotated 0.42 rad (about 24°).","It moves from 130 px left of the badge to 130 px right of it (660 px) at 0.45–1.5 s, quadratic ease-in-out.","Sparkle: a four-point star at the top-right corner at 1.38–1.98 s; size 30 × sin(πq) × (1 + 0.2(1 − q)), rotating 0.9 rad.","The badge itself does not move."],"zh-Hans":["每 2.35 秒扫光一次；光仅绘制在徽章裁剪区域内，徽章为 400 × 112、圆角半径 28、蓝色渐变。","光带为宽 116 px 的白色渐变，中心透明度 0.72、两边 0；另有宽 12 px、透明度 0.5 的细带，间距 78 px；整体倾斜 0.42 rad，约 24°。","在 0.45–1.5 秒从徽章左侧外 130 px 移至右侧外 130 px，共 660 px，采用二次缓入缓出。","闪光：1.38–1.98 秒在右上角显示四角星，尺寸为 30 × sin(πq) × (1 + 0.2(1 − q))，旋转 0.9 rad。","徽章本身保持静止。"]},"use":{"ja":"ロゴ・バッジ・ボタンに上質な印象を足したいとき。","en":"Use it to give a logo, badge or button a premium finish.","zh-Hans":"适合为标志、徽章或按钮增添精致质感。"},"tags":["light-sweep","shine","sheen","glint","highlight","logo","badge","premium"]},{"id":"023","pack":"motion","no":"23","slug":"glitch","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"グリッチ","en":"Glitch","zh-Hans":"故障干扰"},"meaning":{"ja":"映像がバグったように乱れる","en":"The picture breaks up as if it were malfunctioning","zh-Hans":"画面像信号故障一样错位破碎"},"ask":{"ja":"タイトルに一瞬だけグリッチを入れて。0.3秒、色ずれは弱めで、点滅はさせないで。","en":"Add a brief glitch to the title: 0.3 s, a mild color split, no flashing.","zh-Hans":"标题加短暂故障干扰，持续 0.3 秒，色差轻一些，不要闪屏。"},"summary":{"ja":"文字が横にずれ、色がずれ、帯が走る。明るさの点滅はさせない。","en":"Text slices shift sideways, colours split and small bars appear, with no brightness flashing.","zh-Hans":"文字切片横向错位，颜色分离并出现短色条，不产生亮度闪烁。"},"spec":{"ja":["白い太字（104px）。4.7秒に2回乱れる: 0.55〜1.25秒（5コマ）と 2.9〜3.74秒（6コマ）。それ以外は静止","1コマ0.14秒。コマごとに決め打ちの乱れを表示する（なめらかに動かさず、コマ送りで切り替える）","色ずれ: コーラルの文字を左へ7〜16px・下へ2px、シアン（#22D3EE）の文字を右へ同じ量・上へ2px、白の文字を上に重ねる","横ずれ: 高さ10〜35pxの横帯2〜4本（y=40〜150）を、左右どちらかへ18〜64pxずらす","小さな色の帯3本（コーラル・シアン・黄、幅30〜120×高さ5〜12）をランダムな位置に置く","背景の明るさは変えない（画面全体の点滅をしない）。乱数はシード固定"],"en":["White bold text (104 px). It glitches twice per 4.7 s: 0.55–1.25 s (5 steps) and 2.9–3.74 s (6 steps); otherwise it is still.","Each step lasts 0.14 s and shows one fixed disturbance (stepped, not smoothly animated).","Colour split: a coral copy shifted 7–16 px left and 2 px down, a cyan (#22D3EE) copy shifted the same amount right and 2 px up, with the white text on top.","Slice shift: 2–4 horizontal strips (10–35 px tall, y 40–150) are displaced 18–64 px to the left or right.","Three small colour bars (coral, cyan, yellow; 30–120 wide × 5–12 tall) at random positions.","Background brightness never changes (no full-frame flashing). The random values use a fixed seed."],"zh-Hans":["文字为 104 px 白色粗体；每 4.7 秒干扰两次：0.55–1.25 秒为 5 帧，2.9–3.74 秒为 6 帧，其余时间静止。","每帧持续 0.14 秒，显示固定的干扰状态，逐帧跳变而非平滑运动。","颜色分离：珊瑚色副本左移 7–16 px、下移 2 px；青色（#22D3EE）副本等量右移并上移 2 px；最上层叠白色文字。","切片错位：2–4 条横向切片，高 10–35 px、y 40–150，向左或向右错开 18–64 px。","随机放置三根小色条，颜色为珊瑚、青、黄，宽 30–120、高 5–12。","背景亮度不变，不做全屏闪烁；随机数使用固定种子。"]},"use":{"ja":"デジタル感・エラー・不穏さを出したいとき。タイトルや場面転換のアクセントに。","en":"Use it for a digital, error or uneasy feel, as an accent on titles and scene changes.","zh-Hans":"适合为标题或转场添加数字、报错或不安氛围。"},"tags":["glitch","rgb-split","chromatic-aberration","distortion","digital","error","slice"]},{"id":"024","pack":"motion","no":"24","slug":"impact-shake","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"インパクトシェイク","en":"Impact shake","zh-Hans":"冲击震屏"},"meaning":{"ja":"着地の衝撃で画面が揺れる","en":"The whole frame shakes when something lands","zh-Hans":"物体落地时带动整幅画面震动"},"ask":{"ja":"見出しがドンと落ちた瞬間に、インパクトシェイクを入れて。0.4秒で収まる程度に。","en":"Add an impact shake when the headline lands; it should settle within 0.4 s.","zh-Hans":"标题砸下的一瞬间加冲击震屏，约 0.4 秒内平稳下来。"},"summary":{"ja":"重い見出しの板がドンと落ち、その衝撃で画面ごと揺れる。","en":"A heavy headline slab drops with a thud and the whole frame shakes from the impact.","zh-Hans":"沉重的标题板砸落地面，冲击使整幅画面震动。"},"spec":{"ja":["2.35秒で1回（1回目は黄色の板、2回目はコーラルの板）。板は250×100・角丸18","落下: 0.3〜0.62秒で画面上の外から床へ。easeIn（3乗）で加速。落下中は縦に1.12倍のびる","0.62秒に着地。画面全体を1.1秒揺らす: 横 15px × e^(−5t) × sin(2π·5t)、縦 11px × e^(−5t) × cos(2π·6.5t)、傾き 0.02rad × e^(−5t) × sin(2π·5t + 0.6)","板は着地後0.3秒、縦に最大22%つぶれて戻る（横はその分ひろがる。基準は底辺）","背景の箱4つは0.03〜0.06秒遅れて最大24px跳ねる（0.5秒）。床から白い線6本と、ほこりの丸6個が0.55秒で広がって消える","退場: 1.85〜2.2秒に板が上へ300px（backIn s=1.6）"],"en":["One drop per 2.35 s (a yellow slab first, then a coral one). The slab is 250 × 100, radius 18.","Fall: 0.3–0.62 s from above the frame to the floor, cubic ease-in (accelerating). While falling it is stretched 1.12× vertically.","Lands at 0.62 s. The whole frame shakes for 1.1 s: x 15 px × e^(−5t) × sin(2π·5t), y 11 px × e^(−5t) × cos(2π·6.5t), rotation 0.02 rad × e^(−5t) × sin(2π·5t + 0.6).","For 0.3 s after landing the slab squashes vertically by up to 22% and recovers (it widens by the same amount; anchored at its base).","Four background blocks hop up to 24 px, 0.03–0.06 s late, over 0.5 s. Six white lines and six dust puffs spread from the floor and fade within 0.55 s.","Exit: the slab moves 300 px up at 1.85–2.2 s (backIn, s = 1.6)."],"zh-Hans":["每 2.35 秒落下一次，先黄色板，再珊瑚色板；板为 250 × 100、圆角半径 18。","0.3–0.62 秒从画面上方落到地面，采用三次缓入加速，落下时纵向拉伸 1.12×。","0.62 秒落地，整幅画面震动 1.1 秒：x 15 px × e^(−5t) × sin(2π·5t)，y 11 px × e^(−5t) × cos(2π·6.5t)，旋转 0.02 rad × e^(−5t) × sin(2π·5t + 0.6)。","落地后 0.3 秒内纵向最多压扁 22% 再恢复，横向相应变宽，锚点为底边。","四个背景块延迟 0.03–0.06 秒，在 0.5 秒内最多跳高 24 px；六根白线和六团圆形尘土从地面散开，并在 0.55 秒内消失。","退场：1.85–2.2 秒标题板上移 300 px，使用 backIn（s = 1.6）。"]},"use":{"ja":"重要な見出しや数字を、重さと衝撃で強く印象づけたいとき。","en":"Use it to land an important headline or number with weight and force.","zh-Hans":"适合用重量和冲击感突出重要标题或数字。"},"tags":["shake","impact","camera-shake","slam","drop","thud","headline","emphasis"]},{"id":"025","pack":"camera","no":"01","slug":"pan","category":"camera-movement","width":539,"height":208,"cycle":9.4,"name":{"ja":"パン","en":"Pan","zh-Hans":"水平摇镜"},"meaning":{"ja":"カメラを横に振る","en":"Pivot the camera left or right","zh-Hans":"机位固定，镜头向左或向右转动"},"ask":{"ja":"カメラの位置は固定で、街並みを左から右へゆっくりパン。5秒かけて。","en":"Slow pan from left to right across the skyline, camera fixed in place, over 5 seconds.","zh-Hans":"固定机位，用五秒从左向右缓慢摇过城市天际线。"},"summary":{"ja":"カメラの位置は変えず、首を左から右へ振る。回転なので手前も奥も同じ量だけ横に流れる。","en":"The camera stays in place and pivots from left to right; because it is a rotation, near and far layers slide sideways by the same amount.","zh-Hans":"相机原地从左向右转动；由于是旋转，远近图层按相同角度横向滑动。"},"spec":{"ja":["カメラ: 位置固定（高さ1.5m）、ヨーだけ -0.32rad → +0.32rad（-18° → +18°、計約37°）","時間: 0.5秒から3.4秒まで2.9秒かけて回す。イージングは3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","被写体: 人物（身長約1.8m）は正面8m先で動かない。画面上では右から左へ流れる","視差なし: 山・建物・木・人物が同じ角度ぶん動く（焦点距離330px、539×208のカード）","戻り: 3.4〜4.2秒は止め、最後の0.5秒で開始状態へクロスフェード（1周4.7秒）","右上に角度を整数の度で表示（-18° → +18°）"],"en":["Camera: position fixed (height 1.5 m); yaw only, -0.32 rad → +0.32 rad (-18° → +18°, about 37° in total)","Timing: rotate from 0.5 s to 3.4 s (2.9 s), cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","Subject: a person (about 1.8 m tall) stands still 8 m ahead and slides right-to-left in frame","No parallax: mountains, buildings, trees and the person all shift by the same angle (focal length 330 px on a 539×208 card)","Return: hold 3.4–4.2 s, then cross-fade back to the start over the last 0.5 s (one pass = 4.7 s)","Top-right readout shows the angle in whole degrees (-18° → +18°)"],"zh-Hans":["机位固定，高 1.5 m；仅偏航，-0.32 rad → +0.32 rad，即 -18° → +18°，总计约 37°。","0.5 秒至 3.4 秒转动，持续 2.9 秒，采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","人物高约 1.8 m，在前方 8 m 处静止，画面中从右向左滑动。","无视差：山、建筑、树和人物以相同角度偏移；539×208 卡片的焦距为 330 px。","3.4–4.2 秒停留，最后 0.5 秒交叉淡化回起点，每轮 4.7 秒。","右上角以整数度数显示角度，-18° → +18°。"]},"use":{"ja":"横に広い場所を見せるとき、または視線を左右の別の対象へ移すとき。","en":"To reveal a wide location or to shift attention from one side of the scene to the other.","zh-Hans":"适合展示宽阔环境，或将注意力从画面一侧引向另一侧。"},"tags":["pan","panning","yaw","rotate","horizontal","camera move","reveal"],"aliases":{"zh-Hans":["摇镜","横摇"]}},{"id":"026","pack":"camera","no":"02","slug":"tilt","category":"camera-movement","width":539,"height":208,"cycle":9.4,"name":{"ja":"ティルト","en":"Tilt","zh-Hans":"俯仰摇镜"},"meaning":{"ja":"カメラを縦に振る","en":"Pivot the camera up or down","zh-Hans":"机位固定，镜头向上或向下转动"},"ask":{"ja":"人物の足元から塔の先まで、ゆっくりティルトアップ。","en":"Slow tilt up from the person's feet to the top of the tower.","zh-Hans":"镜头从人物脚部缓慢上摇到塔顶。"},"summary":{"ja":"カメラの位置は変えず、首を下から上へ振る。足元の人物から塔の先端まで見上げていく。","en":"The camera stays in place and pivots upward, from a person at ground level up to the top of a tower.","zh-Hans":"相机在原地向上转动，从地面人物逐渐摇到塔顶。"},"spec":{"ja":["カメラ: 位置固定（高さ1.4m）、ピッチだけ -0.06rad → +0.36rad（-3° → +21°、計約24°）","時間: 0.5秒から3.4秒まで2.9秒。3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","被写体: 人物は7m先で動かない。その奥26mに高さ9.5mの塔（先端のアンテナは11.8mまで）","画面上は全体が上から下へ流れ、人物は下へ切れていき、塔の上部と先端のアンテナが入ってくる","戻り: 3.4〜4.2秒は止め、最後の0.5秒で開始状態へクロスフェード（1周4.7秒）","右上に角度を整数の度で表示（-3° → +21°）"],"en":["Camera: position fixed (height 1.4 m); pitch only, -0.06 rad → +0.36 rad (-3° → +21°, about 24° in total)","Timing: 0.5 s to 3.4 s (2.9 s), cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","Subject: a person stands still 7 m ahead; a 9.5 m tower (antenna tip at 11.8 m) stands 26 m away behind","On screen everything slides downward: the person leaves at the bottom while the tower top and its antenna enter","Return: hold 3.4–4.2 s, then cross-fade back to the start over the last 0.5 s (one pass = 4.7 s)","Top-right readout shows the angle in whole degrees (-3° → +21°)"],"zh-Hans":["机位固定，高 1.4 m；仅俯仰，-0.06 rad → +0.36 rad，即 -3° → +21°，总计约 24°。","时间为 0.5 秒至 3.4 秒，持续 2.9 秒，采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","人物在前方 7 m 静止；后方 26 m 处有高 9.5 m 的塔，天线顶端高 11.8 m。","画面中的物体整体下移，人物从底部离开，塔顶和天线进入画面。","3.4–4.2 秒停留，最后 0.5 秒交叉淡化回起点，每轮 4.7 秒。","右上角以整数度数显示角度，-3° → +21°。"]},"use":{"ja":"建物や人物の高さ・大きさを見せるとき。","en":"To show the height or scale of a building or a person.","zh-Hans":"适合展示建筑或人物的高度与体量。"},"tags":["tilt","tilt up","pitch","vertical","look up","camera move"],"aliases":{"zh-Hans":["纵摇","上摇","下摇"]}},{"id":"027","pack":"camera","no":"03","slug":"dolly-in","category":"camera-movement","width":539,"height":208,"cycle":9.4,"name":{"ja":"ドリーイン","en":"Dolly in","zh-Hans":"镜头推进"},"meaning":{"ja":"カメラごと被写体に近づく","en":"Move the camera toward the subject","zh-Hans":"相机向主体移动"},"ask":{"ja":"人物の顔へゆっくりドリーイン。ズームではなく、カメラごと近づく。","en":"Slow dolly in toward her face; move the camera, do not zoom.","zh-Hans":"缓慢向她的脸推进，移动相机，不要变焦。"},"summary":{"ja":"カメラそのものが被写体へ前進する。手前の物ほど大きく速く流れ、奥の山はほとんど変わらない。","en":"The camera itself moves toward the subject; near objects grow and pass quickly while the distant mountains barely change.","zh-Hans":"相机本身接近主体；近处物体迅速放大并掠过，远山几乎不变。"},"spec":{"ja":["カメラ: 前（奥行き方向）へ 0m → 5.8m 進む。高さ1.5m、向きと焦点距離（330px＝24mm表示）は固定","時間: 0.5秒から3.4秒まで2.9秒。3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","被写体: 人物は8m先で動かない。距離が8m → 2.2mになり、画面上の大きさは約3.6倍","視差あり: 手前の杭（左1.5m・奥3.6m）と岩（右1.6m・奥4.8m）は途中で画面外へ抜ける。120m以上先の山はほぼ同じ大きさ","戻り: 3.4〜4.2秒は止め、最後の0.5秒で開始状態へクロスフェード（1周4.7秒）","右上の表示は 24mm のまま変わらない（04 ズームインとの違い）"],"en":["Camera: moves forward (in depth) 0 m → 5.8 m; height 1.5 m, direction and focal length (330 px, shown as 24mm) fixed","Timing: 0.5 s to 3.4 s (2.9 s), cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","Subject: a person stands still 8 m ahead; distance goes 8 m → 2.2 m, so they appear about 3.6× larger","Parallax: a foreground post (1.5 m left, 3.6 m deep) and a rock (1.6 m right, 4.8 m deep) pass out of frame; mountains 120 m+ away stay almost the same size","Return: hold 3.4–4.2 s, then cross-fade back to the start over the last 0.5 s (one pass = 4.7 s)","The top-right readout stays at 24mm (the difference from 04 Zoom in)"],"zh-Hans":["相机沿纵深前进 0 m → 5.8 m；高 1.5 m，朝向与焦距固定；焦距为 330 px，界面显示 24mm。","时间为 0.5 秒至 3.4 秒，持续 2.9 秒，采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","人物在前方 8 m 静止，距离从 8 m → 2.2 m，画面尺寸变为约 3.6×。","视差：左侧 1.5 m、纵深 3.6 m 的前景柱和右侧 1.6 m、纵深 4.8 m 的岩石移出画面；120 m 以外的山几乎不变大。","3.4–4.2 秒停留，最后 0.5 秒交叉淡化回起点，每轮 4.7 秒。","右上角始终显示 24mm，与 04 变焦放大不同。"]},"use":{"ja":"人物の感情や一点へ、空間の奥行きを感じさせながら寄るとき。","en":"To move in on a person or detail while keeping a sense of depth.","zh-Hans":"适合接近人物或细节，同时保留空间纵深。"},"tags":["dolly","dolly in","push in","track in","move forward","parallax","camera move"],"aliases":{"zh-Hans":["推镜头","镜头推进","推轨"]}},{"id":"028","pack":"camera","no":"04","slug":"zoom-in","category":"camera-movement","width":539,"height":208,"cycle":9.4,"name":{"ja":"ズームイン","en":"Zoom in","zh-Hans":"变焦放大"},"meaning":{"ja":"レンズで寄る（位置は動かない）","en":"Magnify with the lens (camera stays put)","zh-Hans":"机位不动，通过镜头焦距放大画面"},"ask":{"ja":"カメラは動かさず、窓辺の人物へ3秒でズームイン。","en":"The camera stays still; zoom in on the person at the window over 3 seconds.","zh-Hans":"相机保持不动，用三秒变焦放大窗边的人物。"},"summary":{"ja":"カメラの位置は動かさず、レンズの焦点距離だけを伸ばす。画面全体が同じ比率で拡大する。","en":"The camera does not move; only the focal length gets longer, so the whole picture enlarges by the same ratio.","zh-Hans":"相机不动，只增加焦距，因此整幅画面按同一比例放大。"},"spec":{"ja":["カメラ: 位置・向きは固定（高さ1.5m）。焦点距離だけ 330px → 1200px（24mm → 87mm表示、約3.6倍）","倍率は指数補間: f = 330 × (8/2.2)^p。p は 0.5秒〜3.4秒（2.9秒）の3次イーズインアウト","被写体: 人物は8m先で動かない。最終の大きさは 03 ドリーインと同じ約3.6倍","視差なし: 手前の杭・岩、人物、建物、山がすべて同じ比率で大きくなる（重なり方が変わらない）","戻り: 3.4〜4.2秒は止め、最後の0.5秒で開始状態へクロスフェード（1周4.7秒）","右上に焦点距離を mm で表示（24mm → 87mm）"],"en":["Camera: position and direction fixed (height 1.5 m); only the focal length changes, 330 px → 1200 px (shown as 24mm → 87mm, about 3.6×)","Exponential interpolation: f = 330 × (8/2.2)^p, where p is a cubic ease-in-out from 0.5 s to 3.4 s (2.9 s)","Subject: a person stands still 8 m ahead; the final size matches 03 Dolly in (about 3.6×)","No parallax: the foreground post and rock, the person, buildings and mountains all scale by the same ratio (overlaps do not change)","Return: hold 3.4–4.2 s, then cross-fade back to the start over the last 0.5 s (one pass = 4.7 s)","Top-right readout shows the focal length in mm (24mm → 87mm)"],"zh-Hans":["位置和朝向固定，高 1.5 m；仅焦距变化，330 px → 1200 px，显示为 24mm → 87mm，约 3.6×。","指数插值 f = 330 × (8/2.2)^p；p 在 0.5 秒至 3.4 秒采用三次缓入缓出，持续 2.9 秒。","人物在前方 8 m 静止，最终尺寸与 03 镜头推进相同，约 3.6×。","无视差：前景柱、岩石、人物、建筑、山都按同一比例缩放，遮挡关系不变。","3.4–4.2 秒停留，最后 0.5 秒交叉淡化回起点，每轮 4.7 秒。","右上角以 mm 显示焦距，24mm → 87mm。"]},"use":{"ja":"その場から動かずに一点へ注目を集めるとき。ドリーインより平面的で観察する印象になる。","en":"To direct attention to one point without moving the camera; it looks flatter and more observational than a dolly in.","zh-Hans":"适合不移动机位地突出某个位置；比镜头推进更平面、更有观察感。"},"tags":["zoom","zoom in","focal length","lens","magnify","telephoto","camera move"],"aliases":{"zh-Hans":["变焦","光学放大"]}},{"id":"029","pack":"camera","no":"05","slug":"tracking-shot","category":"camera-movement","width":539,"height":208,"cycle":9.4,"name":{"ja":"トラッキング","en":"Tracking shot","zh-Hans":"跟拍镜头"},"meaning":{"ja":"被写体と並んで動く","en":"Move along with the subject","zh-Hans":"相机与主体同向同行"},"ask":{"ja":"歩く人物を真横からトラッキング。同じ速さで並んで動く。","en":"Tracking shot from the side, moving along with the walking person at the same speed.","zh-Hans":"从侧面跟拍行走的人物，相机与人物同速移动。"},"summary":{"ja":"歩く人物と同じ速さでカメラが真横に並走する。人物は画面中央のまま、手前の杭ほど速く後ろへ流れる。","en":"The camera moves sideways at the same speed as a walking person; the person stays centred while nearer posts sweep past faster.","zh-Hans":"相机与行人同速横移，人物始终居中，近处柱子更快掠过。"},"spec":{"ja":["カメラ: 右へ等速 1.7m/s で横移動（x = -4.0m → +4.0m、4.7秒）。高さ1.3m、向きは正面のまま。イージングなし","被写体: 人物はカメラと同じ x を歩く（奥7.5m）。画面中央から動かない。脚と腕は sin(u×7)×0.42rad で振る","視差: 奥4mに1.6m間隔で並ぶ杭が最も速く左へ流れ、木、建物（48m先）の順に遅くなり、山はほぼ動かない","右上に「→ 1.7m/s」を表示","くり返し: 4.7秒ごとに開始位置へ戻る（杭と地面の格子は継ぎ目が合うが、背景の建物と木は位置が飛ぶ）"],"en":["Camera: moves right at a constant 1.7 m/s (x = -4.0 m → +4.0 m in 4.7 s); height 1.3 m, facing straight ahead; no easing","Subject: a person walks at the same x as the camera (7.5 m away) and stays in the centre of frame; legs and arms swing by sin(u×7)×0.42 rad","Parallax: posts every 1.6 m at 4 m depth sweep left fastest, then trees, then buildings (48 m away); mountains hardly move","Top-right readout shows \"→ 1.7m/s\"","Repeat: jumps back to the start every 4.7 s (posts and ground grid line up at the seam; background buildings and trees jump)"],"zh-Hans":["相机以恒定 1.7 m/s 向右移动，在 4.7 秒内 x = -4.0 m → +4.0 m；高 1.3 m，正向取景，无缓动。","人物的 x 与相机一致，距离 7.5 m，始终居中；手臂与腿按 sin(u×7)×0.42 rad 摆动。","视差：纵深 4 m、间隔 1.6 m 的柱子最快向左掠过，其次是树，再是 48 m 远的建筑；山几乎不动。","右上角显示“→ 1.7m/s”。","每 4.7 秒跳回起点；柱子和地面网格在接缝处对齐，背景建筑和树会跳变。"]},"use":{"ja":"歩く・走る人物に付いていき、移動している感じを保ったまま表情や動作を見せるとき。","en":"To follow a walking or running subject and keep the sense of movement while showing their action.","zh-Hans":"适合跟随行走或奔跑的主体，兼顾动作与运动感。"},"tags":["tracking","tracking shot","follow","truck","lateral","sideways","parallax","walk"]},{"id":"030","pack":"camera","no":"06","slug":"orbit-arc-shot","category":"camera-movement","width":539,"height":208,"cycle":9.4,"name":{"ja":"オービット","en":"Orbit (Arc shot)","zh-Hans":"环绕镜头"},"meaning":{"ja":"被写体の周りを回り込む","en":"Circle around the subject","zh-Hans":"相机围绕主体做弧形运动"},"ask":{"ja":"立っている人物の周りを半周オービット。人物は画面の中央のまま。","en":"Half orbit around the standing person, keeping them in the center of the frame.","zh-Hans":"围绕站立人物拍半圈，保持人物位于画面中心。"},"summary":{"ja":"被写体を中心に、カメラが円を描いて回り込む。人物は中央のまま、背景の木と建物が横に大きく流れる。","en":"The camera travels on a circle around the subject; the person stays centred while the trees and buildings behind sweep sideways.","zh-Hans":"相机沿圆周绕主体移动，人物保持居中，身后的树与建筑横向掠过。"},"spec":{"ja":["カメラ: 人物（正面9m先）を中心とする半径6mの円周上を -0.95rad → +0.95rad（-54° → +54°、計約109°）移動","向き: 常に中心を向く（ヨー = -角度）。高さ1.7m、ピッチ -0.07rad（約4°下向き）で固定","時間: 0.5秒から3.6秒まで3.1秒。3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","被写体: 人物は動かない。顔の白い点が角度に応じて横へずれ、回り込みが分かる。足元に半径1.3mの点線の円","背景: 半径10mに12本の木を等間隔で並べ、回り込むと人物の後ろを横切る","戻り: 3.6〜4.2秒は止め、最後の0.5秒で開始状態へクロスフェード。右上に角度（-54° → +54°）"],"en":["Camera: travels on a circle of radius 6 m centred on the person (9 m ahead), from -0.95 rad → +0.95 rad (-54° → +54°, about 109° in total)","Direction: always faces the centre (yaw = -angle); height 1.7 m, pitch fixed at -0.07 rad (about 4° down)","Timing: 0.5 s to 3.6 s (3.1 s), cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","Subject: the person does not move; a white dot on the face shifts sideways with the angle; a dashed circle of radius 1.3 m marks the ground","Background: 12 trees evenly spaced on a 10 m radius cross behind the person as the camera moves round","Return: hold 3.6–4.2 s, then cross-fade back over the last 0.5 s; top-right readout shows the angle (-54° → +54°)"],"zh-Hans":["相机以位于前方 9 m 的人物为圆心，沿半径 6 m 的圆移动；角度 -0.95 rad → +0.95 rad，即 -54° → +54°，总计约 109°。","始终朝向圆心，偏航角 = -angle；高 1.7 m，俯仰固定为 -0.07 rad，约向下 4°。","0.5 秒至 3.6 秒运动，持续 3.1 秒，采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","人物不动；脸上的白点随角度横移；地面有半径 1.3 m 的虚线圆。","12 棵树均匀排列在半径 10 m 的圆周上，相机环绕时从人物背后经过。","3.6–4.2 秒停留，最后 0.5 秒交叉淡化复位；右上角显示 -54° → +54°。"]},"use":{"ja":"人物や商品を立体的に見せたいとき、登場や決めの場面を強調するとき。","en":"To show a person or product in three dimensions, or to emphasise an entrance or a key moment.","zh-Hans":"适合立体展示人物或产品，也可突出登场与关键时刻。"},"tags":["orbit","arc shot","circle","360","rotate around","revolve","camera move"],"aliases":{"zh-Hans":["环绕","弧形运镜"]}},{"id":"031","pack":"camera","no":"07","slug":"crane-up","category":"camera-movement","width":539,"height":208,"cycle":9.4,"name":{"ja":"クレーンアップ","en":"Crane up","zh-Hans":"升降镜头上升"},"meaning":{"ja":"カメラが上へ昇っていく","en":"Lift the camera up","zh-Hans":"抬升相机机位"},"ask":{"ja":"人物の目の高さから、街全体が見える高さまでクレーンアップ。","en":"Crane up from eye level until the whole town comes into view.","zh-Hans":"相机从视线高度向上升，直到整个城镇进入画面。"},"summary":{"ja":"カメラが真上へ上昇しながら下を向き、人物を見下ろす構図になる。","en":"The camera rises while tilting down until it looks down on the person.","zh-Hans":"相机一边上升一边俯拍，逐渐从上方看向人物。"},"spec":{"ja":["カメラ: 高さ 1.4m → 9m へ上昇。同時に前へ 0m → 1.5m 進む","向き: 人物（8m先）を画面に収めるよう下へ振る。ピッチ = -0.86 × atan2(高さ-1.0, 8-前進量)。約 -2.5° → -44°","時間: 0.5秒から3.4秒まで2.9秒。3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","被写体: 人物は動かない。上昇につれて小さくなり、地面の格子が画面いっぱいに広がって地平線は上へ抜ける","戻り: 3.4〜4.2秒は止め、最後の0.5秒で開始状態へクロスフェード（1周4.7秒）","右上に高さを表示（↑ 1.4m → ↑ 9.0m）"],"en":["Camera: rises from 1.4 m to 9 m while moving forward 0 m → 1.5 m","Direction: tilts down to keep the person (8 m ahead) in frame; pitch = -0.86 × atan2(height - 1.0, 8 - forward), about -2.5° → -44°","Timing: 0.5 s to 3.4 s (2.9 s), cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","Subject: the person does not move; they get smaller as the camera rises, the ground grid fills the frame and the horizon leaves at the top","Return: hold 3.4–4.2 s, then cross-fade back to the start over the last 0.5 s (one pass = 4.7 s)","Top-right readout shows the height (↑ 1.4m → ↑ 9.0m)"],"zh-Hans":["机位从 1.4 m 升至 9 m，同时向前移动 0 m → 1.5 m。","向下俯仰以保持前方 8 m 的人物在画面内；俯仰 = -0.86 × atan2(height - 1.0, 8 - forward)，约 -2.5° → -44°。","0.5 秒至 3.4 秒运动，持续 2.9 秒，采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","人物不动，随机位上升变小；地面网格铺满画面，地平线从顶部离开。","3.4–4.2 秒停留，最后 0.5 秒交叉淡化回起点，每轮 4.7 秒。","右上角显示高度，↑ 1.4m → ↑ 9.0m。"]},"use":{"ja":"場面の終わりに人物から離れて全体を見せるとき、場所の広さを明かすとき。","en":"To pull away from a person at the end of a scene or to reveal how large the location is.","zh-Hans":"适合场景结尾拉开与人物的距离，或揭示环境规模。"},"tags":["crane","crane up","jib","boom up","rise","high angle","camera move"]},{"id":"032","pack":"camera","no":"08","slug":"dolly-zoom-vertigo","category":"camera-movement","width":539,"height":208,"cycle":9.4,"name":{"ja":"ドリーズーム","en":"Dolly zoom (Vertigo)","zh-Hans":"滑动变焦（希区柯克变焦）"},"meaning":{"ja":"人物はそのまま背景だけ伸び縮み","en":"Subject stays, background warps","zh-Hans":"主体大小不变，背景透视发生变化"},"ask":{"ja":"気づいた瞬間の顔にドリーズーム。人物の大きさは変えず、背景だけが遠ざかる。","en":"Dolly zoom on his face at the moment he realizes: he stays the same size while the background stretches away.","zh-Hans":"他恍然大悟时对脸做滑动变焦，人物大小不变，背景向远处拉伸。"},"summary":{"ja":"カメラを引きながら同じ比率でズームする。人物の大きさは変わらず、背景だけが迫ってくる。","en":"The camera pulls back while zooming in by the same ratio; the person keeps the same size and only the background closes in.","zh-Hans":"相机后退，同时按相同比例变焦放大；人物大小不变，背景却向前逼近。"},"spec":{"ja":["カメラ: 人物（8m先）との距離 d を 3.2m → 8m に広げる（4.8m後退）。高さ1.3m","焦点距離: f = 330 × d/8 px。132px → 330px（10mm → 24mm表示）。距離と焦点距離の比を一定に保つ","時間: 0.5秒から3.4秒まで2.9秒。3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","被写体: 人物は動かず、画面上の高さも一定。頭（1.8m）と足元に幅160pxの青い点線を引き、大きさが変わらないことを示す","背景: 建物（48m先）は約2.2倍、山は約2.4倍に拡大して人物の後ろに迫る。人物より手前の地面は逆に縮む","戻り: 3.4〜4.2秒は止め、最後の0.5秒で開始状態へクロスフェード（1周4.7秒）"],"en":["Camera: distance d to the person (8 m ahead) widens from 3.2 m → 8 m (a 4.8 m pull-back); height 1.3 m","Focal length: f = 330 × d/8 px, i.e. 132 px → 330 px (shown as 10mm → 24mm), keeping distance ÷ focal length constant","Timing: 0.5 s to 3.4 s (2.9 s), cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","Subject: the person does not move and keeps the same height in frame; blue dashed lines 160 px wide at head (1.8 m) and feet show the size is constant","Background: buildings (48 m away) grow about 2.2× and mountains about 2.4×, closing in behind the person, while the ground in front of the person shrinks","Return: hold 3.4–4.2 s, then cross-fade back to the start over the last 0.5 s (one pass = 4.7 s)"],"zh-Hans":["前方 8 m 处为人物，相机到人物的距离 d 从 3.2 m → 8 m，后退 4.8 m；机位高 1.3 m。","焦距 f = 330 × d/8 px，即 132 px → 330 px，显示 10mm → 24mm；保持距离 ÷ 焦距不变。","0.5 秒至 3.4 秒运动，持续 2.9 秒，采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","人物静止，画面高度不变；头顶 1.8 m 和脚底处有宽 160 px 的蓝色虚线，标示恒定尺寸。","48 m 远的建筑放大约 2.2×，山约 2.4×，向人物身后逼近；人物前方地面缩小。","3.4–4.2 秒停留，最后 0.5 秒交叉淡化回起点，每轮 4.7 秒。"]},"use":{"ja":"人物が何かに気づいた瞬間や、不安・動揺を映像で表すとき。","en":"For a moment of realisation, or to show unease or shock visually.","zh-Hans":"适合表现领悟、不安或震惊的瞬间。"},"tags":["dolly zoom","vertigo","zolly","push pull","background stretch","unease","camera move"],"aliases":{"zh-Hans":["希区柯克","眩晕变焦"]}},{"id":"033","pack":"camera","no":"09","slug":"rack-focus","category":"shooting-style-time","width":539,"height":208,"cycle":9.4,"name":{"ja":"ラックフォーカス","en":"Rack focus","zh-Hans":"焦点转移"},"meaning":{"ja":"ピントを手前と奥のあいだで送る","en":"Shift focus between near and far","zh-Hans":"焦点在近景与远景间切换"},"ask":{"ja":"手前のカップから奥の人物へ、1秒でラックフォーカス。","en":"Rack focus from the cup in the foreground to the person behind it, in 1 second.","zh-Hans":"用一秒把焦点从前景杯子转移到后方人物。"},"summary":{"ja":"カメラは動かさず、ピントを手前の花から奥の人物へ送る。ぼけている側が入れ替わる。","en":"The camera does not move; focus shifts from a flower in the foreground to a person behind it, swapping which one is blurred.","zh-Hans":"相机静止，焦点由前景花朵转向后方人物，二者的虚实关系互换。"},"spec":{"ja":["カメラ: 位置・向き・焦点距離すべて固定（高さ1.1m）。変わるのはぼかしの量だけ","ぼかし: 手前の花（左0.75m・奥2m）を 0px → 7px、人物と背景（人物は右0.9m・奥9m）を 6px → 0px。地面の格子は背景の0.6倍","時間: 1.0秒から2.6秒まで1.6秒。3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","ピント枠: 青い四隅の枠が花から人物へ直線移動し、一辺の半分が 46px → 30px に縮む","被写体: 花も人物も動かない","戻り: 2.6〜4.2秒は止め、最後の0.5秒で開始状態へクロスフェード。右上にピント距離（◎ 2m → ◎ 9m）"],"en":["Camera: position, direction and focal length all fixed (height 1.1 m); only the blur amounts change","Blur: the foreground flower (0.75 m left, 2 m away) goes 0 px → 7 px; the person and background (person 0.9 m right, 9 m away) go 6 px → 0 px; the ground grid uses 0.6× the background blur","Timing: 1.0 s to 2.6 s (1.6 s), cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","Focus marker: blue corner brackets travel in a straight line from the flower to the person, half-width shrinking 46 px → 30 px","Subject: neither the flower nor the person moves","Return: hold 2.6–4.2 s, then cross-fade back over the last 0.5 s; top-right readout shows focus distance (◎ 2m → ◎ 9m)"],"zh-Hans":["位置、朝向、焦距均固定，机位高 1.1 m；只改变模糊程度。","前景花朵在左侧 0.75 m、距离 2 m，模糊 0 px → 7 px；人物与背景从 6 px → 0 px，人物在右侧 0.9 m、距离 9 m；地面网格的模糊量为背景的 0.6×。","1.0 秒至 2.6 秒变焦点，持续 1.6 秒，采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","蓝色角括号焦点框沿直线从花移向人物，半宽由 46 px → 30 px。","花朵和人物都不移动。","2.6–4.2 秒停留，最后 0.5 秒交叉淡化复位；右上角显示对焦距离 ◎ 2m → ◎ 9m。"]},"use":{"ja":"カットを割らずに、見てほしい対象を手前から奥（または逆）へ移すとき。","en":"To move attention from foreground to background (or back) without cutting.","zh-Hans":"适合不切镜地把注意力从前景引向背景，或反向引导。"},"tags":["rack focus","focus pull","pull focus","depth of field","blur","bokeh","foreground"],"aliases":{"zh-Hans":["拉焦","移焦"]}},{"id":"034","pack":"camera","no":"10","slug":"handheld","category":"shooting-style-time","width":539,"height":208,"cycle":9.4,"name":{"ja":"手持ち","en":"Handheld","zh-Hans":"手持摄影"},"meaning":{"ja":"手で持って撮ったように小さく揺らす（ハンドヘルド）","en":"A slight shake, as if the camera were held by hand","zh-Hans":"像手持相机拍摄一样轻微晃动"},"ask":{"ja":"手持ちで、歩く人物の後ろをついていく。揺れは弱めに。","en":"Handheld shot following behind the walking person, with only a slight shake.","zh-Hans":"用手持镜头从后方跟随行人，只保留轻微晃动。"},"summary":{"ja":"三脚を使わず手で持ったような、小さく不規則な揺れを画面全体に加える。","en":"Adds a small, irregular shake to the whole frame, as if the camera were held by hand instead of on a tripod.","zh-Hans":"整幅画面出现轻微、不规则的晃动，模拟手持相机而非三脚架。"},"spec":{"ja":["カメラ: 位置はほぼ固定。ヨー・ピッチ・ロール・高さに、周期の違う正弦波を重ねた揺れを足す（T = 2π×u/4.7）","ヨー(rad) = 0.016·sin(3T) + 0.008·sin(7T+1) + 0.004·sin(13T+2)。最大で約±1.6°","ピッチ(rad) = 0.012·sin(4T+2) + 0.006·sin(9T+0.5) + 0.003·sin(17T+1.2)。最大で約±1.2°","ロール(rad) = 0.02·sin(5T+1) + 0.008·sin(11T+3)。最大で約±1.6°。高さ = 1.5 + 0.03·sin(6T) m","被写体: 人物は6.5m先で動かない。イージングや止めはなく揺れ続ける","係数がすべて整数倍なので4.7秒で継ぎ目なく戻る。右上に「HANDHELD」"],"en":["Camera: position almost fixed; yaw, pitch, roll and height each get a sum of sine waves with different periods (T = 2π×u/4.7)","Yaw (rad) = 0.016·sin(3T) + 0.008·sin(7T+1) + 0.004·sin(13T+2), at most about ±1.6°","Pitch (rad) = 0.012·sin(4T+2) + 0.006·sin(9T+0.5) + 0.003·sin(17T+1.2), at most about ±1.2°","Roll (rad) = 0.02·sin(5T+1) + 0.008·sin(11T+3), at most about ±1.6°; height = 1.5 + 0.03·sin(6T) m","Subject: a person stands still 6.5 m ahead; the shake runs continuously with no easing or hold","All multipliers are integers, so it loops seamlessly every 4.7 s; top-right readout shows \"HANDHELD\""],"zh-Hans":["机位基本固定，偏航、俯仰、横滚和高度分别叠加不同周期的正弦波，T = 2π×u/4.7。","偏航（rad）= 0.016·sin(3T) + 0.008·sin(7T+1) + 0.004·sin(13T+2)，最大约 ±1.6°。","俯仰（rad）= 0.012·sin(4T+2) + 0.006·sin(9T+0.5) + 0.003·sin(17T+1.2)，最大约 ±1.2°。","横滚（rad）= 0.02·sin(5T+1) + 0.008·sin(11T+3)，最大约 ±1.6°；高度 = 1.5 + 0.03·sin(6T) m。","人物在前方 6.5 m 静止；晃动持续进行，无缓动或停留。","所有频率倍数均为整数，每 4.7 秒无缝循环；右上角显示“HANDHELD”。"]},"use":{"ja":"ドキュメンタリーのような臨場感や、その場にいる感じを出すとき。","en":"To give a documentary feel or the sense of being present in the scene.","zh-Hans":"适合纪实风格或增强身临其境的感觉。"},"tags":["handheld","camera shake","shaky","documentary","wobble","noise","realism"]},{"id":"035","pack":"camera","no":"11","slug":"fpv-drone-shot","category":"shooting-style-time","width":539,"height":208,"cycle":9.4,"name":{"ja":"FPV","en":"FPV drone shot","zh-Hans":"FPV 穿越机镜头"},"meaning":{"ja":"ドローンで突き進む疾走感","en":"Fast, immersive fly-through","zh-Hans":"快速、沉浸式的第一人称飞行"},"ask":{"ja":"FPVドローンで、森の木々の間をすり抜けて川の上へ出る。","en":"FPV drone shot weaving between the trees and out over the river.","zh-Hans":"用 FPV 穿越机镜头穿过树林，再飞到河面上方。"},"summary":{"ja":"並木の間を低空・高速で前進しながら、機体を左右に傾けて蛇行する一人称視点。","en":"A first-person view flying low and fast between two rows of trees, banking from side to side.","zh-Hans":"第一人称视角低空高速穿过两排树，左右侧倾转弯。"},"spec":{"ja":["カメラ: 前へ等速 14m/s（50km/h表示）。イージングなしで進み続ける。ピッチは -0.05rad で固定","蛇行（T = 2π×u/4.7、4.7秒に2往復）: 横位置 0.6·sin(2T-0.4) m、高さ 1.4 + 0.5·sin(2T) m","傾き: ロール 0.22·sin(2T+0.6) rad（約±12.6°）、ヨー 0.05·sin(2T) rad（約±2.9°）","被写体なし。左右3.6mの位置に高さ4.2mの木を8m間隔で並べ、左右は4mずらす。次々に手前へ流れる","スピード線: 中心から放射状に10本、長さ約32〜76px（横方向ほど長い）、半透明の灰色。外側へ流れて循環する","止め・戻りのクロスフェードなし（4.7秒ごとに木の並びの位相がずれて切り替わる）"],"en":["Camera: flies forward at a constant 14 m/s (shown as 50km/h) with no easing; pitch fixed at -0.05 rad","Weave (T = 2π×u/4.7, two swings per 4.7 s): sideways 0.6·sin(2T-0.4) m, height 1.4 + 0.5·sin(2T) m","Bank: roll 0.22·sin(2T+0.6) rad (about ±12.6°), yaw 0.05·sin(2T) rad (about ±2.9°)","No subject. Trees 4.2 m tall stand 3.6 m to each side, every 8 m, the two rows offset by 4 m, and rush toward the camera","Speed lines: 10 radial strokes about 32–76 px long (longer toward the sides) in translucent grey, flowing outward and recycling","No hold and no cross-fade reset (the tree rows shift phase when it restarts every 4.7 s)"],"zh-Hans":["相机以恒定 14 m/s 前飞，显示为 50km/h，无缓动；俯仰固定 -0.05 rad。","穿行摆动：T = 2π×u/4.7，每 4.7 秒摆动两次；横移 0.6·sin(2T-0.4) m，高度 1.4 + 0.5·sin(2T) m。","侧倾横滚为 0.22·sin(2T+0.6) rad，约 ±12.6°；偏航为 0.05·sin(2T) rad，约 ±2.9°。","无主体；树高 4.2 m，位于两侧各 3.6 m 处，间隔 8 m，两排错开 4 m，迎面快速掠过。","10 根半透明灰色放射速度线，长约 32–76 px，越靠两侧越长；向外流动并循环。","无停留或交叉淡化复位；每 4.7 秒重新开始时，树列相位会变化。"]},"use":{"ja":"スピード感と没入感を出すとき。場所の中を一気に通り抜けて見せるとき。","en":"For speed and immersion, or to fly through a location in one continuous move.","zh-Hans":"适合表现速度和沉浸感，或用连续镜头穿越场地。"},"tags":["fpv","drone","fly through","first person","banking","speed","aerial"]},{"id":"036","pack":"camera","no":"12","slug":"dutch-angle","category":"shooting-style-time","width":539,"height":208,"cycle":9.4,"name":{"ja":"ダッチアングル","en":"Dutch angle","zh-Hans":"荷兰角"},"meaning":{"ja":"画面を斜めに傾ける","en":"Tilt the frame diagonally","zh-Hans":"让画面倾斜构图"},"ask":{"ja":"不安な場面なので、ダッチアングルで15度ほど傾けて。","en":"Use a Dutch angle of about 15 degrees for this uneasy scene.","zh-Hans":"这个不安的场景用约十五度的荷兰角。"},"summary":{"ja":"水平だったカメラを光軸まわりに傾け、地平線を斜めにしたまま止める。","en":"A level camera rolls around its lens axis and holds with the horizon on a diagonal.","zh-Hans":"水平机位绕镜头轴旋转，然后保持倾斜的地平线。"},"spec":{"ja":["カメラ: 位置固定（高さ1.5m）。ロールだけ 0 → 0.36rad（約21°）。画面中央を軸に全体が回る","時間: 0.6秒から2.2秒まで1.6秒。3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","被写体: 人物は7m先で動かない。地平線・建物・人物がそろって同じ角度だけ傾く","止め: 2.2〜4.2秒は傾いたまま保つ（傾けた構図そのものを見せる時間）","戻り: 最後の0.5秒で水平の開始状態へクロスフェード（1周4.7秒）","右上に角度を表示（∠ 0° → ∠ 21°）"],"en":["Camera: position fixed (height 1.5 m); roll only, 0 → 0.36 rad (about 21°); the whole picture turns around the frame centre","Timing: 0.6 s to 2.2 s (1.6 s), cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","Subject: a person stands still 7 m ahead; horizon, buildings and person all tilt by the same angle","Hold: stays tilted from 2.2 s to 4.2 s (time to read the tilted composition itself)","Return: cross-fade back to the level start over the last 0.5 s (one pass = 4.7 s)","Top-right readout shows the angle (∠ 0° → ∠ 21°)"],"zh-Hans":["机位固定，高 1.5 m；仅横滚，0 → 0.36 rad，约 21°；整幅画面绕中心旋转。","0.6 秒至 2.2 秒旋转，持续 1.6 秒，采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","人物在前方 7 m 静止，地平线、建筑和人物以相同角度倾斜。","从 2.2 秒到 4.2 秒保持倾斜，留出观看构图的时间。","最后 0.5 秒交叉淡化回水平起点，每轮 4.7 秒。","右上角显示角度，∠ 0° → ∠ 21°。"]},"use":{"ja":"不安・緊張・違和感を画面で表すとき。","en":"To express unease, tension or the feeling that something is wrong.","zh-Hans":"适合表现不安、紧张或异常感。"},"tags":["dutch angle","dutch tilt","canted angle","oblique","roll","tension","tilted horizon"]},{"id":"037","pack":"camera","no":"13","slug":"slow-motion","category":"shooting-style-time","width":539,"height":208,"cycle":9.4,"name":{"ja":"スローモーション","en":"Slow motion","zh-Hans":"慢动作"},"meaning":{"ja":"動きをゆっくり見せる","en":"Play the action slower","zh-Hans":"以更慢速度播放动作"},"ask":{"ja":"水しぶきが上がる瞬間を、スローモーションで。","en":"Show the moment of the splash in slow motion.","zh-Hans":"用慢动作呈现水花溅起的瞬间。"},"summary":{"ja":"固定カメラの前で人物がゆっくり跳び上がり、葉もゆっくり落ちる。動き全体を引き伸ばして見せる。","en":"In front of a fixed camera a person rises and falls slowly through a jump while leaves drift down slowly; the whole action is stretched out.","zh-Hans":"固定机位下，人物缓慢跃起落下，树叶缓慢飘落，整个动作被拉长。"},"spec":{"ja":["カメラ: 完全に固定（高さ1.3m）。動くのは被写体だけ","被写体: 人物（7m先）が1回の跳躍に3.8秒かける（0.5秒〜4.3秒）。高さ = 4q(1-q)×1.1m の放物線、頂点1.1m。q は等速","跳んでいる間は両腕を上げる。跳ぶ前の0.5秒と着地後の0.4秒は立ったまま","葉: 9枚が高さ3.4mから地面まで4.7秒かけて落ち、回転する。位相を1/9ずつずらして循環","右上に「120fps ×0.25」を表示（4倍に引き伸ばした再生という設定）","止め・クロスフェードなし。4.7秒で継ぎ目なくくり返す"],"en":["Camera: completely fixed (height 1.3 m); only the subject moves","Subject: a person 7 m away takes 3.8 s for one jump (0.5 s to 4.3 s); height = 4q(1-q)×1.1 m, a parabola peaking at 1.1 m, with q linear in time","Both arms are raised while airborne; the person stands still for 0.5 s before the jump and 0.4 s after landing","Leaves: 9 leaves fall from 3.4 m to the ground over 4.7 s while rotating, each offset by 1/9 of the cycle","Top-right readout shows \"120fps ×0.25\" (playback stretched 4×)","No hold and no cross-fade; loops seamlessly every 4.7 s"],"zh-Hans":["机位完全固定，高 1.3 m；只有主体运动。","人物距离 7 m，一次跳跃持续 3.8 秒，从 0.5 秒到 4.3 秒；高度 = 4q(1-q)×1.1 m，为峰值 1.1 m 的抛物线，q 随时间线性变化。","空中双臂举起；起跳前静止 0.5 秒，落地后静止 0.4 秒。","9 片叶子在 4.7 秒内从 3.4 m 高处旋转落地，每片错开周期的 1/9。","右上角显示“120fps ×0.25”，播放时长拉长 4×。","无停留、无交叉淡化，每 4.7 秒无缝循环。"]},"use":{"ja":"一瞬の動きや表情をじっくり見せたいとき、感情の山場を強調するとき。","en":"To let viewers study a brief action or expression, or to emphasise an emotional peak.","zh-Hans":"适合观察短暂动作或表情，也可强化情绪高潮。"},"tags":["slow motion","slow-mo","slomo","high frame rate","120fps","time stretch","jump"]},{"id":"038","pack":"camera","no":"14","slug":"speed-ramp","category":"shooting-style-time","width":539,"height":208,"cycle":9.4,"name":{"ja":"スピードランプ","en":"Speed ramp","zh-Hans":"速度渐变"},"meaning":{"ja":"速い→遅いと速さを変える","en":"Change speed mid-shot","zh-Hans":"同一镜头中平滑改变播放速度"},"ask":{"ja":"ジャンプの頂点だけ遅くなるスピードランプ。前後は通常の速さで。","en":"Speed ramp: normal speed, slowing at the top of the jump, then back to normal.","zh-Hans":"做速度渐变：正常速度起步，到跳跃顶点放慢，再恢复正常。"},"summary":{"ja":"1つのショットの途中で再生速度を速い状態から遅い状態へ滑らかに変える。左下のグラフが速度を示す。","en":"Within one shot the playback speed changes smoothly from fast to slow; a graph at bottom left shows the speed.","zh-Hans":"同一镜头中播放速度从快到慢平滑变化，左下角曲线显示当前速度。"},"spec":{"ja":["カメラ: 完全に固定（高さ1.3m）。変わるのは再生速度だけ","再生速度: 2.4倍 → 0.25倍。切り替えは1.2秒から1.9秒までの0.7秒、2次のイーズインアウト（cubic-bezier(0.45,0,0.55,1) 相当）","被写体: 人物（8m先）が左6mから右へ走る。位置 x = -6 + 映像時間×2.0 m。速い区間で一気に近づく","跳躍: x が -1.5m〜2.5m の間で放物線、頂点0.99m、両腕を上げる。約0.94秒で踏み切り、滞空の大半をスローで見せて約3.68秒で着地","グラフ: 左下に幅120×高さ40pxの速度曲線と現在位置の青い点（半径5px）","戻り: 4.2秒で止め、最後の0.5秒で開始状態へクロスフェード。右上に倍率（×2.4 → ×0.3）"],"en":["Camera: completely fixed (height 1.3 m); only the playback speed changes","Playback speed: 2.4× → 0.25×; the change takes 0.7 s (1.2 s to 1.9 s) with a quadratic ease-in-out (about cubic-bezier(0.45,0,0.55,1))","Subject: a person 8 m away runs from 6 m left toward the right; x = -6 + footage time × 2.0 m; they close in quickly during the fast section","Jump: a parabola while x is between -1.5 m and 2.5 m, peak 0.99 m, arms raised; take-off at about 0.94 s, most of the airtime plays in slow motion, landing at about 3.68 s","Graph: a 120×40 px speed curve at bottom left with a blue dot (radius 5 px) at the current time","Return: stops at 4.2 s, then cross-fades back over the last 0.5 s; top-right readout shows the rate (×2.4 → ×0.3)"],"zh-Hans":["机位完全固定，高 1.3 m；只改变播放速度。","播放速度 2.4× → 0.25×，在 0.7 秒内改变，时间为 1.2 秒至 1.9 秒；采用二次缓入缓出，约 cubic-bezier(0.45,0,0.55,1)。","人物距离 8 m，从左侧 6 m 处向右跑；x = -6 + 素材时间 × 2.0 m，快速段迅速接近。","在 x 为 -1.5 m 至 2.5 m 时沿抛物线跳跃，峰值 0.99 m，双臂举起；约 0.94 秒起跳，大部分腾空时间慢放，约 3.68 秒落地。","左下角显示 120×40 px 的速度曲线，半径 5 px 的蓝点标记当前时间。","4.2 秒停止，最后 0.5 秒交叉淡化复位；右上角显示倍率 ×2.4 → ×0.3。"]},"use":{"ja":"動きの見せ場だけをスローにして、前後はテンポよく進めたいとき。","en":"To slow down only the key part of an action while keeping the lead-in quick.","zh-Hans":"适合仅放慢动作关键部分，保持前段节奏紧凑。"},"tags":["speed ramp","time remap","ramping","fast to slow","variable speed","velocity"]},{"id":"039","pack":"camera","no":"15","slug":"time-lapse","category":"shooting-style-time","width":539,"height":208,"cycle":9.4,"name":{"ja":"タイムラプス","en":"Time-lapse","zh-Hans":"延时摄影"},"meaning":{"ja":"長い時間を早送りで見せる","en":"Compress hours into seconds","zh-Hans":"把数小时压缩为几秒"},"ask":{"ja":"夕方から夜まで、街の灯りがともっていくタイムラプス。","en":"Time-lapse of the city from dusk to night as the lights come on.","zh-Hans":"用延时摄影表现城市从黄昏到夜晚、灯光逐渐亮起。"},"summary":{"ja":"固定カメラのまま、朝6時から夕方18時までを数秒に縮める。太陽・雲・人・影が早送りで動く。","en":"With a fixed camera, 06:00 to 18:00 is compressed into a few seconds; sun, clouds, people and shadows move in fast forward.","zh-Hans":"固定机位将 06:00 到 18:00 压缩为几秒，太阳、云、人和影子快速运动。"},"spec":{"ja":["カメラ: 完全に固定（高さ1.6m、ピッチ +0.08rad＝約5°上向き）","時間: 0.4秒から4.1秒まで3.7秒で12時間ぶん進める。3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","太陽: 角度 a = -1.25rad → +1.25rad の弧を左から右へ。位置は (sin a×120, cos a×60 - 8) m、奥170m","雲3つ: 右へ合計140m流れ、80mごとに循環。人影7つ: 左右18mの幅をそれぞれ6回横切る（奇数番と偶数番は逆向き）","建物の影: 太陽と反対側へ伸び、太陽の動きに合わせて向きが振れる（半透明の灰色）","戻り: 最後の0.5秒で開始状態へクロスフェード。右上の時計は 06:00 → 18:00 を10分刻みで表示"],"en":["Camera: completely fixed (height 1.6 m, pitch +0.08 rad, about 5° up)","Timing: 12 hours pass in 3.7 s (0.4 s to 4.1 s), cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","Sun: travels left to right along an arc, angle a = -1.25 rad → +1.25 rad; position (sin a×120, cos a×60 - 8) m at 170 m depth","Three clouds drift 140 m to the right in total, wrapping every 80 m; seven small figures each cross an 18 m width 6 times (odd and even ones in opposite directions)","Building shadows fall away from the sun and swing as it moves (translucent grey)","Return: cross-fade back to the start over the last 0.5 s; the top-right clock runs 06:00 → 18:00 in 10-minute steps"],"zh-Hans":["机位完全固定，高 1.6 m，俯仰 +0.08 rad，约上仰 5°。","12 小时压缩为 3.7 秒，时间为 0.4 秒至 4.1 秒；采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","太阳从左向右沿弧线运动，a = -1.25 rad → +1.25 rad；位置为 (sin a×120, cos a×60 - 8) m，纵深 170 m。","三朵云总共向右移动 140 m，每 80 m 循环；七个小人物各穿过 18 m 宽的范围 6 次，奇偶编号方向相反。","半透明灰色建筑影子背向太阳投射，并随太阳运动摆动。","最后 0.5 秒交叉淡化复位；右上角时钟从 06:00 → 18:00，以 10 分钟为步进。"]},"use":{"ja":"長い時間の経過や、街・空・作業の変化を短く見せるとき。","en":"To show a long stretch of time, or how a city, sky or task changes, in a short clip.","zh-Hans":"适合短片表现长时间流逝，或城市、天空、任务的变化。"},"tags":["time-lapse","timelapse","fast forward","time compression","sun","clouds","day to night"]},{"id":"040","pack":"camera","no":"16","slug":"freeze-frame","category":"shooting-style-time","width":539,"height":208,"cycle":9.4,"name":{"ja":"フリーズフレーム","en":"Freeze frame","zh-Hans":"定格"},"meaning":{"ja":"動きを一瞬止める","en":"Pause the action for a beat","zh-Hans":"将动作暂停片刻"},"ask":{"ja":"振り向いた瞬間でフリーズフレーム。1秒止めて、名前を出す。","en":"Freeze frame at the moment she turns around; hold for 1 second and show her name.","zh-Hans":"她转身时定格一秒，并显示名字。"},"summary":{"ja":"跳び上がった人物が頂点に来た瞬間に映像を止め、1.4秒後に続きから再開する。","en":"The picture stops at the moment a jumping person reaches the top, then resumes from the same frame 1.4 s later.","zh-Hans":"人物跳至最高点时画面定格，1.4 秒后从同一帧继续。"},"spec":{"ja":["カメラ: 完全に固定（高さ1.3m）。止まるのは映像の時間","停止: 1.6秒で止め、3.0秒で再開（1.4秒間）。映像時間は 0〜1.6秒は等速、停止中は1.6秒のまま、再開後は u-1.4","被写体: 人物（7m先）の跳躍は映像時間0.6〜2.6秒の放物線、頂点1.1m。停止位置は頂点ちょうど（進み50%）","停止中は落ち葉9枚も止まる。葉の速さは 13 スローモーションの1.5倍","停止の印: 太さ5pxの青い枠と、下中央の一時停止マーク（68×40pxの白い角丸に青い縦棒2本）。出入りは0.12秒のフェード","右上に停止中だけ「FREEZE」を表示。戻りのクロスフェードなし"],"en":["Camera: completely fixed (height 1.3 m); what stops is the footage time","Freeze: stops at 1.6 s and resumes at 3.0 s (1.4 s); footage time runs normally for 0–1.6 s, stays at 1.6 s while frozen, then continues as u-1.4","Subject: the jump of a person 7 m away is a parabola over footage time 0.6–2.6 s, peak 1.1 m; the freeze lands exactly on the peak (50% through)","Nine falling leaves also stop during the freeze; they fall 1.5× as fast as in 13 Slow motion","Freeze markers: a 5 px blue border and a pause icon at bottom centre (two blue bars on a 68×40 px white rounded box), fading in and out over 0.12 s","Top-right readout shows \"FREEZE\" only while frozen; no cross-fade reset"],"zh-Hans":["机位完全固定，高 1.3 m；暂停的是素材时间。","1.6 秒定格，3.0 秒恢复，持续 1.4 秒；素材时间在 0–1.6 秒正常前进，定格时保持 1.6 秒，之后按 u-1.4 继续。","人物距离 7 m，素材时间 0.6–2.6 秒内按抛物线跳跃，峰值 1.1 m；定格恰好位于最高点，即进度 50%。","九片落叶同步暂停，其下落速度是 13 慢动作的 1.5×。","定格标记包括 5 px 蓝色边框和底部中央的暂停图标；图标为 68×40 px 白色圆角框内的两条蓝条，淡入淡出各 0.12 秒。","仅定格时右上角显示“FREEZE”；无交叉淡化复位。"]},"use":{"ja":"決定的な瞬間を強調するとき、止めた画に名前や説明のテロップを載せるとき。","en":"To emphasise a decisive moment, or to pause so a name or caption can be placed over the frame.","zh-Hans":"适合强调决定性瞬间，或暂停以叠加名字和字幕。"},"tags":["freeze frame","still frame","pause","hold","stop motion","highlight"]},{"id":"041","pack":"camera","no":"17","slug":"jump-cut","category":"transitions","width":539,"height":208,"cycle":9.4,"name":{"ja":"ジャンプカット","en":"Jump cut","zh-Hans":"跳切"},"meaning":{"ja":"同じ画角のまま時間を飛ばす","en":"Same framing, skip ahead in time","zh-Hans":"保持构图，跳过一段时间"},"ask":{"ja":"同じ画角のままジャンプカットでつないで、準備の様子をテンポよく見せる。","en":"Use jump cuts from the same framing to move quickly through the preparation.","zh-Hans":"用相同构图的跳切，快速呈现准备过程。"},"summary":{"ja":"カメラの位置も画角も同じまま、人物の位置と時刻だけが飛ぶ。同じ場面の中で時間を省く切り方。","en":"Camera position and framing stay the same while the person's position and the clock jump; time is skipped inside one scene.","zh-Hans":"机位和构图不变，人物位置与时钟跳变，跳过同一场景中的时间。"},"spec":{"ja":["つなぎ方: つなぎの効果なしの直結（0フレーム）。5ショットを0.94秒ずつ（4.7秒÷5）","カメラ: 全ショット同じ位置・同じ画角（高さ1.4m、正面向き）。背景は1pxも動かない","変わるもの: 人物（7m先）の横位置が -2.2m → 1.4m → -0.4m → 2.4m → 0.6m と飛ぶ。2・4番目は両腕を上げた姿勢","各ショットの中では人物は動かない（位置と姿勢の差だけで飛びを見せる）","右上の時計: 10:02 → 10:17 → 10:41 → 11:06 → 11:30。同じ場所で時間が飛んだことを示す","5番目から1番目へも直結で戻る"],"en":["Join: a straight cut with no effect (0 frames); 5 shots of 0.94 s each (4.7 s ÷ 5)","Camera: identical position and framing in every shot (height 1.4 m, facing forward); the background does not move by a pixel","What changes: the person (7 m away) jumps in sideways position, -2.2 m → 1.4 m → -0.4 m → 2.4 m → 0.6 m; in shots 2 and 4 both arms are raised","Within each shot the person is still (the jump is shown only by the difference in position and pose)","Top-right clock: 10:02 → 10:17 → 10:41 → 11:06 → 11:30, showing that time was skipped in the same place","Shot 5 cuts straight back to shot 1"],"zh-Hans":["直接硬切，无特效，0 帧过渡；共 5 个镜头，每个 0.94 秒，即 4.7 秒 ÷ 5。","各镜头机位和构图完全一致，高 1.4 m、正向取景，背景不移动任何像素。","人物距离 7 m，横向位置依次跳为 -2.2 m → 1.4 m → -0.4 m → 2.4 m → 0.6 m；镜头 2 和 4 中双臂举起。","每个镜头内人物静止，只通过位置和姿态差异体现跳变。","右上角时钟依次为 10:02 → 10:17 → 10:41 → 11:06 → 11:30，表明同一地点的时间被跳过。","镜头 5 直接切回镜头 1。"]},"use":{"ja":"話や作業の間を詰めてテンポを上げるとき、時間の経過を短く示すとき。","en":"To tighten pauses in talk or work and raise the pace, or to show time passing quickly.","zh-Hans":"适合压缩讲话或工作中的停顿、提升节奏，或快速表现时间流逝。"},"tags":["jump cut","cut","time skip","same framing","vlog","ellipsis","edit"]},{"id":"042","pack":"camera","no":"18","slug":"match-cut","category":"transitions","width":539,"height":208,"cycle":9.4,"name":{"ja":"マッチカット","en":"Match cut","zh-Hans":"匹配剪辑"},"meaning":{"ja":"形や動きをそろえて場面を変える","en":"Cut on a matching shape or motion","zh-Hans":"利用相似形状或动作连接两个镜头"},"ask":{"ja":"丸いコーヒーカップから、同じ位置にある満月へマッチカット。","en":"Match cut from the round coffee cup to a full moon in the same position.","zh-Hans":"从圆形咖啡杯匹配切到相同位置的满月。"},"summary":{"ja":"投げ上げたボールが、次のカットでは同じ位置・同じ大きさの太陽になる。形をそろえて別の場面へつなぐ。","en":"A thrown ball becomes, in the next shot, a sun at the same position and size; two different scenes are joined on a matching shape.","zh-Hans":"抛出的球在下一镜头变为同位置、同尺寸的太阳，以相似形状连接不同场景。"},"spec":{"ja":["つなぎ方: 2.3秒で直結（0フレーム）。前後で青い円の位置（中心から右120px・上46px）と半径17pxを一致させる","前の絵（0〜2.3秒）: 固定カメラ（高さ1.4m）。人物（左1.2m・奥7m）が0.5秒から両腕を上げてボールを投げる。3次のイーズアウト（cubic-bezier(0.33,1,0.68,1) 相当）","ボール: 人物の頭上（高さ2.3m）から一致点へ移動。半径 5px → 17px、途中は最大30px上へふくらむ弧","後の絵（2.3〜4.7秒）: 別の場所（建物なし・高さ1.2m）。同じ位置の青い円が太陽になり、2.4秒かけて14px下がる","目印: 半径26pxの青い点線の円を、カットの前後0.7秒だけフェードで表示","右上に「SHOT 1」→「SHOT 2」。4.7秒でSHOT 1へ直結で戻る"],"en":["Join: a straight cut at 2.3 s (0 frames); the blue circle has the same position (120 px right, 46 px above centre) and radius 17 px on both sides","Outgoing shot (0–2.3 s): fixed camera (height 1.4 m); a person (1.2 m left, 7 m away) throws a ball from 0.5 s, cubic ease-out (about cubic-bezier(0.33,1,0.68,1))","Ball: travels from above the person's head (2.3 m high) to the match point; radius 5 px → 17 px, on an arc bulging up to 30 px","Incoming shot (2.3–4.7 s): a different place (no buildings, height 1.2 m); the blue circle in the same spot is now the sun and sinks 14 px over 2.4 s","Marker: a blue dashed circle of radius 26 px fades in and out within 0.7 s either side of the cut","Top-right readout shows \"SHOT 1\" → \"SHOT 2\"; at 4.7 s it cuts straight back to SHOT 1"],"zh-Hans":["2.3 秒直接硬切，0 帧过渡；切点两侧蓝色圆的位置均为中心右侧 120 px、上方 46 px，半径 17 px。","前镜头为 0–2.3 秒，机位固定、高 1.4 m；人物位于左侧 1.2 m、距离 7 m，从 0.5 秒开始抛球，采用三次缓出，约 cubic-bezier(0.33,1,0.68,1)。","球从人物头上 2.3 m 高处移到匹配点，半径从 5 px → 17 px，弧线最多向上隆起 30 px。","后镜头为 2.3–4.7 秒，换到无建筑的场地，机位高 1.2 m；同位置的蓝圆成为太阳，在 2.4 秒内下沉 14 px。","切点前后各 0.7 秒内，半径 26 px 的蓝色虚线圆淡入淡出。","右上角显示“SHOT 1”→“SHOT 2”；4.7 秒时直接切回 SHOT 1。"]},"use":{"ja":"時間や場所が大きく離れた2つの場面を、形や動きの共通点で意味を持たせてつなぐとき。","en":"To link two scenes far apart in time or place through a shared shape or motion.","zh-Hans":"适合以共同形状或动作连接时空相距较远的场景。"},"tags":["match cut","graphic match","shape match","cut","transition","edit"]},{"id":"043","pack":"camera","no":"19","slug":"whip-pan","category":"transitions","width":539,"height":208,"cycle":9.4,"name":{"ja":"ホイップパン","en":"Whip pan","zh-Hans":"甩镜转场"},"meaning":{"ja":"素早く振ってブレで次へ","en":"Fast pan blur into the next shot","zh-Hans":"快速摇镜，在运动模糊中切换镜头"},"ask":{"ja":"ホイップパンで右へ素早く振って、次の場所へつなぐ。","en":"Whip pan to the right and land in the next location.","zh-Hans":"向右甩镜，落到下一个地点。"},"summary":{"ja":"カメラを素早く横に振り、流れてぼけた映像の中で次の場面に入れ替える。","en":"The camera swings sideways very fast and the next scene is swapped in during the streaked blur.","zh-Hans":"相机高速横向转动，在条纹状模糊最强时替换场景。"},"spec":{"ja":["つなぎ方: 1.7秒から2.5秒までの0.8秒。前半0.4秒は前の絵を振り出し、後半0.4秒は次の絵が振り込んで止まる","前半: 前の絵のヨーを 0 → +0.45rad（約26°）、2次のイーズインアウト。後半: 次の絵のヨーを -0.45rad → 0、同じイージング","入れ替え: 進み50%の瞬間に直結で差し替える。ぶれが最大なので切れ目は見えない","ぶれ: 前後1.6フレームぶん（30fps）の範囲を9枚描いて平均する","カメラ: 高さ1.4m。振っている間以外は固定。被写体（Aは人物、Bは車と街）は動かない","4.7秒ごとに A→B、B→A を交互に行う（往復で9.4秒）。右上に「A → B」「B → A」"],"en":["Join: 0.8 s, from 1.7 s to 2.5 s; in the first 0.4 s the outgoing shot swings away, in the last 0.4 s the incoming shot swings in and settles","First half: outgoing yaw 0 → +0.45 rad (about 26°), quadratic ease-in-out; second half: incoming yaw -0.45 rad → 0, same easing","Swap: a straight replacement at the 50% point, hidden because the blur is at its strongest","Blur: 9 renders spread over ±1.6 frames (at 30 fps) are averaged","Camera: height 1.4 m, fixed except during the swing; the subjects (a person in A, a car and city in B) do not move","Alternates A→B and B→A every 4.7 s (9.4 s for the round trip); top-right readout shows \"A → B\" / \"B → A\""],"zh-Hans":["转场持续 0.8 秒，从 1.7 秒到 2.5 秒；前 0.4 秒前镜头甩出，后 0.4 秒后镜头甩入并稳定。","前半段偏航从 0 → +0.45 rad，约 26°，采用二次缓入缓出；后半段从 -0.45 rad → 0，使用相同缓动。","在进度 50% 时直接替换，此时模糊最强，掩盖切换。","模糊取9 次渲染平均，采样范围为 ±1.6 帧，按 30 fps 计算。","机位高 1.4 m，除甩镜外固定；主体静止，A 为人物，B 为汽车与城市。","每 4.7 秒交替 A→B 与 B→A，往返 9.4 秒；右上角显示“A → B”或“B → A”。"]},"use":{"ja":"勢いを保ったまま場所や話題を切り替えるとき。","en":"To change location or topic while keeping the energy up.","zh-Hans":"适合保持动势地切换地点或话题。"},"tags":["whip pan","swish pan","motion blur","fast pan","transition","energy"]},{"id":"044","pack":"camera","no":"20","slug":"cross-dissolve","category":"transitions","width":539,"height":208,"cycle":9.4,"name":{"ja":"クロスディゾルブ","en":"Cross dissolve","zh-Hans":"交叉溶解"},"meaning":{"ja":"前後の映像を重ねて溶かす","en":"Blend one shot into the next","zh-Hans":"前后两个镜头逐渐叠化"},"ask":{"ja":"朝の部屋から夜の同じ部屋へ、1秒のクロスディゾルブ。","en":"Cross dissolve from the room in the morning to the same room at night, 1 second.","zh-Hans":"从早晨的房间交叉溶解到夜晚的同一房间，持续一秒。"},"summary":{"ja":"前の絵に次の絵を重ね、不透明度を上げていって入れ替える。途中は2つの絵が透けて重なる。","en":"The next picture is laid over the current one and its opacity rises until it takes over; both show through each other midway.","zh-Hans":"下一画面叠在当前画面上，透明度逐渐增加至完全替代；中途两者同时可见。"},"spec":{"ja":["つなぎ方: 1.5秒から3.0秒までの1.5秒。次の絵の不透明度を 0 → 100%","イージング: 2次のイーズインアウト（cubic-bezier(0.45,0,0.55,1) 相当）。中間の2.25秒で50%","前の絵は不透明のまま下に置き、その上に次の絵を重ねる（前の絵を先に消さない）","カメラ: 両方の絵とも固定（Aは高さ1.4m、Bは高さ1.6m・ピッチ+0.1rad）。被写体も動かない","0〜1.5秒は前の絵だけ、3.0〜4.7秒は次の絵だけを見せる","4.7秒ごとに A→B、B→A を交互に行う（往復で9.4秒）。右上に「A → B」「B → A」"],"en":["Join: 1.5 s, from 1.5 s to 3.0 s; the incoming picture's opacity goes 0 → 100%","Easing: quadratic ease-in-out (about cubic-bezier(0.45,0,0.55,1)); 50% at 2.25 s","The outgoing picture stays fully opaque underneath and the incoming one is drawn on top (the outgoing one is not faded out first)","Camera: fixed in both pictures (A at height 1.4 m; B at height 1.6 m, pitch +0.1 rad); the subjects do not move either","Only the outgoing picture shows for 0–1.5 s, only the incoming one for 3.0–4.7 s","Alternates A→B and B→A every 4.7 s (9.4 s for the round trip); top-right readout shows \"A → B\" / \"B → A\""],"zh-Hans":["转场持续 1.5 秒，从 1.5 秒到 3.0 秒；后画面透明度 0 → 100%。","采用二次缓入缓出，约 cubic-bezier(0.45,0,0.55,1)，于 2.25 秒达到 50%。","前画面在底层保持完全不透明，后画面绘制在上方，不先淡出前画面。","两画面机位均固定，A 高 1.4 m，B 高 1.6 m、俯仰 +0.1 rad；主体也静止。","0–1.5 秒仅显示前画面，3.0–4.7 秒仅显示后画面。","每 4.7 秒交替 A→B 与 B→A，往返 9.4 秒；右上角显示“A → B”或“B → A”。"]},"use":{"ja":"時間の経過や場所の移動を穏やかに伝えるとき、回想へ入るとき。","en":"To convey a gentle passage of time or change of place, or to move into a memory.","zh-Hans":"适合柔和地表现时间或地点变化，也可进入回忆。"},"tags":["cross dissolve","dissolve","crossfade","fade","opacity","blend","transition"]},{"id":"045","pack":"camera","no":"21","slug":"wipe","category":"transitions","width":539,"height":208,"cycle":9.4,"name":{"ja":"ワイプ","en":"Wipe","zh-Hans":"划像转场"},"meaning":{"ja":"境目が横切って画面が入れ替わる","en":"A moving edge replaces the shot","zh-Hans":"移动的边界逐步替换画面"},"ask":{"ja":"左から右へのワイプで、次の場面に入れ替える。","en":"Wipe from left to right into the next scene.","zh-Hans":"用从左向右的划像转场进入下一场景。"},"summary":{"ja":"縦の境界線が左から右へ動き、通過した側から次の絵に置き換わる。","en":"A vertical edge moves from left to right and the next picture replaces the current one behind it.","zh-Hans":"竖直边界从左向右移动，边界后方逐渐替换为下一画面。"},"spec":{"ja":["つなぎ方: 1.7秒から2.8秒までの1.1秒。境界線が左端の外（x=-4px）から右端の外（x=543px）へ移動","イージング: 3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当）","境界線の左側に次の絵、右側に前の絵を表示。どちらの絵も位置は動かさない（押し出しではなく切り抜き）","境界: 幅4pxの青い縦線を、移動中だけ表示","カメラ: 両方の絵とも固定。被写体も動かない","4.7秒ごとに A→B、B→A を交互に行う（往復で9.4秒）。右上に「A → B」「B → A」"],"en":["Join: 1.1 s, from 1.7 s to 2.8 s; the edge travels from just outside the left side (x = -4 px) to just outside the right side (x = 543 px)","Easing: cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1))","The incoming picture shows left of the edge and the outgoing one right of it; neither picture moves (a reveal by clipping, not a push)","Edge: a 4 px blue vertical line, visible only while it is moving","Camera: fixed in both pictures; the subjects do not move either","Alternates A→B and B→A every 4.7 s (9.4 s for the round trip); top-right readout shows \"A → B\" / \"B → A\""],"zh-Hans":["转场持续 1.1 秒，从 1.7 秒到 2.8 秒；边界从左侧外 x = -4 px 移至右侧外 x = 543 px。","采用三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。","边界左侧显示后画面，右侧显示前画面；两幅画面均不移动，通过裁剪揭示，而非推移。","边界为 4 px 宽蓝色竖线，仅在运动中可见。","两画面的机位与主体均固定。","每 4.7 秒交替 A→B 与 B→A，往返 9.4 秒；右上角显示“A → B”或“B → A”。"]},"use":{"ja":"場面や話題の区切りをはっきり見せたいとき、比較の前後を切り替えるとき。","en":"To mark a clear change of scene or topic, or to switch between the two sides of a comparison.","zh-Hans":"适合明确划分场景或话题，也可切换对比的两侧。"},"tags":["wipe","linear wipe","reveal","clip","edge","left to right","transition"]},{"id":"046","pack":"camera","no":"22","slug":"smash-cut","category":"transitions","width":539,"height":208,"cycle":9.4,"name":{"ja":"スマッシュカット","en":"Smash cut","zh-Hans":"冲击硬切"},"meaning":{"ja":"対照的な場面へ前触れなく切り替える","en":"Abrupt cut to a contrasting scene","zh-Hans":"突然切到反差强烈的场景"},"ask":{"ja":"静かな寝室から、騒がしい交差点へスマッシュカット。","en":"Smash cut from the quiet bedroom to a noisy intersection.","zh-Hans":"从安静卧室冲击硬切到嘈杂路口。"},"summary":{"ja":"人物が寝ている静かな場面から、前触れなく激しい場面へ直結で切り替える。音量メーターも一気に上がる。","en":"A quiet scene of a person asleep cuts with no warning straight to an intense one; the volume meter jumps at the same moment.","zh-Hans":"熟睡人物的安静场景毫无预兆地切成强烈画面，音量表同时跃升。"},"spec":{"ja":["つなぎ方: 2.4秒で直結（0フレーム）。つなぎの効果は入れず、前後の落差で見せる","前の絵（0〜2.4秒）: 固定カメラ（高さ1.2m、焦点距離330px）。7m先で横になった人物、「z」の文字が3つ浮かんで消える。音量メーターは8段中ほぼ0〜1段（0.08±0.04）","後の絵（2.4〜4.2秒）: 焦点距離を2.6倍（858px）にして寄り、ロール -0.12rad（約-7°）で傾ける。人物は両腕を上げ、放射状の青い線18本","後の絵の揺れ: ロール ±0.03rad（毎秒約6回）と ヨー ±0.006rad（毎秒約8回）で振る。音量メーターは0.85±0.15でほぼ満杯","戻り: 最後の0.5秒で静かな絵へクロスフェード（2次のイーズインアウト）","右上に「♪ 静か」→「♪ 大音量」"],"en":["Join: a straight cut at 2.4 s (0 frames); no transition effect, the contrast does the work","Outgoing shot (0–2.4 s): fixed camera (height 1.2 m, focal length 330 px); a person lying down 7 m away, three \"z\" letters float up and fade; volume meter at about 0–1 of 8 bars (0.08±0.04)","Incoming shot (2.4–4.2 s): focal length 2.6× (858 px) for a tight framing, rolled -0.12 rad (about -7°); the person has both arms raised, with 18 radial blue lines","Shake in the incoming shot: roll ±0.03 rad (about 6 cycles per second) and yaw ±0.006 rad (about 8 per second); volume meter at 0.85±0.15, nearly full","Return: cross-fade back to the quiet shot over the last 0.5 s (quadratic ease-in-out)","Top-right readout shows \"♪ 静か\" (quiet) → \"♪ 大音量\" (loud)"],"zh-Hans":["2.4 秒直接硬切，0 帧过渡，无转场特效，依靠内容反差。","前镜头为 0–2.4 秒，机位固定、高 1.2 m、焦距 330 px；人物躺在 7 m 外，三个“z”上浮淡出；8 格音量表约亮 0–1 格，数值 0.08±0.04。","后镜头为 2.4–4.2 秒，焦距变为 2.6×，即 858 px，形成紧景别；横滚 -0.12 rad，约 -7°；人物双臂举起，周围18 条蓝色放射线。","后镜头横滚 ±0.03 rad，约每秒6 次，偏航 ±0.006 rad，约每秒8 次；音量表为 0.85±0.15，接近满格。","最后 0.5 秒以二次缓入缓出交叉淡化回安静镜头。","右上角显示“♪ 静か”（安静）→“♪ 大音量”（大音量）。"]},"use":{"ja":"笑いや驚きを作るとき。静と動、予想と現実の落差を一瞬で見せるとき。","en":"For comedy or shock, showing in an instant the gap between calm and chaos or between expectation and reality.","zh-Hans":"适合制造喜剧或震撼，瞬间呈现平静与混乱、预期与现实的反差。"},"tags":["smash cut","hard cut","abrupt","contrast","quiet to loud","comedy","transition"]},{"id":"047","pack":"camera","no":"23","slug":"j-cut","category":"transitions","width":539,"height":208,"cycle":9.4,"name":{"ja":"Jカット","en":"J-cut","zh-Hans":"J 型剪辑（声音先入）"},"meaning":{"ja":"次の場面の音が先に聞こえる","en":"Next scene's audio starts first","zh-Hans":"下一场景的声音先于画面出现"},"ask":{"ja":"Jカットで、次の場面の波の音を先に聞かせてから、海の映像に切り替える。","en":"J-cut: let the sound of waves from the next scene start before cutting to the sea.","zh-Hans":"用 J 型剪辑，让下一场景的海浪声先响起，再切到海面。"},"summary":{"ja":"映像が切り替わる前に、次の場面の音が先に入る。上に映像、下に映像と音のタイムラインを表示する。","en":"The next scene's audio starts before the picture changes; the picture is shown on top with video and audio timelines below.","zh-Hans":"下一场景的声音先进入，随后画面切换；上方是画面，下方是音视频时间线。"},"spec":{"ja":["つなぎ方: 映像は直結。音だけ映像より先に次の場面（B）へ切り替える。ずれはタイムライン全体の20%（0.72秒）","再生ヘッド: 0.4秒から4.0秒まで3.6秒かけて等速で左から右へ。音の切り替えは35%（約1.66秒）、映像の切り替えは55%（約2.38秒）","ずれている区間（35〜55%）は、映像がAのまま音だけBになる。区間を薄い青の帯と青い点線2本で強調","画面構成: 上134pxが映像（固定カメラ・被写体は動かない）、下74pxが「映像」「音」の2段のタイムライン（A＝灰色、B＝薄い青、音の段に波形）","表示: 映像の左下に「映像A / 映像B」、右下に今流れている音（「♪ Aの音」灰色 →「♪ Bの音」青）","戻り: 最後の0.5秒で開始状態へクロスフェード（1周4.7秒）"],"en":["Join: the picture is a straight cut; only the audio switches to the next scene (B) before the picture does. The offset is 20% of the timeline (0.72 s)","Playhead: moves left to right at constant speed over 3.6 s (0.4 s to 4.0 s); audio switches at 35% (about 1.66 s), picture at 55% (about 2.38 s)","In the offset section (35–55%) the picture is still A while the audio is already B; the section is marked with a pale blue band and two blue dashed lines","Layout: the top 134 px is the picture (fixed camera, subjects do not move); the bottom 74 px holds two timeline rows, video and audio (A grey, B pale blue, waveform on the audio row)","Labels: \"映像A / 映像B\" (video A / B) at bottom left of the picture; the audio now playing at bottom right (\"♪ Aの音\" grey → \"♪ Bの音\" blue)","Return: cross-fade back to the start over the last 0.5 s (one pass = 4.7 s)"],"zh-Hans":["画面直接硬切，音频先切到下一场景 B；错位量为时间线的 20%，即 0.72 秒。","播放头在 3.6 秒内从左向右匀速移动，时间为 0.4 秒至 4.0 秒；音频在 35% 处切换，约 1.66 秒，画面在 55% 处切换，约 2.38 秒。","错位区间 35–55% 内，画面仍为 A，声音已为 B；用浅蓝色带与两条蓝色虚线标出。","布局：上方 134 px 为画面，机位和主体固定；下方 74 px 为视频、音频两行时间线，A 灰色、B 浅蓝色，音频行带波形。","画面左下角标签为“映像A / 映像B”，即视频 A / B；右下角标出当前声音，从灰色“♪ Aの音”变为蓝色“♪ Bの音”。","最后 0.5 秒交叉淡化回起点，每轮 4.7 秒。"]},"use":{"ja":"次の場面への期待を先に作りたいとき、会話や場面転換を自然につなぐとき。","en":"To build anticipation for the next scene, or to make a change of scene or speaker feel natural.","zh-Hans":"适合为下一场景铺垫，或让场景与说话人切换更自然。"},"tags":["j-cut","j cut","split edit","audio lead","sound first","audio transition","edit"]},{"id":"048","pack":"camera","no":"24","slug":"l-cut","category":"transitions","width":539,"height":208,"cycle":9.4,"name":{"ja":"Lカット","en":"L-cut","zh-Hans":"L 型剪辑（声音延续）"},"meaning":{"ja":"前の場面の音が後まで残る","en":"Previous scene's audio carries over","zh-Hans":"上一场景的声音延续到下一画面"},"ask":{"ja":"Lカットで、彼女の話し声を残したまま、聞き手の顔に切り替える。","en":"L-cut: keep her voice going while cutting to the listener's face.","zh-Hans":"用 L 型剪辑，切到倾听者面部时继续保留她的声音。"},"summary":{"ja":"映像が次の場面に切り替わったあとも、前の場面の音がしばらく残る。上に映像、下に映像と音のタイムラインを表示する。","en":"The previous scene's audio carries on for a while after the picture has changed; the picture is shown on top with video and audio timelines below.","zh-Hans":"画面切换后，上一场景的声音继续片刻；上方是画面，下方是音视频时间线。"},"spec":{"ja":["つなぎ方: 映像は直結。音だけ映像より後に次の場面（B）へ切り替える。ずれはタイムライン全体の20%（0.72秒）","再生ヘッド: 0.4秒から4.0秒まで3.6秒かけて等速で左から右へ。映像の切り替えは55%（約2.38秒）、音の切り替えは75%（約3.10秒）","ずれている区間（55〜75%）は、映像がBになっても音はAのまま。区間を薄い青の帯と青い点線2本で強調","画面構成: 上134pxが映像（固定カメラ・被写体は動かない）、下74pxが「映像」「音」の2段のタイムライン（A＝灰色、B＝薄い青、音の段に波形）","表示: 映像の左下に「映像A / 映像B」、右下に今流れている音（「♪ Aの音」灰色 →「♪ Bの音」青）","戻り: 最後の0.5秒で開始状態へクロスフェード（1周4.7秒）"],"en":["Join: the picture is a straight cut; only the audio switches to the next scene (B) after the picture does. The offset is 20% of the timeline (0.72 s)","Playhead: moves left to right at constant speed over 3.6 s (0.4 s to 4.0 s); picture switches at 55% (about 2.38 s), audio at 75% (about 3.10 s)","In the offset section (55–75%) the picture is already B while the audio is still A; the section is marked with a pale blue band and two blue dashed lines","Layout: the top 134 px is the picture (fixed camera, subjects do not move); the bottom 74 px holds two timeline rows, video and audio (A grey, B pale blue, waveform on the audio row)","Labels: \"映像A / 映像B\" (video A / B) at bottom left of the picture; the audio now playing at bottom right (\"♪ Aの音\" grey → \"♪ Bの音\" blue)","Return: cross-fade back to the start over the last 0.5 s (one pass = 4.7 s)"],"zh-Hans":["画面直接硬切，音频后切到下一场景 B；错位量为时间线的 20%，即 0.72 秒。","播放头在 3.6 秒内从左向右匀速移动，时间为 0.4 秒至 4.0 秒；画面在 55% 处切换，约 2.38 秒，音频在 75% 处切换，约 3.10 秒。","错位区间 55–75% 内，画面已为 B，声音仍为 A；用浅蓝色带与两条蓝色虚线标出。","布局：上方 134 px 为画面，机位和主体固定；下方 74 px 为视频、音频两行时间线，A 灰色、B 浅蓝色，音频行带波形。","画面左下角标签为“映像A / 映像B”，即视频 A / B；右下角标出当前声音，从灰色“♪ Aの音”变为蓝色“♪ Bの音”。","最后 0.5 秒交叉淡化回起点，每轮 4.7 秒。"]},"use":{"ja":"話している人の声を残したまま、聞き手の反応や関連する映像を見せるとき。","en":"To keep a speaker's voice running while showing the listener's reaction or related footage.","zh-Hans":"适合保留说话人的声音，同时展示倾听者反应或相关画面。"},"tags":["l-cut","l cut","split edit","audio lag","sound carries over","audio transition","edit"]},{"id":"049","pack":"ui","no":"01","slug":"modal-dialog","category":"open-overlay","width":542,"height":191,"cycle":4.5,"name":{"ja":"モーダル","en":"Modal dialog","zh-Hans":"模态对话框"},"meaning":{"ja":"画面を暗くして中央に窓が出る","en":"A window opens in the middle while the page behind dims","zh-Hans":"居中弹出窗口，后方页面变暗"},"ask":{"ja":"削除ボタンを押したらモーダルで確認を出して。背景は4割ほど暗くし、0.3秒で少し拡大しながらフェードイン。","en":"When the delete button is pressed, show a confirmation in a modal dialog. Dim the page about 40% and fade it in over 0.3 s with a slight scale-up.","zh-Hans":"点击删除按钮时显示模态确认框，背景约变暗 40%，用 0.3 秒淡入并略微放大。"},"summary":{"ja":"「開く」ボタンを押すと画面全体が暗くなり、中央に小窓が少し拡大しながら出る。×を押すと閉じる。","en":"Clicking \"Open\" dims the whole page and a small window scales up slightly into the centre; clicking × closes it.","zh-Hans":"点击“打开”后页面变暗，小窗口略微放大并出现在中央，点击 × 关闭。"},"spec":{"ja":["4.5秒周期・カード542×191。カーソルが0.95秒に左下の「開く」ボタン（120×36）へ着き、1.0秒にクリック","開く量 a: 1.0〜1.32秒に easeOutCubic で 0→1。全面に rgba(18,20,28) の幕を不透明度 0.42×a で敷く","窓: 白 280×140・角丸12を (271, 97) 中心に置き、影 blur 24・下へ8・濃さ0.25。拡大率 0.9+0.1×a、不透明度 a","窓の中: 見出しの太線・本文2行・右下に青いボタン 88×30・右上に×","閉じる: カーソルが3.0秒に×へ移り3.3秒にクリック。a に (1 − easeInOutCubic(3.3〜3.58秒)) を掛けて消す"],"en":["4.5 s cycle on a 542×191 card. The cursor reaches the \"Open\" button (120×36, lower left) at 0.95 s and clicks at 1.0 s.","Open amount a: 0→1 over 1.0–1.32 s with easeOutCubic. A full-card scrim rgba(18,20,28) at opacity 0.42·a.","Window: white 280×140, radius 12, centred at (271, 97), shadow blur 24, offset y 8, alpha 0.25. Scale 0.9 + 0.1·a, opacity a.","Inside: a bold title bar, two text lines, a blue 88×30 button at lower right and × at top right.","Close: the cursor moves to × by 3.0 s and clicks at 3.3 s; a is multiplied by (1 − easeInOutCubic over 3.3–3.58 s)."],"zh-Hans":["542×191 卡片，周期 4.5 秒。光标于 0.95 秒到达左下角 120×36 的“打开”按钮，1.0 秒点击。","展开量 a 在 1.0–1.32 秒由 0→1，使用 easeOutCubic；全卡片遮罩颜色 rgba(18,20,28)，透明度 0.42·a。","窗口为白色 280×140，圆角 12，中心 (271, 97)，阴影模糊 24、y 偏移 8、透明度 0.25；缩放 0.9 + 0.1·a，透明度 a。","内部有粗体标题、两行文字、右下角 88×30 蓝色按钮和右上角 ×。","关闭：光标于 3.0 秒前移至 ×，3.3 秒点击；a 乘以 (1 − easeInOutCubic)，作用于 3.3–3.58 秒。"]},"use":{"ja":"確認・入力など、今の作業を止めて1つのことに集中させたいとき。","en":"Use it when the user must stop and deal with one thing, such as a confirmation or a short form.","zh-Hans":"适合需要用户暂时专注处理的确认操作或短表单。"},"tags":["modal","modal-dialog","dialog","popup","overlay","backdrop","lightbox","confirm"],"aliases":{"zh-Hans":["弹窗","对话框"]}},{"id":"050","pack":"ui","no":"02","slug":"drawer","category":"open-overlay","width":542,"height":191,"cycle":4.5,"name":{"ja":"ドロワー","en":"Drawer (Off-canvas)","zh-Hans":"侧边抽屉"},"meaning":{"ja":"横からメニューが引き出される","en":"A menu panel slides in from the side of the screen","zh-Hans":"菜单面板从屏幕侧边滑入"},"ask":{"ja":"メニューボタンを押したら左からドロワーを出して。幅は画面の4割、0.4秒で引き出し、背景は少し暗く。","en":"Open a drawer from the left when the menu button is pressed: 40% of the screen wide, sliding in over 0.4 s, with the page slightly dimmed.","zh-Hans":"点击菜单按钮后从左侧打开抽屉，宽度为屏幕的 40%，滑入耗时 0.4 秒，背景略微变暗。"},"summary":{"ja":"「メニュー」を押すと左から縦長のパネルが引き出され、外側を押すと戻る。","en":"Clicking \"Menu\" slides a tall panel in from the left; clicking outside slides it back.","zh-Hans":"点击“菜单”后高面板从左侧滑入，点击外部后滑回。"},"spec":{"ja":["4.5秒周期・カード542×191。カーソルが左上の「メニュー」ボタン（110×34）を1.0秒にクリック","開く量 a: 1.0〜1.38秒に easeOutCubic で 0→1。全面に rgba(18,20,28) の幕を不透明度 0.36×a","パネル: 白・幅210・カードの高さいっぱい。x = −210 + 210×a で左端から出る。影 blur 22・濃さ0.25","パネルの中: 上に丸アイコン（半径14）と名前、下に32px間隔で4行のメニュー。1行目は薄い青の帯で選択中","閉じる: カーソルがパネルの外 (420, 120) を3.3秒にクリック。a に (1 − easeInOutCubic(3.3〜3.65秒)) を掛けて左へ戻す"],"en":["4.5 s cycle on a 542×191 card. The cursor clicks the \"Menu\" button (110×34, top left) at 1.0 s.","Open amount a: 0→1 over 1.0–1.38 s with easeOutCubic. Full-card scrim rgba(18,20,28) at opacity 0.36·a.","Panel: white, 210 wide, full card height, x = −210 + 210·a so it slides in from the left edge. Shadow blur 22, alpha 0.25.","Inside: an avatar (radius 14) and name at the top, then four menu rows 32 px apart; the first row is selected with a light-blue band.","Close: the cursor clicks outside at (420, 120) at 3.3 s; a is multiplied by (1 − easeInOutCubic over 3.3–3.65 s) and the panel slides back."],"zh-Hans":["542×191 卡片，周期 4.5 秒。光标于 1.0 秒点击左上角 110×34 的“菜单”按钮。","展开量 a 在 1.0–1.38 秒由 0→1，使用 easeOutCubic；全卡片遮罩 rgba(18,20,28)，透明度 0.36·a。","面板为白色、宽 210、高度铺满卡片；x = −210 + 210·a，从左边缘滑入；阴影模糊 22、透明度 0.25。","顶部放半径 14 的头像和名字，下方四行菜单间隔 32 px，第一行以浅蓝色带标记选中。","关闭：3.3 秒光标点击外部 (420, 120)；a 乘以 (1 − easeInOutCubic)，作用于 3.3–3.65 秒，面板滑回。"]},"use":{"ja":"スマホの全体メニューや、絞り込み条件など、場所を取る操作を横に隠しておきたいとき。","en":"Use it to keep navigation or filters off screen until needed, especially on mobile.","zh-Hans":"适合在需要时才展示导航或筛选，尤其适用于移动端。"},"tags":["drawer","off-canvas","offcanvas","side-menu","navigation-drawer","sheet","sidebar","slide-in"],"aliases":{"zh-Hans":["抽屉菜单","侧栏"]}},{"id":"051","pack":"ui","no":"03","slug":"bottom-sheet","category":"open-overlay","width":542,"height":191,"cycle":4.5,"name":{"ja":"ボトムシート","en":"Bottom sheet","zh-Hans":"底部弹出面板"},"meaning":{"ja":"下からパネルがせり上がる","en":"A panel slides up from the bottom of the screen","zh-Hans":"面板从屏幕底部向上滑出"},"ask":{"ja":"「詳細を見る」を押したらボトムシートで詳細を出して。高さは画面の4割、0.4秒でせり上げ、下へ引くと閉じる。","en":"Show the details in a bottom sheet when \"View details\" is tapped: 40% of the screen tall, rising over 0.4 s, closing when dragged down.","zh-Hans":"点击“查看详情”后弹出底部面板，高度为屏幕的 40%，用 0.4 秒升起，下拖关闭。"},"summary":{"ja":"指で「詳細を見る」を押すと下からパネルがせり上がり、上端のつまみを下へ引くと閉じる。","en":"A finger taps \"View details\" and a panel rises from the bottom; dragging its handle down closes it.","zh-Hans":"手指轻点“查看详情”，面板从底部升起；向下拖动把手即可关闭。"},"spec":{"ja":["4.5秒周期・カード542×191。指（半径17の半透明の丸＋白い縁）が下中央の「詳細を見る」（170×36の青い角丸）を1.0秒に押す","開く量: 1.05〜1.45秒に easeOutCubic で 0→1。全面に rgba(18,20,28) の幕を不透明度 0.36×a","シート: 白・高さ136・上の角丸18。上端 y = 191 − 136×a。影 blur 22・上へ4。上端中央につまみ 52×6","シートの中: 見出しの太線と、アイコン（26×26）付きの2行","閉じる: 指が2.75秒につまみ (271, 68) に乗り、3.0〜3.6秒に下へ引く。a に (1 − easeInOutCubic(3.0〜3.6秒)) を掛け、シートが指と一緒に下へ消える"],"en":["4.5 s cycle on a 542×191 card. A finger (semi-transparent circle, radius 17, white rim) taps the \"View details\" pill (170×36, bottom centre) at 1.0 s.","Open amount: 0→1 over 1.05–1.45 s with easeOutCubic. Full-card scrim rgba(18,20,28) at opacity 0.36·a.","Sheet: white, 136 tall, top corners radius 18, top edge at y = 191 − 136·a. Shadow blur 22, offset y −4. A 52×6 grab handle at top centre.","Inside: a bold title bar and two rows with 26×26 icons.","Close: the finger lands on the handle (271, 68) at 2.75 s and drags down over 3.0–3.6 s; a is multiplied by (1 − easeInOutCubic over 3.0–3.6 s), so the sheet follows the finger off the bottom."],"zh-Hans":["542×191 卡片，周期 4.5 秒。手指用半径 17、白边的半透明圆表示，于 1.0 秒点击底部居中的 170×36“查看详情”胶囊按钮。","展开量在 1.05–1.45 秒由 0→1，使用 easeOutCubic；全卡片遮罩 rgba(18,20,28)，透明度 0.36·a。","白色面板高 136，上角半径 18，顶边 y = 191 − 136·a；阴影模糊 22、y 偏移 −4；顶部中央把手为 52×6。","内部有粗体标题和两行内容，配 26×26 图标。","关闭：手指于 2.75 秒落在把手 (271, 68)，在 3.0–3.6 秒下拖；a 乘以3.0–3.6 秒内的 (1 − easeInOutCubic)，面板随手指滑出底部。"]},"use":{"ja":"スマホで、今の画面を残したまま詳細や選択肢を出したいとき。","en":"Use it on mobile to show details or choices while keeping the current screen in view.","zh-Hans":"适合移动端在保留当前页面背景时展示详情或选项。"},"tags":["bottom-sheet","sheet","modal-sheet","mobile","slide-up","drag-to-dismiss","panel"],"aliases":{"zh-Hans":["底部抽屉","底部弹层"]}},{"id":"052","pack":"ui","no":"04","slug":"accordion","category":"open-overlay","width":542,"height":191,"cycle":4.5,"name":{"ja":"アコーディオン","en":"Accordion","zh-Hans":"折叠面板"},"meaning":{"ja":"押すと中身が開閉する","en":"Click a heading to show or hide its content","zh-Hans":"点击标题展开或收起对应内容"},"ask":{"ja":"よくある質問をアコーディオンにして。押した項目だけ0.35秒で開き、矢印を180度回して。","en":"Make the FAQ an accordion: the clicked item opens over 0.35 s and its arrow turns 180°.","zh-Hans":"FAQ 用折叠面板，点击项在 0.35 秒内展开，箭头转动 180°。"},"summary":{"ja":"3段の見出しのうち1段目を押すと下に本文が開き、下の段が押し下げられる。もう一度押すと閉じる。","en":"Clicking the first of three headings opens its content and pushes the rows below down; clicking again closes it.","zh-Hans":"点击三个标题中的第一项，内容展开并推开下方行，再次点击则收起。"},"spec":{"ja":["4.5秒周期・カード542×191。3段の見出し（幅494・高さ34・角丸8・間隔6）。右端に下向きの矢印","カーソルが0.95秒に1段目に着き、1.0秒と3.3秒にクリック","開く量 ex: 1.0〜1.35秒に easeInOutCubic で 0→1、3.3〜3.62秒に同じく 1→0","1段目の高さを 34 → 92（+58×ex）に伸ばし、下の段をその分押し下げる。本文2行は枠の中に切り抜いて不透明度 ex で出す","開いている間、矢印は 180°×ex 回り、枠は薄い青・見出しは青になる"],"en":["4.5 s cycle on a 542×191 card. Three headings (494 wide, 34 tall, radius 8, gap 6) with a down chevron at the right.","The cursor reaches the first heading at 0.95 s and clicks at 1.0 s and 3.3 s.","Open amount ex: 0→1 over 1.0–1.35 s with easeInOutCubic, then 1→0 over 3.3–3.62 s.","The first row grows from 34 to 92 tall (+58·ex) and pushes the rows below down; its two content lines are clipped to the row and fade in with opacity ex.","While open, the chevron rotates 180°·ex, the border turns light blue and the heading blue."],"zh-Hans":["542×191 卡片，周期 4.5 秒。三个标题宽 494、高 34、圆角 8、间隔 6，右侧有向下箭头。","光标于 0.95 秒到达首个标题，在 1.0 秒和 3.3 秒点击。","展开量 ex 在 1.0–1.35 秒由 0→1，再于 3.3–3.62 秒由 1→0，使用 easeInOutCubic。","首行高度由 34 增至 92，增量 +58·ex，并推开下方各行；两行内容裁剪在行内，以透明度 ex 淡入。","展开时箭头旋转 180°·ex，边框变浅蓝，标题变蓝。"]},"use":{"ja":"FAQや詳細な説明など、見出しだけ並べて中身は必要な人にだけ見せたいとき。","en":"Use it for FAQs or long details where people scan the headings and open only what they need.","zh-Hans":"适合常见问题或较长详情，便于先浏览标题再按需展开。"},"tags":["accordion","collapsible","expand","collapse","disclosure","faq","details"],"aliases":{"zh-Hans":["手风琴","折叠"]}},{"id":"053","pack":"ui","no":"05","slug":"dropdown-menu","category":"open-overlay","width":542,"height":191,"cycle":4.5,"name":{"ja":"ドロップダウン","en":"Dropdown (select)","zh-Hans":"下拉选择器"},"meaning":{"ja":"押すと選択肢が下に広がる","en":"Click a field to drop a list of options below it","zh-Hans":"点击字段后在下方展开选项"},"ask":{"ja":"都道府県の入力欄をドロップダウンにして。押したら0.25秒で選択肢を下に開き、選んだら閉じて値を入れて。","en":"Make the prefecture field a dropdown: open the options below it in 0.25 s and close it with the value filled in once one is picked.","zh-Hans":"地区字段用下拉选择器，0.25 秒展开下方选项，选中后关闭并填入值。"},"summary":{"ja":"入力欄を押すと下に4つの選択肢が開き、「名古屋」を選ぶと閉じて欄に入る。","en":"Clicking the field opens four options below it; picking \"Nagoya\" closes the list and fills the field.","zh-Hans":"点击字段展开四个选项，选择“名古屋”后列表关闭并填入字段。"},"spec":{"ja":["4.5秒周期・カード542×191。入力欄 260×38（角丸8）に「選択してください」と右端の矢印。カーソルが1.0秒にクリック","開く量: 1.0〜1.25秒に easeOutCubic で 0→1。一覧（白 260×112・影 blur 18）が不透明度とともに上から6px下りて出る。矢印は180°回り、枠は青2px","一覧は26px間隔の4行（東京・大阪・名古屋・福岡）。カーソルが下りるにつれ1.55秒から大阪、1.95秒から名古屋の行を薄い青で強調","2.3秒に名古屋をクリック: 一覧は2.3〜2.45秒に (1 − easeInOutCubic) で閉じ、プレースホルダーは2.2〜2.3秒に消え、「名古屋」が2.32〜2.42秒に出る","戻し: 名古屋は3.9〜4.08秒に消え、プレースホルダーが4.1〜4.3秒に戻る（文字を重ねない）"],"en":["4.5 s cycle on a 542×191 card. A 260×38 field (radius 8) shows a placeholder and a chevron; the cursor clicks it at 1.0 s.","Open amount: 0→1 over 1.0–1.25 s with easeOutCubic. The list (white 260×112, shadow blur 18) fades in while dropping 6 px. The chevron turns 180° and the field border becomes 2 px blue.","Four options 26 px apart (Tokyo, Osaka, Nagoya, Fukuoka in Japanese). As the cursor moves down, Osaka is highlighted light blue from 1.55 s and Nagoya from 1.95 s.","Click on Nagoya at 2.3 s: the list closes over 2.3–2.45 s (1 − easeInOutCubic); the placeholder fades out over 2.2–2.3 s and \"Nagoya\" fades in over 2.32–2.42 s.","Reset: Nagoya fades out over 3.9–4.08 s, then the placeholder returns over 4.1–4.3 s, so the two texts never overlap."],"zh-Hans":["542×191 卡片，周期 4.5 秒。字段为 260×38、圆角 8，显示占位文字和箭头；光标于 1.0 秒点击。","展开量在 1.0–1.25 秒由 0→1，使用 easeOutCubic；白色 260×112 列表、阴影模糊 18，淡入并下移 6 px；箭头转 180°，字段边框变为 2 px 蓝线。","四个选项间隔 26 px，原演示为日文东京、大阪、名古屋、福冈；光标下移时，大阪从 1.55 秒、名古屋从 1.95 秒起显示浅蓝高亮。","2.3 秒点击名古屋：列表在 2.3–2.45 秒用 (1 − easeInOutCubic) 关闭；占位文字于 2.2–2.3 秒淡出，“名古屋”于 2.32–2.42 秒淡入。","复位：名古屋于 3.9–4.08 秒淡出，占位文字于 4.1–4.3 秒恢复，二者不重叠。"]},"use":{"ja":"フォームで、決まった候補の中から1つを選ばせたいとき。","en":"Use it in a form when people pick one value from a fixed list.","zh-Hans":"适合表单中从固定列表选择单个值。"},"tags":["dropdown","dropdown-menu","select","picker","combobox","options","form"]},{"id":"054","pack":"ui","no":"06","slug":"tooltip","category":"open-overlay","width":542,"height":191,"cycle":4.5,"name":{"ja":"ツールチップ","en":"Tooltip","zh-Hans":"悬浮提示"},"meaning":{"ja":"乗せると小さな説明が出る","en":"Hover over something to show a short label","zh-Hans":"悬停时显示简短说明"},"ask":{"ja":"「?」アイコンにツールチップを付けて。カーソルを乗せて0.2秒で上に説明を出し、離れたら消して。","en":"Add a tooltip to the \"?\" icon: show the note above it 0.2 s after hover, and hide it when the cursor leaves.","zh-Hans":"给“?”图标加悬浮提示，悬停 0.2 秒后在上方显示，移开即隐藏。"},"summary":{"ja":"カーソルを「?」に乗せると、上に黒い吹き出しで短い説明が出る。離れると消える。","en":"Hovering over a \"?\" icon shows a short note in a dark bubble above it; it disappears when the cursor leaves.","zh-Hans":"悬停“?”图标时，上方出现深色说明气泡，移开后消失。"},"spec":{"ja":["4.5秒周期・カード542×191。見出しの横に「?」（半径13の青い丸枠）を (196, 121) に置く","カーソルは押さずに乗せるだけ: 1.05秒に「?」へ着き、3.15秒まで留まり、4.1秒にカードの外へ出る","出る量 a: 1.15〜1.35秒に easeOutCubic で 0→1。不透明度 a で、6px下から所定の位置へ上がる","吹き出し: #26282c の 184×36・角丸8、上端 y 64。下に幅16・高さ8の三角で「?」を指す。白い15pxの文字「小さな説明が出る」","消える: 3.25〜3.45秒に直線で 1→0"],"en":["4.5 s cycle on a 542×191 card. A \"?\" icon (blue ring, radius 13) at (196, 121) next to a label.","The cursor only hovers, no click: it arrives on \"?\" at 1.05 s, stays until 3.15 s and leaves the card by 4.1 s.","Show amount a: 0→1 over 1.15–1.35 s with easeOutCubic; opacity a, rising 6 px into place.","Bubble: #26282c, 184×36, radius 8, top at y 64, with a 16-wide, 8-tall triangle pointing down at the icon; white 15 px text.","Hide: linear 1→0 over 3.25–3.45 s."],"zh-Hans":["542×191 卡片，周期 4.5 秒。“?”为半径 13 的蓝色圆环，位于 (196, 121)，旁边有标签。","光标只悬停、不点击；1.05 秒到达“?”，停到 3.15 秒，4.1 秒前离开卡片。","显现量 a 在 1.15–1.35 秒由 0→1，使用 easeOutCubic；透明度 a，上移 6 px 到位。","气泡色 #26282c，尺寸 184×36、圆角 8，顶部 y 64；下方有宽 16、高 8 的三角指向图标；文字为白色 15 px。","隐藏：3.25–3.45 秒线性从 1→0。"]},"use":{"ja":"アイコンや略語など、見ればすぐ分かる補足を1行だけ添えたいとき。","en":"Use it to add a one-line hint to an icon or abbreviation without taking space on the page.","zh-Hans":"适合为图标或缩写补充一句提示，不占用页面固定空间。"},"tags":["tooltip","hint","hover","help","info","title"]},{"id":"055","pack":"ui","no":"07","slug":"popover","category":"open-overlay","width":542,"height":191,"cycle":4.5,"name":{"ja":"ポップオーバー","en":"Popover","zh-Hans":"气泡弹出框"},"meaning":{"ja":"押すと吹き出しの小窓が出る","en":"Click a button to open a small panel pointing at it","zh-Hans":"点击按钮打开指向该按钮的小面板"},"ask":{"ja":"「詳細」ボタンにポップオーバーを付けて。押したら右に吹き出しの小窓を0.3秒で出し、OKで閉じて。","en":"Attach a popover to the \"Details\" button: clicking opens a small panel to its right over 0.3 s, and OK closes it.","zh-Hans":"给“详情”按钮加气泡弹出框，点击后用 0.3 秒在右侧打开，点“确定”关闭。"},"summary":{"ja":"「詳細」を押すと右に、三角でボタンを指す白い小窓が出る。小窓のOKを押すと閉じる。","en":"Clicking \"Details\" opens a small white panel to its right with a pointer at the button; clicking OK inside closes it.","zh-Hans":"点击“详情”后右侧出现白色小面板，尖角指向按钮，点击内部“确定”关闭。"},"spec":{"ja":["4.5秒周期・カード542×191。青い枠のボタン「詳細」108×36 を (24, 112) に置く。カーソルが1.0秒にクリック","出る量 a: 1.0〜1.28秒に easeOutCubic で 0→1。不透明度 a で、6px右から所定の位置へ寄る","小窓: 白 300×120・角丸10を (156, 62) に置き、1pxの枠線、影 blur 22・下へ6。左辺の y 122〜138 に幅10の三角でボタンを指す","中身: 見出しの太線・本文2行・下に枠のボタン 70×26 と青いOK 72×26","閉じる: カーソルが3.0秒にOK (402, 157) へ移り3.3秒にクリック。a に (1 − easeInOutCubic(3.3〜3.5秒)) を掛ける"],"en":["4.5 s cycle on a 542×191 card. An outlined blue \"Details\" button (108×36) at (24, 112); the cursor clicks it at 1.0 s.","Show amount a: 0→1 over 1.0–1.28 s with easeOutCubic; opacity a, sliding 6 px in from the right.","Panel: white 300×120, radius 10, at (156, 62), 1 px border, shadow blur 22, offset y 6. A 10-wide triangle on its left edge (y 122–138) points at the button.","Inside: a bold title bar, two text lines, an outlined 70×26 button and a blue 72×26 OK button.","Close: the cursor moves to OK (402, 157) by 3.0 s and clicks at 3.3 s; a is multiplied by (1 − easeInOutCubic over 3.3–3.5 s)."],"zh-Hans":["542×191 卡片，周期 4.5 秒。蓝色描边“详情”按钮为 108×36，位于 (24, 112)，光标于 1.0 秒点击。","显现量 a 在 1.0–1.28 秒由 0→1，使用 easeOutCubic；透明度 a，从右侧滑入 6 px。","面板为白色 300×120、圆角 10，位于 (156, 62)，边框 1 px，阴影模糊 22、y 偏移 6；左边缘 y 122–138 处有宽 10 的三角指向按钮。","内部有粗体标题、两行文字、70×26 描边按钮和 72×26 蓝色“确定”按钮。","关闭：光标在 3.0 秒前移至“确定”(402, 157)，3.3 秒点击；a 乘以 3.3–3.5 秒内的 (1 − easeInOutCubic)。"]},"use":{"ja":"ボタンの近くで、短い設定や確認をその場で済ませたいとき。","en":"Use it for a short setting or confirmation that belongs right next to the button that opened it.","zh-Hans":"适合紧邻触发按钮的简短设置或确认操作。"},"tags":["popover","popup","callout","bubble","flyout","overlay"]},{"id":"056","pack":"ui","no":"08","slug":"toast","category":"open-overlay","width":542,"height":191,"cycle":4.5,"name":{"ja":"トースト","en":"Toast notification","zh-Hans":"轻提示通知"},"meaning":{"ja":"隅に通知が出て自動で消える","en":"A short message appears in a corner and goes away on its own","zh-Hans":"角落短暂出现消息，随后自动消失"},"ask":{"ja":"保存したら右下にトーストで「保存しました」と出して。0.35秒で右から出し、2秒後に自動で消して。","en":"After saving, show \"Saved\" as a toast at the bottom right: slide it in from the right in 0.35 s and dismiss it automatically after 2 s.","zh-Hans":"保存后在右下角显示“已保存”轻提示，用 0.35 秒从右侧滑入，两秒后自动关闭。"},"summary":{"ja":"「保存」を押すと右下に黒い通知が右から滑り込み、残り時間の線が縮みきると右へ消える。","en":"Clicking \"Save\" slides a dark notice into the bottom-right corner; when its time bar runs out it slides away.","zh-Hans":"点击“保存”后，深色通知滑入右下角；倒计时条走完后滑出。"},"spec":{"ja":["4.5秒周期・カード542×191。左下の青い「保存」ボタン（110×36）をカーソルが1.0秒にクリックし、左下へ去る","通知: #26282c の 214×52・角丸10。右端から18px・下端から16pxの位置に、1.05〜1.4秒に easeOutCubic で右から240px滑り込む","中身: 青い丸に白いチェックと、白い15pxの「保存しました」","下端に残り時間の線（幅194→0・高さ3）を1.4〜3.2秒に直線で縮める","消える: 3.2〜3.55秒に easeInOutCubic で右へ240px滑り出る"],"en":["4.5 s cycle on a 542×191 card. The cursor clicks the blue \"Save\" button (110×36, bottom left) at 1.0 s and leaves to the bottom left.","Toast: #26282c, 214×52, radius 10, 18 px from the right and 16 px from the bottom; slides in 240 px from the right over 1.05–1.4 s with easeOutCubic.","Inside: a white check in a blue circle and white 15 px text \"Saved\".","A time-left line along the bottom (3 px tall) shrinks linearly from 194 px to 0 over 1.4–3.2 s.","Exit: slides 240 px out to the right over 3.2–3.55 s with easeInOutCubic."],"zh-Hans":["542×191 卡片，周期 4.5 秒。光标于 1.0 秒点击左下角 110×36 蓝色“保存”按钮，再移向左下方离开。","通知色 #26282c，尺寸 214×52、圆角 10，距右侧 18 px、底部 16 px；1.05–1.4 秒以 easeOutCubic 从右侧 240 px 外滑入。","内部为蓝圆中的白色对勾和 15 px 白色“已保存”文字。","底部倒计时线高 3 px，在 1.4–3.2 秒从 194 px 线性缩至 0。","3.2–3.55 秒用 easeInOutCubic 向右滑出 240 px。"]},"use":{"ja":"保存・送信などの結果を、作業を止めずに短く知らせたいとき。","en":"Use it to confirm a result such as a save or send without interrupting the user.","zh-Hans":"适合不打断用户地确认保存、发送等操作结果。"},"tags":["toast","snackbar","notification","alert","message","auto-dismiss"],"aliases":{"zh-Hans":["消息提示","轻提示"]}},{"id":"057","pack":"ui","no":"09","slug":"tabs","category":"select-switch","width":542,"height":191,"cycle":4.5,"name":{"ja":"タブ","en":"Tabs","zh-Hans":"标签页"},"meaning":{"ja":"見出しを押して中身を切り替える","en":"Click a label to switch which panel is shown","zh-Hans":"点击标签切换显示的内容面板"},"ask":{"ja":"料金ページの上にタブを3つ置いて。押したら下線を0.25秒で滑らせ、中身を0.2秒のクロスフェードで切り替えて。","en":"Put three tabs at the top of the pricing page. On click, slide the underline over 0.25 s and cross-fade the content in 0.2 s.","zh-Hans":"价格页顶部放三个标签页，点击后下划线用 0.25 秒滑动，内容用 0.2 秒交叉淡化。"},"summary":{"ja":"「概要・料金・レビュー」のタブを順に押すと、青い下線が滑って移り、下の中身が入れ替わる。","en":"Clicking the tabs \"Overview, Pricing, Reviews\" in turn slides a blue underline across and swaps the content below.","zh-Hans":"依次点击“概览、价格、评价”，蓝色下划线移动，下方内容切换。"},"spec":{"ja":["4.5秒周期・カード542×191。タブ3つ（x 24・114・204、幅 70・70・100）。下に2pxの区切り線（y 50）と、4pxの青い下線","カーソルが1.0秒に2つ目、2.2秒に3つ目、3.4秒に1つ目をクリック","下線: 位置と幅を各クリックから0.25秒、easeInOutCubic で次のタブへ移す（3つ目から1つ目へは中央を通って戻る）","文字: 選択中は青・太字、それ以外は灰色。切り替わりは1.1・2.3・3.5秒","中身: 前のパネルが0.2秒で直線的に消え、0.1秒後に次のパネルが0.2秒で出る（出るとき8px下から上がる）"],"en":["4.5 s cycle on a 542×191 card. Three tabs at x 24, 114, 204, widths 70, 70, 100; a 2 px divider at y 50 and a 4 px blue underline.","The cursor clicks the second tab at 1.0 s, the third at 2.2 s and the first at 3.4 s.","Underline: position and width move to the new tab over 0.25 s from each click with easeInOutCubic (from the third back to the first it passes through the middle).","Labels: selected is blue and bold, others grey; the switch happens at 1.1, 2.3 and 3.5 s.","Content: the old panel fades out linearly in 0.2 s; 0.1 s later the new one fades in over 0.2 s while rising 8 px."],"zh-Hans":["542×191 卡片，周期 4.5 秒。三个标签 x 为 24, 114, 204，宽为 70, 70, 100；y 50 处有 2 px 分隔线和 4 px 蓝色下划线。","光标于 1.0 秒点击第二项、2.2 秒第三项、3.4 秒第一项。","每次点击后，下划线的位置与宽度在 0.25 秒内以 easeInOutCubic 移至新标签；从第三项返回第一项时经过中间。","选中标签为蓝色粗体，其余灰色；状态在 1.1, 2.3, 3.5 秒切换。","旧内容在 0.2 秒内线性淡出；0.1 秒后新内容开始用 0.2 秒淡入，同时上移 8 px。"]},"use":{"ja":"同じ場所で、並んだ種類の情報を切り替えて見せたいとき。","en":"Use it to show several related views in the same space and let people switch between them.","zh-Hans":"适合在同一空间切换多个相关视图。"},"tags":["tabs","tab-bar","tabbed","navigation","switch-view","underline"]},{"id":"058","pack":"ui","no":"10","slug":"carousel","category":"select-switch","width":542,"height":191,"cycle":4.5,"name":{"ja":"カルーセル","en":"Carousel","zh-Hans":"轮播"},"meaning":{"ja":"横に送って順番に見せる","en":"Slides that move sideways to show one item at a time","zh-Hans":"横向滑动，每次展示一个项目"},"ask":{"ja":"トップの画像をカルーセルにして。右矢印で1枚ずつ0.4秒で送り、下に今の位置の点を出して。","en":"Turn the top images into a carousel: the right arrow moves one slide in 0.4 s, with position dots below.","zh-Hans":"顶部图片做成轮播，点击右箭头用 0.4 秒切一张，下方显示位置指示点。"},"summary":{"ja":"右の矢印を押すたびに、横に並んだ3種類の絵が1枚ずつ左へ送られ、下の点が移る。","en":"Each click on the right arrow slides a row of three different images one step to the left, and the dot below moves.","zh-Hans":"每次点击右箭头，三张不同图片组成的行左移一格，下方指示点同步切换。"},"spec":{"ja":["4.5秒周期・カード542×191。スライド 330×138・角丸8を中央に置き、間隔18。両隣が端から少し見える","左右に白い丸ボタン（半径18・影 blur 10）と矢印。下に点3つ（今の位置は青の 16×8、他は 8×8）","カーソルが右の矢印 (514, 88) を1.0・2.1・3.2秒にクリック","各クリックで、0.4秒かけて easeInOutCubic で列を左へ348px（1枚＋間隔）送る","絵は3種類（山の風景・丸3つ・棒グラフ）の繰り返しなので、3回送ると最初の絵に戻る"],"en":["4.5 s cycle on a 542×191 card. Slides 330×138, radius 8, centred with an 18 px gap; the neighbours peek in at the edges.","White round buttons (radius 18, shadow blur 10) with chevrons at left and right; three dots below (current one blue 16×8, others 8×8).","The cursor clicks the right arrow (514, 88) at 1.0, 2.1 and 3.2 s.","Each click moves the row 348 px left (one slide plus gap) over 0.4 s with easeInOutCubic.","The three pictures (landscape, three circles, bar chart) repeat, so after three moves the first is back."],"zh-Hans":["542×191 卡片，周期 4.5 秒。图片为 330×138、圆角 8，居中，间隔 18 px，两侧露出相邻图片的一部分。","左右为半径 18、阴影模糊 10 的白色圆形箭头按钮；下方三个点，当前为蓝色 16×8，其余 8×8。","光标在 1.0, 2.1, 3.2 秒点击右箭头 (514, 88)。","每次点击后，整行在 0.4 秒内以 easeInOutCubic 左移 348 px，即一张图片加间隔。","三张图片为风景、三个圆、柱状图，循环排列，移动三次后回到首张。"]},"use":{"ja":"限られた場所で、画像やおすすめを何枚も順に見せたいとき。","en":"Use it to show several images or featured items in limited space, one at a time.","zh-Hans":"适合在有限空间内逐个展示多张图片或推荐内容。"},"tags":["carousel","slider","slideshow","gallery","swipe","paging-dots"]},{"id":"059","pack":"ui","no":"11","slug":"toggle-switch","category":"select-switch","width":542,"height":191,"cycle":4.5,"name":{"ja":"トグルスイッチ","en":"Toggle switch","zh-Hans":"开关"},"meaning":{"ja":"オン・オフを切り替える","en":"Flip a setting on or off","zh-Hans":"在开启和关闭之间切换设置"},"ask":{"ja":"通知設定の各行にトグルスイッチを置いて。押したら0.2秒でつまみを滑らせ、オンは青にして。","en":"Put a toggle switch on each notification setting: the knob slides in 0.2 s and the track turns blue when on.","zh-Hans":"每个通知设置加开关，滑块用 0.2 秒移动，开启时轨道变蓝。"},"summary":{"ja":"設定の3行のうち上の2つのスイッチを順にオンにし、その後オフに戻す。","en":"The switches on the first two of three setting rows are turned on in turn, then off again.","zh-Hans":"三个设置行中，前两个开关依次打开，再依次关闭。"},"spec":{"ja":["4.5秒周期・カード542×191。設定の行3つ（60px間隔・区切り線あり）。右端 x 450 に 64×34・角丸17 の溝と、白いつまみ（半径13・影）","カーソルのクリック: 1行目オン1.0秒、2行目オン1.8秒、1行目オフ3.0秒、2行目オフ3.6秒。3行目はオフのまま","1回の切り替えは0.2秒・easeOutCubic。つまみを30px（17→47）滑らせる","溝の色は灰色 #d9d7d5 から青 #1f5ae8 へ、切り替えの進み具合で重ねて変える"],"en":["4.5 s cycle on a 542×191 card. Three setting rows 60 px apart with dividers. At x 450 a 64×34 track (radius 17) and a white knob (radius 13, shadow).","Clicks: row 1 on at 1.0 s, row 2 on at 1.8 s, row 1 off at 3.0 s, row 2 off at 3.6 s. Row 3 stays off.","Each switch takes 0.2 s with easeOutCubic; the knob slides 30 px (17 → 47).","The track colour blends from grey #d9d7d5 to blue #1f5ae8 with the switch progress."],"zh-Hans":["542×191 卡片，周期 4.5 秒。三个设置行间隔 60 px，带分隔线；x 450 处放 64×34、圆角半径 17 的轨道和半径 13、带阴影的白色滑块。","点击：第 1 行在 1.0 秒开，第 2 行在 1.8 秒开，第 1 行在 3.0 秒关，第 2 行在 3.6 秒关；第 3 行保持关闭。","每次切换持续 0.2 秒，使用 easeOutCubic；滑块移动 30 px，从 17 → 47。","轨道随切换进度从灰色 #d9d7d5 混合到蓝色 #1f5ae8。"]},"use":{"ja":"設定画面で、すぐ反映されるオン・オフを並べたいとき。","en":"Use it for settings that take effect immediately and have only two states.","zh-Hans":"适合只有两种状态且即时生效的设置。"},"tags":["toggle","switch","toggle-switch","on-off","boolean","settings"]},{"id":"060","pack":"ui","no":"12","slug":"segmented-control","category":"select-switch","width":542,"height":191,"cycle":4.5,"name":{"ja":"セグメントコントロール","en":"Segmented control","zh-Hans":"分段控制器"},"meaning":{"ja":"並んだボタンで表示を切り替える","en":"A row of joined buttons that switches the view","zh-Hans":"一组相连按钮用于切换视图"},"ask":{"ja":"グラフの上に「日・週・月」のセグメントコントロールを置いて。押したら選択の背景を0.25秒で滑らせ、グラフも同時に変えて。","en":"Put a Day / Week / Month segmented control above the chart: the selected background slides over 0.25 s and the chart changes with it.","zh-Hans":"图表上方加日、周、月分段控制器，选中背景用 0.25 秒滑动，图表同步变化。"},"summary":{"ja":"「日・週・月」を押すと青い選択部分が滑って移り、下の棒グラフの高さが変わる。","en":"Clicking Day, Week or Month slides a blue highlight across and the bar chart below changes height.","zh-Hans":"点击日、周、月后，蓝色选中背景滑动，下方柱状图高度随之改变。"},"spec":{"ja":["4.5秒周期・カード542×191。灰色の台 300×40・角丸10 を (121, 12) に置き、3等分（各100）に「日・週・月」","選択部分: 青の 92×32・角丸8（影 blur 6）。選ばれた文字は白","カーソルが1.0秒に「週」、2.1秒に「月」、3.3秒に「日」をクリック。選択部分は各0.25秒、easeInOutCubic で滑る","下の棒グラフ: 幅34・58px間隔の7本（6本目だけ青）。高さを3組のデータ（例 30〜85 / 40〜100 / 60〜115）の間で、選択部分と同時に easeInOutCubic で変える"],"en":["4.5 s cycle on a 542×191 card. A grey 300×40 base (radius 10) at (121, 12), split into three 100-wide segments: Day, Week, Month (in Japanese).","Selection: blue 92×32, radius 8, shadow blur 6; the selected label is white.","The cursor clicks Week at 1.0 s, Month at 2.1 s and Day at 3.3 s; the selection slides over 0.25 s each with easeInOutCubic.","Chart below: seven bars 34 wide, 58 px apart (the sixth is blue). Heights move between three data sets (about 30–85, 40–100, 60–115) together with the selection, eased the same way."],"zh-Hans":["542×191 卡片，周期 4.5 秒。灰色底座为 300×40、圆角 10，位于 (121, 12)，分为三个宽 100 的区段，原演示为日文日、周、月。","选中背景为蓝色 92×32、圆角 8、阴影模糊 6，选中文字为白色。","光标在 1.0 秒点击周、2.1 秒点击月、3.3 秒点击日；每次以 easeInOutCubic 在 0.25 秒内移动选中背景。","下方七根柱条宽 34、间距 58 px，第六根为蓝色；高度随选择在约 30–85, 40–100, 60–115 三组数据间变化，使用相同缓动。"]},"use":{"ja":"同じデータの見え方を、2〜4通りから切り替えたいとき。","en":"Use it to switch between two to four views of the same content, such as day, week and month.","zh-Hans":"适合在同一内容的两到四种视图之间切换，如日、周、月。"},"tags":["segmented-control","segmented-button","button-group","toggle-group","switcher","view-switch"]},{"id":"061","pack":"ui","no":"13","slug":"filter-chips","category":"select-switch","width":542,"height":191,"cycle":4.5,"name":{"ja":"チップ","en":"Filter chips","zh-Hans":"筛选标签"},"meaning":{"ja":"押して絞り込み条件を付け外し","en":"Small pills you click to add or remove a filter","zh-Hans":"点击胶囊标签添加或移除筛选条件"},"ask":{"ja":"一覧の上に絞り込みのチップを並べて。押したらチェックを付けて青くし、0.15秒で一覧を絞り込んで。","en":"Add filter chips above the list: a clicked chip gets a check mark and turns blue, and the list filters within 0.15 s.","zh-Hans":"列表上方加筛选标签，选中后变蓝并出现对勾，列表在 0.15 秒内筛选完成。"},"summary":{"ja":"「新着」「無料」のチップを押すとチェックが付いて青くなり、条件に合わないカードが薄くなる。","en":"Clicking the \"New\" and \"Free\" chips adds a check mark and turns them blue, and cards that do not match fade out.","zh-Hans":"点击“最新”和“免费”后标签变蓝并加对勾，不匹配的卡片淡出。"},"spec":{"ja":["4.5秒周期・カード542×191。チップ4つ「すべて・新着・人気・無料」: 高さ34・角丸17、幅は文字幅+32、10px間隔で左から並べる","カーソルのクリック: 新着オン0.95秒、無料オン1.75秒、新着オフ3.0秒、無料オフ3.6秒","1回の切り替えは0.15秒・easeOutCubic。チップが18px広がって左にチェックが出て、地は薄い青・枠と文字は青","下の一覧: カード4枚（242×54、2列2段）。条件に合わないカードは不透明度を 1 → 0.12 に下げる"],"en":["4.5 s cycle on a 542×191 card. Four chips (\"All, New, Popular, Free\" in Japanese): 34 tall, radius 17, width = text + 32, 10 px apart from the left.","Clicks: New on at 0.95 s, Free on at 1.75 s, New off at 3.0 s, Free off at 3.6 s.","Each change takes 0.15 s with easeOutCubic: the chip widens 18 px to make room for a check mark; fill light blue, border and text blue.","List below: four cards (242×54, two columns, two rows); cards that do not match drop from opacity 1 to 0.12."],"zh-Hans":["542×191 卡片，周期 4.5 秒。四个标签原文为日文的全部、最新、热门、免费；高 34、圆角半径 17，宽度 = 文字宽 + 32，从左向右间隔 10 px。","点击：0.95 秒选中最新，1.75 秒选中免费，3.0 秒取消最新，3.6 秒取消免费。","每次以 easeOutCubic 在 0.15 秒内变化；标签加宽 18 px 以放置对勾，填充浅蓝色，文字与边框为蓝色。","下方四张卡片为 242×54，两行两列；不匹配卡片的透明度从 1 降至 0.12。"]},"use":{"ja":"一覧や検索結果を、条件を重ねて手早く絞り込ませたいとき。","en":"Use it to let people narrow a list or search results by combining a few quick filters.","zh-Hans":"适合组合多个快捷条件，缩小列表或搜索结果范围。"},"tags":["chips","filter-chips","tags","filter","facets","pills"]},{"id":"062","pack":"ui","no":"14","slug":"range-slider","category":"select-switch","width":542,"height":191,"cycle":4.5,"name":{"ja":"レンジスライダー","en":"Range slider","zh-Hans":"区间滑块"},"meaning":{"ja":"つまみ2つで範囲を選ぶ","en":"Two handles on one track pick a minimum and a maximum","zh-Hans":"在同一轨道上用两个滑块选择上下限"},"ask":{"ja":"価格の絞り込みをレンジスライダーにして。つまみは2つ、動かしている間は値を吹き出しで出して。","en":"Make the price filter a range slider with two handles, showing each value in a bubble while it is dragged.","zh-Hans":"价格筛选使用双滑块区间选择器，拖动时在气泡中显示数值。"},"summary":{"ja":"価格のスライダーで、左のつまみを右へ、右のつまみを左へ動かして範囲を狭め、元に戻す。","en":"On a price slider, the left handle is dragged right and the right handle left to narrow the range, then both go back.","zh-Hans":"价格滑轨左滑块向右、右滑块向左拖动以收窄区间，随后都返回原位。"},"spec":{"ja":["4.5秒周期・カード542×191。溝: x 54〜488・高さ8・y 120。つまみ2つの間を青で塗る。範囲は ¥0〜¥10,000","つまみ: 白・半径13・青い3pxの縁。ドラッグ中は半径15になり、半径24の薄い青の円が付く","下限: 1.0〜1.6秒に 0.1→0.3（¥1,000→¥3,000）、3.55〜3.9秒に戻す。上限: 2.1〜2.6秒に 1.0→0.8（¥10,000→¥8,000）、2.95〜3.3秒に戻す。どれも easeInOutCubic","各つまみの上に値の吹き出し（高さ28・ドラッグ中は青地に白文字）。右上に「¥1,000 〜 ¥10,000」の形で範囲を青で出し、100円単位で更新","カーソルがつまみに乗って一緒に動く（押す時刻 1.0・2.1・2.95・3.55秒）"],"en":["4.5 s cycle on a 542×191 card. Track: x 54–488, 8 tall, at y 120; the part between the two handles is blue. Range ¥0–¥10,000.","Handles: white, radius 13, 3 px blue rim; while dragged, radius 15 with a light-blue halo of radius 24.","Low handle: 0.1 → 0.3 (¥1,000 → ¥3,000) over 1.0–1.6 s, back over 3.55–3.9 s. High handle: 1.0 → 0.8 (¥10,000 → ¥8,000) over 2.1–2.6 s, back over 2.95–3.3 s. All easeInOutCubic.","A value bubble (28 tall) above each handle, blue with white text while dragged. The range \"¥1,000 – ¥10,000\" is shown in blue at top right, updated in ¥100 steps.","The cursor sits on the handle it drags (presses at 1.0, 2.1, 2.95 and 3.55 s)."],"zh-Hans":["542×191 卡片，周期 4.5 秒。轨道 x 54–488，高 8，y 120；两滑块之间为蓝色，范围 ¥0–¥10,000。","滑块为半径 13 的白圆，蓝边宽 3 px；拖动时半径变为 15，外加半径 24 的浅蓝光晕。","下限在 1.0–1.6 秒从 0.1 → 0.3，即 ¥1,000 → ¥3,000，3.55–3.9 秒返回；上限在 2.1–2.6 秒从 1.0 → 0.8，即 ¥10,000 → ¥8,000，2.95–3.3 秒返回；均用 easeInOutCubic。","各滑块上方有高 28 的数值气泡，拖动时蓝底白字；右上角蓝色显示“¥1,000 – ¥10,000”，按 ¥100 步进更新。","光标始终位于被拖动滑块上，在 1.0, 2.1, 2.95, 3.55 秒按下。"]},"use":{"ja":"価格・日付・数量などを、下限と上限の範囲で絞り込ませたいとき。","en":"Use it to filter by a range, such as price, date or size, with a minimum and a maximum.","zh-Hans":"适合筛选价格、日期、尺寸等带最小值和最大值的范围。"},"tags":["range-slider","slider","dual-thumb","min-max","price-filter","range"]},{"id":"063","pack":"ui","no":"15","slug":"stepper","category":"select-switch","width":542,"height":191,"cycle":4.5,"name":{"ja":"ステッパー","en":"Stepper (+/−)","zh-Hans":"数字步进器"},"meaning":{"ja":"＋/−ボタンで数を増減する","en":"Plus and minus buttons that change a number by one","zh-Hans":"通过加减按钮逐个调整数值"},"ask":{"ja":"数量の欄をステッパーにして。＋と−で1ずつ増減し、押すたびに数字を0.25秒で少し弾ませて。","en":"Make the quantity field a stepper: + and − change it by one, and the number pops slightly for 0.25 s on each press.","zh-Hans":"数量字段用数字步进器，+ 和 − 每次改变一，按下后数字用 0.25 秒轻微弹动。"},"summary":{"ja":"＋を3回押して数が1から4に増え、−を3回押して1に戻る。押すたびに数字が少し弾む。","en":"Pressing + three times raises the number from 1 to 4, and pressing − three times brings it back to 1; the number pops on each press.","zh-Hans":"连续点击三次 +，数字从 1 增至 4，再点击三次 − 回到 1，每次都轻微弹动。"},"spec":{"ja":["4.5秒周期・カード542×191。枠 200×60・角丸12 を (171, 52) に置く。左60pxに「−」、右60pxに「＋」（青）、中央に30pxの太い数字","カーソルのクリック: ＋を0.9・1.35・1.8秒（1→4）、−を2.8・3.25・3.7秒（4→1）","押した側の区画を、押す0.05秒前から0.15秒後まで薄い青にする","数字: 押すたびに拡大率 1.18 → 1 を0.25秒で直線的に戻し、その間は青"],"en":["4.5 s cycle on a 542×191 card. A 200×60 box (radius 12) at (171, 52): \"−\" in the left 60 px, a blue \"+\" in the right 60 px, and a bold 30 px number in the middle.","Clicks: + at 0.9, 1.35, 1.8 s (1 → 4), − at 2.8, 3.25, 3.7 s (4 → 1).","The pressed segment is tinted light blue from 0.05 s before to 0.15 s after each click.","Number: on each press its scale goes linearly from 1.18 back to 1 over 0.25 s, and it is blue meanwhile."],"zh-Hans":["542×191 卡片，周期 4.5 秒。框为 200×60、圆角 12，位于 (171, 52)；左侧 60 px 为“−”，右侧 60 px 为蓝色“+”，中间为 30 px 粗体数字。","点击 + 的时间为 0.9, 1.35, 1.8 秒，数值 1 → 4；点击 − 的时间为 2.8, 3.25, 3.7 秒，数值 4 → 1。","每次点击前 0.05 秒至点击后 0.15 秒，对应区段填充浅蓝色。","每次按下后，数字缩放在 0.25 秒内由 1.18 线性回到 1，期间保持蓝色。"]},"use":{"ja":"カートの数量や人数など、小さな数を1つずつ変えさせたいとき。","en":"Use it for small whole numbers changed one at a time, such as quantity or number of guests.","zh-Hans":"适合逐个调整商品数量、人数等较小整数。"},"tags":["stepper","quantity","number-input","increment","decrement","plus-minus","spin-button"]},{"id":"064","pack":"ui","no":"16","slug":"pagination","category":"select-switch","width":542,"height":191,"cycle":4.5,"name":{"ja":"ページネーション","en":"Pagination","zh-Hans":"分页器"},"meaning":{"ja":"番号でページを送る","en":"Numbered buttons that move between pages","zh-Hans":"使用带页码的按钮切换页面"},"ask":{"ja":"検索結果の下にページネーションを付けて。今のページは青い丸にし、押したら0.2秒で丸を移して一覧を入れ替えて。","en":"Add pagination under the search results: the current page is a blue circle that moves in 0.2 s on click, and the list is replaced.","zh-Hans":"搜索结果下方加分页器，当前页用蓝圆标记，点击后用 0.2 秒移动并替换列表。"},"summary":{"ja":"下の番号で2、3と押すと青い丸が移り、上の一覧が切り替わる。最後に1へ戻る。","en":"Clicking 2 and then 3 in the page numbers moves the blue circle and swaps the list above; finally it goes back to 1.","zh-Hans":"依次点击页码 2、3，蓝圆移动、上方列表切换，最后回到 1。"},"spec":{"ja":["4.5秒周期・カード542×191。「‹ 1 2 3 4 5 ›」を直径36・間隔8で中央に並べる（y 160）。今のページに青い丸（半径18）、文字は白","カーソルが1.0秒に2、2.1秒に3、3.3秒に1をクリック","青い丸は各0.2秒、easeInOutCubic で1ページ44pxずつ移る（3から1へは一度に88px）","上の一覧（3行）は1.05・2.15・3.35秒の前後0.2秒で不透明度を 1→0→1 と下げて、中身を入れ替える"],"en":["4.5 s cycle on a 542×191 card. \"‹ 1 2 3 4 5 ›\" centred, each 36 in diameter with 8 px gaps, at y 160. A blue circle (radius 18) marks the current page, with white text.","The cursor clicks 2 at 1.0 s, 3 at 2.1 s and 1 at 3.3 s.","The blue circle moves 44 px per page over 0.2 s each with easeInOutCubic (88 px at once from 3 back to 1).","The three-row list above dips in opacity 1 → 0 → 1 within 0.2 s either side of 1.05, 2.15 and 3.35 s, and its content changes at the dip."],"zh-Hans":["542×191 卡片，周期 4.5 秒。“‹ 1 2 3 4 5 ›”居中，按钮直径 36、间隔 8 px，y 160；当前页为半径 18 的蓝圆，白色文字。","光标在 1.0 秒点击 2，2.1 秒点击 3，3.3 秒点击 1。","每跨一页移动 44 px，持续 0.2 秒，使用 easeInOutCubic；从 3 回 1 一次移动 88 px。","上方三行列表的透明度在 1.05, 2.15, 3.35 秒前后各 0.2 秒内按 1 → 0 → 1 变化，在最低点替换内容。"]},"use":{"ja":"検索結果や記事一覧など、長い一覧をページに分けて見せたいとき。","en":"Use it to split a long list, such as search results or articles, into numbered pages.","zh-Hans":"适合把较长的搜索结果或文章列表分成带编号的页面。"},"tags":["pagination","pager","page-numbers","paging","next-prev","navigation"]},{"id":"065","pack":"ui","no":"17","slug":"hamburger-menu","category":"navigate-status","width":542,"height":191,"cycle":4.5,"name":{"ja":"ハンバーガーメニュー","en":"Hamburger menu","zh-Hans":"汉堡菜单"},"meaning":{"ja":"三本線を押すとメニューが開く","en":"A three-line icon that opens the menu","zh-Hans":"点击三横线图标打开菜单"},"ask":{"ja":"スマホのヘッダー右にハンバーガーメニューを置いて。押したら三本線を0.3秒で×に変え、メニューを上から下ろして。","en":"Put a hamburger menu at the right of the mobile header: on tap, morph the three lines into × in 0.3 s and drop the menu down from the top.","zh-Hans":"移动端页头右侧放汉堡菜单，点击后用 0.3 秒把三条线变成 ×，菜单从顶部下拉。"},"summary":{"ja":"ヘッダー右の三本線を押すと×に変わり、ヘッダーの下からメニューが下りてくる。もう一度押すと閉じる。","en":"Clicking the three-line icon at the header's right turns it into ×, and a menu drops down from under the header; clicking again closes it.","zh-Hans":"点击页头右侧三横线，图标变为 ×，菜单从页头下方滑出，再点关闭。"},"spec":{"ja":["4.5秒周期・カード542×191。高さ44の白いヘッダー。右の (500, 22) に三本線（長さ24・太さ3・8px間隔）","カーソルが1.0秒と3.3秒にクリック。開く量 a: 1.0〜1.3秒に easeInOutCubic で 0→1、3.3〜3.6秒に 1→0","三本線→×: 上下の線を中央へ8px寄せつつ ±45°回し、中の線を不透明度 1−a で消す。開いている間は青","メニュー: 白・高さ140。上端 y = 44 − 140 + 140×a でヘッダーの下から下りる（ヘッダーの下だけ見せる）。影 blur 16。中に4項目、1つ目は青"],"en":["4.5 s cycle on a 542×191 card. A white 44-tall header; three lines (24 long, 3 thick, 8 px apart) at (500, 22) on the right.","The cursor clicks at 1.0 s and 3.3 s. Open amount a: 0→1 over 1.0–1.3 s, 1→0 over 3.3–3.6 s, easeInOutCubic.","Lines to ×: the top and bottom lines move 8 px to the centre and rotate ±45°; the middle line fades with opacity 1 − a. Blue while open.","Menu: white, 140 tall, top at y = 44 − 140 + 140·a so it drops from under the header (clipped below the header), shadow blur 16, four items, the first blue."],"zh-Hans":["542×191 卡片，周期 4.5 秒。白色页头高 44；右侧 (500, 22) 处有三条长 24、粗 3、间隔 8 px 的线。","光标在 1.0 秒和 3.3 秒点击；展开量 a 在 1.0–1.3 秒由 0→1，在 3.3–3.6 秒由 1→0，均用 easeInOutCubic。","线条变为 ×：上下两条向中心移 8 px 并旋转 ±45°；中线透明度为 1 − a，打开时图标为蓝色。","白色菜单高 140，顶部 y = 44 − 140 + 140·a，从页头下方滑出，仅在页头以下区域可见；阴影模糊 16，四个菜单项，首项为蓝色。"]},"use":{"ja":"スマホなど幅の狭い画面で、全体メニューを1つのボタンにしまいたいとき。","en":"Use it on narrow screens to tuck the main navigation behind one button.","zh-Hans":"适合窄屏中将主导航收纳到单个按钮后方。"},"tags":["hamburger-menu","hamburger","menu-icon","nav-toggle","mobile-menu","menu"]},{"id":"066","pack":"ui","no":"18","slug":"breadcrumbs","category":"navigate-status","width":542,"height":191,"cycle":4.5,"name":{"ja":"パンくずリスト","en":"Breadcrumbs","zh-Hans":"面包屑导航"},"meaning":{"ja":"今いる場所を階層で示す","en":"A trail of links showing where the page sits in the site","zh-Hans":"用链接路径标明当前页面在站点中的位置"},"ask":{"ja":"記事ページの上にパンくずリストを付けて。「ホーム › 講座 › Web制作」の形で、今のページは太字でリンクなし。","en":"Add breadcrumbs above the article: \"Home › Courses › Web design\", with the current page in bold and not linked.","zh-Hans":"文章上方加“首页 › 课程 › 网页设计”面包屑，当前页加粗且不可点击。"},"summary":{"ja":"パンくずの「講座」を押すと一つ上の一覧ページに戻り、一覧のカードを押すと元の詳細ページへ進む。","en":"Clicking \"Courses\" in the breadcrumbs goes up to the list page; clicking a card there returns to the detail page.","zh-Hans":"点击面包屑中的“课程”返回列表，再点击卡片回到详情。"},"spec":{"ja":["4.5秒周期・カード542×191。上に「ホーム › 講座 › Web制作」（17px）。リンクは青、今のページは黒の太字。下に区切り線（y 46）","カーソルが「講座」に乗ると0.9〜1.2秒に下線、1.0秒にクリック","上へ戻る量 up: 1.0〜1.25秒に easeInOutCubic で 0→1。「› Web制作」が消え、「講座」が今のページ（黒の太字）になる","中身: 詳細ページ（見出しと本文）から、3枚のカード（158×118・山の絵付き）の一覧へ不透明度で切り替える","戻る: カーソルが1枚目のカードに乗り（2.45〜2.8秒に青い枠）、2.7秒にクリック。2.7〜2.95秒に元の詳細ページへ"],"en":["4.5 s cycle on a 542×191 card. At the top \"Home › Courses › Web design\" (in Japanese, 17 px): links blue, current page black and bold; a divider at y 46.","The cursor hovers \"Courses\" (underline 0.9–1.2 s) and clicks at 1.0 s.","Up amount: 0→1 over 1.0–1.25 s with easeInOutCubic. \"› Web design\" fades out and \"Courses\" becomes the current page (black, bold).","Content cross-fades from a detail page (title and text) to a list of three cards (158×118, with a landscape picture).","Back: the cursor moves onto the first card (blue outline 2.45–2.8 s) and clicks at 2.7 s; the detail page returns over 2.7–2.95 s."],"zh-Hans":["542×191 卡片，周期 4.5 秒。顶部为日文“首页 › 课程 › 网页设计”，字号 17 px；链接蓝色，当前页黑色加粗，y 46 处有分隔线。","光标悬停“课程”时在 0.9–1.2 秒显示下划线，1.0 秒点击。","返回上级的进度在 1.0–1.25 秒以 easeInOutCubic 从 0→1；“› 网页设计”淡出，“课程”变为黑色粗体当前页。","内容由标题加正文的详情交叉淡化为三张 158×118、带风景图的列表卡片。","返回详情：光标移到首张卡片，2.45–2.8 秒显示蓝色轮廓，2.7 秒点击，2.7–2.95 秒恢复详情。"]},"use":{"ja":"階層の深いサイトで、今いる場所と上の階層への戻り道を示したいとき。","en":"Use it on sites with deep hierarchies to show where the page is and give a way back up.","zh-Hans":"适合层级较深的网站，帮助定位并返回上级页面。"},"tags":["breadcrumbs","breadcrumb","trail","hierarchy","navigation","path"]},{"id":"067","pack":"ui","no":"19","slug":"mega-menu","category":"navigate-status","width":542,"height":191,"cycle":4.5,"name":{"ja":"メガメニュー","en":"Mega menu","zh-Hans":"大型下拉菜单"},"meaning":{"ja":"大きな一覧メニューが広がる","en":"A wide panel of grouped links that opens from the main menu","zh-Hans":"从主导航展开含分组链接的宽面板"},"ask":{"ja":"ヘッダーの「製品」にメガメニューを付けて。乗せたら0.25秒で全幅のパネルを下ろし、3列のリンクと画像を並べて。","en":"Give \"Products\" in the header a mega menu: on hover, drop a full-width panel in 0.25 s with three columns of links and an image.","zh-Hans":"页头“产品”用大型下拉菜单，悬停后用 0.25 秒展开全宽面板，放三列链接和一张图。"},"summary":{"ja":"ヘッダーの「製品」にカーソルを乗せると、全幅のパネルが下りて3列のリンクと画像が並ぶ。離れると閉じる。","en":"Hovering over \"Products\" in the header drops a full-width panel with three columns of links and an image; it closes when the cursor leaves.","zh-Hans":"悬停页头“产品”，全宽面板下拉，内含三列链接和图片；移开后关闭。"},"spec":{"ja":["4.5秒周期・カード542×191。高さ42のヘッダーに「製品・料金・サポート」（各16px、下向き矢印付き）","カーソルは押さずに乗せるだけ: 1.0秒に「製品」へ着く。開く量 a: 1.05〜1.3秒に easeOutCubic で 0→1。「製品」は青・下線付きになる","パネル: 白・全幅・高さ146。ヘッダーの下から12px上から下りつつ不透明度 a で出る。影 blur 18・下へ8","中身: 130px間隔の3列（青い見出しと3つのリンク）と、右に絵 104×112。カーソルが下りて1.75〜2.9秒に2列目の2つ目のリンクを薄い青で強調","閉じる: カーソルが2.9秒からパネルの外へ出て、3.15〜3.4秒に (1 − easeInOutCubic) で消える"],"en":["4.5 s cycle on a 542×191 card. A 42-tall header with \"Products, Pricing, Support\" (in Japanese, 16 px, each with a down chevron).","The cursor only hovers: it reaches \"Products\" at 1.0 s. Open amount a: 0→1 over 1.05–1.3 s with easeOutCubic; \"Products\" turns blue with an underline.","Panel: white, full width, 146 tall, dropping 12 px into place under the header while fading in with a. Shadow blur 18, offset y 8.","Inside: three columns 130 px apart (a blue heading and three links each) and a 104×112 picture at the right. The cursor moves down and the second link of the second column is highlighted light blue from 1.75 to 2.9 s.","Close: the cursor leaves the panel from 2.9 s; it fades over 3.15–3.4 s (1 − easeInOutCubic)."],"zh-Hans":["542×191 卡片，周期 4.5 秒。页头高 42，使用 16 px 日文产品、价格、支持，各有下箭头。","光标仅悬停，1.0 秒到达“产品”；展开量 a 在 1.05–1.3 秒以 easeOutCubic 从 0→1，“产品”变蓝并显示下划线。","白色面板全宽、高 146，在页头下方向下移动 12 px 到位，同时以 a 淡入；阴影模糊 18、y 偏移 8。","内部三列间隔 130 px，每列含蓝色标题和三个链接，右侧为 104×112 图片；光标向下移动，第二列第二链接在 1.75 至 2.9 秒高亮浅蓝。","光标从 2.9 秒起离开，面板在 3.15–3.4 秒用 (1 − easeInOutCubic) 淡出。"]},"use":{"ja":"製品やサービスが多いサイトで、全体を一度に見渡せるメニューにしたいとき。","en":"Use it on sites with many products or sections so visitors can see the whole range at once.","zh-Hans":"适合产品或栏目较多的网站，让访客一次看到整体范围。"},"tags":["mega-menu","megamenu","dropdown-navigation","navigation","header-menu","multi-column"]},{"id":"068","pack":"ui","no":"20","slug":"step-indicator","category":"navigate-status","width":542,"height":191,"cycle":4.5,"name":{"ja":"ステップインジケーター","en":"Step indicator","zh-Hans":"步骤指示器"},"meaning":{"ja":"手続きの何番目かを示す","en":"Shows which step of a process you are on","zh-Hans":"显示流程当前进行到哪一步"},"ask":{"ja":"申し込みフォームの上にステップインジケーターを付けて。入力・確認・支払い・完了の4段階で、済んだ段階はチェックにして。","en":"Add a step indicator above the sign-up form with four steps: Details, Review, Payment, Done; completed steps show a check.","zh-Hans":"注册表单上方放四步指示器：资料、确认、支付、完成，已完成步骤显示对勾。"},"summary":{"ja":"「次へ」を押すたびに、4段階の丸が順にチェックに変わり、青い線が次の段階へ伸びる。","en":"Each click on \"Next\" turns the next of four step circles into a check and extends the blue line to the following step.","zh-Hans":"每点一次“下一步”，当前步骤圆圈变对勾，蓝线延长到后续步骤。"},"spec":{"ja":["4.5秒周期・カード542×191。4つの段階「入力・確認・支払い・完了」を x 80・207・334・461、y 35 に置く。丸は半径17、間を灰色の4pxの線でつなぐ","カーソルが右下の「次へ」（110×38）を0.9・1.7・2.5秒にクリック","押すたびに、今の段階は青い丸に白いチェック、次の段階は青い丸に白い番号になる。未到達は白い丸に灰色の縁と番号","青い線は1回につき127px、0.3秒の easeInOutCubic で伸びる。3回目で4つすべてがチェックになる","戻し: 3.75〜4.05秒に段階の表示ごと消し、4.05〜4.3秒に1段目の状態で出し直す"],"en":["4.5 s cycle on a 542×191 card. Four steps (\"Details, Review, Payment, Done\" in Japanese) at x 80, 207, 334, 461, y 35; circles of radius 17 joined by a 4 px grey line.","The cursor clicks \"Next\" (110×38, bottom right) at 0.9, 1.7 and 2.5 s.","On each click the current step becomes a blue circle with a white check and the next becomes the current one (blue circle, white number). Steps not reached are white with a grey rim.","The blue line grows 127 px per click over 0.3 s with easeInOutCubic; after the third click all four are checked.","Reset: the indicator fades out over 3.75–4.05 s and fades back in at step 1 over 4.05–4.3 s."],"zh-Hans":["542×191 卡片，周期 4.5 秒。四步原文为日文资料、确认、支付、完成，x 为 80, 207, 334, 461，y 35；圆半径 17，以 4 px 灰线连接。","光标在 0.9, 1.7, 2.5 秒点击右下角 110×38 的“下一步”。","每次点击后当前步变为蓝圆白色对勾，下一步变为蓝圆白色数字；未到达步骤为白底灰边。","每次点击蓝线用 easeInOutCubic 在 0.3 秒内增长 127 px；第三次点击后四步都显示对勾。","复位：指示器在 3.75–4.05 秒淡出，4.05–4.3 秒从第 1 步状态淡入。"]},"use":{"ja":"申し込みや購入など、何段階かに分かれた手続きで今の位置を示したいとき。","en":"Use it in multi-step flows such as sign-up or checkout to show progress and what is left.","zh-Hans":"适合注册、结算等多步骤流程，展示当前进度与剩余步骤。"},"tags":["step-indicator","stepper","steps","progress-steps","wizard","multi-step","checkout"]},{"id":"069","pack":"ui","no":"21","slug":"skeleton-screen","category":"navigate-status","width":542,"height":191,"cycle":4.5,"name":{"ja":"スケルトン","en":"Skeleton screen","zh-Hans":"骨架屏"},"meaning":{"ja":"読み込み中に灰色の枠を出す","en":"Grey shapes stand in for content while it loads","zh-Hans":"加载时用灰色形状占据内容位置"},"ask":{"ja":"一覧の読み込み中はスケルトンを出して。中身と同じ形の灰色の枠にして、光が左から右へ0.9秒で流れるように。","en":"While the list loads, show a skeleton screen: grey blocks in the shape of the content, with a shine sweeping left to right every 0.9 s.","zh-Hans":"列表加载时显示骨架屏，用灰块保持内容形状，每 0.9 秒从左向右扫过一道光。"},"summary":{"ja":"再読み込みを押すと、一覧の中身が同じ形の灰色の枠に変わり、光が横に流れる。読み込みが済むと中身に戻る。","en":"Clicking reload turns the list into grey blocks of the same shape with a sweeping shine; the content returns when loading ends.","zh-Hans":"点击重新加载后，列表变为同形状的灰块并有扫光，加载完成后恢复内容。"},"spec":{"ja":["4.5秒周期・カード542×191。2行の一覧（絵 96×56 と文字3行）。右上の再読み込みアイコンをカーソルが1.0秒にクリック","1.05〜1.2秒に直線で、中身から同じ位置・同じ大きさの灰色 #e9e7e5 の角丸の枠へ切り替える","光: 白の帯（幅160、両端は透明・中央は不透明度0.75）を、0.9秒ごとに左（x −200）から右（x 742）へ流す。枠の上だけに重ねる","3.0〜3.3秒に直線で中身へ戻す"],"en":["4.5 s cycle on a 542×191 card. A two-row list (a 96×56 picture and three text lines each). The cursor clicks the reload icon at top right at 1.0 s.","Over 1.05–1.2 s (linear) the content switches to grey #e9e7e5 rounded blocks of the same size and position.","Shine: a white band 160 wide (transparent at the edges, opacity 0.75 in the middle) sweeps from x −200 to x 742 every 0.9 s, drawn only over the blocks.","The content returns over 3.0–3.3 s (linear)."],"zh-Hans":["542×191 卡片，周期 4.5 秒。两行列表，每行一张 96×56 图片和三行文字；光标于 1.0 秒点击右上角重载图标。","1.05–1.2 秒线性切换为同尺寸、同位置的灰色 #e9e7e5 圆角块。","白色光带宽 160，两端透明、中心透明度 0.75，每 0.9 秒从 x −200 扫至 x 742，仅绘制在灰块区域。","3.0–3.3 秒线性恢复内容。"]},"use":{"ja":"読み込みに少し時間がかかる一覧やカードで、待っている間も画面の形を見せたいとき。","en":"Use it for lists or cards that take a moment to load, so the layout is visible while people wait.","zh-Hans":"适合加载稍慢的列表或卡片，让用户等待时仍能看到页面布局。"},"tags":["skeleton","skeleton-screen","placeholder","shimmer","loading","ghost-content"]},{"id":"070","pack":"ui","no":"22","slug":"spinner","category":"navigate-status","width":542,"height":191,"cycle":4.5,"name":{"ja":"スピナー","en":"Spinner","zh-Hans":"加载旋转指示器"},"meaning":{"ja":"くるくる回って待ちを示す","en":"A spinning circle that means \"please wait\"","zh-Hans":"旋转圆环表示正在等待"},"ask":{"ja":"送信中はボタンの上にスピナーを出して。1秒に1回転強で回し、終わったら青い丸のチェックに替えて。","en":"While sending, show a spinner over the form, turning a little over once per second, then replace it with a blue check when done.","zh-Hans":"发送时在表单上显示加载旋转指示器，每秒转略多于一圈，完成后换成蓝色对勾。"},"summary":{"ja":"「送信」を押すと画面が白くかすみ、中央で青い弧が回る。済むとチェックに変わって消える。","en":"Clicking \"Send\" washes the card white and a blue arc spins in the middle; when finished it changes to a check and fades.","zh-Hans":"点击“发送”后卡片蒙白，中央蓝色圆弧旋转，完成后变为对勾并淡出。"},"spec":{"ja":["4.5秒周期・カード542×191。下中央の「送信」（120×40）をカーソルが1.0秒にクリック","1.05〜1.2秒に直線で、全面に白の幕（不透明度0.78）とスピナーを出す","スピナー: (271, 92) に半径26・太さ6の薄い輪と、その上に長さ243°（1.35π）の青い弧（端は丸）。1秒に1.3回転（468°/秒）で回す","2.95〜3.05秒にスピナーを消し、2.95〜3.2秒に青い丸（半径28）と白いチェックを拡大率 0.7→1（easeOutCubic）で出す","3.75〜4.0秒に直線で幕ごと消す"],"en":["4.5 s cycle on a 542×191 card. The cursor clicks \"Send\" (120×40, bottom centre) at 1.0 s.","Over 1.05–1.2 s (linear) a white scrim (opacity 0.78) and the spinner fade in over the whole card.","Spinner at (271, 92): a pale ring, radius 26, 6 thick, with a blue 243° (1.35π) arc on top (round caps), turning 1.3 times per second (468°/s).","Over 2.95–3.05 s the spinner fades; over 2.95–3.2 s a blue circle (radius 28) with a white check scales 0.7 → 1 (easeOutCubic).","Everything fades out linearly over 3.75–4.0 s."],"zh-Hans":["542×191 卡片，周期 4.5 秒。光标于 1.0 秒点击底部居中的 120×40“发送”按钮。","1.05–1.2 秒线性淡入透明度 0.78 的白色全卡片遮罩和旋转指示器。","指示器中心 (271, 92)，浅色环半径 26、线宽 6；上层蓝色圆弧长 243°，即 1.35π，圆形端点，每秒转 1.3 圈，即 468°/s。","2.95–3.05 秒旋转环淡出；2.95–3.2 秒带白色对勾的半径 28 蓝圆由 0.7 → 1 放大，使用 easeOutCubic。","3.75–4.0 秒全部线性淡出。"]},"use":{"ja":"送信・保存など、終わるまでの時間が読めない短い待ちを示したいとき。","en":"Use it for short waits of unknown length, such as sending or saving.","zh-Hans":"适合发送、保存等时长未知的短暂等待。"},"tags":["spinner","loading","loader","activity-indicator","progress-circle","busy"],"aliases":{"zh-Hans":["转圈","加载"]}},{"id":"071","pack":"ui","no":"23","slug":"badge","category":"navigate-status","width":542,"height":191,"cycle":4.5,"name":{"ja":"バッジ","en":"Badge","zh-Hans":"数字角标"},"meaning":{"ja":"件数を小さな丸で示す","en":"A small dot with a number showing a count","zh-Hans":"用小圆点中的数字提示数量"},"ask":{"ja":"ヘッダーのベルにバッジを付けて未読数を出して。増えるたびに0.3秒で少し弾ませ、開いたら消して。","en":"Add a badge to the bell in the header to show the unread count: it pops for 0.3 s each time the count goes up and disappears when opened.","zh-Hans":"页头铃铛加未读角标，计数增加时用 0.3 秒弹动，打开后消失。"},"summary":{"ja":"ヘッダーのベルに通知が届くたび、右上の青い丸の数が1・2・3と増える。ベルを押すと消える。","en":"Each time a notification arrives, the blue dot on the bell in the header counts up 1, 2, 3; clicking the bell clears it.","zh-Hans":"每收到通知，页头铃铛上的蓝点依次显示 1、2、3，点击铃铛后清空。"},"spec":{"ja":["4.5秒周期・カード542×191。高さ54のヘッダー。右の (482, 27) にベルの線画","バッジ: ベル右上（+12, −12）に半径12の青い丸、白い2.5pxの縁、白い14pxの数字","通知が0.7・1.3・1.9秒に届き、数が 1→2→3。1つ目は0.7〜0.9秒に easeOutCubic で拡大して出る","届くたびに拡大率 1.3→1 を0.3秒で戻し、同時に波紋（半径 12→28、不透明度 0.5→0）を0.5秒で広げる","カーソルが2.95秒にベルへ着き3.0秒にクリック。3.0〜3.25秒に easeInOutCubic でバッジを0まで縮める"],"en":["4.5 s cycle on a 542×191 card. A 54-tall header with a line-drawn bell at (482, 27) on the right.","Badge: a blue circle of radius 12 at the bell's top right (+12, −12), 2.5 px white rim, white 14 px number.","Notifications arrive at 0.7, 1.3 and 1.9 s: the count goes 1 → 2 → 3. The first scales in over 0.7–0.9 s with easeOutCubic.","Each arrival pops the scale from 1.3 back to 1 over 0.3 s and sends out a ripple ring (radius 12 → 28, opacity 0.5 → 0) over 0.5 s.","The cursor reaches the bell at 2.95 s and clicks at 3.0 s; the badge shrinks to 0 over 3.0–3.25 s with easeInOutCubic."],"zh-Hans":["542×191 卡片，周期 4.5 秒。页头高 54，右侧 (482, 27) 处有线描铃铛。","角标为半径 12 的蓝圆，位于铃铛右上方 (+12, −12)，白边 2.5 px，数字为白色 14 px。","通知在 0.7, 1.3, 1.9 秒到达，计数 1 → 2 → 3；第一次在 0.7–0.9 秒以 easeOutCubic 放大出现。","每次到达时，缩放在 0.3 秒内从 1.3 回到 1，并在 0.5 秒内发出波纹，半径 12 → 28、透明度 0.5 → 0。","光标于 2.95 秒到达铃铛，3.0 秒点击；角标在 3.0–3.25 秒用 easeInOutCubic 缩至 0。"]},"use":{"ja":"未読・新着・カートの中身など、件数を目立たせたいとき。","en":"Use it to call attention to a count, such as unread messages or items in a cart.","zh-Hans":"适合提示未读消息数、购物车数量等计数。"},"tags":["badge","notification-badge","counter","count","dot","unread"]},{"id":"072","pack":"ui","no":"24","slug":"empty-state","category":"navigate-status","width":542,"height":191,"cycle":4.5,"name":{"ja":"エンプティステート","en":"Empty state","zh-Hans":"空状态"},"meaning":{"ja":"中身がないときの案内画面","en":"The screen shown when there is nothing to list yet","zh-Hans":"没有可列出的内容时展示引导界面"},"ask":{"ja":"リストが空になったらエンプティステートを出して。線画のアイコン、「まだ何もありません」、追加するボタンを0.35秒で出して。","en":"When the list is empty, show an empty state: a line icon, \"Nothing here yet\" and an add button, fading in over 0.35 s.","zh-Hans":"列表为空时显示线描图标、“暂无内容”和添加按钮，在 0.35 秒内淡入。"},"summary":{"ja":"一覧の2行をごみ箱で順に消すと、空の箱の線画と「まだ何もありません」「追加する」ボタンが出る。","en":"Deleting the two list rows with their trash icons brings up an empty-box drawing, \"Nothing here yet\" and an \"Add\" button.","zh-Hans":"通过垃圾桶图标删除两行列表后，出现空盒子插画、“暂无内容”和“添加”按钮。"},"spec":{"ja":["4.5秒周期・カード542×191。2行の一覧（494×48・角丸8、右端にごみ箱）","カーソルがごみ箱を0.95秒と1.65秒にクリック。各行は0.3秒の easeInOutCubic で左へ60px動きながら消え、2行目は1行目の位置へ58px上がる","1.95〜2.3秒に直線で、空の状態を8px下から上げつつ出す: 青い線画の受け箱、「まだ何もありません」（16px）、青い「追加する」ボタン（112×34）","カーソルが3.3秒に「追加する」をクリック。空の状態は3.25〜3.45秒に消え、2行が3.35〜3.7秒に easeOutCubic で左から戻る"],"en":["4.5 s cycle on a 542×191 card. A two-row list (494×48, radius 8, a trash icon at the right).","The cursor clicks the trash icons at 0.95 s and 1.65 s. Each row slides 60 px left while fading out over 0.3 s (easeInOutCubic); the second row moves up 58 px into the first slot.","Over 1.95–2.3 s (linear) the empty state fades in while rising 8 px: a blue line drawing of an inbox tray, \"Nothing here yet\" (16 px, in Japanese) and a blue \"Add\" button (112×34).","The cursor clicks \"Add\" at 3.3 s; the empty state fades over 3.25–3.45 s and the two rows come back from the left over 3.35–3.7 s with easeOutCubic."],"zh-Hans":["542×191 卡片，周期 4.5 秒。两行列表，尺寸 494×48、圆角 8，右侧有垃圾桶图标。","光标在 0.95 秒和 1.65 秒点击删除；每行在 0.3 秒内以 easeInOutCubic 左移 60 px 并淡出；第二行上移 58 px 填补首行位置。","1.95–2.3 秒空状态线性淡入并上移 8 px，包括蓝色线描收件盘、16 px 日文“暂无内容”和 112×34 蓝色“添加”按钮。","光标于 3.3 秒点击添加；空状态在 3.25–3.45 秒淡出，两行列表在 3.35–3.7 秒以 easeOutCubic 从左侧返回。"]},"use":{"ja":"初めて使う画面や、検索で何も見つからないときに、次にすることを案内したいとき。","en":"Use it for first-use screens or no-results pages to tell people what to do next.","zh-Hans":"适合首次使用或无结果页面，告诉用户下一步可做什么。"},"tags":["empty-state","no-data","zero-state","blank-state","no-results","onboarding"]},{"id":"073","pack":"lp","no":"01","slug":"parallax-scrolling","category":"scroll","width":539,"height":208,"cycle":4.8,"name":{"ja":"パララックススクロール","en":"Parallax scrolling","zh-Hans":"视差滚动"},"meaning":{"ja":"スクロールで奥の層ほどゆっくり動く","en":"On scroll, background layers move slower than the content","zh-Hans":"页面滚动时背景图层比内容移动得慢"},"ask":{"ja":"ファーストビューの背景をパララックススクロールにして。背景はスクロール量の0.3倍で動かして。","en":"Make the hero background a parallax scroll: move it at 0.3× the scroll distance.","zh-Hans":"首屏背景做视差滚动，位移为滚动距离的 0.3×。"},"summary":{"ja":"ページを下へスクロールすると、見出しはふつうに上がり、空と太陽・遠い山・近い山はそれより遅く動く。","en":"As the page scrolls down, the headline moves up normally while the sky and sun, far hills and near hills move more slowly.","zh-Hans":"页面下滚时，标题正常上移，天空、太阳、远山与近山移动得更慢。"},"spec":{"ja":["表示域 511×168 のブラウザの窓。スクロール量: 0.3〜1.9秒で 0→120px、2.9〜4.3秒で 120→0（easeInOut 3乗）","各層の移動量 = スクロール量 × 係数。空と太陽 0.15、遠い山 0.4、近い山 0.7","見出し（28px）・ボタン・次のセクションは 1.0（ふつうのスクロール）","次のセクション（白地）はファーストビューの下端（168px）から始まり、遅れて動く背景の上にかぶさる","右端のスクロールバーのつまみもスクロール量に合わせて動く"],"en":["A browser window with a 511 × 168 viewport. Scroll: 0→120 px at 0.3–1.9 s, 120→0 at 2.9–4.3 s (cubic ease-in-out).","Each layer moves by scroll × factor: sky and sun 0.15, far hills 0.4, near hills 0.7.","Headline (28 px), button and the next section move at 1.0 (normal scrolling).","The next section (white) starts at the bottom of the hero (168 px) and slides over the slower background.","The scrollbar thumb on the right moves with the scroll."],"zh-Hans":["浏览器视口为 511 × 168；滚动在 0.3–1.9 秒从 0→120 px，2.9–4.3 秒从 120→0，采用三次缓入缓出。","各层位移 = 滚动量 × 系数：天空与太阳 0.15，远山 0.4，近山 0.7。","28 px 标题、按钮和下一分区的系数为 1.0，即正常滚动。","白色下一分区从首屏底部 168 px 处开始，滑过移动较慢的背景。","右侧滚动条滑块随滚动同步移动。"]},"use":{"ja":"ファーストビューや区切りの写真に奥行きを出したいとき。","en":"Use it to give the hero or a section photo a sense of depth.","zh-Hans":"适合为首屏或分区照片增加纵深。"},"tags":["parallax","parallax-scrolling","scroll","depth","layers","hero","background"],"aliases":{"zh-Hans":["视差","滚动视差"]}},{"id":"074","pack":"lp","no":"02","slug":"fade-in-on-scroll","category":"scroll","width":539,"height":208,"cycle":4.8,"name":{"ja":"スクロールでフェードイン","en":"Fade-in on scroll","zh-Hans":"滚动淡入"},"meaning":{"ja":"画面に入った要素がふわっと現れる","en":"Elements fade in as they scroll into view","zh-Hans":"元素滚入视口时逐渐显现"},"ask":{"ja":"各セクションの見出しとカードを、スクロールでフェードインさせて。下から30px、0.6秒で。","en":"Fade in each section's heading and cards on scroll: up from 30 px below, over 0.6 s.","zh-Hans":"各区标题和卡片滚入时，从下方 30 px 处用 0.6 秒上移淡入。"},"summary":{"ja":"スクロールで画面に入った見出し・カード・本文が、それぞれ下から浮かび上がりながら現れる。","en":"As the page scrolls, the heading, the cards and the body text each rise into place and fade in when they enter the view.","zh-Hans":"随页面滚动，标题、卡片和正文进入视口后分别上移到位并淡入。"},"spec":{"ja":["スクロール量: 0.35〜1.0秒で 0→95px、1.5〜2.1秒で 95→200px、3.2〜4.4秒で 200→0（いずれも easeInOut 3乗）","判定線は表示域の高さの85%（上から143px）。要素の上端がこの線より上に来た時刻に発火（Intersection Observer の考え方）","発火から0.7秒で 不透明度 0→1、下から28px → 0 へ（easeOut 3乗）","要素は見出し（ページ上 172px）・カード3枚の列（206px）・本文（334px）の3つ。最初はどれも画面の下に隠れている。列のカードは同時に出る","スクロールで戻って画面の下へ出た要素は、見えない所で元の状態に戻る（次に入るとまた出る）"],"en":["Scroll: 0→95 px at 0.35–1.0 s, 95→200 px at 1.5–2.1 s, 200→0 at 3.2–4.4 s (all cubic ease-in-out).","Trigger line at 85% of the viewport height (143 px from the top). An element fires when its top edge passes above it (the Intersection Observer idea).","After firing, over 0.7 s: opacity 0→1 and offset 28 px below → 0 (cubic ease-out).","Three elements: the heading (172 px down the page), a row of three cards (206 px) and body text (334 px), all below the view at first. The cards in the row appear together.","When an element leaves the bottom of the view on the way back up, it is reset out of sight and plays again next time."],"zh-Hans":["滚动：0.35–1.0 秒为 0→95 px，1.5–2.1 秒为 95→200 px，3.2–4.4 秒为 200→0，均用三次缓入缓出。","触发线为视口高度的 85%，距顶 143 px；元素顶边越过此线时触发，类似 Intersection Observer。","触发后在 0.7 秒内，透明度 0→1，下方偏移 28 px → 0，采用三次缓出。","三个元素初始均在视口下方：标题距页面顶 172 px，一行三张卡片在 206 px，正文在 334 px；卡片同时出现。","向上滚回时，元素离开视口底部后恢复隐藏，下次进入重新播放。"]},"use":{"ja":"縦に長いLPで、読み進めるごとに内容を一つずつ見せたいとき。","en":"Use it on a long landing page to bring content in piece by piece as the reader scrolls.","zh-Hans":"适合长落地页，让内容随阅读逐段出现。"},"tags":["fade-in","scroll-reveal","reveal-on-scroll","intersection-observer","aos","entrance","scroll"]},{"id":"075","pack":"lp","no":"03","slug":"sticky-header","category":"scroll","width":539,"height":208,"cycle":4.8,"name":{"ja":"追従ヘッダー","en":"Sticky header","zh-Hans":"吸顶页头"},"meaning":{"ja":"スクロールしてもヘッダーが上に残る","en":"The header stays at the top while the page scrolls","zh-Hans":"页面滚动时页头固定在顶部"},"ask":{"ja":"ヘッダーを追従ヘッダーにして。上に張り付いたら下に薄い影を付けて。","en":"Make the header a sticky header, with a soft shadow once it sticks to the top.","zh-Hans":"页头设置吸顶，固定后增加柔和阴影。"},"summary":{"ja":"上のお知らせの帯はスクロールで消えるが、その下のヘッダーは画面の上端に来たところで止まり、本文がその下を通っていく。","en":"The announcement strip scrolls away, but the header below it stops at the top edge and the content scrolls underneath.","zh-Hans":"公告条滚出后，下方页头停在顶部，正文从其下方滚过。"},"spec":{"ja":["スクロール量: 0.4〜1.3秒で 0→110px、1.9〜2.8秒で 110→250px、3.4〜4.4秒で 250→0（easeInOut 3乗）","ページの一番上に高さ22pxのお知らせの帯（濃紺）、その下に高さ34pxのヘッダー（ロゴ・メニュー3つ・ボタン）","ヘッダーの位置 = max(22 − スクロール量, 0)。帯が見えなくなった所で上端に止まる（position: sticky; top: 0）","止まってからの24pxのスクロールで、ヘッダーの下に高さ12pxの影を 不透明度 0→0.16 で付ける","本文（写真・見出し・カード3枚）はヘッダーの下をふつうにスクロールする"],"en":["Scroll: 0→110 px at 0.4–1.3 s, 110→250 px at 1.9–2.8 s, 250→0 at 3.4–4.4 s (cubic ease-in-out).","At the very top, a 22 px announcement strip (navy); below it a 34 px header (logo, three menu items, button).","Header position = max(22 − scroll, 0): once the strip is gone, it stops at the top edge (position: sticky; top: 0).","Over the next 24 px of scroll, a 12 px shadow under the header fades from 0 to 0.16 opacity.","The content (photo, heading, three cards) scrolls normally under the header."],"zh-Hans":["滚动：0.4–1.3 秒为 0→110 px，1.9–2.8 秒为 110→250 px，3.4–4.4 秒为 250→0，采用三次缓入缓出。","顶部深蓝公告条高 22 px，其下页头高 34 px，含标志、三个菜单项和按钮。","页头位置 = max(22 − scroll, 0)；公告条离开后固定在顶边，对应 position: sticky; top: 0。","随后 24 px 的滚动范围内，页头下方 12 px 阴影透明度从 0 增至 0.16。","照片、标题和三张卡片在页头下方正常滚动。"]},"use":{"ja":"長いページでも、メニューや申し込みボタンにいつでも手が届くようにしたいとき。","en":"Use it to keep the menu and the call-to-action within reach on a long page.","zh-Hans":"适合长页面中持续保留导航和行动按钮。"},"tags":["sticky","sticky-header","fixed-header","position-sticky","navigation","header","scroll"]},{"id":"076","pack":"lp","no":"04","slug":"pinning","category":"scroll","width":539,"height":208,"cycle":4.8,"name":{"ja":"ピン留め","en":"Pinning","zh-Hans":"滚动固定分区"},"meaning":{"ja":"セクションを止めて中身だけ進める","en":"A section stays fixed while scrolling advances its content","zh-Hans":"分区保持固定，滚动推进内部内容"},"ask":{"ja":"「3ステップ」のセクションをピン留めして、スクロールで1ステップずつ写真と番号を切り替えて。","en":"Pin the three-step section and switch the photo and number one step at a time as the user scrolls.","zh-Hans":"固定三步介绍分区，用户滚动时逐步切换图片和编号。"},"summary":{"ja":"濃紺のセクションが画面いっぱいに来たところで止まり、スクロールし続けると番号と写真がステップ1→2→3と切り替わり、終わると再び流れていく。","en":"A navy section stops when it fills the view; further scrolling steps the number and photo through 1→2→3, then the section scrolls on.","zh-Hans":"深蓝分区铺满视口后停住，继续滚动时编号与图片依次切换 1→2→3，随后分区继续滚走。"},"spec":{"ja":["スクロール量: 0.3〜3.0秒で 0→500px、3.5〜4.5秒で 500→0（easeInOut 3乗）","セクション（高さ168・濃紺）はスクロール量110pxで上端に着き、そこから300pxのあいだ止まる（GSAP ScrollTrigger の pin）","止まっている間の進み具合 p = (スクロール量 − 110) / 300。左の縦線（長さ124）が p に合わせて朱色で伸びる","p が 1/3 と 2/3 の所（前後 ±0.07、easeInOut 3乗）で次のステップへ: 番号（46px）が52px、写真（226×124）が124px 上へ送られる","300px 進むと止めを外し、セクションは次の白いセクションと一緒に上へ流れる"],"en":["Scroll: 0→500 px at 0.3–3.0 s, 500→0 at 3.5–4.5 s (cubic ease-in-out).","The section (168 tall, navy) reaches the top at 110 px of scroll and stays there for the next 300 px (a GSAP ScrollTrigger pin).","Progress while pinned: p = (scroll − 110) / 300. A vertical line (124 long) on the left fills in orange with p.","At p = 1/3 and 2/3 (±0.07, cubic ease-in-out) it moves to the next step: the number (46 px) rolls up 52 px and the photo (226 × 124) slides up 124 px.","After 300 px the pin is released and the section scrolls up with the white section below it."],"zh-Hans":["滚动：0.3–3.0 秒为 0→500 px，3.5–4.5 秒为 500→0，采用三次缓入缓出。","深蓝分区高 168，滚动到 110 px 时到达顶部，并在后续 300 px 内保持固定，类似 GSAP ScrollTrigger pin。","固定期间进度 p = (scroll − 110) / 300；左侧长 124 的竖线按 p 填充橙色。","在 p = 1/3 和 2/3 时切换下一步，过渡范围 ±0.07，三次缓入缓出；46 px 编号上滚 52 px，226 × 124 照片上移 124 px。","经过 300 px 后解除固定，分区与下方白色分区一起向上滚动。"]},"use":{"ja":"手順・特長・ビフォーアフターを、1画面で順番に見せたいとき。","en":"Use it to walk through steps, features or a before/after in one screen.","zh-Hans":"适合在同一屏内分步展示流程、功能或前后对比。"},"tags":["pin","pinning","scrolltrigger","gsap","scroll-driven","steps","storytelling"],"aliases":{"zh-Hans":["滚动钉住","固定滚动"]}},{"id":"077","pack":"lp","no":"05","slug":"horizontal-scroll","category":"scroll","width":539,"height":208,"cycle":4.8,"name":{"ja":"横スクロール","en":"Horizontal scroll","zh-Hans":"横向滚动"},"meaning":{"ja":"縦のスクロールで中身が横に流れる","en":"Scrolling down moves the content sideways","zh-Hans":"向下滚动，内容横向移动"},"ask":{"ja":"実績のセクションを横スクロールにして。縦にスクロールした分だけ、カードを左へ流して。","en":"Turn the work section into a horizontal scroll: move the cards left as far as the user scrolls down.","zh-Hans":"作品区做横向滚动，用户下滚时卡片向左移动相应距离。"},"summary":{"ja":"縦にスクロールすると、セクションが止まったまま、番号付きの作品カード4枚が左へ流れていく。","en":"As the page scrolls down, the section holds still and four numbered work cards travel to the left.","zh-Hans":"页面向下滚动时分区固定，四张带编号的作品卡片向左移动。"},"spec":{"ja":["スクロール量: 0.3〜3.0秒で 0→420px、3.5〜4.5秒で 420→0（easeInOut 3乗）","見出し「WORKS」は上へ流れ、セクションはスクロール量40pxで上端に着いて止まる","カード: 200×112 を4枚、間隔20、左右の余白34。横に動く量 = 34×2 + 200×4 + 20×3 − 511 = 417px","カードの横位置 = 元の位置 − p × 417。p = (スクロール量 − 40) / 380（スクロールに比例・イージングなし）","スクロールバーのつまみは縦に動き、カードは横に動く"],"en":["Scroll: 0→420 px at 0.3–3.0 s, 420→0 at 3.5–4.5 s (cubic ease-in-out).","The heading \"WORKS\" scrolls away; the section reaches the top at 40 px of scroll and stays there.","Cards: four at 200 × 112, gap 20, side padding 34. Horizontal travel = 34·2 + 200·4 + 20·3 − 511 = 417 px.","Card x = start x − p × 417, with p = (scroll − 40) / 380: linear in scroll, no easing.","The scrollbar thumb moves down while the cards move sideways."],"zh-Hans":["滚动：0.3–3.0 秒为 0→420 px，3.5–4.5 秒为 420→0，采用三次缓入缓出。","“WORKS”标题滚走，滚动到 40 px 时分区到达顶部并固定。","四张卡片各 200 × 112，间隔 20，两侧留白 34；横移距离 = 34·2 + 200·4 + 20·3 − 511 = 417 px。","卡片 x = 初始 x − p × 417，p = (scroll − 40) / 380；与滚动线性对应，无缓动。","卡片横移时滚动条滑块仍向下移动。"]},"use":{"ja":"作品・事例・商品を、縦長のページの中で横一列に見せたいとき。","en":"Use it to show work, case studies or products in a row inside a long vertical page.","zh-Hans":"适合在纵向长页中成排展示作品、案例或产品。"},"tags":["horizontal-scroll","sideways","scrolltrigger","pin","gallery","portfolio","scroll"]},{"id":"078","pack":"lp","no":"06","slug":"scroll-snap","category":"scroll","width":539,"height":208,"cycle":4.8,"name":{"ja":"スクロールスナップ","en":"Scroll snap","zh-Hans":"滚动吸附"},"meaning":{"ja":"スクロールが区切りの位置にピタッと止まる","en":"Scrolling settles exactly on the next section","zh-Hans":"滚动后准确停在下一分区边缘"},"ask":{"ja":"セクションごとにスクロールスナップさせて。少し回しただけで次のセクションの頭に合わせて。","en":"Add scroll snap per section, so a small scroll lands on the top of the next section.","zh-Hans":"每个分区加滚动吸附，轻微滚动后自动停在下一分区顶部。"},"summary":{"ja":"少しだけスクロールすると、残りは自動で送られて、次のセクションの頭がちょうど画面の上にそろう。","en":"After a small scroll, the page carries itself the rest of the way until the next section's top lines up with the top of the view.","zh-Hans":"轻微滚动后，页面自动补完剩余距离，将下一分区顶边与视口顶部对齐。"},"spec":{"ja":["セクションの高さ = 表示域の高さ（168px）。1つ目は薄い青地、2つ目は濃紺","2.4秒で1回。0.45〜0.85秒に手で34pxだけスクロール（easeOut 3乗）","0.9〜1.5秒に残りの134pxを自動で送り、次のセクションの頭に合わせる（easeOut 3乗）","後半の2.4秒は同じ動きを上向きに行い、1つ目のセクションへ戻る（scroll-snap-type: y mandatory の動き）"],"en":["Each section is as tall as the viewport (168 px). The first is pale blue, the second navy.","One snap per 2.4 s. At 0.45–0.85 s the user scrolls only 34 px (cubic ease-out).","At 0.9–1.5 s the page moves the remaining 134 px by itself and lines up the next section's top (cubic ease-out).","The second 2.4 s does the same upward, back to the first section (the behaviour of scroll-snap-type: y mandatory)."],"zh-Hans":["每个分区与视口等高，为 168 px；第一屏浅蓝，第二屏深蓝。","每 2.4 秒吸附一次；0.45–0.85 秒用户仅滚动 34 px，采用三次缓出。","0.9–1.5 秒页面自动补完剩余 134 px，对齐下一分区顶部，采用三次缓出。","第二个 2.4 秒同样向上返回首屏，对应 scroll-snap-type: y mandatory。"]},"use":{"ja":"1画面ずつ区切って見せるLPや、スライドのようなページにしたいとき。","en":"Use it for a page that should read one full screen at a time, like slides.","zh-Hans":"适合像幻灯片一样逐屏阅读的页面。"},"tags":["scroll-snap","snap","full-page","sections","css","mandatory","scroll"]},{"id":"079","pack":"lp","no":"07","slug":"scroll-progress-bar","category":"scroll","width":539,"height":208,"cycle":4.8,"name":{"ja":"スクロールプログレスバー","en":"Scroll progress bar","zh-Hans":"阅读进度条"},"meaning":{"ja":"読み進めた割合を上の線で見せる","en":"A bar at the top shows how far you have read","zh-Hans":"顶部进度条显示阅读位置"},"ask":{"ja":"記事ページの上にスクロールプログレスバーを付けて。太さ4px、色はブランドの朱色で。","en":"Add a scroll progress bar at the top of the article page, 4 px thick, in the brand orange.","zh-Hans":"文章页顶部加 4 px 品牌橙色阅读进度条。"},"summary":{"ja":"記事を少しずつ読み進めるごとに、画面の上端の線が左から伸び、最後まで来ると端まで届く。","en":"As the article is read a bit at a time, the line along the top grows from the left and reaches the far end at the bottom of the page.","zh-Hans":"逐段阅读时，顶部线条从左向右增长，到页面底部时填满。"},"spec":{"ja":["記事のページを 0→430px までスクロール。110pxずつ4回、それぞれ0.45秒で動いて0.4秒止まる（easeInOut 3乗）","3.75〜4.55秒で 430→0 に戻る","表示域の上端に高さ6pxの線。地は薄いグレー、伸びる部分は朱色","伸びる幅 = 511px × スクロール量 / 430（スクロールの割合そのまま。CSS の animation-timeline: scroll() と同じ）"],"en":["The article scrolls 0→430 px in four 110 px steps, each moving for 0.45 s then pausing 0.4 s (cubic ease-in-out).","It returns 430→0 at 3.75–4.55 s.","A 6 px bar along the top of the viewport: light grey track, orange fill.","Fill width = 511 px × scroll / 430, the scroll fraction itself (the same as CSS animation-timeline: scroll())."],"zh-Hans":["文章以四个 110 px 步长从 0→430 px 滚动，每次运动 0.45 秒再停 0.4 秒，采用三次缓入缓出。","3.75–4.55 秒从 430→0 返回。","视口顶部进度条高 6 px，浅灰轨道、橙色填充。","填充宽度 = 511 px × scroll / 430，与滚动比例直接对应，类似 CSS animation-timeline: scroll()。"]},"use":{"ja":"長い記事やコラムで、あとどれくらいで読み終わるかを伝えたいとき。","en":"Use it on long articles to show how much is left to read.","zh-Hans":"适合长文章，提示剩余阅读量。"},"tags":["progress-bar","reading-progress","scroll-progress","indicator","scroll-driven","article"]},{"id":"080","pack":"lp","no":"08","slug":"highlighter-animation","category":"scroll","width":539,"height":208,"cycle":4.8,"name":{"ja":"マーカーアニメーション","en":"Highlighter animation","zh-Hans":"荧光笔划线"},"meaning":{"ja":"大事な言葉に蛍光ペンの線が引かれる","en":"A highlighter stroke is drawn under key words","zh-Hans":"关键词下方逐渐画出高亮笔迹"},"ask":{"ja":"強調したい言葉に、スクロールで画面に入ったらマーカーアニメーションで黄色の線を引いて。0.8秒で左から。","en":"When the key phrase scrolls into view, draw a yellow highlighter animation under it, left to right in 0.8 s.","zh-Hans":"关键词滚入视口后，用 0.8 秒从左向右画出黄色荧光笔高亮。"},"summary":{"ja":"スクロールで文章が画面に入ると、大事な言葉の下半分に黄色い蛍光ペンの線が左から引かれる。","en":"As the copy scrolls into view, a yellow highlighter stroke is drawn left to right across the lower half of the key words.","zh-Hans":"文案滚入时，关键词下半部从左向右出现黄色荧光笔笔迹。"},"spec":{"ja":["スクロール量: 0.35〜1.0秒で 0→90px、1.6〜2.2秒で 90→180px、3.3〜4.4秒で 180→0（easeInOut 3乗）","文章は2行（20px・太字）。ページ上の 190px と 290px にあり、最初は画面の下に隠れている","行の上端が判定線（表示域の高さの80%＝134px）より上に来た時刻に、強調する言葉の下に線を引き始める","線: 黄色 #FFE36B、高さ11（文字の下寄り。ベースラインの8px上〜3px下）。幅 0→言葉の幅 を0.8秒で左から（easeOut 3乗）。文字の後ろに描く","画面の下へ出た行は、見えない所で線を消して元に戻す"],"en":["Scroll: 0→90 px at 0.35–1.0 s, 90→180 px at 1.6–2.2 s, 180→0 at 3.3–4.4 s (cubic ease-in-out).","Two lines of copy (20 px, bold) at 190 px and 290 px down the page, hidden below the view at first.","When a line's top passes the trigger line (80% of the viewport height, 134 px), the stroke under its key words starts.","Stroke: yellow #FFE36B, 11 tall, in the lower part of the text (8 px above to 3 px below the baseline). Width 0 → word width from the left over 0.8 s (cubic ease-out), drawn behind the text.","Lines that leave the bottom of the view are reset out of sight."],"zh-Hans":["滚动：0.35–1.0 秒为 0→90 px，1.6–2.2 秒为 90→180 px，3.3–4.4 秒为 180→0，采用三次缓入缓出。","两行 20 px 粗体文案分别距页面顶 190 px 和 290 px，初始隐藏在视口下方。","行顶边越过视口高度 80% 的触发线，即 134 px 时，开始为关键词划线。","笔迹色 #FFE36B，高 11，位于文字下部，从基线上方 8 px 到下方 3 px；宽度在 0.8 秒内由 0 增至词宽，从左向右，采用三次缓出，绘于文字后方。","文案离开视口底部时恢复隐藏。"]},"use":{"ja":"LPの本文で、いちばん伝えたい一言を読んでいる瞬間に目立たせたいとき。","en":"Use it in landing-page copy to make the one phrase that matters stand out as it is read.","zh-Hans":"适合落地页文案，在阅读时突出核心短语。"},"tags":["highlighter","marker","text-highlight","emphasis","scroll-reveal","copy","underline"]},{"id":"081","pack":"lp","no":"09","slug":"hover-lift","category":"hover-click","width":539,"height":208,"cycle":4.8,"name":{"ja":"ホバーで浮き上がる","en":"Hover lift","zh-Hans":"悬停抬升"},"meaning":{"ja":"カーソルを乗せると影を付けて浮く","en":"On hover, the element rises with a deeper shadow","zh-Hans":"悬停时元素上浮，阴影加深"},"ask":{"ja":"カードにカーソルを乗せたら、ホバーで浮き上がるようにして。上に8px、影を濃く、0.3秒で。","en":"Give the cards a hover lift: up 8 px with a deeper shadow, over 0.3 s.","zh-Hans":"卡片悬停时用 0.3 秒上浮 8 px，阴影加深。"},"summary":{"ja":"カーソルが乗ったカードだけが少し上に持ち上がり、下の影が広がる。カーソルが離れると元に戻る。","en":"Only the card under the cursor lifts slightly and its shadow spreads; it settles back when the cursor leaves.","zh-Hans":"只有光标下的卡片略微上浮、阴影扩散，光标移开后回落。"},"spec":{"ja":["カード3枚（146×128・角丸10）。カーソルが左から順に約1秒ずつ乗る","乗ったら0.3秒で上へ10px（easeOut 3乗）。離れたら同じ0.3秒で戻る（CSS の transition と同じ）","影: ぼかし 6→22px、下へのずれ 2→12px、濃さ 0.08→0.22 を移動と一緒に変える","地は薄いグレー、カードは白（影が見えるように）"],"en":["Three cards (146 × 128, radius 10). The cursor rests on each, left to right, for about 1 s.","On hover the card rises 10 px over 0.3 s (cubic ease-out); on leave it returns over the same 0.3 s (like a CSS transition).","Shadow, changed together with the lift: blur 6→22 px, y offset 2→12 px, opacity 0.08→0.22.","Light grey page, white cards, so the shadow reads."],"zh-Hans":["三张卡片为 146 × 128、圆角 10；光标从左到右，在每张上停留约1 秒。","悬停时卡片在 0.3 秒内上移 10 px，三次缓出；移开时同样用 0.3 秒返回，类似 CSS transition。","阴影同步变化：模糊 6→22 px，y 偏移 2→12 px，透明度 0.08→0.22。","浅灰页面、白色卡片，保证阴影清晰可见。"]},"use":{"ja":"カード・ボタンなど、押せる物を押せそうに見せたいとき。","en":"Use it to make cards and buttons look clickable.","zh-Hans":"适合让卡片和按钮呈现可点击感。"},"tags":["hover","lift","float","card","shadow","translatey","interaction"]},{"id":"082","pack":"lp","no":"10","slug":"image-zoom-on-hover","category":"hover-click","width":539,"height":208,"cycle":4.8,"name":{"ja":"ホバーで画像ズーム","en":"Image zoom on hover","zh-Hans":"悬停图片放大"},"meaning":{"ja":"枠はそのままで写真だけ拡大する","en":"The photo enlarges inside a fixed frame","zh-Hans":"固定边框内的照片逐渐放大"},"ask":{"ja":"実績の写真にホバーで画像ズームを付けて。枠は固定で、中身を1.1倍まで0.5秒で。","en":"Add an image zoom on hover to the work photos: fixed frame, content to 1.1× over 0.5 s.","zh-Hans":"作品照片悬停时保持边框不变，内部用 0.5 秒放大到 1.1×。"},"summary":{"ja":"カーソルが乗った写真だけが、枠の大きさは変えずに中身がゆっくり拡大し、離れると戻る。","en":"The photo under the cursor slowly enlarges while its frame stays the same size, and shrinks back when the cursor leaves.","zh-Hans":"光标下的照片缓慢放大，外框尺寸不变，移开后缩回。"},"spec":{"ja":["写真の枠 222×118（角丸8）を2つ並べる。カーソルが左、右の順に約1.5秒ずつ乗る","乗ったら0.5秒で中身の拡大率 1→1.15（中心から・easeOut 3乗）。離れたら同じ0.5秒で戻る","枠の外にはみ出した部分は切る（overflow: hidden）。枠と下の文字は動かない"],"en":["Two photo frames, 222 × 118 (radius 8). The cursor rests on the left one, then the right one, for about 1.5 s each.","On hover the content scales 1→1.15 from the centre over 0.5 s (cubic ease-out); on leave it returns over 0.5 s.","Anything outside the frame is clipped (overflow: hidden). The frame and the caption do not move."],"zh-Hans":["两个 222 × 118、圆角 8 的照片框；光标先停左侧再右侧，各约 1.5 秒。","悬停时内容在 0.5 秒内以三次缓出从中心缩放 1→1.15，移开后用 0.5 秒返回。","框外内容裁剪，对应 overflow: hidden；边框和说明文字不移动。"]},"use":{"ja":"写真の一覧（実績・商品・記事）で、どれを選ぼうとしているかを伝えたいとき。","en":"Use it on photo grids (work, products, articles) to show which item is about to be chosen.","zh-Hans":"适合在作品、商品或文章图片网格中提示即将选中的项目。"},"tags":["hover","zoom","image","scale","overflow-hidden","thumbnail","gallery"]},{"id":"083","pack":"lp","no":"11","slug":"cursor-follower","category":"hover-click","width":539,"height":208,"cycle":4.8,"name":{"ja":"マウスストーカー","en":"Cursor follower","zh-Hans":"光标跟随"},"meaning":{"ja":"カーソルを丸が遅れて追いかける","en":"A shape trails the mouse pointer with a delay","zh-Hans":"图形稍有延迟地跟随鼠标"},"ask":{"ja":"サイト全体にマウスストーカーを付けて。直径30pxの朱色の丸が、少し遅れてカーソルを追うように。","en":"Add a cursor follower across the site: a 30 px orange circle that trails the pointer slightly.","zh-Hans":"全站增加光标跟随，30 px 橙色圆略微落后于鼠标。"},"summary":{"ja":"カーソルがページの上を動き回ると、朱色の丸が少し遅れてそのあとを追いかける。","en":"As the cursor moves around the page, an orange circle follows it a little behind.","zh-Hans":"光标在页面中移动，橙色圆稍微滞后地跟随。"},"spec":{"ja":["カーソルの道筋: x = 255 + 175·sin(2πt/4.8)、y = 86 + 46·sin(4πt/4.8)（8の字を横に寝かせた形・4.8秒で1周）","丸: 半径17・朱色・不透明度0.88。カーソルの下に描く","追いかけ方: 毎フレーム（60fps）残りの距離の12%ずつ近づく（x += (カーソルのx − x) × 0.12）","カーソル（矢印）はそのまま見せる"],"en":["Cursor path: x = 255 + 175·sin(2πt/4.8), y = 86 + 46·sin(4πt/4.8) (a figure eight lying on its side, one lap per 4.8 s).","Circle: radius 17, orange, opacity 0.88, drawn under the cursor.","Follow rule: every frame (60 fps) it covers 12% of the remaining distance (x += (cursor x − x) × 0.12).","The arrow cursor stays visible."],"zh-Hans":["光标轨迹 x = 255 + 175·sin(2πt/4.8)，y = 86 + 46·sin(4πt/4.8)，为横向八字，每 4.8 秒一圈。","跟随圆半径 17、橙色、透明度 0.88，绘制在光标下方。","每帧按 60 fps 计算，走完剩余距离的 12%，即 x += (cursor x − x) × 0.12。","箭头光标始终可见。"]},"use":{"ja":"ブランドサイトやポートフォリオで、触っている感じや遊び心を足したいとき。","en":"Use it on brand sites and portfolios to add a playful, hands-on feel.","zh-Hans":"适合品牌站和作品集，增加互动与趣味。"},"tags":["cursor","custom-cursor","cursor-follower","mouse-follow","lerp","trail","interaction"]},{"id":"084","pack":"lp","no":"12","slug":"magnetic-button","category":"hover-click","width":539,"height":208,"cycle":4.8,"name":{"ja":"マグネティックボタン","en":"Magnetic button","zh-Hans":"磁吸按钮"},"meaning":{"ja":"近づいたカーソルにボタンが吸い寄せられる","en":"The button is pulled toward a nearby cursor","zh-Hans":"按钮被附近的光标轻微吸引"},"ask":{"ja":"問い合わせボタンをマグネティックボタンにして。カーソルとの差の0.3倍だけ寄って、離れたらぷるんと戻して。","en":"Make the contact button a magnetic button: move 0.3× toward the cursor, and spring back when it leaves.","zh-Hans":"联系按钮做磁吸效果，向光标移动距离的 0.3×，移开后弹回。"},"summary":{"ja":"カーソルが近づくとボタンがカーソルの方へ引き寄せられてついていき、離れるとぷるんと揺れて元の位置に戻る。","en":"As the cursor comes near, the button is drawn toward it and follows; when the cursor leaves, the button wobbles back to its place.","zh-Hans":"光标靠近时按钮被吸引并跟随，离开后晃动回原位。"},"spec":{"ja":["ボタン 168×52（朱色・角丸26）を中央に置く。引き寄せる範囲はボタンの中心から半径110px","範囲内: 目標のずれ = (カーソル − ボタンの中心) × 0.35。毎フレーム（60fps）残りの18%ずつ目標へ近づく","範囲外へ出たら、その時のずれから 0 へ1.1秒で戻す。イージングは elastic.out(1, 0.3)（2^(−10x)·sin((x − 0.075)·2π/0.3) + 1）","カーソルは左の外から入り、ボタンのまわりを回ってから右の外へ出る"],"en":["A 168 × 52 button (orange, radius 26) in the centre. The pull range is a 110 px radius from the button's centre.","Inside the range: target offset = (cursor − button centre) × 0.35; every frame (60 fps) the button covers 18% of the way to the target.","On leaving the range it returns from its current offset to 0 over 1.1 s with elastic.out(1, 0.3): 2^(−10x)·sin((x − 0.075)·2π/0.3) + 1.","The cursor enters from the left, circles the button and leaves to the right."],"zh-Hans":["居中橙色按钮为 168 × 52、圆角 26，吸引范围为距按钮中心半径 110 px。","范围内目标偏移 = (光标 − 按钮中心) × 0.35；每帧按 60 fps 计算，完成到目标距离的 18%。","离开范围后，在 1.1 秒内从当前偏移回到 0，使用 elastic.out(1, 0.3)：2^(−10x)·sin((x − 0.075)·2π/0.3) + 1。","光标从左侧进入，绕按钮后从右侧离开。"]},"use":{"ja":"申し込み・問い合わせなど、いちばん押してほしいボタンを目立たせたいとき。","en":"Use it on the one button you most want clicked, such as sign-up or contact.","zh-Hans":"适合重点突出注册、联系等关键按钮。"},"tags":["magnetic","magnetic-button","hover","cursor","elastic","cta","interaction"],"aliases":{"zh-Hans":["磁吸","弹性"]}},{"id":"085","pack":"lp","no":"13","slug":"ripple-effect","category":"hover-click","width":539,"height":208,"cycle":4.8,"name":{"ja":"リップルエフェクト","en":"Ripple effect","zh-Hans":"点击涟漪"},"meaning":{"ja":"押した場所から波紋が広がる","en":"A ripple spreads from the point that was pressed","zh-Hans":"波纹从按下位置向外扩散"},"ask":{"ja":"送信ボタンにリップルエフェクトを付けて。押した位置から白い円が0.6秒で広がって消えるように。","en":"Add a ripple effect to the submit button: a white circle spreads from the click point and fades in 0.6 s.","zh-Hans":"提交按钮加点击涟漪，白圆从点击点扩散，并在 0.6 秒内淡出。"},"summary":{"ja":"ボタンを押すたびに、押した場所を中心に白い円が広がってボタンの中を満たし、薄れて消える。","en":"Each click sends a white circle out from the click point to fill the button, then it fades away.","zh-Hans":"每次点击都会从点击位置扩散出白圆，覆盖按钮后消失。"},"spec":{"ja":["ボタン 280×56（朱色・角丸10）。0.7秒に左寄り、2.9秒に右寄りの場所をクリック","円の中心 = クリックした点。半径 0 → クリック点から一番遠いボタンの角までの距離、0.6秒で（easeOut 3乗）","色は白・不透明度0.4。クリックから0.3〜0.8秒で 0 まで薄くする","円はボタンの形で切り取る（overflow: hidden）。文字は円の上に描く"],"en":["Button 280 × 56 (orange, radius 10). Clicks at 0.7 s (left of centre) and 2.9 s (right of centre).","The circle is centred on the click point; its radius grows from 0 to the distance to the button's farthest corner over 0.6 s (cubic ease-out).","White at 0.4 opacity, fading to 0 between 0.3 and 0.8 s after the click.","The circle is clipped to the button (overflow: hidden); the label sits above it."],"zh-Hans":["橙色按钮为 280 × 56、圆角 10；0.7 秒点击中心偏左，2.9 秒点击中心偏右。","圆心为点击点；半径在 0.6 秒内从 0 增至该点到按钮最远角的距离，采用三次缓出。","白色透明度 0.4，在点击后 0.3 到 0.8 秒之间淡至 0。","圆裁剪在按钮内，对应 overflow: hidden，按钮文字在圆上方。"]},"use":{"ja":"ボタンやリストを押したことを、その場ですぐ返したいとき。","en":"Use it to confirm a press on a button or list item right where it happened.","zh-Hans":"适合在实际点击位置反馈按钮或列表项的按下动作。"},"tags":["ripple","ink-ripple","material","click","tap","feedback","button"]},{"id":"086","pack":"lp","no":"14","slug":"underline-animation","category":"hover-click","width":539,"height":208,"cycle":4.8,"name":{"ja":"下線アニメーション","en":"Underline animation","zh-Hans":"下划线动画"},"meaning":{"ja":"乗せたリンクの下線が左から伸びる","en":"A link's underline grows from the left on hover","zh-Hans":"悬停链接时，下划线从左侧伸展"},"ask":{"ja":"メニューのリンクに下線アニメーションを付けて。乗せたら左から0.3秒で伸び、離れたら右へ抜けるように。","en":"Add an underline animation to the menu links: grow from the left in 0.3 s on hover, and exit to the right on leave.","zh-Hans":"菜单链接悬停时用 0.3 秒从左侧画出下划线，移开后向右消退。"},"summary":{"ja":"カーソルが乗ったリンクの下に、朱色の線が左から伸び、離れると線は右へ縮んで抜けていく。","en":"Under the link the cursor is on, an orange line grows from the left; when the cursor leaves, the line shrinks away to the right.","zh-Hans":"光标所在链接下方的橙线从左伸展，移开时向右缩短消失。"},"spec":{"ja":["リンク3つ（20px・太字・間隔56）。カーソルが左から順に約1秒ずつ乗る（当たり判定は文字の左右6px広め）","下線: 朱色・太さ3・ベースラインの8px下","乗ったら 幅 0→100% を0.3秒で左端から伸ばす（easeOut 3乗）","離れたら 左端を右へ0.3秒で動かし、右へ抜けるように消す（transform-origin を右にした scaleX と同じ）"],"en":["Three links (20 px, bold, 56 apart). The cursor rests on each, left to right, for about 1 s (hit area 6 px wider than the text on each side).","Underline: orange, 3 thick, 8 px below the baseline.","On hover, width 0→100% from the left end over 0.3 s (cubic ease-out).","On leave, the left end moves right over 0.3 s, so the line exits to the right (like scaleX with transform-origin on the right)."],"zh-Hans":["三个链接为 20 px 粗体、间隔 56；光标从左到右各停约1 秒，命中区在文字两侧各加宽 6 px。","橙色下划线粗 3，位于基线下方 8 px。","悬停时宽度在 0.3 秒内从 0→100%，由左端展开，采用三次缓出。","移开后左端在 0.3 秒内向右移动，使线条向右退出，类似以右侧为 transform-origin 的 scaleX。"]},"use":{"ja":"ヘッダーのメニューや本文のリンクで、どこを指しているかを上品に伝えたいとき。","en":"Use it on menu and text links to show where the pointer is, quietly.","zh-Hans":"适合菜单和文字链接，以轻量方式提示悬停位置。"},"tags":["underline","hover","link","navigation","menu","text-link","scalex"]},{"id":"087","pack":"lp","no":"15","slug":"before-after-slider","category":"hover-click","width":539,"height":208,"cycle":4.8,"name":{"ja":"ビフォーアフタースライダー","en":"Before/after slider","zh-Hans":"前后对比滑块"},"meaning":{"ja":"境目をドラッグして前と後を見比べる","en":"Drag a divider to compare before and after","zh-Hans":"拖动分隔线比较处理前后"},"ask":{"ja":"施工例の写真をビフォーアフタースライダーにして。真ん中の線をドラッグすると、左が施工前、右が施工後で見比べられるように。","en":"Show the project photos as a before/after slider: drag the middle line to compare before on the left and after on the right.","zh-Hans":"项目照片做前后对比滑块，拖动中线比较左侧处理前与右侧处理后。"},"summary":{"ja":"写真の真ん中の線をドラッグして左右に動かすと、左側は色のない「前」、右側は色のある「後」の範囲が入れ替わる。","en":"Dragging the line in the middle of the photo left and right changes how much of the grey \"before\" (left) and the coloured \"after\" (right) is shown.","zh-Hans":"左右拖动照片中线，改变左侧灰色处理前和右侧彩色处理后的显示比例。"},"spec":{"ja":["写真の枠 359×140（角丸10）。右は加工後（色あり）、左は同じ写真を加工前に（彩度を抜き、濃紺 不透明度0.18 を重ねる）","境目より左だけ加工前を見せる（clip）。境目に白い線（幅3）と、左右の矢印の付いた白い丸（半径17）","0.7秒に丸をつかみ、境目の位置を 50%→20%（0.75〜1.55秒）→82%（1.55〜2.65秒）→50%（2.65〜3.55秒）。いずれも easeInOut 3乗","3.62秒に離す。左上に BEFORE、右上に AFTER の札"],"en":["Photo frame 359 × 140 (radius 10). Right: the edited photo in colour. Left: the same photo as the \"before\" (saturation removed, navy at 0.18 opacity on top).","The before image is clipped to the left of the divider. On the divider: a white line (3 wide) and a white circle (radius 17) with left/right arrows.","At 0.7 s the circle is grabbed; the divider goes 50%→20% (0.75–1.55 s) →82% (1.55–2.65 s) →50% (2.65–3.55 s), all cubic ease-in-out.","Released at 3.62 s. Labels BEFORE (top left) and AFTER (top right)."],"zh-Hans":["照片框为 359 × 140、圆角 10；右侧为彩色处理后照片，左侧为同图处理前版本，去饱和并叠加透明度 0.18 的深蓝色。","处理前图片裁剪在分隔线左侧；分隔线为宽 3 的白线，带半径 17、含左右箭头的白圆。","0.7 秒抓住圆形把手；分隔线由 50%→20%（0.75–1.55 秒）→82%（1.55–2.65 秒）→50%（2.65–3.55 秒），均用三次缓入缓出。","3.62 秒松手；左上角标 BEFORE，右上角标 AFTER。"]},"use":{"ja":"施工・美容・写真の補正など、変化そのものを売りにするLPで。","en":"Use it on pages that sell a change: renovation, beauty, photo retouching.","zh-Hans":"适合装修、美容、照片修饰等强调改变的页面。"},"tags":["before-after","image-comparison","slider","drag","compare","clip","photo"]},{"id":"088","pack":"lp","no":"16","slug":"exit-intent-popup","category":"hover-click","width":539,"height":208,"cycle":4.8,"name":{"ja":"離脱防止ポップアップ","en":"Exit-intent popup","zh-Hans":"离站挽留弹窗"},"meaning":{"ja":"ページを離れそうな時に出す引き止めの小窓","en":"A popup shown when the visitor is about to leave","zh-Hans":"访客准备离开时出现弹窗"},"ask":{"ja":"LPに離脱防止ポップアップを付けて。カーソルが画面の上へ出たら、クーポンの小窓を1回だけ出して。","en":"Add an exit-intent popup to the landing page: when the cursor leaves through the top, show a coupon popup once.","zh-Hans":"落地页增加一次性的离站挽留弹窗，光标从顶部移出时展示优惠券。"},"summary":{"ja":"カーソルがページの上の方（タブや閉じるボタンのある所）へ出ていくと、背景が暗くなって「ちょっと待って！」の小窓が開く。×で閉じる。","en":"When the cursor heads out through the top of the page (toward the tabs and close button), the page dims and a \"Wait!\" popup opens. The × closes it.","zh-Hans":"光标向页顶浏览器标签和关闭按钮移动时，页面变暗并弹出“稍等”窗口，点 × 关闭。"},"spec":{"ja":["カーソルは 0.7〜1.25秒にページの中からブラウザのアドレスバーの方へ上がる（easeInOut 3乗）","表示域の上端（y = 0）を越えた時刻（約1.07秒）に発火（document の mouseleave で clientY ≤ 0 と同じ判定）","発火の0.05〜0.45秒後に開く（easeOut 3乗）: 背景 濃紺 不透明度 0→0.5、小窓（260×132・角丸12）不透明度 0→1、拡大率 0.9→1","小窓の中は見出し・割引の一言（朱色）・クーポンのボタン・右上の×","2.9秒に×をクリック。0.03〜0.25秒後に消える（等速）"],"en":["The cursor rises from the page toward the browser's address bar at 0.7–1.25 s (cubic ease-in-out).","It fires when the cursor crosses the top edge of the viewport (y = 0, at about 1.07 s), the same test as mouseleave on document with clientY ≤ 0.","Opens 0.05–0.45 s after firing (cubic ease-out): backdrop navy 0→0.5 opacity; popup (260 × 132, radius 12) opacity 0→1 and scale 0.9→1.","Inside: a heading, a discount line (orange), a coupon button and an × at the top right.","Click on the × at 2.9 s; it disappears 0.03–0.25 s later (linear)."],"zh-Hans":["光标在 0.7–1.25 秒从页面上移至浏览器地址栏，采用三次缓入缓出。","光标越过视口顶边 y = 0 时触发，约 1.07 秒，等价于 document 的 mouseleave 且 clientY ≤ 0。","触发后 0.05–0.45 秒以三次缓出打开；深蓝遮罩透明度 0→0.5，弹窗为 260 × 132、圆角 12，透明度 0→1、缩放 0.9→1。","内部有标题、橙色折扣说明、优惠券按钮和右上角 ×。","2.9 秒点击 ×，随后 0.03–0.25 秒线性消失。"]},"use":{"ja":"申し込みや購入の直前で帰ってしまう人に、最後の一押しをしたいとき。","en":"Use it to make one last offer to visitors who are about to leave without converting.","zh-Hans":"适合向尚未转化、准备离开的访客提供最后一次优惠。"},"tags":["exit-intent","popup","mouseleave","coupon","conversion","retention","lp"]},{"id":"089","pack":"lp","no":"17","slug":"preloader","category":"loading-loops","width":539,"height":208,"cycle":4.8,"name":{"ja":"ローディング画面","en":"Preloader","zh-Hans":"预加载屏"},"meaning":{"ja":"読み込み中に出す画面","en":"A screen shown while the page loads","zh-Hans":"页面加载期间显示的过渡屏幕"},"ask":{"ja":"サイトを開いたときのローディング画面を作って。ロゴと％の数字を出して、100%になったら幕が上がるように。","en":"Make a preloader for the site: logo and a percentage, and the screen lifts away at 100%.","zh-Hans":"站点加载时显示标志和百分比，达到 100% 后整屏向上移走。"},"summary":{"ja":"濃紺の画面でロゴの下の数字が0%から100%まで進み、終わると画面が上へ抜けて、下のページがふわっと現れる。","en":"On a navy screen the number under the logo counts from 0% to 100%; then the screen lifts away and the page underneath fades in.","zh-Hans":"深蓝屏幕上，标志下方数字由 0% 增至 100%，随后屏幕抬升离开，下方页面淡入。"},"spec":{"ja":["表示域いっぱいの濃紺の画面に、ロゴ・数字（28px）・線（180×4）","0.25〜2.1秒で 0→100%（easeOut 3乗・整数に丸める）。線も同じ割合で朱色に伸びる","2.3〜2.85秒に画面ごと上へ168px抜ける（easeInOut 3乗）","ページの見出し・写真は 2.35〜2.95秒に 不透明度 0→1、14px下から上がる（easeOut 3乗）","4.25〜4.75秒に画面が上から下りてきて、0%の状態に戻る（次の読み込み）"],"en":["A navy screen fills the viewport with a logo, a number (28 px) and a bar (180 × 4).","0→100% at 0.25–2.1 s (cubic ease-out, rounded to whole numbers); the bar fills in orange at the same rate.","At 2.3–2.85 s the whole screen moves up 168 px and out (cubic ease-in-out).","The page heading and photo fade in 0→1 and rise from 14 px below at 2.35–2.95 s (cubic ease-out).","At 4.25–4.75 s the screen comes back down from the top, at 0% (the next load)."],"zh-Hans":["深蓝屏铺满视口，内有标志、28 px 数字和 180 × 4 进度条。","0.25–2.1 秒从 0→100%，采用三次缓出并取整数，橙色进度条同比填充。","2.3–2.85 秒整屏上移 168 px 离场，采用三次缓入缓出。","2.35–2.95 秒页面标题和照片透明度 0→1，并从下方 14 px 上移，采用三次缓出。","4.25–4.75 秒加载屏从顶部返回，显示 0%，模拟下一次加载。"]},"use":{"ja":"写真や動画の多いサイトで、読み込みの待ち時間をブランドの見せ場にしたいとき。","en":"Use it on image- or video-heavy sites to turn the loading wait into a brand moment.","zh-Hans":"适合图片或视频较多的网站，将等待过程融入品牌展示。"},"tags":["preloader","loading-screen","loader","percentage","intro","splash","curtain"]},{"id":"090","pack":"lp","no":"18","slug":"lazy-loading","category":"loading-loops","width":539,"height":208,"cycle":4.8,"name":{"ja":"遅延読み込み","en":"Lazy loading","zh-Hans":"懒加载"},"meaning":{"ja":"画面に入った画像だけを読み込む","en":"Images load only when they come into view","zh-Hans":"图片进入视口后才开始加载"},"ask":{"ja":"ギャラリーの画像を遅延読み込みにして。読み込むまでは灰色の枠、届いたら0.3秒でフェードインして。","en":"Lazy load the gallery images: grey placeholders until loaded, then fade in over 0.3 s.","zh-Hans":"图库图片使用懒加载，完成前显示灰色占位，加载后用 0.3 秒淡入。"},"summary":{"ja":"スクロールで画面に入った灰色の枠に読み込み中の印が回り、画像が届くと順にフェードインする。上の段は最初から読み込み済み。","en":"As grey placeholders scroll into view, a spinner turns in each, and the images fade in as they arrive. The top row is loaded from the start.","zh-Hans":"灰色占位滚入后中央出现旋转指示器，图片到达后淡入；首行从一开始就已加载。"},"spec":{"ja":["画像の枠 151×92 を3列×3段。1段目は最初から表示。スクロール量: 0.35〜1.1秒で 0→110px、1.7〜2.5秒で 110→225px、3.5〜4.5秒で 225→0（easeInOut 3乗）","枠の上端が表示域の下端（168px）より上に入った時刻に読み込み開始。列ごとに0.12秒ずつずらす","読み込み中の0.45秒は、枠の中央で回る印（半径11・0.8秒で1回転）","そのあと0.35秒で画像の不透明度 0→1（easeOut 3乗）。読み込み前の枠には画像の印を描く","画面の下へ出た枠は、見えない所で読み込み前に戻る"],"en":["A 3 × 3 grid of 151 × 92 placeholders; the first row is shown from the start. Scroll: 0→110 px at 0.35–1.1 s, 110→225 px at 1.7–2.5 s, 225→0 at 3.5–4.5 s (cubic ease-in-out).","Loading starts when a placeholder's top edge passes above the bottom of the viewport (168 px), with each column 0.12 s later than the one to its left.","For 0.45 s a spinner (radius 11, one turn per 0.8 s) turns in the placeholder's centre.","Then the image fades in 0→1 over 0.35 s (cubic ease-out). Unloaded placeholders show an image icon.","Placeholders that leave the bottom of the view are reset out of sight."],"zh-Hans":["3 × 3 网格，每格 151 × 92，首行初始即显示；滚动在 0.35–1.1 秒为 0→110 px，1.7–2.5 秒为 110→225 px，3.5–4.5 秒为 225→0，均用三次缓入缓出。","占位顶边越过视口底部 168 px 时开始加载，每列比左侧列晚 0.12 秒。","占位中央的半径 11 旋转环显示 0.45 秒，每 0.8 秒转一圈。","随后图片透明度在 0.35 秒内从 0→1，采用三次缓出；未加载的占位显示图片图标。","占位离开视口底部时恢复未加载状态。"]},"use":{"ja":"画像の多いページで、最初の表示を速くしたいとき。","en":"Use it on image-heavy pages to make the first view load faster.","zh-Hans":"适合图片较多的页面，加快首屏显示。"},"tags":["lazy-loading","lazy-load","images","placeholder","performance","spinner","gallery"]},{"id":"091","pack":"lp","no":"19","slug":"infinite-scroll","category":"loading-loops","width":539,"height":208,"cycle":4.8,"name":{"ja":"無限スクロール","en":"Infinite scroll","zh-Hans":"无限滚动"},"meaning":{"ja":"下まで来ると続きが自動で足される","en":"More items load automatically at the bottom","zh-Hans":"到达列表底部时自动加载更多"},"ask":{"ja":"お知らせの一覧を無限スクロールにして。下まで来たら読み込み表示を出して、10件ずつ足して。","en":"Make the news list an infinite scroll: show a spinner at the bottom and add ten items at a time.","zh-Hans":"新闻列表做无限滚动，底部显示旋转指示器，每次追加十条。"},"summary":{"ja":"一覧を下へスクロールして最後まで来ると、読み込み中の印が回り、新しい項目が3件足されて続きが読めるようになる。","en":"Scrolling down to the end of the list brings up a spinner, then three new items are added so reading can go on.","zh-Hans":"下滚到列表末尾出现加载环，随后追加三个条目，可继续阅读。"},"spec":{"ja":["項目（331×44・角丸8・間隔52）の一覧。最後の項目の下に読み込み中の印（半径10・0.8秒で1回転）","スクロール量: 0.25〜0.85秒で 38→116px、1.15〜1.75秒で 116→194px（easeInOut 3乗）。一覧の終わりが見えて止まる","2.6秒に3件を足す: 各項目 0.35秒で 不透明度 0→1、10px下から上がる（easeOut 3乗）。印は新しい終わりへ移る","1周期で3件（156px）ぶん進む。中身は3件ごとにくり返すので、周期の終わりと始まりは同じ見た目"],"en":["A list of items (331 × 44, radius 8, 52 apart) with a spinner (radius 10, one turn per 0.8 s) under the last item.","Scroll: 38→116 px at 0.25–0.85 s, 116→194 px at 1.15–1.75 s (cubic ease-in-out); it stops with the end of the list in view.","At 2.6 s three items are added: each fades 0→1 and rises from 10 px below over 0.35 s (cubic ease-out). The spinner moves to the new end.","Each cycle advances by three items (156 px). The content repeats every three items, so the end of the cycle looks the same as the start."],"zh-Hans":["列表项为 331 × 44、圆角 8、间距 52；末项下方有半径 10 的加载环，每 0.8 秒转一圈。","滚动在 0.25–0.85 秒为 38→116 px，1.15–1.75 秒为 116→194 px，采用三次缓入缓出，停在末尾可见处。","2.6 秒追加三个条目，各在 0.35 秒内从透明度 0→1、下方 10 px 处上移，采用三次缓出；加载环移动到新末尾。","每周期前进三个条目，即 156 px；内容每三项重复，使周期末与开始相同。"]},"use":{"ja":"SNSのタイムラインやお知らせ一覧のように、終わりを気にせず読み続けてほしいとき。","en":"Use it for feeds and news lists that people should keep reading without paging.","zh-Hans":"适合不需翻页、持续浏览的信息流和新闻列表。"},"tags":["infinite-scroll","endless-scroll","load-more","feed","pagination","spinner","list"]},{"id":"092","pack":"lp","no":"20","slug":"page-transition","category":"loading-loops","width":539,"height":208,"cycle":4.8,"name":{"ja":"ページ遷移アニメーション","en":"Page transition","zh-Hans":"页面转场"},"meaning":{"ja":"ページを移るときの切り替えの演出","en":"An animation that bridges two pages","zh-Hans":"用动画连接两个页面"},"ask":{"ja":"ページ遷移アニメーションを付けて。リンクを押したら朱色の幕が左から右へ横切って次のページに切り替わるように。","en":"Add a page transition: on link click, an orange panel sweeps across left to right and the next page appears.","zh-Hans":"点击链接后让橙色面板从左向右扫过，再显示下一页面。"},"summary":{"ja":"作品の一覧でカードを押すと朱色の幕が左から画面を覆い、URLが変わって幕が右へ抜けると詳しいページになっている。「一覧へ」で同じように戻る。","en":"Clicking a card in the work list sweeps an orange panel across from the left; the URL changes and the panel exits to the right on the detail page. \"Back to list\" returns the same way.","zh-Hans":"点击作品卡片后橙色面板从左覆盖，URL 切换，面板向右退出并显露详情；返回列表使用相同方式。"},"spec":{"ja":["0.8秒にカードをクリック。0.9〜1.3秒に幕（朱色・表示域いっぱい・中央にロゴ）が左から入って全体を覆う（easeInOut 3乗）","1.3秒、覆われている間にページとアドレスバーのURL（/works → /works/02）を切り替える","1.4〜1.85秒に幕が右へ抜ける（easeInOut 3乗）","3.0秒に「← 一覧へ」をクリック。3.1〜3.5秒に入り、3.5秒に切り替え、3.6〜4.05秒に抜ける","ヘッダーも含めて表示域全体を覆う"],"en":["Click on a card at 0.8 s. At 0.9–1.3 s a panel (orange, full viewport, logo in the centre) enters from the left and covers everything (cubic ease-in-out).","At 1.3 s, while covered, the page and the URL in the address bar (/works → /works/02) switch.","At 1.4–1.85 s the panel exits to the right (cubic ease-in-out).","Click on \"← Back to list\" at 3.0 s: the panel enters at 3.1–3.5 s, the page switches at 3.5 s and the panel exits at 3.6–4.05 s.","The panel covers the whole viewport, header included."],"zh-Hans":["0.8 秒点击卡片；0.9–1.3 秒全视口橙色面板从左进入并覆盖全部，中央有标志，采用三次缓入缓出。","1.3 秒完全遮住时切换页面和地址栏 URL，从 /works → /works/02。","1.4–1.85 秒面板向右退出，采用三次缓入缓出。","3.0 秒点击“← 返回列表”；面板 3.1–3.5 秒进入，3.5 秒切换页面，3.6–4.05 秒退出。","面板覆盖整个视口，包括页头。"]},"use":{"ja":"ブランドサイトやポートフォリオで、ページを移るときの間をつなぎたいとき。","en":"Use it on brand sites and portfolios to link one page to the next.","zh-Hans":"适合品牌站和作品集，连接前后页面。"},"tags":["page-transition","transition","view-transitions","navigation","wipe","barba","spa"]},{"id":"093","pack":"lp","no":"21","slug":"smooth-scroll","category":"loading-loops","width":539,"height":208,"cycle":4.8,"name":{"ja":"スムーススクロール","en":"Smooth scroll","zh-Hans":"平滑滚动"},"meaning":{"ja":"ページ内リンクでなめらかに移動する","en":"In-page links glide to their target instead of jumping","zh-Hans":"页内链接平滑移动到目标，而非直接跳转"},"ask":{"ja":"メニューのページ内リンクをスムーススクロールにして。固定ヘッダーの高さ分ずらして止めて。","en":"Make the menu's in-page links smooth scroll, stopping below the fixed header.","zh-Hans":"菜单页内链接使用平滑滚动，停在固定页头下方。"},"summary":{"ja":"メニューの「料金」を押すとページがなめらかに料金の欄まで動き、右下の上向きボタンを押すと同じように一番上へ戻る。","en":"Clicking \"Pricing\" in the menu glides the page down to the pricing section; the up arrow at the bottom right glides it back to the top.","zh-Hans":"点击菜单“价格”后页面平滑下滚至价格区，右下角向上箭头平滑返回顶部。"},"spec":{"ja":["0.9秒にメニューの「料金」をクリック。0.95〜2.0秒（1.05秒）でスクロール量 0→296px（easeInOut 3乗）","止まる位置 = 料金の欄の上端（330px）− 固定ヘッダーの高さ（34px）","スクロール量が60pxを超えると、右下に「ページの先頭へ」の丸ボタン（半径15）が40pxかけて現れる","3.1秒にそのボタンをクリック。3.15〜4.2秒で 296→0（easeInOut 3乗）","料金の欄に入っている間、メニューの「料金」を朱色にする"],"en":["At 0.9 s the \"Pricing\" menu item is clicked; scroll goes 0→296 px over 0.95–2.0 s (1.05 s, cubic ease-in-out).","Stop position = top of the pricing section (330 px) − fixed header height (34 px).","Once scroll passes 60 px, a round back-to-top button (radius 15) fades in over the next 40 px at the bottom right.","At 3.1 s that button is clicked; scroll goes 296→0 over 3.15–4.2 s (cubic ease-in-out).","While the pricing section is in view, \"Pricing\" in the menu turns orange."],"zh-Hans":["0.9 秒点击价格菜单；0.95–2.0 秒滚动从 0→296 px，持续 1.05 秒，采用三次缓入缓出。","停止位置 = 价格区顶部 330 px − 固定页头高度 34 px。","滚动超过 60 px 后，右下角半径 15 的返回顶部按钮在后续 40 px 内淡入。","3.1 秒点击返回顶部；3.15–4.2 秒滚动从 296→0，采用三次缓入缓出。","价格区可见时，菜单中的“价格”变为橙色。"]},"use":{"ja":"目次やメニューから同じページの中の欄へ移るとき、今どこへ動いたかを分かりやすくしたいとき。","en":"Use it when a menu or table of contents jumps within the same page, so the reader sees where they went.","zh-Hans":"适合页内导航或目录，让读者理解移动方向与位置。"},"tags":["smooth-scroll","scroll-behavior","anchor-link","in-page-link","back-to-top","navigation"]},{"id":"094","pack":"lp","no":"22","slug":"marquee","category":"loading-loops","width":539,"height":208,"cycle":4.8,"name":{"ja":"マーキー","en":"Marquee","zh-Hans":"无缝跑马灯"},"meaning":{"ja":"文字や画像が帯で流れ続ける","en":"Text or logos scroll across in an endless band","zh-Hans":"文字或标志沿条带持续循环滚动"},"ask":{"ja":"サービス名をマーキーで右から左へ流して。途切れずにループさせて、速さは1秒に80pxくらい。","en":"Run the service names in a marquee from right to left, looping without a gap, at about 80 px per second.","zh-Hans":"服务名称从右向左无缝跑马灯滚动，速度约每秒 80 px。"},"summary":{"ja":"濃紺の帯の中で、大きな英字のサービス名と朱色の点が、途切れずに左へ流れ続ける。","en":"Inside a navy band, large service names separated by orange dots keep moving to the left without a gap.","zh-Hans":"深蓝色条带中，大号服务名称以橙点分隔，持续向左移动，没有空隙。"},"spec":{"ja":["帯: 高さ58・濃紺・表示域の幅いっぱい。文字: 30px・太字・字間1px・白","4語（WEB DESIGN / BRANDING / MOTION / UI/UX）を1組とし、語の間は64px、その真ん中に朱色の点（半径6）","1周期（4.8秒）で1組の幅（この環境で約881px）だけ等速で左へ動かす。1組の幅を測って位置を 周期で折り返すので、つなぎ目が出ない","表示域の幅が埋まるまで同じ組をくり返して並べる"],"en":["Band: 58 tall, navy, full viewport width. Text: 30 px, heavy weight, 1 px letter spacing, white.","One set is four words (WEB DESIGN / BRANDING / MOTION / UI/UX), 64 px apart, with an orange dot (radius 6) in each gap.","Each cycle (4.8 s) moves left by the width of one set (about 881 px here) at constant speed. The set is measured and the offset wraps by that width, so there is no visible seam.","The set is repeated until the viewport width is filled."],"zh-Hans":["条带高 58、深蓝、视口全宽；文字为 30 px 粗体、字距 1 px、白色。","一组为四个词 WEB DESIGN / BRANDING / MOTION / UI/UX，间隔 64 px，每个间隙有半径 6 的橙点。","每 4.8 秒匀速左移一组的宽度，本例约 881 px；测量组宽并按组宽循环偏移，避免可见接缝。","重复整组直到铺满视口宽度。"]},"use":{"ja":"サービス名・取引先のロゴ・キャッチコピーを、にぎやかに見せたいとき。","en":"Use it to show service names, client logos or a tagline with energy.","zh-Hans":"适合有动感地展示服务名称、客户标志或标语。"},"tags":["marquee","ticker","infinite-loop","scrolling-text","logo-strip","band","loop"]},{"id":"095","pack":"lp","no":"23","slug":"animated-gradient","category":"loading-loops","width":539,"height":208,"cycle":4.8,"name":{"ja":"グラデーションアニメーション","en":"Animated gradient","zh-Hans":"动态渐变"},"meaning":{"ja":"背景の色の混ざり方が動き続ける","en":"Background colours keep drifting and blending","zh-Hans":"背景颜色持续漂移融合"},"ask":{"ja":"ファーストビューの背景をグラデーションアニメーションにして。朱色と青がゆっくり混ざり合うように、10秒で1周。","en":"Give the hero an animated gradient background: orange and blue slowly blending, one loop every 10 s.","zh-Hans":"首屏使用橙蓝缓慢融合的动态渐变背景，每十秒一轮。"},"summary":{"ja":"見出しの後ろで、朱色・薄い朱色・青・薄い青のぼんやりした色の塊がゆっくり回り、混ざり方が変わり続ける。","en":"Behind the headline, soft patches of orange, light orange, blue and light blue drift in circles and keep blending differently.","zh-Hans":"标题后方柔和的橙、浅橙、蓝、浅蓝色块沿圆弧漂移，持续形成不同混色。"},"spec":{"ja":["地は #FFF1EB。その上に円形のグラデーション4つ（中心の色→外側で透明・各不透明度0.85）","朱色（半径230）・薄い朱色 #FFB08F（210）・青（240）・薄い青 #9DB6FB（200）","各中心は楕円の上を4.8秒で1周する（横の半径 70・60・80・50、縦の半径 30・40・30・35、出だしの角度 0・2.1・4.2・1.0rad）","上に白の見出し（34px）とボタン。グラデーションだけが動く"],"en":["Base colour #FFF1EB, with four radial gradients on top (centre colour → transparent at the edge, each at 0.85 opacity).","Orange (radius 230), light orange #FFB08F (210), blue (240), light blue #9DB6FB (200).","Each centre travels an ellipse once per 4.8 s (x radii 70, 60, 80, 50; y radii 30, 40, 30, 35; start angles 0, 2.1, 4.2, 1.0 rad).","A white headline (34 px) and a button sit on top; only the gradient moves."],"zh-Hans":["底色 #FFF1EB，上叠四个径向渐变，中心为实色、边缘透明，每个透明度 0.85。","橙色半径 230，浅橙 #FFB08F 为 210，蓝色为 240，浅蓝 #9DB6FB 为 200。","各中心每 4.8 秒走完椭圆；横向半径 70, 60, 80, 50，纵向半径 30, 40, 30, 35，初始角 0, 2.1, 4.2, 1.0 rad。","上方叠加 34 px 白色标题和按钮，仅渐变运动。"]},"use":{"ja":"写真を使わずに、ファーストビューや見出しの背景に動きと華やかさを出したいとき。","en":"Use it to add movement and colour behind a hero or heading without using a photo.","zh-Hans":"适合无需照片的首屏或标题背景，增添颜色与轻微动感。"},"tags":["gradient","animated-gradient","mesh-gradient","background","hero","ambient","loop"]},{"id":"096","pack":"lp","no":"24","slug":"floating-animation","category":"loading-loops","width":539,"height":208,"cycle":4.8,"name":{"ja":"ふわふわアニメーション","en":"Floating animation","zh-Hans":"悬浮动画"},"meaning":{"ja":"飾りがゆっくり上下に浮き沈みする","en":"Elements bob gently up and down","zh-Hans":"元素轻柔地上下浮动"},"ask":{"ja":"ファーストビューのスマホの画像に、ふわふわアニメーションを付けて。上下8px、2.4秒で1往復。","en":"Give the phone image in the hero a floating animation: 8 px up and down, one bob every 2.4 s.","zh-Hans":"首屏手机图加悬浮动画，上下 8 px，每 2.4 秒起伏一次。"},"summary":{"ja":"見出しの横で、スマホの画像とハートの丸・評価の札が、それぞれ少しずつずれてゆっくり上下し、スマホの下の影も伸び縮みする。","en":"Next to the headline, a phone, a heart badge and a rating chip each bob gently out of step, and the shadow under the phone grows and shrinks.","zh-Hans":"标题旁的手机、心形徽章和评分标签错开节奏轻轻浮动，手机下方阴影随之缩放。"},"spec":{"ja":["スマホ（92×132）: y = −8·sin(2πt/2.4)（2.4秒で1往復・サイン波なので両端でゆっくり）","ハートの丸（半径20）: y = −6·sin(2πt/1.6 + 1.2)。評価の札（76×30）: y = −6·sin(2πt/2.4 + 2.4)","スマホの下の影（横54×縦6の楕円）: 大きさ・濃さを (1 + y/40) 倍にする。上がると小さく薄くなる","周期 2.4秒と1.6秒はどちらも4.8秒を割り切るので、つなぎ目が出ない"],"en":["Phone (92 × 132): y = −8·sin(2πt/2.4), one bob per 2.4 s; a sine slows at both ends.","Heart badge (radius 20): y = −6·sin(2πt/1.6 + 1.2). Rating chip (76 × 30): y = −6·sin(2πt/2.4 + 2.4).","Shadow under the phone (54 × 6 ellipse): size and opacity scale by (1 + y/40), so it shrinks and fades as the phone rises.","Both periods (2.4 s and 1.6 s) divide 4.8 s, so the loop has no seam."],"zh-Hans":["手机为 92 × 132，y = −8·sin(2πt/2.4)，每 2.4 秒起伏一次；正弦曲线使两端自然减速。","心形徽章半径 20，y = −6·sin(2πt/1.6 + 1.2)；评分标签为 76 × 30，y = −6·sin(2πt/2.4 + 2.4)。","手机阴影为 54 × 6 椭圆，尺寸和透明度乘以 (1 + y/40)，手机升高时阴影缩小变淡。","2.4 秒和 1.6 秒两个周期都能整除 4.8 秒，循环无接缝。"]},"use":{"ja":"アプリやサービスの画像、アイコンなどの飾りに、静かな動きを足したいとき。","en":"Use it to add quiet motion to product images, app mockups or decorative icons.","zh-Hans":"适合产品图片、应用模型和装饰图标的轻量持续动效。"},"tags":["floating","float","bob","hover-animation","keyframes","translatey","decoration","loop"]},{"id":"097","pack":"photo","no":"01","slug":"backlighting","category":"lighting","width":539,"height":208,"cycle":5,"name":{"ja":"逆光","en":"Backlighting","zh-Hans":"逆光"},"meaning":{"ja":"被写体の真後ろから光を当てる","en":"The light source sits behind the subject","zh-Hans":"光源位于主体后方"},"ask":{"ja":"草原に立つ人物を逆光で。夕日を頭の真後ろに置き、髪の輪郭が光ってふんわりとかすむように。","en":"Backlit portrait of a person in a meadow, the low sun right behind their head, glowing hair outline and soft haze.","zh-Hans":"草地逆光人像，低位太阳在人物头后，发丝轮廓发亮，带柔和光雾。"},"summary":{"ja":"画面の外にあった太陽が人物の頭の真後ろへ回り込む。胸像の縁が細く光り、全体に淡い光の色がかかり、カメラ側の体は暗く沈む。","en":"The sun moves from outside the frame to directly behind the person's head; a thin bright edge appears around the figure, a pale warm haze covers the frame and the side facing the camera darkens.","zh-Hans":"太阳从画面外移动到头后，人物边缘出现细亮边，暖色薄雾铺满画面，朝向相机的一面变暗。"},"spec":{"ja":["場面①: 地平線（y150）の前に胸から上の人物（頭の中心 x270, y78・半径29px、顔・髪なし）。光はアンバー #FFC75A の平らな面、影は一段濃い #33405A","太陽: 半径20px。左上の画面外（x40, y−40）から頭の真後ろ（x270, y56）へ。周りに半径2.6倍・1.7倍の平らな光の輪（#FFE3A3、35%・60%）","輪郭: 胸像の形を幅7pxの線でなぞってから中を塗り、外側3.5pxの光の縁だけを残す","人物 #4D5A75 → #33405A。空 #FAF9F7 → #FFF4DC、全体に #FFE3A3 を22%重ねる","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 1: a head-and-shoulders figure in front of a horizon at y 150 (head centre x 270, y 78, radius 29 px, no face or hair). light is a flat amber #FFC75A shape, shadow a flat #33405A one","Sun: radius 20 px, from outside the frame (top left, x 40, y −40) to directly behind the head (x 270, y 56), with flat rings of 2.6× and 1.7× the radius (#FFE3A3 at 35% and 60%)","Outline: the figure is stroked with a 7 px line and then filled, leaving a 3.5 px bright edge outside it","Figure #4D5A75 → #33405A; sky #FAF9F7 → #FFF4DC; #FFE3A3 laid over the whole frame at 22%","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 1：地平线 y 150 前的头肩人物，头部中心 x 270、y 78、半径 29 px，不绘制五官和头发。 明部为平涂琥珀色 #FFC75A，暗部为平涂 #33405A。","太阳半径 20 px，从左上画外 (x 40, y −40) 移至头后 (x 270, y 56)；平涂光环半径为太阳的 2.6× 和 1.7×，颜色 #FFE3A3，透明度分别 35% 和 60%。","先以 7 px 线描人物再填充，在外侧留下 3.5 px 亮边。","人物 #4D5A75 → #33405A，天空 #FAF9F7 → #FFF4DC；全画面叠加透明度 22% 的 #FFE3A3。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"やわらかく明るい人物写真や、光に包まれた雰囲気を出したいとき。","en":"For airy, glowing portraits or any image that should feel bathed in light.","zh-Hans":"适合轻盈、通透的人像或沐浴在光线中的画面。"},"tags":["backlighting","backlit","contre-jour","sun behind","haze","glow","halo"]},{"id":"098","pack":"photo","no":"02","slug":"rim-light","category":"lighting","width":539,"height":208,"cycle":5,"name":{"ja":"リムライト","en":"Rim light","zh-Hans":"轮廓光"},"meaning":{"ja":"後ろからの光で輪郭だけを光らせる","en":"A light from behind that outlines the subject's edge","zh-Hans":"后方光源勾勒主体边缘"},"ask":{"ja":"黒背景の人物に、斜め後ろ左右からリムライト。顔は暗いままで、頭と肩の輪郭だけ細く光らせて。","en":"Portrait on a black background with rim lights from both rear sides; the face stays dark and only the outline of the head and shoulders glows.","zh-Hans":"黑背景人像，后方两侧布轮廓光，面部保持暗，只照亮头肩外轮廓。"},"summary":{"ja":"周りが暗く落ち、斜め後ろ左右の2灯で、暗い人物の頭と肩の両側にだけ細い光の縁が出る。右下の図で2灯の位置を示す。","en":"The surroundings go dark and two lights behind the person, left and right, draw thin bright edges only along both sides of the head and shoulders; the plan at the bottom right shows where the two lights are.","zh-Hans":"周围变暗，后方左右两灯只在头肩两边勾出细亮边，右下角示意灯位。"},"spec":{"ja":["場面①: 地平線（y150）の前に胸から上の人物（頭の中心 x270, y78・半径29px、顔・髪なし）。","背景: 明るい場面 → 暗い場面（空 #2B2D33、地面 #24252A）。人物 #4D5A75 → #1F2128","光の縁: 胸像と同じ形をアンバー #FFC75A で左右に3.5px・上に2.5pxずらして2枚、暗い胸像の後ろに置く（縁の幅3.5px）","右下の配置図（66×66px）: 光は真上から見て ±135°（斜め後ろ左右）。右上の表示「±135°」","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 1: a head-and-shoulders figure in front of a horizon at y 150 (head centre x 270, y 78, radius 29 px, no face or hair). ","Background: light scene → dark scene (sky #2B2D33, ground #24252A); figure #4D5A75 → #1F2128","Bright edges: two copies of the figure in amber #FFC75A, shifted 3.5 px left and right and 2.5 px up, placed behind the dark figure (3.5 px wide edges)","Plan at the bottom right (66×66 px): lights at ±135° seen from above (behind, left and right); top-right readout \"±135°\"","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 1：地平线 y 150 前的头肩人物，头部中心 x 270、y 78、半径 29 px，不绘制五官和头发。","亮场变为暗场，天空 #2B2D33、地面 #24252A；人物 #4D5A75 → #1F2128。","将人物复制两份，填琥珀色 #FFC75A，分别左右偏移 3.5 px、上移 2.5 px，放在暗人物后方，形成宽 3.5 px 的亮边。","右下角俯视灯位图为 66×66 px；两灯在后方左右 ±135°，右上角显示“±135°”。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"暗い背景から人物や商品を切り離して、形をくっきり見せたいとき。","en":"To separate a person or product from a dark background and show its shape.","zh-Hans":"适合让人物或产品从暗背景中分离，并展示形状。"},"tags":["rim light","rim lighting","edge light","backlight","kicker","outline","studio"],"aliases":{"zh-Hans":["边缘光","轮廓光"]}},{"id":"099","pack":"photo","no":"03","slug":"silhouette","category":"lighting","width":539,"height":208,"cycle":5,"name":{"ja":"シルエット","en":"Silhouette","zh-Hans":"剪影"},"meaning":{"ja":"明るい空を背に、被写体を黒い形だけで見せる","en":"The subject shows as a black shape against a bright sky","zh-Hans":"主体在亮天空前呈现为暗色轮廓"},"ask":{"ja":"夕焼けの浜辺でジャンプする人物をシルエットで。露出は空に合わせて、人物とヤシの木は真っ黒に。","en":"Silhouette of a person jumping on a beach at sunset; expose for the sky so the person and the palm tree turn pure black.","zh-Hans":"夕阳海滩上的跳跃人物剪影，按天空曝光，让人物和棕榈树呈纯黑。"},"summary":{"ja":"露出を明るい夕空に合わせていくと、人物・建物・街灯・木が細部のない黒い形になり、空だけが明るく残る。","en":"As the exposure is set for the bright evening sky, the person, buildings, lamp and tree turn into flat black shapes with no detail and only the sky stays bright.","zh-Hans":"按明亮晚霞曝光后，人物、建筑、路灯和树变成无细节的暗色块，只保留天空亮度。"},"spec":{"ja":["場面①: 地平線（y150）の前に胸から上の人物（頭の中心 x270, y78・半径29px、顔・髪なし）。","空: #FAF9F7 → 上 #FFEDC4・地平線近くの帯（y92〜150）#FFCF73","空以外の形はすべて #2A2D36、遠くの丘は #4A4546。人物は #22252D","太陽: 半径20px、x404 で y60 → y128 へ沈み、丘に半分隠れる","右上の表示: ±0.0 EV → −2.0 EV","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 1: a head-and-shoulders figure in front of a horizon at y 150 (head centre x 270, y 78, radius 29 px, no face or hair). ","Sky: #FAF9F7 → #FFEDC4 at the top and a #FFCF73 band near the horizon (y 92–150)","Everything but the sky becomes #2A2D36, the far hills #4A4546; the figure #22252D","Sun: radius 20 px at x 404, sinking from y 60 to y 128, half hidden by the hills","Top-right readout: ±0.0 EV → −2.0 EV","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 1：地平线 y 150 前的头肩人物，头部中心 x 270、y 78、半径 29 px，不绘制五官和头发。","天空从 #FAF9F7 变为顶部 #FFEDC4，地平线附近 y 92–150 为 #FFCF73 色带。","除天空外都变为 #2A2D36，远山为 #4A4546，人物为 #22252D。","太阳半径 20 px，x 404，y 从 60 下沉至 128，被山丘遮住一半。","右上角显示曝光补偿 ±0.0 EV → −2.0 EV。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"夕日や窓の光を背景に、形とポーズだけで印象を残したいとき。","en":"When the shape and pose should carry the picture, against a sunset or a bright window.","zh-Hans":"适合以形状和姿态表达内容，背景可用日落或明亮窗户。"},"tags":["silhouette","backlit","sunset","contre-jour","black shape","underexposed"]},{"id":"100","pack":"photo","no":"04","slug":"split-lighting","category":"lighting","width":539,"height":208,"cycle":5,"name":{"ja":"スプリットライティング","en":"Split lighting","zh-Hans":"分割光"},"meaning":{"ja":"真横からの光で顔を半分ずつ明暗に分ける","en":"Light from the side splits the face into lit and dark halves","zh-Hans":"侧光将面部分成明暗两半"},"ask":{"ja":"男性の横からスプリットライティングで。光は真横90°、鼻筋を境に顔の左半分は影に沈めて。","en":"Portrait with split lighting: the light at 90° to the side, the face divided down the nose, the far half in shadow.","zh-Hans":"人像使用分割光，灯位在侧面 90°，沿鼻梁分割面部，远侧一半处于阴影。"},"summary":{"ja":"光が正面寄り（20°）から真横（90°）へ回り、頭の影が三日月から半分へ広がって、顔が鼻筋の位置で縦に明暗2つに分かれる。","en":"The light swings from near the front (20°) to directly at the side (90°); the shadow on the head grows from a crescent to exactly half, splitting the face down the middle.","zh-Hans":"灯从接近正面的 20° 移至正侧面 90°，头部阴影由月牙扩大到一半，沿中线分割脸部。"},"spec":{"ja":["場面①: 地平線（y150）の前に胸から上の人物（頭の中心 x270, y78・半径29px、顔・髪なし）。背景は一段暗い場面（空 #E7E5E1）へ","光: 画面の左から。角度 20° → 90°（右下の配置図と右上の表示「90° · ↑0°」）","頭: 明暗の境 x = 270 + cos(角度)·√(29² − dy²) より右が影 #33405A、左が光 #FFC75A。90°で中心線の真っすぐな境","胴（半幅56px）: 境 x = 270 + cos(角度)·56 より右が影、左端の帯が光","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 1: a head-and-shoulders figure in front of a horizon at y 150 (head centre x 270, y 78, radius 29 px, no face or hair). the background drops to a darker scene (sky #E7E5E1)","Light: from the left of the frame, angle 20° → 90° (plan at the bottom right, top-right readout \"90° · ↑0°\")","Head: right of x = 270 + cos(angle)·√(29² − dy²) is shadow #33405A, left is light #FFC75A; at 90° the edge is the straight centre line","Body (half-width 56 px): right of x = 270 + cos(angle)·56 is shadow, a strip on the left edge is lit","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 1：地平线 y 150 前的头肩人物，头部中心 x 270、y 78、半径 29 px，不绘制五官和头发。 背景变暗，天空为 #E7E5E1。","光从画面左侧照入，角度 20° → 90°；右下为灯位图，右上显示“90° · ↑0°”。","头部：x = 270 + cos(angle)·√(29² − dy²) 右侧为阴影 #33405A，左侧为亮部 #FFC75A；90° 时明暗边界为中心直线。","身体半宽 56 px；x = 270 + cos(angle)·56 的右侧为暗部，左边缘有亮带。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"強さや緊張感のある人物写真にしたいとき。","en":"For dramatic, tense or moody portraits.","zh-Hans":"适合戏剧化、紧张或情绪浓重的人像。"},"tags":["split lighting","side light","portrait lighting","half face","dramatic","chiaroscuro"],"aliases":{"zh-Hans":["侧光","阴阳光"]}},{"id":"101","pack":"photo","no":"05","slug":"rembrandt-lighting","category":"lighting","width":539,"height":208,"cycle":5,"name":{"ja":"レンブラントライティング","en":"Rembrandt lighting","zh-Hans":"伦勃朗光"},"meaning":{"ja":"影側の頬に三角形の光が残る斜め上からの光","en":"High side light that leaves a lit triangle on the shadow cheek","zh-Hans":"高位侧光在暗侧脸颊留下三角亮区"},"ask":{"ja":"老人の肖像をレンブラントライティングで。光は斜め45°・上から、影側の頬に小さな三角形の光を残して。","en":"Portrait of an old man in Rembrandt lighting: light from 45° to the side and above, leaving a small triangle of light on the shadow-side cheek.","zh-Hans":"老人肖像用伦勃朗光，从侧上方 45° 照射，暗侧脸颊保留小三角亮区。"},"summary":{"ja":"斜め45°・上45°の光が入り、顔の右側が影に沈む中で、影側の頬にだけ小さな逆三角形の光が残る。","en":"A light 45° to the side and 45° up comes on; the right side of the face falls into shadow except for a small inverted triangle of light on the shadow-side cheek.","zh-Hans":"侧面 45°、上方 45° 的灯亮起，右半脸进入阴影，暗侧脸颊只留一个倒三角亮区。"},"spec":{"ja":["場面①: 地平線（y150）の前に胸から上の人物（頭の中心 x270, y78・半径29px、顔・髪なし）。背景は一段暗い場面（空 #E7E5E1）へ","頭: x = 270 + 0.04·29 より右が影 #33405A、左が光 #FFC75A","光の三角形: (x270+0.24R, y78−0.12R)・(x270+0.7R, y78−0.12R)・(x270+0.24R, y78+0.5R)、R=29（幅約13px・高さ約18px）。光の面との間に約6pxの影の帯","胴: 左端（中心から−0.45×56px より左）が光、右（+0.3×56px より右）が影。右下の配置図で光は45°、右上の表示「45° · ↑45°」","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 1: a head-and-shoulders figure in front of a horizon at y 150 (head centre x 270, y 78, radius 29 px, no face or hair). the background drops to a darker scene (sky #E7E5E1)","Head: right of x = 270 + 0.04·29 is shadow #33405A, left is light #FFC75A","Light triangle: (x 270+0.24R, y 78−0.12R), (x 270+0.7R, y 78−0.12R), (x 270+0.24R, y 78+0.5R) with R = 29 (about 13 px wide, 18 px tall), separated from the lit side by a shadow strip about 6 px wide","Body: lit left of centre −0.45×56 px, shadow right of +0.3×56 px; plan shows the light at 45°, top-right readout \"45° · ↑45°\"","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 1：地平线 y 150 前的头肩人物，头部中心 x 270、y 78、半径 29 px，不绘制五官和头发。 背景变暗，天空为 #E7E5E1。","头部 x = 270 + 0.04·29 右侧为阴影 #33405A，左侧为亮部 #FFC75A。","亮三角顶点为 (x 270+0.24R, y 78−0.12R)、(x 270+0.7R, y 78−0.12R)、(x 270+0.24R, y 78+0.5R)，R = 29，约宽 13 px、高 18 px；与主亮面间隔约宽 6 px 的阴影带。","身体中心左侧 −0.45×56 px 以外为亮部，右侧 +0.3×56 px 以外为暗部；灯位图为 45°，右上显示“45° · ↑45°”。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"絵画のような重みと立体感のある人物写真にしたいとき。","en":"For portraits with a painterly, sculpted, classic look.","zh-Hans":"适合具有绘画、雕塑和古典质感的人像。"},"tags":["rembrandt lighting","portrait lighting","triangle","45 degree light","chiaroscuro","painterly"],"aliases":{"zh-Hans":["三角光"]}},{"id":"102","pack":"photo","no":"06","slug":"butterfly-lighting","category":"lighting","width":539,"height":208,"cycle":5,"name":{"ja":"バタフライライティング","en":"Butterfly lighting","zh-Hans":"蝴蝶光"},"meaning":{"ja":"正面の高い位置から当て、鼻の下に蝶形の影","en":"High frontal light that casts a butterfly shadow under the nose","zh-Hans":"正前方高位光在鼻下形成蝴蝶状阴影"},"ask":{"ja":"女性のビューティーポートレートをバタフライライティングで。光は顔の正面・真上寄り45°、鼻の下に小さな蝶の形の影を。","en":"Beauty portrait with butterfly lighting: light straight in front and 45° above, a small butterfly-shaped shadow under the nose.","zh-Hans":"美妆人像用蝴蝶光，灯在正前方上仰 45°，鼻下留小型蝴蝶状阴影。"},"summary":{"ja":"顔の正面・高い位置からの光が入り、顔は左右対称に明るくなり、あごの下にだけ左右対称の小さな影が落ちる。","en":"A light in front of the face and high above comes on; the face lights evenly on both sides and only a small symmetrical shadow falls under the chin.","zh-Hans":"前方高位灯亮起，面部左右均匀受光，演示仅在下巴下方显示小而对称的阴影。"},"spec":{"ja":["場面①: 地平線（y150）の前に胸から上の人物（頭の中心 x270, y78・半径29px、顔・髪なし）。背景は一段暗い場面（空 #E7E5E1）へ","頭: 全体が光 #FFC75A（影なし）","あごの下の影: 楕円（中心 y78+1.06R・横0.72R・縦0.38R、R=29 → 約21×11px）、色 #33405A","胴: 中心から ±0.8×56px が光、外側の細い帯は元の色。右下の配置図で光はカメラ側（0°）、右上の表示「0° · ↑45°」","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 1: a head-and-shoulders figure in front of a horizon at y 150 (head centre x 270, y 78, radius 29 px, no face or hair). the background drops to a darker scene (sky #E7E5E1)","Head: entirely lit #FFC75A (no shadow side)","Shadow under the chin: an ellipse centred at y 78+1.06R, 0.72R wide and 0.38R tall (R = 29, about 21×11 px), colour #33405A","Body: lit within ±0.8×56 px of the centre, thin outer strips keep the base colour; plan shows the light on the camera side (0°), top-right readout \"0° · ↑45°\"","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 1：地平线 y 150 前的头肩人物，头部中心 x 270、y 78、半径 29 px，不绘制五官和头发。 背景变暗，天空为 #E7E5E1。","头部完全填充亮色 #FFC75A，无侧面阴影。","下巴下方阴影为椭圆，中心 y 78+1.06R，宽 0.72R、高 0.38R；R = 29，约 21×11 px，颜色 #33405A。","身体中心 ±0.8×56 px 内为亮部，外侧细带保留底色；灯位图在相机一侧 0°，右上显示“0° · ↑45°”。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"顔立ちをきれいに見せたい美容・ファッションの人物写真で。","en":"For beauty and fashion portraits that flatter the face.","zh-Hans":"适合美妆和时尚人像，修饰面部轮廓。"},"tags":["butterfly lighting","paramount lighting","beauty lighting","portrait lighting","overhead light","glamour"],"aliases":{"zh-Hans":["派拉蒙光","美人光"]}},{"id":"103","pack":"photo","no":"07","slug":"golden-hour","category":"lighting","width":539,"height":208,"cycle":5,"name":{"ja":"ゴールデンアワー","en":"Golden hour","zh-Hans":"黄金时刻"},"meaning":{"ja":"日没前・日の出後の低く赤みのある光","en":"The low, warm light just after sunrise or before sunset","zh-Hans":"日出后或日落前的低角度暖光"},"ask":{"ja":"草原の人物をゴールデンアワーの光で。太陽は地平線近く、影が長く伸びて全体が橙色に。","en":"A person in a field at golden hour: the sun near the horizon, long shadows, everything warm orange.","zh-Hans":"黄金时刻的田野人物，太阳贴近地平线，长阴影，整体暖橙色。"},"summary":{"ja":"太陽が地平線近くまで下り、空と地面が橙に染まり、人物の左側が光り、街灯と木の影が右へ長く伸びる。","en":"The sun drops to just above the horizon; sky and ground turn orange, the left side of the person lights up and the shadows of the lamp and tree stretch far to the right.","zh-Hans":"太阳降到地平线上方，天空和地面变橙，人物左侧受光，路灯与树影向右拉长。"},"spec":{"ja":["場面①: 地平線（y150）の前に胸から上の人物（頭の中心 x270, y78・半径29px、顔・髪なし）。","太陽: 半径18px、(x110, y−30) → (x96, y136)。丘に半分隠れる","色: 空 #FAF9F7 → 上 #FFE8BC・地平線近く #FFCF80、地面 #F1F0EE → #F6DDB0。人物の光 #FFB547・影 #3E3650","頭: 光は左から約66°、境より右が影。胴は左側が光・右側が影","影: 街灯と木の根元から右へ、長さ 0 → 150px（色 #DDAA6E）。右上の時刻 12:00 → 17:40","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 1: a head-and-shoulders figure in front of a horizon at y 150 (head centre x 270, y 78, radius 29 px, no face or hair). ","Sun: radius 18 px, from (x 110, y −30) to (x 96, y 136), half hidden by the hills","Colour: sky #FAF9F7 → #FFE8BC at the top and #FFCF80 near the horizon, ground #F1F0EE → #F6DDB0; light on the figure #FFB547, shadow #3E3650","Head: light from the left at about 66°, shadow right of the edge; body lit on the left, shadow on the right","Shadows: from the foot of the lamp and tree to the right, length 0 → 150 px (#DDAA6E); top-right time 12:00 → 17:40","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 1：地平线 y 150 前的头肩人物，头部中心 x 270、y 78、半径 29 px，不绘制五官和头发。","太阳半径 18 px，从 (x 110, y −30) 移至 (x 96, y 136)，被山丘遮住一半。","天空 #FAF9F7 → 顶部 #FFE8BC、地平线附近 #FFCF80；地面 #F1F0EE → #F6DDB0，人物亮部 #FFB547、暗部 #3E3650。","头部从左侧约 66° 受光，边界右侧为阴影；身体左亮右暗。","路灯和树的影子从根部向右延伸，长度 0 → 150 px，颜色 #DDAA6E；右上时间 12:00 → 17:40。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"あたたかく、なつかしく、やさしい雰囲気の写真にしたいとき。","en":"For warm, nostalgic, gentle-feeling images.","zh-Hans":"适合温暖、怀旧、柔和的画面。"},"tags":["golden hour","magic hour","sunset light","warm light","long shadows","low sun"],"aliases":{"zh-Hans":["金色时刻"]}},{"id":"104","pack":"photo","no":"08","slug":"blue-hour","category":"lighting","width":539,"height":208,"cycle":5,"name":{"ja":"ブルーアワー","en":"Blue hour","zh-Hans":"蓝调时刻"},"meaning":{"ja":"日没後・日の出前の、空が深い青になる時間","en":"The time after sunset or before sunrise when the sky turns deep blue","zh-Hans":"日落后或日出前天空呈深蓝的时段"},"ask":{"ja":"港町の夜景をブルーアワーで。空は深い青、ビルの窓と街灯の暖かい光が水面に映るように。","en":"Harbour city at blue hour: deep blue sky, warm windows and streetlights reflected in the water.","zh-Hans":"港口城市蓝调时刻，深蓝天空，暖色窗灯和街灯倒映水中。"},"summary":{"ja":"太陽が沈みきると、空が深い青の2段になり、建物の窓と街灯がアンバーに灯り、人物は青い影の形になる。","en":"Once the sun has set, the sky turns two bands of deep blue, the windows and street lamp come on in amber and the person becomes a dark blue shape.","zh-Hans":"日落后天空变成两段深蓝，窗户与路灯亮起琥珀色，人物变为深蓝轮廓。"},"spec":{"ja":["場面①: 地平線（y150）の前に胸から上の人物（頭の中心 x270, y78・半径29px、顔・髪なし）。","太陽: 半径18px、x120 で y40 → y190 へ沈む（効果の量が70%に達するまで）。40〜80%で消える","色: 空 上 #2C3B5E・地平線近く #4A6191、地面 #283452、建物 #34446B、人物 #1C2439","灯り: 窓の3つに1つと街灯の電球が #FFC75A。電球の周りに半径13px・8pxの平らな光の輪（#FFE3A3、35%・60%）","右上の時刻 12:00 → 18:35","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 1: a head-and-shoulders figure in front of a horizon at y 150 (head centre x 270, y 78, radius 29 px, no face or hair). ","Sun: radius 18 px at x 120, sinking from y 40 to y 190 while the effect reaches 70%, fading out between 40% and 80%","Colour: sky #2C3B5E at the top and #4A6191 near the horizon, ground #283452, buildings #34446B, figure #1C2439","Lights: one window in three and the lamp bulb turn #FFC75A; flat rings of 13 px and 8 px (#FFE3A3 at 35% and 60%) around the bulb","Top-right time 12:00 → 18:35","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 1：地平线 y 150 前的头肩人物，头部中心 x 270、y 78、半径 29 px，不绘制五官和头发。","太阳半径 18 px，x 120；效果到 70% 时，y 从 40 下沉至 190，在 40% 到 80% 之间淡出。","天空顶部 #2C3B5E、近地平线 #4A6191，地面 #283452，建筑 #34446B，人物 #1C2439。","每三扇窗有一扇与灯泡变为 #FFC75A；灯泡外有 13 px 和 8 px 平涂光环，#FFE3A3，透明度分别 35% 与 60%。","右上时间 12:00 → 18:35。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"夜景を、真っ暗になる前の青い空と街の灯りの両方で見せたいとき。","en":"For city and night scenes that need both a blue sky and glowing lights.","zh-Hans":"适合同时保留蓝色天空和发光灯火的城市夜景。"},"tags":["blue hour","twilight","dusk","night city","cityscape","deep blue sky"]},{"id":"105","pack":"photo","no":"09","slug":"bokeh","category":"lens-camera","width":539,"height":208,"cycle":5,"name":{"ja":"ボケ","en":"Bokeh","zh-Hans":"散景光斑"},"meaning":{"ja":"ピントの外の点光源が丸くやわらかくぼける","en":"Out-of-focus points of light melt into soft discs","zh-Hans":"失焦点光源化为柔和圆形光斑"},"ask":{"ja":"夜の街に立つ人物を、背景の街の灯りが大きな丸いボケになるように。f/1.4で、人物にはピントを合わせて。","en":"Person in a city at night with big round bokeh from the street lights behind; f/1.4, focus on the person.","zh-Hans":"夜城人物，身后街灯形成大圆散景，f/1.4，对焦人物。"},"summary":{"ja":"絞りを開けていくと、ピントの合った人物はそのまま、背景の建物はぼけ、街灯と遠くの灯りが大きく薄い光の丸に広がる。","en":"As the aperture opens, the in-focus person stays sharp, the buildings behind soften and the street lamps and distant lights spread into large, pale discs.","zh-Hans":"光圈开大后，人物保持清晰，后方建筑柔化，街灯和远处光点扩成浅色大圆斑。"},"spec":{"ja":["場面②: 街角。奥に建物の列・木・街灯（x114, 292, 494）、道は y132〜162、人物は左手前（足元 x176, y200・身長124px）。背景は一段暗い場面（空 #E7E5E1）へ","背景（人物以外）のぼけ: 0 → 6px","灯り: 街灯3つ（大きさ1.25）と、横45pxおきの12個（高さ y44〜114・大きさ0.6〜1.2、固定シード）。丸の半径 = (2.4 + 15 × 効果の量) × 大きさ","丸: 不透明度 100% → 55%、街灯はアンバー #FFC75A・遠くの灯りは #FFE3A3、縁にアンバーの1.2pxの線","人物はくっきりのまま。右上の絞り f/16 → f/1.4（8段）","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 2: a street corner; buildings, trees and street lamps (x 114, 292, 494) behind a road at y 132–162; the person stands front left (feet at x 176, y 200, 124 px tall). the background drops to a darker scene (sky #E7E5E1)","Background blur (everything but the person): 0 → 6 px","Lights: the three lamps (size 1.25) and 12 more spaced 45 px apart (y 44–114, size 0.6–1.2, fixed seed); disc radius = (2.4 + 15 × effect) × size","Discs: opacity 100% → 55%, lamps amber #FFC75A, distant lights #FFE3A3, with a 1.2 px amber rim","The person stays sharp; top-right aperture f/16 → f/1.4 (8 stops)","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 2：街角的建筑、树和路灯位于 y 132–162 的道路后方，路灯 x 114, 292, 494；人物站在左前方，脚底 x 176、y 200，高 124 px。 背景变暗，天空 #E7E5E1。","人物以外的背景模糊从 0 → 6 px。","三盏灯尺寸 1.25，另有 12 个间隔 45 px 的光点，y 44–114，尺寸 0.6–1.2，固定随机种子；光斑半径 = (2.4 + 15 × 效果强度) × 尺寸。","圆斑透明度 100% → 55%；路灯为琥珀色 #FFC75A，远灯 #FFE3A3，带 1.2 px 琥珀色边缘。","人物保持清晰；右上光圈 f/16 → f/1.4，共 8 挡。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"人物や商品を背景から浮かせ、夜や祝祭のやわらかな雰囲気を出したいとき。","en":"To lift a person or product off the background and add a soft, festive night mood.","zh-Hans":"适合突出人物或产品，并增添柔和、热闹的夜间氛围。"},"tags":["bokeh","shallow depth of field","background blur","wide aperture","f/1.4","out of focus","lights"],"aliases":{"zh-Hans":["虚化","焦外","光斑"]}},{"id":"106","pack":"photo","no":"10","slug":"tilt-shift","category":"lens-camera","width":539,"height":208,"cycle":5,"name":{"ja":"ティルトシフト","en":"Tilt-shift","zh-Hans":"移轴微缩效果"},"meaning":{"ja":"上下をぼかして本物の町を模型のように見せる","en":"Blur top and bottom so a real scene looks like a miniature","zh-Hans":"上下模糊，让真实场景像微缩模型"},"ask":{"ja":"高い所から見下ろした町をティルトシフトで。中央の帯だけピントを合わせて上下を強くぼかし、色を濃くしてミニチュア風に。","en":"High-angle view of a town with a tilt-shift look: a narrow sharp band across the middle, strong blur above and below, boosted colour, like a miniature model.","zh-Hans":"俯拍城镇做移轴效果，中间窄带清晰，上下强模糊，色彩增强，像微缩模型。"},"summary":{"ja":"街の上下の帯がぼけていき、道と車と小さな人たちの並ぶ中央の帯だけにピントが残って、模型の街のように見える。","en":"The top and bottom bands of the street blur while only the middle band with the road, the car and the small people stays in focus, so the street looks like a model.","zh-Hans":"街景上下模糊，只有中间道路、汽车和小人物清晰，使街道像模型。"},"spec":{"ja":["街角（奥に建物の列・木・街灯、道は y132〜162）から手前の人物を外し、歩道に身長23〜26pxの小さな人4人（足元 y172）を置く。車は5秒で x−60 → 600 を走る","ピントの帯: y66〜176 はくっきり","ぼけ: y0〜42 と y190〜208 は 0 → 7px、y42〜66 と y176〜190 は 0 → 3px","帯の境に破線（6px線・5px間・#8E8E93・75%）","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["The street corner (buildings, trees and lamps behind a road at y 132–162) without the large person; four small people 23–26 px tall stand on the pavement (feet at y 172); the car drives from x −60 to 600 every 5 s","Focus band: y 66–176 stays sharp","Blur: y 0–42 and y 190–208 go 0 → 7 px; y 42–66 and y 176–190 go 0 → 3 px","Dashed lines on the band edges (6 px dash, 5 px gap, #8E8E93 at 75%)","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["街角有建筑、树和路灯，道路 y 132–162，无前景大人物；四个小人物高 23–26 px，站在人行道上，脚底 y 172；汽车每 5 秒从 x −60 行驶到 600。","清晰带为 y 66–176。","模糊：y 0–42 与 y 190–208 从 0 → 7 px，y 42–66 与 y 176–190 从 0 → 3 px。","清晰带边缘有虚线，线段 6 px、间隔 5 px，颜色 #8E8E93、透明度 75%。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"街や行事を、かわいらしい模型の世界のように見せたいとき。","en":"To make a city or event look like a toy model world.","zh-Hans":"适合把城市或活动现场表现为玩具模型世界。"},"tags":["tilt-shift","miniature","miniature effect","fake miniature","selective focus","toy town","focus band"]},{"id":"107","pack":"photo","no":"11","slug":"long-exposure","category":"lens-camera","width":539,"height":208,"cycle":5,"name":{"ja":"長時間露光","en":"Long exposure","zh-Hans":"长曝光"},"meaning":{"ja":"シャッターを長く開け、動く光を線にする","en":"Keep the shutter open long so moving lights become lines","zh-Hans":"延长快门时间，让移动光源形成光轨"},"ask":{"ja":"夜の道路を長時間露光で。シャッター8秒で、車の形は消えて、ヘッドライトとテールランプだけが白と赤の光の線になるように。","en":"Night road as a long exposure, 8-second shutter: the cars disappear and only their headlights and tail lights remain as white and red trails.","zh-Hans":"夜间道路做长曝光，快门八秒，车辆消失，只留白色车头灯和红色尾灯光轨。"},"summary":{"ja":"街が夜になり、走る車の本体は薄く消えていき、後ろに赤い尾灯の線が伸び、反対車線には白とアンバーの光の線が通る。","en":"The street turns to night; the moving car fades to almost nothing, a red tail-light line stretches out behind it and white and amber lines run along the opposite lane.","zh-Hans":"街景变夜色，移动车辆几乎消失，身后拉出红色尾灯线，对向车道出现白色与琥珀色光轨。"},"spec":{"ja":["場面②: 街角。奥に建物の列・木・街灯（x114, 292, 494）、道は y132〜162、人物は左手前（足元 x176, y200・身長124px）。色は夜（空 #2C3B5E、窓の3つに1つが #FFC75A）へ","車: 5秒で x−60 → 600。本体の不透明度 100% → 10%","尾灯の線: x−60 から車の位置まで。y145 に #FF5B4D 2.6px、y149 に #FF8A6E 1.4px","反対車線の線: 画面幅いっぱい。y135 #FFE9B8 2.6px、y138.5 #FFC75A 1.6px、y141.5 #FFE9B8 1.2px（効果の量で濃くなる）","右上のシャッター速度 1/250 → 8″","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 2: a street corner; buildings, trees and street lamps (x 114, 292, 494) behind a road at y 132–162; the person stands front left (feet at x 176, y 200, 124 px tall). colours go to night (sky #2C3B5E, one window in three #FFC75A)","Car: x −60 → 600 every 5 s; body opacity 100% → 10%","Tail-light line: from x −60 to the car: #FF5B4D 2.6 px at y 145 and #FF8A6E 1.4 px at y 149","Opposite lane: full-width lines #FFE9B8 2.6 px at y 135, #FFC75A 1.6 px at y 138.5 and #FFE9B8 1.2 px at y 141.5 (they fade in with the effect)","Top-right shutter speed 1/250 → 8″","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 2：街角的建筑、树和路灯位于 y 132–162 的道路后方，路灯 x 114, 292, 494；人物站在左前方，脚底 x 176、y 200，高 124 px。 转为夜色，天空 #2C3B5E，每三扇窗一扇为 #FFC75A。","汽车每 5 秒从 x −60 行驶至 600，车身透明度 100% → 10%。","尾灯线从 x −60 延伸到汽车位置：y 145 为 #FF5B4D、宽 2.6 px，y 149 为 #FF8A6E、宽 1.4 px。","对向车道全宽光轨：y 135 为 #FFE9B8、宽 2.6 px；y 138.5 为 #FFC75A、宽 1.6 px；y 141.5 为 #FFE9B8、宽 1.2 px，随效果淡入。","右上快门 1/250 → 8″。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"夜の街の流れや、水・雲のなめらかな動きを1枚で見せたいとき。","en":"To show traffic flow, or silky water and clouds, in a single still.","zh-Hans":"适合单张照片表现车流、丝绸状流水或云层运动。"},"tags":["long exposure","light trails","slow shutter","night photography","car trails","motion"]},{"id":"108","pack":"photo","no":"12","slug":"panning-shot","category":"lens-camera","width":539,"height":208,"cycle":5,"name":{"ja":"流し撮り","en":"Panning shot","zh-Hans":"追随摄影"},"meaning":{"ja":"動く被写体を追って撮り、背景だけ流す","en":"Follow a moving subject so only the background streaks","zh-Hans":"跟随运动主体，使背景形成横向拖影"},"ask":{"ja":"走る赤い車を流し撮りで。シャッター1/15秒、車はくっきり、背景の木や建物は横に流れるように。","en":"Panning shot of a red car driving past, 1/15 s shutter: the car sharp, the trees and buildings behind streaked sideways.","zh-Hans":"红车驶过时做追随摄影，快门 1/15 秒，车身清晰，树和建筑横向拖影。"},"summary":{"ja":"走る車をカメラが追い、車は画面の中央でくっきりしたまま、背景の建物や木や街灯だけが横に流れる。","en":"The camera follows the moving car: the car stays sharp in the middle of the frame while only the buildings, trees and lamps behind it streak sideways.","zh-Hans":"相机跟随行驶的车，车在画面中央保持清晰，只有后方建筑、树和路灯横向模糊。"},"spec":{"ja":["街角: 奥に建物の列・木・街灯、道は y132〜162（手前の人物なし）","車: 効果なしでは5秒で x−80 → 620 を走る。効果ありでは x270 ±10px にとどまる","流れ: 背景を横に46pxの幅へ12枚ずらして重ね、平均をとる（幅 0 → 46px）","車輪: 線が5秒で12回転","右上のシャッター速度 1/1000 → 1/15","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Street corner: buildings, trees and lamps behind a road at y 132–162 (no large person in front)","Car: without the effect it drives from x −80 to 620 in 5 s; with it, it stays at x 270 ±10 px","Streak: the background is drawn 12 times spread over 46 px sideways and averaged (spread 0 → 46 px)","Wheels: a spoke line turns 12 times per 5 s","Top-right shutter speed 1/1000 → 1/15","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["街角建筑、树和路灯位于 y 132–162 的道路后方，无前景大人物。","无效果时汽车在 5 秒内从 x −80 行驶到 620；有效果时停留在 x 270 ±10 px。","背景横向分散 46 px 绘制12 次并取平均，分散量 0 → 46 px。","车轮辐条每 5 秒旋转12 圈。","右上快门 1/1000 → 1/15。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"車・自転車・ランナーなどのスピード感を、1枚の写真で見せたいとき。","en":"To show the speed of a car, bike or runner in a still photo.","zh-Hans":"适合静态照片表现汽车、自行车或跑者的速度。"},"tags":["panning","panning shot","motion blur","speed","sports photography","slow shutter"]},{"id":"109","pack":"photo","no":"13","slug":"lens-flare","category":"lens-camera","width":539,"height":208,"cycle":5,"name":{"ja":"レンズフレア","en":"Lens flare","zh-Hans":"镜头眩光"},"meaning":{"ja":"強い光でレンズの中に光の輪や玉が出る","en":"Rings and spots of light from a bright source in the lens","zh-Hans":"强光进入镜头后形成光环与光斑"},"ask":{"ja":"山の上の太陽を入れて、レンズフレアを。太陽から画面の中心をはさんで反対側へ、色のついた光の玉が並ぶように。","en":"Mountain landscape with the sun in frame and lens flare: coloured ghosts lined up from the sun through the centre to the opposite side.","zh-Hans":"山景中让太阳入镜，彩色眩光鬼影从太阳经画面中心排列到对侧。"},"summary":{"ja":"太陽が建物の陰から空へ出ると、太陽に光の筋が出て、太陽から画面の中心をはさんだ反対側まで、光の玉と六角形と輪が一列に並ぶ。","en":"As the sun comes out from behind a building, rays appear around it and a line of light dots, hexagons and a ring runs from the sun through the centre of the frame to the opposite side.","zh-Hans":"太阳从建筑后露出时出现放射光线，圆斑、六边形和光环沿太阳与画面中心连线排列到另一侧。"},"spec":{"ja":["場面②: 街角。奥に建物の列・木・街灯（x114, 292, 494）、道は y132〜162、人物は左手前（足元 x176, y200・身長124px）。","太陽: 半径13px、建物の陰（x428, y74）→ 空（x474, y30）","光の筋: 8本、太陽の中心から17pxの所から26px・44pxの所まで交互（長さ9px・27px、アンバー 1.6px・75%）","光の玉: 太陽から中心を通る線の上、t = 0.45・0.8・1.15・1.45・1.75・2.0（t=1 が画面の中心）に、円 半径7px・六角形13px・円5px・六角形22px・円9px・輪30px（幅3px）","色はアンバー #FFC75A と #FFE3A3、不透明度 40〜70% × 効果の量","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 2: a street corner; buildings, trees and street lamps (x 114, 292, 494) behind a road at y 132–162; the person stands front left (feet at x 176, y 200, 124 px tall). ","Sun: radius 13 px, from behind a building (x 428, y 74) to open sky (x 474, y 30)","Rays: 8, from 17 px out from the centre of the sun to 26 px or 44 px, alternating (9 px and 27 px long; amber, 1.6 px, 75%)","Flare: on the line from the sun through the centre at t = 0.45, 0.8, 1.15, 1.45, 1.75 and 2.0 (t = 1 is the centre): a 7 px circle, a 13 px hexagon, a 5 px circle, a 22 px hexagon, a 9 px circle and a 30 px ring (3 px line)","Colours amber #FFC75A and #FFE3A3 at 40–70% × the effect","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 2：街角的建筑、树和路灯位于 y 132–162 的道路后方，路灯 x 114, 292, 494；人物站在左前方，脚底 x 176、y 200，高 124 px。","太阳半径 13 px，从建筑后 (x 428, y 74) 移到开阔天空 (x 474, y 30)。","8 条光线从距太阳中心 17 px 处向外延伸，终点交替为 26 px 和 44 px，长度为 9 px 与 27 px；琥珀色、宽 1.6 px、透明度 75%。","眩光沿太阳至中心的直线放在 t = 0.45, 0.8, 1.15, 1.45, 1.75, 2.0，t = 1 为画面中心；依次是 7 px 圆、13 px 六边形、5 px 圆、22 px 六边形、9 px 圆、30 px 光环，环线宽 3 px。","颜色为琥珀 #FFC75A 和 #FFE3A3，透明度 40–70% × 效果强度。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"太陽や照明のまぶしさ、夏の日差し、映画のような光を足したいとき。","en":"To add glare, summer sunshine or a cinematic light feel.","zh-Hans":"适合增加炫目、夏日阳光或电影光感。"},"tags":["lens flare","flare","ghosting","sun flare","starburst","cinematic"]},{"id":"110","pack":"photo","no":"14","slug":"fisheye-lens","category":"lens-camera","width":539,"height":208,"cycle":5,"name":{"ja":"魚眼レンズ","en":"Fisheye lens","zh-Hans":"鱼眼镜头"},"meaning":{"ja":"中心がふくらみ、直線が丸く曲がる超広角","en":"Ultra-wide lens that bulges the centre and bends straight lines","zh-Hans":"超广角使中央鼓起、直线弯曲"},"ask":{"ja":"街の通りを魚眼レンズで。画角180°で、ビルの縦の線が外側へ丸く曲がるように。","en":"City street through a fisheye lens, 180° view, the building edges bowing outward.","zh-Hans":"用鱼眼镜头拍城市街道，视野 180°，建筑边缘向外弯曲。"},"summary":{"ja":"街角の中心がふくらみ、建物の縦の線と道の横の線が外側へ丸く曲がり、四隅はそのまま残る。","en":"The middle of the street scene bulges out; the vertical lines of the buildings and the lines of the road bow outward while the corners stay where they are.","zh-Hans":"街景中央向外鼓起，建筑竖线和道路线弯曲，四角保持原位。"},"spec":{"ja":["場面②: 街角。奥に建物の列・木・街灯（x114, 292, 494）、道は y132〜162、人物は左手前（足元 x176, y200・身長124px）。","変形: 中心からの距離 d の点を g = (1 + k) / (1 + k·d²/R²) 倍に動かす。R = 中心から角までの距離（289px）","k: 0 → 1.25。中心は2.25倍に拡大、四隅は動かない","形の輪郭は6pxおきに刻んでから変形するので、直線が曲線になる","右上の焦点距離 24mm → 8mm","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 2: a street corner; buildings, trees and street lamps (x 114, 292, 494) behind a road at y 132–162; the person stands front left (feet at x 176, y 200, 124 px tall). ","Warp: a point at distance d from the centre moves to g = (1 + k) / (1 + k·d²/R²) times that distance, R = distance from the centre to a corner (289 px)","k: 0 → 1.25; the centre is magnified 2.25×, the corners do not move","Every outline is cut every 6 px before warping, so straight lines become curves","Top-right focal length 24mm → 8mm","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 2：街角的建筑、树和路灯位于 y 132–162 的道路后方，路灯 x 114, 292, 494；人物站在左前方，脚底 x 176、y 200，高 124 px。","变形：距中心 d 的点，其距离乘以 g = (1 + k) / (1 + k·d²/R²)，R 为中心到角的距离，即 289 px。","k 从 0 → 1.25，中央放大 2.25×，四角不动。","变形前每隔 6 px 细分轮廓，使直线可弯曲。","右上焦距 24mm → 8mm。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"迫力・遊び心・のぞき穴のような視点を出したいとき（スケボー、ミュージックビデオなど）。","en":"For bold, playful or peephole-like views (skateboarding, music videos).","zh-Hans":"适合大胆、趣味或窥视孔风格，如滑板和音乐视频。"},"tags":["fisheye","fisheye lens","barrel distortion","ultra wide","8mm","distortion"]},{"id":"111","pack":"photo","no":"15","slug":"chromatic-aberration","category":"lens-camera","width":539,"height":208,"cycle":5,"name":{"ja":"色収差","en":"Chromatic aberration","zh-Hans":"色差"},"meaning":{"ja":"明暗の境に赤や青紫の色ずれが出る","en":"Red and blue-violet colour fringes along high-contrast edges","zh-Hans":"高反差边缘出现红色和蓝紫色边"},"ask":{"ja":"白い空と黒い枝の写真に、色収差を少し。画面の端に向かって、枝の縁に赤と青紫の色ずれが出るように。","en":"Black branches against a white sky with slight chromatic aberration: red and blue-violet fringes on the edges, stronger toward the corners.","zh-Hans":"白天空前的黑树枝加轻微色差，边缘有红色、蓝紫色镶边，越靠角落越强。"},"summary":{"ja":"街角の絵を赤・緑・青に分け、少しずつ違う大きさで重ねると、人物や建物や街灯の縁に赤と青緑のずれが出て、画面の端ほど大きくなる。","en":"The street scene is split into red, green and blue and the three are laid back together at slightly different sizes, so red and cyan fringes appear on the edges of the person, buildings and lamps, larger towards the sides.","zh-Hans":"街景拆为红绿蓝三通道，以略不同尺寸重新叠加，人物、建筑和路灯边缘出现红青边，越靠两侧越明显。"},"spec":{"ja":["場面②: 街角。奥に建物の列・木・街灯（x114, 292, 494）、道は y132〜162、人物は左手前（足元 x176, y200・身長124px）。","分け方: 絵に赤 #FF0000・緑 #00FF00・青 #0000FF を乗算して3枚にし、黒の上に加算で重ねる","大きさ（画面の中心から）: 赤 1 + 2s、緑 1 + s、青 1。s = 0 → 0.02","ずれ: 画面の左右の端で赤と青が約11px離れる、中心では0","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 2: a street corner; buildings, trees and street lamps (x 114, 292, 494) behind a road at y 132–162; the person stands front left (feet at x 176, y 200, 124 px tall). ","Split: the image is multiplied by red #FF0000, green #00FF00 and blue #0000FF into three copies and added back together over black","Scale about the centre: red 1 + 2s, green 1 + s, blue 1, with s = 0 → 0.02","Offset: red and blue end up about 11 px apart at the left and right edges, 0 at the centre","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 2：街角的建筑、树和路灯位于 y 132–162 的道路后方，路灯 x 114, 292, 494；人物站在左前方，脚底 x 176、y 200，高 124 px。","把图像分别乘以红 #FF0000、绿 #00FF00、蓝 #0000FF 得到三份，再在黑底上相加。","围绕中心缩放：红 1 + 2s、绿 1 + s、蓝 1，s = 0 → 0.02。","左右边缘红蓝最终相距约 11 px，中心偏移为 0。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"古いレンズやVHS、グリッチのような、少し崩れた質感を足したいとき。","en":"To add an imperfect old-lens, VHS or glitch feel.","zh-Hans":"适合旧镜头、VHS 或故障风格的不完美质感。"},"tags":["chromatic aberration","color fringing","rgb split","lens aberration","fringe","glitch"]},{"id":"112","pack":"photo","no":"16","slug":"vignette","category":"lens-camera","width":539,"height":208,"cycle":5,"name":{"ja":"周辺減光（ビネット）","en":"Vignette","zh-Hans":"暗角"},"meaning":{"ja":"画面の四隅が暗くなり、中央に目が集まる","en":"The corners darken and draw the eye to the centre","zh-Hans":"边角变暗，将视线引向中心"},"ask":{"ja":"海辺の写真に、ビネットを強めに。四隅だけなだらかに暗くして、中央の人物に目が行くように。","en":"Beach photo with a strong vignette: the corners darken gradually so the eye goes to the person in the middle.","zh-Hans":"海滩照片加明显暗角，四角渐暗，让视线聚焦中央人物。"},"summary":{"ja":"画面の四隅からなだらかに暗くなり、中央の人物と道のあたりだけが明るく残る。","en":"The frame darkens smoothly from the corners while the person and the road in the middle stay bright.","zh-Hans":"画面从四角平滑变暗，中间人物和道路保持明亮。"},"spec":{"ja":["場面②: 街角。奥に建物の列・木・街灯（x114, 292, 494）、道は y132〜162、人物は左手前（足元 x176, y200・身長124px）。","暗くする形: 画面の中心を中心にした楕円（縦は横の 208/539 × 1.35 倍）","楕円の半径（横）334px の45%までは素通し、そこから外へ向かって 0 → 70% の濃さで rgb(32,35,43) を重ねる","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 2: a street corner; buildings, trees and street lamps (x 114, 292, 494) behind a road at y 132–162; the person stands front left (feet at x 176, y 200, 124 px tall). ","Shape: an ellipse centred on the frame (vertical radius = horizontal × 208/539 × 1.35)","Clear out to 45% of the 334 px horizontal radius, then rgb(32,35,43) rising from 0% to 70% towards the edge","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 2：街角的建筑、树和路灯位于 y 132–162 的道路后方，路灯 x 114, 292, 494；人物站在左前方，脚底 x 176、y 200，高 124 px。","以画面中心为椭圆中心，纵向半径 = 横向半径 × 208/539 × 1.35。","横向半径为 334 px，内侧 45% 保持透明，随后 rgb(32,35,43) 向边缘从 0% 增至 70%。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"主役に視線を集めたいとき、古いレンズの雰囲気を出したいとき。","en":"To focus attention on the subject, or to suggest an old lens.","zh-Hans":"适合突出主体或模拟旧镜头。"},"tags":["vignette","vignetting","dark corners","edge darkening","lens falloff","focus"]},{"id":"113","pack":"photo","no":"17","slug":"high-key","category":"tone-finish","width":539,"height":208,"cycle":5,"name":{"ja":"ハイキー","en":"High-key","zh-Hans":"高调摄影"},"meaning":{"ja":"明るい色だけで作る、白っぽく影の薄い写真","en":"A bright, white-toned image with very light shadows","zh-Hans":"整体明亮偏白，阴影很浅"},"ask":{"ja":"白い机の上のカップと瓶を、ハイキーで。背景は真っ白、影はごく薄く、全体を明るい色だけでまとめて。","en":"High-key still life of a cup and a bottle on a white table: pure white background, very faint shadows, only light tones.","zh-Hans":"白桌上的杯瓶静物用高调摄影，纯白背景，阴影极淡，整体浅色。"},"summary":{"ja":"風景と人物が白に近い明るい色だけになり、影はごく薄くなって、右下のヒストグラムの山が右端へ寄る。","en":"The landscape and the person turn to light, near-white colours with very faint shadows, and the hump of the histogram at the bottom right moves to the right end.","zh-Hans":"风景和人物变为近白浅色，阴影很淡，右下直方图峰向右侧移动。"},"spec":{"ja":["場面③: 左に胸像（頭の中心 x140, y82・半径28px）、右に丘・家・木・太陽（x432, y54・半径15px）。","色: 空 #FAF9F7 → #FFFFFF、丘 #EAEDF1 → #F5F6F8、人物 #4D5A75 → #B9C0CE、影 #33405A → #A6AEBF、太陽 #F5A524 → #FFD889","ヒストグラム（96×46px・20本）: 山の中心 0.56 → 0.85、幅 0.2 → 0.09","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 3: a bust on the left (head centre x 140, y 82, radius 28 px) and hills, a house, trees and the sun (x 432, y 54, radius 15 px) on the right. ","Colour: sky #FAF9F7 → #FFFFFF, hills #EAEDF1 → #F5F6F8, figure #4D5A75 → #B9C0CE, shadow #33405A → #A6AEBF, sun #F5A524 → #FFD889","Histogram (96×46 px, 20 bars): peak centre 0.56 → 0.85, width 0.2 → 0.09","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 3：左侧半身像的头部中心 x 140、y 82、半径 28 px；右侧有山丘、房屋、树与太阳，太阳 x 432、y 54、半径 15 px。","天空 #FAF9F7 → #FFFFFF，山丘 #EAEDF1 → #F5F6F8，人物 #4D5A75 → #B9C0CE，阴影 #33405A → #A6AEBF，太阳 #F5A524 → #FFD889。","直方图为 96×46 px、20 根柱；峰中心 0.56 → 0.85，宽度 0.2 → 0.09。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"清潔感・軽やかさ・やさしさを出したい商品や人物の写真で。","en":"For clean, light, gentle product shots and portraits.","zh-Hans":"适合干净、轻盈、柔和的产品照与人像。"},"tags":["high-key","high key","bright","white background","airy","low contrast"]},{"id":"114","pack":"photo","no":"18","slug":"low-key","category":"tone-finish","width":539,"height":208,"cycle":5,"name":{"ja":"ローキー","en":"Low-key","zh-Hans":"低调摄影"},"meaning":{"ja":"暗い色が中心の、光の当たる所だけが浮かぶ写真","en":"A dark image where only the lit parts stand out","zh-Hans":"整体暗，只有受光区域突出"},"ask":{"ja":"黒背景のウイスキーの瓶をローキーで。横からの1灯だけで、光の当たる縁だけ浮かび、画面の大半は黒に沈めて。","en":"Low-key shot of a whisky bottle on black, a single side light, only the lit edges showing and most of the frame in deep black.","zh-Hans":"黑底威士忌瓶用低调摄影，单侧光，只显露受光边缘，画面大部分深黑。"},"summary":{"ja":"画面の大半が暗く沈み、太陽も消えて、横から日の当たる胸像の右の縁だけが光って浮かぶ。ヒストグラムの山は左端へ寄る。","en":"Most of the frame sinks into darkness and the sun goes out; only the right edge of the bust, lit from the side, stays bright. The histogram hump moves to the left end.","zh-Hans":"画面大部分沉入黑暗，太阳消失，只有半身像右侧受光边缘明亮，直方图峰移到左侧。"},"spec":{"ja":["場面③: 左に胸像（頭の中心 x140, y82・半径28px）、右に丘・家・木・太陽（x432, y54・半径15px）。","色: 空 #FAF9F7 → #2B2D33、丘 → #313339・#36383E、地面 → #24252A、人物 → #25272E。太陽と光の輪は空と同じ色になって消える","胸像の右の縁（光の面）は残り、#FFC75A → #FFB547","ヒストグラム: 山の中心 0.56 → 0.14、幅 0.2 → 0.08","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 3: a bust on the left (head centre x 140, y 82, radius 28 px) and hills, a house, trees and the sun (x 432, y 54, radius 15 px) on the right. ","Colour: sky #FAF9F7 → #2B2D33, hills → #313339 and #36383E, ground → #24252A, figure → #25272E; the sun and its rings take the sky colour and disappear","The lit right edge of the bust stays, #FFC75A → #FFB547","Histogram: peak centre 0.56 → 0.14, width 0.2 → 0.08","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 3：左侧半身像的头部中心 x 140、y 82、半径 28 px；右侧有山丘、房屋、树与太阳，太阳 x 432、y 54、半径 15 px。","天空 #FAF9F7 → #2B2D33，山丘变 #313339 与 #36383E，地面变 #24252A，人物变 #25272E；太阳及光环取天空色并消失。","半身像右侧亮边保留，#FFC75A → #FFB547。","直方图峰中心 0.56 → 0.14，宽度 0.2 → 0.08。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"高級感・緊張感・ミステリアスな雰囲気を出したいとき。","en":"For luxurious, tense or mysterious images.","zh-Hans":"适合奢华、紧张或神秘氛围。"},"tags":["low-key","low key","dark","black background","moody","dramatic","chiaroscuro"]},{"id":"115","pack":"photo","no":"19","slug":"black-and-white","category":"tone-finish","width":539,"height":208,"cycle":5,"name":{"ja":"モノクロ","en":"Black and white","zh-Hans":"黑白摄影"},"meaning":{"ja":"色を抜いて明るさだけで見せる","en":"Remove colour and show brightness only","zh-Hans":"移除颜色，只用明暗表现画面"},"ask":{"ja":"海辺のスナップをモノクロで。コントラストは少し強めに、空と砂の明るさの差を残して。","en":"Beach snapshot in black and white, contrast slightly raised, keeping the difference in brightness between sky and sand.","zh-Hans":"海滩快照转为黑白，略增对比，保留天空与沙滩的亮度层次。"},"summary":{"ja":"同じ風景から色が抜け、太陽も人物の縁の光も灰色になり、明るさの差だけで形が見える。","en":"The colour drains from the same landscape; the sun and the light on the figure turn grey and the shapes read only by their brightness.","zh-Hans":"同一风景逐渐褪色，太阳和人物受光边变灰，只靠亮度区分形状。"},"spec":{"ja":["場面③: 左に胸像（頭の中心 x140, y82・半径28px）、右に丘・家・木・太陽（x432, y54・半径15px）。","変換: 各色を明るさ（0.2126R + 0.7152G + 0.0722B）の灰色に置き換え、140を中心にコントラスト1.25倍","例: 人物 #4D5A75 → 約 #4D4D4D、太陽 #F5A524 → 約 #B5B5B5","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 3: a bust on the left (head centre x 140, y 82, radius 28 px) and hills, a house, trees and the sun (x 432, y 54, radius 15 px) on the right. ","Conversion: each colour becomes the grey of its luminance (0.2126R + 0.7152G + 0.0722B), contrast ×1.25 around 140","For example the figure #4D5A75 → about #4D4D4D, the sun #F5A524 → about #B5B5B5","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 3：左侧半身像的头部中心 x 140、y 82、半径 28 px；右侧有山丘、房屋、树与太阳，太阳 x 432、y 54、半径 15 px。","每种颜色按亮度 0.2126R + 0.7152G + 0.0722B 转灰，再以 140 为中心将对比放大 ×1.25。","例如人物 #4D5A75 → 约 #4D4D4D，太阳 #F5A524 → 约 #B5B5B5。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"時代を感じさせたいとき、色より形・光・表情を見せたいとき。","en":"For a timeless feel, or when shape, light and expression matter more than colour.","zh-Hans":"适合经典、恒久的观感，或让形状、光线、表情优先于颜色。"},"tags":["black and white","monochrome","b&w","grayscale","desaturated","classic"]},{"id":"116","pack":"photo","no":"20","slug":"duotone","category":"tone-finish","width":539,"height":208,"cycle":5,"name":{"ja":"デュオトーン","en":"Duotone","zh-Hans":"双色调"},"meaning":{"ja":"暗部と明部を2色だけで表す","en":"Show the image in two colours, one for darks and one for lights","zh-Hans":"用两种颜色分别映射暗部和亮部"},"ask":{"ja":"人物写真を濃い藍とピンクのデュオトーンに。暗い所は藍、明るい所はピンクの2色だけで。","en":"Portrait photo as a navy-and-pink duotone: darks in navy, lights in pink, nothing else.","zh-Hans":"人像做深蓝粉色双色调，暗部深蓝，亮部粉色，不使用其他色相。"},"summary":{"ja":"同じ風景の色が、暗い所は藍、明るい所はピンクの2色の間だけに置き換わる。","en":"The colours of the same landscape are replaced by a range between just two colours: indigo in the darks and pink in the lights.","zh-Hans":"同一风景的颜色被替换为两色之间的层次，暗部靛蓝、亮部粉色。"},"spec":{"ja":["場面③: 左に胸像（頭の中心 x140, y82・半径28px）、右に丘・家・木・太陽（x432, y54・半径15px）。","2色: 暗い側 #1F2A5C、明るい側 #FF9FB2","変換: 各色の明るさ L から t = ((L − 70) / 180)^2.4 を求め、2色を t で混ぜる（明るい色どうしの差を広げる）","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 3: a bust on the left (head centre x 140, y 82, radius 28 px) and hills, a house, trees and the sun (x 432, y 54, radius 15 px) on the right. ","Two colours: #1F2A5C for the dark end, #FF9FB2 for the light end","Conversion: from each colour’s luminance L, t = ((L − 70) / 180)^2.4, and the two colours are mixed by t (this spreads the light tones apart)","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 3：左侧半身像的头部中心 x 140、y 82、半径 28 px；右侧有山丘、房屋、树与太阳，太阳 x 432、y 54、半径 15 px。","暗端颜色 #1F2A5C，亮端颜色 #FF9FB2。","按各颜色亮度 L 计算 t = ((L − 70) / 180)^2.4，再以 t 混合两色，拉开亮部层次。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"ポスター・音楽・SNSの画像を、ブランドの色で統一したいとき。","en":"To unify posters, music artwork or social images in brand colours.","zh-Hans":"适合用品牌色统一海报、音乐封面或社交图片。"},"tags":["duotone","two-tone","gradient map","color overlay","poster","graphic"]},{"id":"117","pack":"photo","no":"21","slug":"teal-and-orange","category":"tone-finish","width":539,"height":208,"cycle":5,"name":{"ja":"ティール＆オレンジ","en":"Teal and orange","zh-Hans":"青橙调色"},"meaning":{"ja":"影を青緑、肌や明部を橙に寄せる色調","en":"Pushes shadows to teal and skin and highlights to orange","zh-Hans":"暗部偏青，肤色与高光偏橙"},"ask":{"ja":"街を歩く人物を映画のようなティール＆オレンジで。影と空は青緑、肌と夕日は橙に寄せて。","en":"Person walking in the city with a cinematic teal and orange grade: shadows and sky toward teal, skin and sunlight toward orange.","zh-Hans":"城市行人做电影感青橙调色，阴影与天空偏青，肤色和阳光偏橙。"},"summary":{"ja":"同じ風景の空・丘・地面・人物の影が青緑へ、日の当たる人物の縁と太陽が橙へ寄り、補色の対比になる。","en":"In the same landscape the sky, hills, ground and the shadowed figure shift to teal while the sunlit edge of the figure and the sun shift to orange, a complementary contrast.","zh-Hans":"天空、山、地面与人物暗部变青，人物受光边缘和太阳变橙，形成互补色对比。"},"spec":{"ja":["場面③: 左に胸像（頭の中心 x140, y82・半径28px）、右に丘・家・木・太陽（x432, y54・半径15px）。","青緑: 空 #CFE6E3、丘 #8CC1BE・#62A2A1、地面 #3F8083、木 #2F6A6E、人物 #1D4E53","橙: 人物の縁の光 #FF9248、太陽 #FF8236、光の輪 #FFC48C","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 3: a bust on the left (head centre x 140, y 82, radius 28 px) and hills, a house, trees and the sun (x 432, y 54, radius 15 px) on the right. ","Teal: sky #CFE6E3, hills #8CC1BE and #62A2A1, ground #3F8083, trees #2F6A6E, figure #1D4E53","Orange: the light on the figure #FF9248, sun #FF8236, sun rings #FFC48C","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 3：左侧半身像的头部中心 x 140、y 82、半径 28 px；右侧有山丘、房屋、树与太阳，太阳 x 432、y 54、半径 15 px。","青色：天空 #CFE6E3，山丘 #8CC1BE 与 #62A2A1，地面 #3F8083，树 #2F6A6E，人物 #1D4E53。","橙色：人物亮部 #FF9248，太阳 #FF8236，太阳光环 #FFC48C。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"映画のポスターや予告編のような、色の対比が強い画にしたいとき。","en":"For a blockbuster, trailer-like look with strong colour contrast.","zh-Hans":"适合色彩反差强烈的商业电影或预告片风格。"},"tags":["teal and orange","orange and teal","cinematic","color grading","blockbuster","film look"],"aliases":{"zh-Hans":["青橙","电影调色"]}},{"id":"118","pack":"photo","no":"22","slug":"film-grain","category":"tone-finish","width":539,"height":208,"cycle":5,"name":{"ja":"フィルムグレイン","en":"Film grain","zh-Hans":"胶片颗粒"},"meaning":{"ja":"フィルム写真のような細かい粒子を乗せる","en":"Fine, film-like grain over the image","zh-Hans":"在画面上叠加细腻胶片质感颗粒"},"ask":{"ja":"海辺の写真にフィルムグレインを。細かい粒子を全体に、黒は少し浮かせて暖かい色に。","en":"Add film grain to the beach photo: fine grain all over, blacks slightly lifted and warm.","zh-Hans":"海滩照片加细腻胶片颗粒，遍布全图，黑位稍抬并偏暖。"},"summary":{"ja":"同じ風景の全体に細かい粒が乗り、色が少し暖かいクリーム色に寄る。","en":"Fine grain appears over the whole of the same landscape and the colours lean slightly towards a warm cream.","zh-Hans":"同一风景全图出现细颗粒，颜色略偏暖奶油色。"},"spec":{"ja":["場面③: 左に胸像（頭の中心 x140, y82・半径28px）、右に丘・家・木・太陽（x432, y54・半径15px）。","粒: 2600個（固定シード）、大きさ 0.8〜1.7px の四角。55%が暗い #3A3530、45%が白","粒の濃さ: 16〜38% × 効果の量。粒の位置は動かさない（ちらつかせない）","色: すべての色を #F2DDBE へ16%寄せる","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 3: a bust on the left (head centre x 140, y 82, radius 28 px) and hills, a house, trees and the sun (x 432, y 54, radius 15 px) on the right. ","Grain: 2,600 squares (fixed seed), 0.8–1.7 px; 55% dark #3A3530, 45% white","Grain opacity: 16–38% × the effect; the grain does not move (no flicker)","Colour: every colour moves 16% towards #F2DDBE","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 3：左侧半身像的头部中心 x 140、y 82、半径 28 px；右侧有山丘、房屋、树与太阳，太阳 x 432、y 54、半径 15 px。","颗粒为 2,600 个固定随机种子的方块，尺寸 0.8–1.7 px；55% 为深色 #3A3530，45% 为白色。","颗粒透明度 16–38% × 效果强度；颗粒不移动、不闪烁。","所有颜色向 #F2DDBE 混合 16%。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"デジタルのつるっとした感じを消して、フィルムの手触りを出したいとき。","en":"To remove the clean digital look and add an analogue film texture.","zh-Hans":"适合减弱纯净数码感，增加模拟胶片纹理。"},"tags":["film grain","grain","noise","analog","35mm film","texture","warm tone"]},{"id":"119","pack":"photo","no":"23","slug":"light-leak","category":"tone-finish","width":539,"height":208,"cycle":5,"name":{"ja":"ライトリーク","en":"Light leak","zh-Hans":"漏光"},"meaning":{"ja":"フィルムに光がもれたような赤橙のにじみ","en":"Red-orange glow as if light leaked onto the film","zh-Hans":"模拟光线漏入胶片形成红橙光晕"},"ask":{"ja":"夏の思い出の写真に、ライトリークを右端から。赤と橙の光がにじみ込むように。","en":"Summer memory photo with a light leak coming in from the right edge, red and orange light bleeding in.","zh-Hans":"夏日回忆照片加右边缘漏光，红橙色光线渗入。"},"summary":{"ja":"同じ風景の右端から、外側ほど淡い黄、端ほど赤い光のにじみが帯になって入り、ゆっくり揺れる。","en":"From the right edge of the same landscape a band of leaked light comes in, pale yellow on the inside and red at the edge, swaying slowly.","zh-Hans":"风景右侧渗入一条缓慢摆动的漏光带，内侧浅黄、边缘红色。"},"spec":{"ja":["場面③: 左に胸像（頭の中心 x140, y82・半径28px）、右に丘・家・木・太陽（x432, y54・半径15px）。","形: 縦長の楕円4枚。中心は右端の外30px（1周で左右に ±6px 揺れる）、縦の半径は画面の高さの1.1倍","横の半径と色: 250px #FFD089 35%、170px #FF9A3D 40%、95px #FF5A3A 45%、45px #FF3B30 50%（横の半径は 0 → この値に広がる）","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 3: a bust on the left (head centre x 140, y 82, radius 28 px) and hills, a house, trees and the sun (x 432, y 54, radius 15 px) on the right. ","Shape: four tall ellipses centred 30 px outside the right edge (swaying ±6 px over the loop), vertical radius 1.1× the frame height","Horizontal radius and colour: 250 px #FFD089 at 35%, 170 px #FF9A3D at 40%, 95 px #FF5A3A at 45%, 45 px #FF3B30 at 50% (each grows from 0 to this radius)","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 3：左侧半身像的头部中心 x 140、y 82、半径 28 px；右侧有山丘、房屋、树与太阳，太阳 x 432、y 54、半径 15 px。","四个竖长椭圆的中心位于右边缘外 30 px，周期内摆动 ±6 px；纵向半径为画面高的 1.1×。","横向半径与颜色分别为 250 px #FFD089、透明度 35%，170 px #FF9A3D、40%，95 px #FF5A3A、45%，45 px #FF3B30、50%；各自半径从 0 增至目标值。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"思い出・夏・青春のような、なつかしく偶然っぽい雰囲気を出したいとき。","en":"For nostalgic, summery, accidental-looking memories.","zh-Hans":"适合怀旧、夏日和偶然捕捉的记忆感。"},"tags":["light leak","film leak","vintage","analog","lomo","warm glow"]},{"id":"120","pack":"photo","no":"24","slug":"double-exposure","category":"tone-finish","width":539,"height":208,"cycle":5,"name":{"ja":"二重露光（多重露光）","en":"Double exposure","zh-Hans":"双重曝光"},"meaning":{"ja":"2枚の写真を1枚に重ねて写し込む","en":"Two photos layered into one frame","zh-Hans":"将两张照片叠合在同一画面"},"ask":{"ja":"横顔のシルエットに森と山の風景を二重露光で重ねて。背景は白、顔の中にだけ風景が見えるように。","en":"Double exposure of a profile silhouette and a forest-and-mountain landscape on a white background, the landscape visible only inside the head.","zh-Hans":"侧面人像剪影与森林山景做双重曝光，白色背景，风景只显示在头部内部。"},"summary":{"ja":"背景が白く飛び、胸像の形の中にだけ、縮めた丘・家・木・太陽の風景が写り込む。","en":"The background turns white and the landscape of hills, house, trees and sun appears, scaled down, only inside the shape of the bust.","zh-Hans":"背景变白，山丘、房屋、树和太阳缩小后只出现在半身像轮廓内部。"},"spec":{"ja":["場面③: 左に胸像（頭の中心 x140, y82・半径28px）、右に丘・家・木・太陽（x432, y54・半径15px）。","背景: 胸像の外は白 #FFFFFF","胸像の中: 同じ風景を0.7倍にして、太陽が頭の右上、丘の稜線が首のあたりに来るように置く","中の色: 空 #D3DBE6、丘 #9AA8BD・#76869F、地面 #55647E、木 #3F4C66","切り替え: 元の写真の上に、二重露光の絵を効果の量で重ねる","時間: 0.4〜1.4秒で効果が入り、4.0秒まで保ち、4.8秒までに元へ戻る（1周5秒、3次のイーズインアウト（cubic-bezier(0.65,0,0.35,1) 相当））"],"en":["Scene 3: a bust on the left (head centre x 140, y 82, radius 28 px) and hills, a house, trees and the sun (x 432, y 54, radius 15 px) on the right. ","Background: white #FFFFFF outside the bust","Inside the bust: the same landscape at 0.7×, placed so the sun sits at the top right of the head and the ridge of the hills runs across the neck","Inside colours: sky #D3DBE6, hills #9AA8BD and #76869F, ground #55647E, trees #3F4C66","Transition: the double exposure is laid over the original picture at the effect amount","Timing: the effect comes in from 0.4 s to 1.4 s, holds until 4.0 s and is gone again by 4.8 s (one pass = 5 s, cubic ease-in-out (about cubic-bezier(0.65,0,0.35,1)))"],"zh-Hans":["场景 3：左侧半身像的头部中心 x 140、y 82、半径 28 px；右侧有山丘、房屋、树与太阳，太阳 x 432、y 54、半径 15 px。","半身像外部背景为白色 #FFFFFF。","轮廓内使用同一风景的 0.7× 缩小版，太阳位于头部右上，山脊横过颈部。","内部颜色：天空 #D3DBE6，山丘 #9AA8BD 和 #76869F，地面 #55647E，树 #3F4C66。","按效果强度将双重曝光版本叠在原图上。","效果在 0.4 秒至 1.4 秒进入，保持到 4.0 秒，在 4.8 秒前消失；每轮 5 秒，三次缓入缓出，约 cubic-bezier(0.65,0,0.35,1)。"]},"use":{"ja":"人物と場所・記憶・内面を1枚で結びつけたい、ポスターやジャケットで。","en":"For posters and covers that tie a person to a place, a memory or an inner world.","zh-Hans":"适合将人物与地点、回忆或内心世界联系起来的海报和封面。"},"tags":["double exposure","multiple exposure","blend","silhouette","surreal","composite"]},{"id":"121","pack":"motion2","no":"01","slug":"anticipation","category":"techniques","width":539,"height":208,"cycle":4.7,"name":{"ja":"アンティシペーション","en":"Anticipation","zh-Hans":"预备动作"},"meaning":{"ja":"動く前に逆へ少し溜める","en":"Pulls back briefly before moving forward","zh-Hans":"先短暂反向蓄力，再向前运动"},"ask":{"ja":"ボタンが右へ飛び出す前にアンティシペーションを入れて。0.3秒かけて逆へ少し引き、つぶれてから出す。","en":"Add anticipation before the button shoots off to the right: pull back slightly for 0.3 s, squash, then go.","zh-Hans":"按钮向右飞出前加预备动作，先用 0.3 秒轻微后退并压缩，再冲出。"},"summary":{"ja":"四角いキャラクターが進む向きと逆へ少し引き、つぶれて溜めてから勢いよく飛び出す。","en":"A square character pulls back against its direction of travel, squashes to wind up, then shoots forward.","zh-Hans":"方形角色先反向后撤并压扁蓄力，然后向前冲出。"},"spec":{"ja":["2.35秒で1回（4.7秒に2回。1回目は左→右、2回目は右→左）。コーラルの角丸四角（86px・角丸24）に白い矢印。出発点は端から108px、床は y=178","溜め: 0.2〜0.95秒。easeInOut（2乗）で進む向きと逆へ44px下がり、横1→1.22・縦1→0.76につぶれ、後ろへ0.18rad傾く","飛び出し: 0.95〜1.38秒（0.43秒）。下がった位置から反対の端まで backOut(s=1.1)（わずかに行き過ぎる）。動きの前半60%で横最大1.55・縦最大0.72に伸ばし（sinの山）、前へ0.08rad傾く","着地: 1.38秒から 0.13·e^(−7t)·sin(17t) で縦横を逆向きに揺らして収める","飛び出しの瞬間、出発点に土けむりの丸3つ（動きの前半70%で消える）、後ろに黄色いスピード線3本（線幅8）"],"en":["One move per 2.35 s (twice per 4.7 s: left to right, then right to left). A coral rounded square (86 px, radius 24) with a white arrow. It starts 108 px from the edge; the floor is at y = 178.","Wind-up: 0.2–0.95 s, quadratic ease-in-out. It backs off 44 px against the direction of travel, squashes to 1.22 wide × 0.76 tall and leans back 0.18 rad.","Launch: 0.95–1.38 s (0.43 s). From the backed-off position to the far end with backOut (s = 1.1), a slight overshoot. In the first 60% of the move it stretches up to 1.55 wide × 0.72 tall (half sine) and leans forward 0.08 rad.","Landing: from 1.38 s, width and height wobble in opposite directions by 0.13·e^(−7t)·sin(17t).","At launch, three dust puffs at the start point (gone within the first 70% of the move) and three yellow speed lines (width 8) behind it."],"zh-Hans":["每 2.35 秒一个动作，每 4.7 秒两次，先左到右再右到左；珊瑚色圆角方块边长 86 px、圆角 24，带白箭头，起点距边缘 108 px，地面 y = 178。","蓄力：0.2–0.95 秒，二次缓入缓出；反向退 44 px，压至宽 1.22 × 高 0.76，后仰 0.18 rad。","发射：0.95–1.38 秒，持续 0.43 秒，从后撤点到远端，以 backOut（s = 1.1）轻微过冲；前 60% 按半正弦最多拉成宽 1.55 × 高 0.72，前倾 0.08 rad。","落定：从 1.38 秒起，宽高按相反方向振荡，幅度 0.13·e^(−7t)·sin(17t)。","发射时起点出现三团尘土，在运动前 70% 内消失；身后三条黄色速度线，线宽 8。"]},"use":{"ja":"ジャンプ・ダッシュ・ボタンの発射など、勢いのある動きの直前に。動きに「ため」と重さを出したいとき。","en":"Use it just before a jump, dash or launch to give the move build-up and weight.","zh-Hans":"适合跳跃、冲刺或发射前，增加铺垫和重量感。"},"tags":["anticipation","wind-up","squash","character","jump","dash","animation-principle"]},{"id":"122","pack":"motion2","no":"02","slug":"follow-through","category":"techniques","width":539,"height":208,"cycle":4.7,"name":{"ja":"フォロースルー","en":"Follow-through","zh-Hans":"跟随惯性"},"meaning":{"ja":"止まった後も一部が遅れて揺れる","en":"Parts keep swinging after the body stops","zh-Hans":"主体停下后，附属部分继续摆动"},"ask":{"ja":"キャラが止まったあと、髪と旗にフォロースルーを入れて。0.5秒くらい遅れて揺れて収まるように。","en":"Give the hair and the flag follow-through after the character stops: they keep swinging for about 0.5 s, then settle.","zh-Hans":"角色停止后，头发与旗子保留约 0.5 秒的跟随惯性，继续摆动再稳定。"},"summary":{"ja":"滑ってきた丸いキャラクターが急に止まり、頭の旗としっぽだけが遅れて揺れて収まる。","en":"A round character slides in and stops suddenly; only the flag on its head and its tail keep swinging, then settle.","zh-Hans":"圆形角色滑入并突然停住，只有头上的旗子和尾巴继续摆动，随后稳定。"},"spec":{"ja":["2.35秒で1回（4.7秒に2回、向きを交互に）。体はミントの丸（半径38）。0.15〜0.85秒で303px進む: 最初の30%で加速し、あとは一定の速さのまま0.85秒で急に止まる","旗（白い棒58px＋黄色い旗）: 角度を体の加速度で押されるばねとして計算。a″ = −121a − 5.5a′ − 0.0175×加速度（固有角振動数11rad/s）。旗の布は棒の角度のさらに0.6倍曲げる","しっぽ: 14pxの節7つ（コーラル・線幅14→6）。遅いばね b″ = −56b − 2.8b′ − 0.012×加速度。節 j は 22/600秒（約0.037秒）×j 遅れた値を使い、振れ幅を ×(0.55 + 0.16j)","計算は1/600秒刻みで先に表にしておく（描画時は表を引くだけ）","各回の最後の0.3秒で、旗としっぽの振れを smoothstep で0にする（ループの継ぎ目を出さない）"],"en":["One move per 2.35 s (twice per 4.7 s, alternating direction). The body is a mint circle (radius 38). It travels 303 px at 0.15–0.85 s: it speeds up over the first 30%, then keeps a constant speed and stops abruptly at 0.85 s.","Flag (58 px white pole with a yellow flag): its angle is a spring pushed by the body's acceleration, a″ = −121a − 5.5a′ − 0.0175 × acceleration (natural frequency 11 rad/s). The cloth bends a further 0.6 × the pole angle.","Tail: seven 14 px segments (coral, width 14→6) on a slower spring, b″ = −56b − 2.8b′ − 0.012 × acceleration. Segment j uses the value from j × 22/600 s (about 0.037 s) earlier, scaled by (0.55 + 0.16j).","Both springs are precomputed in 1/600 s steps; drawing only looks values up.","In the last 0.3 s of each move the swing is faded to 0 with smoothstep, so the loop has no seam."],"zh-Hans":["每 2.35 秒一个动作，每 4.7 秒两次，方向交替；主体为半径 38 的薄荷色圆，在 0.15–0.85 秒移动 303 px，前 30% 加速，随后匀速，在 0.85 秒骤停。","旗子为 58 px 白杆与黄色旗面；角度受主体加速度驱动，a″ = −121a − 5.5a′ − 0.0175 × 加速度，自然频率 11 rad/s；旗布额外弯曲 0.6 × 旗杆角度。","尾巴由七段 14 px 组成，珊瑚色、宽 14→6；用较慢弹簧 b″ = −56b − 2.8b′ − 0.012 × 加速度；第 j 段取 j × 22/600 秒前的值，约 0.037 秒，再乘以 (0.55 + 0.16j)。","两条弹簧曲线均按 1/600 秒步长预计算，绘制时只查表。","每次动作最后 0.3 秒，以 smoothstep 将摆动衰减至 0，保证循环接缝平滑。"]},"use":{"ja":"キャラクターの髪・服・アクセサリー、ロゴの飾りなど、本体に付いている部分に自然な重さを出したいとき。","en":"Use it on hair, clothes, accessories or the trim of a logo, so that the parts attached to the main body feel weighted.","zh-Hans":"适合头发、衣服、配件或标志装饰，让附属部分具有重量。"},"tags":["follow-through","overlapping-action","secondary-motion","spring","drag","character","animation-principle"]},{"id":"123","pack":"motion2","no":"03","slug":"bounce","category":"techniques","width":539,"height":208,"cycle":4.7,"name":{"ja":"バウンス","en":"Bounce","zh-Hans":"落地弹跳"},"meaning":{"ja":"落ちて弾みながら止まる","en":"Falls and bounces lower until it stops","zh-Hans":"落下后反复弹起，幅度逐渐降低"},"ask":{"ja":"ボールを上から落としてバウンスさせて。3回弾んで、だんだん低く。","en":"Drop the ball from the top with a bounce: three bounces, each lower than the last.","zh-Hans":"球从上方落下，弹跳三次，每次高度都比上次低。"},"summary":{"ja":"ボールが落ちて、だんだん低く弾みながら止まる。","en":"A ball drops and bounces lower each time until it comes to rest.","zh-Hans":"球落下并逐次弹得更低，最后静止。"},"spec":{"ja":["2.35秒で1回（4.7秒に2回。1回目は黄、2回目はコーラル）。半径26のボール","0.1秒から、床の190px上から落とす。重力1900px/s²、弾むたびに速さを56%に（反発係数0.56）、跳ね返りの速さが35px/s未満で止まる","横は x=150→390 を 0.1〜1.8秒の easeOut（3乗）で移動","着地の前後0.045秒だけつぶす: 横 1+sq・縦 1−sq、sq は最大 0.4 × min(1, 着地の速さ÷850)。速さ200px/s以上の着地では左右に白い短い線を0.3秒出す","影は高いほど小さく薄く。退場: 1.95〜2.25秒に拡大率へ (1 − backIn(s=2)) を掛けて消す"],"en":["One drop per 2.35 s (twice per 4.7 s: yellow first, then coral). The ball has radius 26.","From 0.1 s it falls from 190 px above the floor. Gravity 1900 px/s²; each bounce keeps 56% of the speed (restitution 0.56); it stops when the rebound speed is below 35 px/s.","Sideways it moves x = 150→390 over 0.1–1.8 s with cubic ease-out.","Squash for 0.045 s either side of each impact: width 1 + sq, height 1 − sq, with sq up to 0.4 × min(1, impact speed ÷ 850). Impacts faster than 200 px/s flick short white lines left and right for 0.3 s.","The shadow gets smaller with height. Exit: 1.95–2.25 s, scale multiplied by (1 − backIn, s = 2)."],"zh-Hans":["每 2.35 秒落下一次，每 4.7 秒两次，先黄色再珊瑚色；球半径 26。","从 0.1 秒起由地面上方 190 px 落下，重力 1900 px/s²；每次反弹保留 56% 速度，恢复系数 0.56；反弹速度低于 35 px/s 时停止。","横向在 0.1–1.8 秒由 x = 150→390，采用三次缓出。","每次碰撞前后各 0.045 秒挤压，宽 1 + sq、高 1 − sq，sq 最大为 0.4 × min(1, 撞击速度 ÷ 850)；撞击速度超过 200 px/s 时，左右闪出白色短线，持续 0.3 秒。","阴影随高度增加而变小；1.95–2.25 秒退场，缩放乘以 (1 − backIn, s = 2)。"]},"use":{"ja":"物が落ちて着地するところ。アイコン・文字・商品を、重さと弾力を感じさせて置きたいとき。","en":"Use it whenever something drops and lands: an icon, a word or a product that should feel heavy and springy.","zh-Hans":"适合需要重量与弹性的图标、文字或产品落地动作。"},"tags":["bounce","drop","gravity","ball","physics","landing","easing"],"aliases":{"zh-Hans":["弹性","反弹"]}},{"id":"124","pack":"motion2","no":"04","slug":"wiggle","category":"techniques","width":539,"height":208,"cycle":4.7,"name":{"ja":"ウィグル","en":"Wiggle","zh-Hans":"不规则抖动"},"meaning":{"ja":"小刻みにランダムに揺れる","en":"Shakes in small, random, continuous jitters","zh-Hans":"持续细小、不规则地晃动"},"ask":{"ja":"通知のベルに弱めのウィグルを付けて。角度は最大10°くらいで、鳴っている間ずっと。","en":"Add a subtle wiggle to the notification bell, up to about 10°, for as long as it rings.","zh-Hans":"通知铃响起时持续轻微抖动，幅度不超过约 10°。"},"summary":{"ja":"ベルが小刻みに不規則に揺れ続ける。1回の衝撃ではなく、ずっと続く細かい揺れ。","en":"A bell keeps jittering irregularly: not one hit, but a small shake that never stops.","zh-Hans":"铃铛持续不规则颤动，是不断发生的小幅摇晃，而非单次冲击。"},"spec":{"ja":["黄色いベル。上端（中央, y=34）を支点に、ずっと揺れ続ける（止まる区間はない）","角度 = 4つのsin波の和。4.7秒あたり23・31・43・59回（約4.9・6.6・9.1・12.6Hz）、振幅 0.085・0.065・0.05・0.035rad（重なると最大約0.235rad＝13.5°）","位置も揺らす: 横は29・47・61回で振幅4・3・2px、縦は37・53回で振幅2.4・1.8px","どの周波数も4.7秒にちょうど整数回なのでループがつながる。互いに割り切れない回数を混ぜて、規則的に見えないようにする","ベルの舌（コーラル・半径13）は逆へ振れる（角度×70px）。両わきに白い振動の弧（半径86と110・線幅6）を明滅させて出し続ける"],"en":["A yellow bell pivoting at its top (centre, y = 34). It never stops moving.","Angle = the sum of four sine waves: 23, 31, 43 and 59 cycles per 4.7 s (about 4.9, 6.6, 9.1 and 12.6 Hz), amplitudes 0.085, 0.065, 0.05 and 0.035 rad (up to about 0.235 rad, 13.5°, when they line up).","Position also jitters: x with 29, 47 and 61 cycles (4, 3, 2 px), y with 37 and 53 cycles (2.4, 1.8 px).","Every frequency is a whole number of cycles per 4.7 s, so the loop joins up; the counts share no common factor, so it does not look regular.","The clapper (coral, radius 13) swings the other way (angle × 70 px). White vibration arcs (radius 86 and 110, width 6) flicker on both sides the whole time."],"zh-Hans":["黄色铃铛以顶部为旋转支点，水平居中、y = 34，始终保持运动。","角度叠加四个正弦波，每 4.7 秒分别为 23, 31, 43, 59 周期，约 4.9, 6.6, 9.1, 12.6 Hz；幅度 0.085, 0.065, 0.05, 0.035 rad，同相时最多约 0.235 rad，即 13.5°。","位置同时抖动：x 使用 29, 47, 61 周期，振幅 4, 3, 2 px；y 使用 37, 53 周期，振幅 2.4, 1.8 px。","每个频率在 4.7 秒内均为整数周期，保证循环；周期数无共同因数，避免规则感。","珊瑚色铃舌半径 13，反向摆动，位移为角度 × 70 px；两侧白色振动弧半径 86 和 110、线宽 6，持续闪现。"]},"use":{"ja":"通知・着信・注意を引きたい物に。ずっと続く小さな揺れで、落ち着かなさや手持ち感を出したいとき。","en":"Use it on a notification, an incoming call or anything that should catch the eye, or to add a restless, handheld feel.","zh-Hans":"适合通知、来电等吸引注意的元素，也可表现躁动或手持感。"},"tags":["wiggle","jitter","shake","random","noise","bell","notification"]},{"id":"125","pack":"motion2","no":"05","slug":"pulse","category":"techniques","width":539,"height":208,"cycle":4.7,"name":{"ja":"パルス","en":"Pulse","zh-Hans":"脉冲缩放"},"meaning":{"ja":"鼓動のように大きさが脈打つ","en":"Its size throbs like a heartbeat","zh-Hans":"尺寸像心跳一样周期起伏"},"ask":{"ja":"ハートのアイコンをパルスさせて。1.2秒ごとに、10%ほど大きくなって戻る。","en":"Make the heart icon pulse: about 10% larger and back, every 1.2 s.","zh-Hans":"心形图标做脉冲缩放，每 1.2 秒放大约 10% 再恢复。"},"summary":{"ja":"ハートが鼓動のように、ドクン・ドクンと大きさを脈打たせ、輪が広がる。","en":"A heart throbs like a heartbeat, a double beat each time, with rings spreading out.","zh-Hans":"心形以双拍节奏跳动，并向外扩散心形轮廓。"},"spec":{"ja":["コーラルのハート。1.175秒に1拍（4.7秒に4拍）。1拍は「ドクン・ドクン」の2段","拡大率 = 1 + 0.26·G(0.2秒, 幅0.065) + 0.15·G(0.44秒, 幅0.07)。G = e^(−((t − 中心)÷幅)²)（急にふくらんで、すぐ戻る山）","ハートの輪郭線を2つ広げる: 0.16秒と0.40秒から、0.8秒で拡大率1.2→2.4（easeOut・3乗）","輪は広がりながら不透明度0.75→0（2つ目は60%の濃さ）、線幅8.5→1.5px"],"en":["A coral heart. One beat per 1.175 s (four per 4.7 s); each beat is a double \"lub-dub\".","Scale = 1 + 0.26·G(0.2 s, width 0.065) + 0.15·G(0.44 s, width 0.07), where G = e^(−((t − centre) ÷ width)²): a quick swell that drops straight back.","Two heart-shaped outlines spread from 0.16 s and 0.40 s: scale 1.2→2.4 over 0.8 s, cubic ease-out.","As they spread, their opacity goes 0.75→0 (the second at 60%) and the line width 8.5→1.5 px."],"zh-Hans":["珊瑚色心形，每 1.175 秒一拍，每 4.7 秒四拍；每拍都是“咚咚”双拍。","缩放 = 1 + 0.26·G(0.2 秒, 宽度 0.065) + 0.15·G(0.44 秒, 宽度 0.07)，G = e^(−((t − centre) ÷ width)²)，迅速膨胀后立即回落。","两条心形轮廓分别从 0.16 秒和 0.40 秒开始扩散，在 0.8 秒内由缩放 1.2→2.4，采用三次缓出。","扩散时透明度 0.75→0，第二条为此值的 60%；线宽 8.5→1.5 px。"]},"use":{"ja":"「いいね」・録音中・ライブ配信中・押してほしいボタンなど、生きている感じや注目を出したいとき。","en":"Use it for a like, a recording or live indicator, or a button you want pressed, to make it feel alive.","zh-Hans":"适合点赞、录制或直播指示、重点按钮，增加生命感。"},"tags":["pulse","heartbeat","throb","scale","loop","like","attention"]},{"id":"126","pack":"motion2","no":"06","slug":"motion-path","category":"techniques","width":539,"height":208,"cycle":4.7,"name":{"ja":"モーションパス","en":"Motion path","zh-Hans":"运动路径"},"meaning":{"ja":"決めた曲線に沿って動く","en":"Moves along a curve that you define","zh-Hans":"沿预先定义的曲线移动"},"ask":{"ja":"紙飛行機を、この曲線のモーションパスに沿って4秒で飛ばして。向きは進む方向に合わせて。","en":"Fly the paper plane along this curve as a motion path in 4 s, turning it to face the direction of travel.","zh-Hans":"纸飞机沿这条运动路径飞行四秒，朝向始终跟随运动方向。"},"summary":{"ja":"点線の道に沿って、紙飛行機が向きを変えながら進み、途中で宙返りする。","en":"A paper plane follows a dotted path, turning as it goes and looping the loop on the way.","zh-Hans":"纸飞机沿点线路径飞行，随路径转向，中途绕一个环。"},"spec":{"ja":["4.7秒で1回、左の画面外から右の画面外へ。道は x = 270 + 112θ − 150·sinθ、y = 106 − 74·cosθ（θ = −π→π）。中央の上で輪になる（宙返り）","θ は時間に比例して進める（道の上の速さは一定でない。輪の部分はゆっくり見える）","紙飛行機は道の向きに回す: 角度 = atan2(74·sinθ, 112 − 150·cosθ)","道は点線（線幅6・間隔2/15）で先に見せておく。通ったあとにミントの線を24区間（θで0.03ずつ）残し、後ろほど細く薄くする"],"en":["One pass per 4.7 s, from off-screen left to off-screen right. The path is x = 270 + 112θ − 150·sinθ, y = 106 − 74·cosθ for θ = −π→π, which makes a loop at the top centre.","θ advances in proportion to time (so the speed along the path is not constant; the loop looks slower).","The plane turns to the path direction: angle = atan2(74·sinθ, 112 − 150·cosθ).","The path is shown in advance as a dotted line (width 6, dash 2/15). A mint trail of 24 segments (0.03 in θ each) follows, thinner and fainter towards the back."],"zh-Hans":["每 4.7 秒从左画外到右画外一轮；路径 x = 270 + 112θ − 150·sinθ，y = 106 − 74·cosθ，θ = −π→π，在顶部中央形成环。","θ 与时间成正比，因此沿路径速度不恒定，绕环时看起来更慢。","飞机按路径方向转动，角度 = atan2(74·sinθ, 112 − 150·cosθ)。","路径提前显示为点线，宽 6、虚线节距 2/15；后方跟随24 段薄荷色拖尾，每段 θ 差 0.03，越靠后越细越淡。"]},"use":{"ja":"飛ぶ物・走る車・地図の上の移動など、決まった道筋を通らせたいとき。","en":"Use it whenever something should follow a set route: a flying object, a car, a journey on a map.","zh-Hans":"适合飞行物、汽车或地图行程等需要固定路线的运动。"},"tags":["motion-path","path","curve","trajectory","follow-path","orient-to-path","loop"],"aliases":{"zh-Hans":["路径动画"]}},{"id":"127","pack":"motion2","no":"07","slug":"ping-pong-loop","category":"techniques","width":539,"height":208,"cycle":4.7,"name":{"ja":"ピンポンループ","en":"Ping-pong loop","zh-Hans":"往返循环"},"meaning":{"ja":"行って戻るを繰り返す","en":"Plays forward, then backward, over and over","zh-Hans":"正向播放后再反向播放，持续重复"},"ask":{"ja":"ローディングの点をピンポンループで左右に往復させて。片道1秒で。","en":"Move the loading dot back and forth as a ping-pong loop, 1 s each way.","zh-Hans":"加载圆点做往返循环，单程一秒。"},"summary":{"ja":"四角が端まで行ったら、同じ道を逆再生のように戻ってくる。往復をくり返す。","en":"A square travels to one end, then comes back along the same path as if played in reverse, again and again.","zh-Hans":"方块运动到一端后，像倒放一样沿原路径返回，持续往返。"},"spec":{"ja":["4.7秒で1往復: 前半2.35秒は再生、後半2.35秒は同じ動きを逆再生（進み具合 g は 0→1→0 を直線で）","ミントの角丸四角（48px・角丸13）が x=92→447 を、高さ 62·|sin(3πg)| の山3つで跳ねて進み、同時に g に合わせて1回転する","残像4つ（0.045秒ずつ遅れ・不透明度0.1〜0.4）","下に再生バー: 再生中は青で「▶ 再生」、逆再生中はコーラルで「◀ 逆再生」。進み具合のバーとつまみが g に合わせて行き来する","両端の折り返し点に縦の柱"],"en":["One round trip per 4.7 s: 2.35 s forward, then the same motion played backwards for 2.35 s (progress g goes 0→1→0, linear).","A mint rounded square (48 px, radius 13) hops from x = 92 to 447 along three arches of height 62·|sin(3πg)|, turning one full turn with g.","Four ghost copies, 0.045 s apart, opacity 0.1–0.4.","A playback bar below: blue with a play label while going forward, coral with a reverse label while going back. The progress bar and its knob follow g.","Vertical posts mark the two turning points."],"zh-Hans":["每 4.7 秒往返一轮，正向 2.35 秒，再反向播放同样动作 2.35 秒；进度 g 线性 0→1→0。","薄荷色圆角方块边长 48 px、圆角 13，从 x = 92 跳至 447，沿三段高度 62·|sin(3πg)| 的弧线运动，并随 g 转一整圈。","四个残影间隔 0.045 秒，透明度 0.1–0.4。","下方播放条正向时为蓝色与播放标签，反向时为珊瑚色与倒放标签；进度条和滑块跟随 g。","两端转折位置用竖柱标记。"]},"use":{"ja":"ローディング・待機中の飾り・繰り返して見せたい動きに。途切れずに往復させたいとき。","en":"Use it for loaders, idle animations and any move that should repeat back and forth without a cut.","zh-Hans":"适合加载、待机或不经跳切反复往返的动作。"},"tags":["ping-pong","loop","boomerang","yoyo","reverse","back-and-forth","loader"]},{"id":"128","pack":"motion2","no":"08","slug":"stop-motion-style","category":"techniques","width":539,"height":208,"cycle":4.7,"name":{"ja":"ストップモーション風","en":"Stop-motion style","zh-Hans":"定格动画风格"},"meaning":{"ja":"コマを落としてカクカク動かす","en":"Moves in choppy steps, with frames dropped","zh-Hans":"通过跳帧产生逐格、顿挫的运动"},"ask":{"ja":"この動きをストップモーション風にして。1秒8コマで、コマごとに少しだけ位置をぶらして。","en":"Make this move stop-motion style: 8 frames per second, with a slight jitter on every frame.","zh-Hans":"这段运动做定格动画风格，每秒八帧，每帧加轻微抖动。"},"summary":{"ja":"星が1秒8コマほどのカクカクした動きで跳ねて進み、コマごとに位置が少しずつぶれる。","en":"A star hops across in choppy steps at about 8 frames per second, each frame slightly off.","zh-Hans":"星形以约每秒八帧的顿挫节奏跳过画面，每帧略有偏差。"},"spec":{"ja":["4.7秒に38コマ（約8コマ/秒・1コマ約0.124秒）。そのコマの絵だけを出し、間は補わない","黄色い星（半径38）が x=−44→583 を、高さ 54·|sin(3πt)| の山3つで跳ねて進み、2回転する","コマごとに決め打ちの乱数でぶらす: 位置 横±5px・縦±4.5px、角度±0.15rad、大きさ±5%","直前の2コマを薄く残す（不透明度0.28と0.12。オニオンスキンのように）","上下に黒いフィルムの帯（各26px・送り穴つき）、右上に「8コマ/秒」"],"en":["38 frames per 4.7 s (about 8 per second, each held for about 0.124 s). Only those frames are drawn; nothing is drawn in between.","A yellow star (radius 38) hops from x = −44 to 583 along three arches of height 54·|sin(3πt)|, turning twice.","Each frame gets a fixed random jitter: position ±5 px across and ±4.5 px up and down, rotation ±0.15 rad, size ±5%.","The previous two frames stay faintly visible (opacity 0.28 and 0.12), like onion skin.","Black film-strip bands top and bottom (26 px each, with sprocket holes) and a frames-per-second label."],"zh-Hans":["每 4.7 秒38 帧，约每秒 8 帧，每帧保持约 0.124 秒；只绘制这些帧，不做帧间补间。","黄色星形半径 38，从 x = −44 跳至 583，沿三段高度 54·|sin(3πt)| 的弧线前进，并转两圈。","每帧使用固定随机扰动：横向 ±5 px、纵向 ±4.5 px、旋转 ±0.15 rad、尺寸 ±5%。","前两帧保留为淡残影，透明度 0.28 和 0.12，类似洋葱皮。","上下各有高 26 px、带齿孔的黑色胶片条，并显示帧率标签。"]},"use":{"ja":"手作り感・クレイアニメ風・コラージュ風の映像に。なめらかすぎる動きを素朴に見せたいとき。","en":"Use it for a handmade, claymation or collage look, when smooth motion feels too slick.","zh-Hans":"适合手工、黏土或拼贴风格，避免过于光滑的运动。"},"tags":["stop-motion","choppy","frame-rate","on-twos","jitter","handmade","claymation"]},{"id":"129","pack":"motion2","no":"09","slug":"text-scramble","category":"text-shapes","width":539,"height":208,"cycle":4.7,"name":{"ja":"テキストスクランブル","en":"Text scramble","zh-Hans":"文字乱码解码"},"meaning":{"ja":"文字がランダムに入れ替わってから決まる","en":"Letters shuffle at random, then settle","zh-Hans":"字符随机变化，随后逐个锁定为目标文字"},"ask":{"ja":"見出しをテキストスクランブルで出して。ランダムな文字が1秒ほど入れ替わって、左から順に決まる。","en":"Bring the headline in with a text scramble: random characters for about 1 s, settling from left to right.","zh-Hans":"标题用文字乱码解码入场，随机字符持续约一秒，再从左到右锁定。"},"summary":{"ja":"ランダムな文字が入れ替わり続け、左から順に正しい単語に決まる。","en":"Random characters keep changing, then lock into the right word from left to right.","zh-Hans":"随机字符持续变化，随后从左到右固定成正确单词。"},"spec":{"ja":["前半2.35秒は「HELLO」、後半は「WORLD」。5文字の等幅フォント（92px）","決まっていない文字: A〜Z（IとOを除く）・0〜9・#$%&@? からランダムに選び、4.7秒に76回（約0.062秒ごと）入れ替える。ミントで不透明度0.75","左から順に決まる: i 文字目は 0.45 + 0.18i 秒（最後は1.17秒）。決まった瞬間から0.22秒は黄、その後は白。拡大率 1 + 0.2·e^(−14t) で落ち着く","1.85秒から右から順にまたランダムへ戻る（i 文字目は 1.85 + 0.08×(4 − i) 秒）","各文字の下に横棒: 決まった文字は青、次に決まる文字は黄、それ以外は紺"],"en":["\"HELLO\" in the first 2.35 s, \"WORLD\" in the second. Five monospaced letters (92 px).","Unsettled slots show random characters from A–Z (without I and O), 0–9 and #$%&@?, changing 76 times per 4.7 s (about every 0.062 s), mint at 75% opacity.","Slots lock from left to right: slot i at 0.45 + 0.18i s (the last at 1.17 s). A newly locked letter is yellow for 0.22 s, then white, settling with scale 1 + 0.2·e^(−14t).","From 1.85 s the slots return to random from right to left (slot i at 1.85 + 0.08 × (4 − i) s).","A bar under each slot: blue when locked, yellow for the next one to lock, navy otherwise."],"zh-Hans":["前 2.35 秒显示“HELLO”，后半显示“WORLD”；五个 92 px 等宽字符。","未锁定位置从 A–Z 中排除 I、O，加上 0–9 和 #$%&@? 随机选字，每 4.7 秒变化 76 次，约每 0.062 秒一次，薄荷色、透明度 75%。","从左向右锁定，第 i 位在 0.45 + 0.18i 秒锁定，最后一位为 1.17 秒；新锁定字符先黄 0.22 秒再变白，缩放按 1 + 0.2·e^(−14t) 回落。","从 1.85 秒起由右向左恢复随机，第 i 位在 1.85 + 0.08 × (4 − i) 秒解锁。","每个字符下有横条：已锁定蓝色、下一个待锁定黄色，其余深蓝。"]},"use":{"ja":"見出し・数字・コードネームの登場に。解読・ハッキング・テック系の雰囲気を出したいとき。","en":"Use it to bring in a headline, a number or a code name with a decoding, hacker or tech feel.","zh-Hans":"适合标题、数字或代号的解码、黑客、科技感入场。"},"tags":["text-scramble","scramble","decode","shuffle","random","text","hacker"],"aliases":{"zh-Hans":["乱码","解码"]}},{"id":"130","pack":"motion2","no":"10","slug":"wave-text","category":"text-shapes","width":539,"height":208,"cycle":4.7,"name":{"ja":"ウェーブテキスト","en":"Wave text","zh-Hans":"波浪文字"},"meaning":{"ja":"文字が波のように順に上下する","en":"Letters rise and fall in turn, like a wave","zh-Hans":"字符依次上下起伏，形成波浪"},"ask":{"ja":"ロゴの文字をウェーブテキストで動かして。1文字ずつずらして、上下20pxくらい。","en":"Animate the logo letters as wave text, each letter slightly behind the last, about 20 px up and down.","zh-Hans":"标志字符做波浪文字，依次略微延迟，上下约 20 px。"},"summary":{"ja":"「WAVE TEXT」の文字が1文字ずつ、波のように順に上下する。","en":"The letters of \"WAVE TEXT\" rise and fall one after another, like a wave.","zh-Hans":"“WAVE TEXT”的字符依次升降，像波浪一样传播。"},"spec":{"ja":["「WAVE TEXT」（70px・太字・字間4px）。4.7秒に3回の波（1波1.567秒）","i 文字目の縦の位置 = −28·sin(φ − 0.62i)。φ = 2π × 3 × 時間 ÷ 4.7（隣の文字は0.62radずつ遅れる）","上がっている文字ほど縦に伸ばし（1 + 0.06·s）、色を白→黄に寄せる（s = sin の値。0〜1に制限して混ぜる）","各文字の下に影の楕円。文字が上がるほど小さくする"],"en":["\"WAVE TEXT\" (70 px, bold, 4 px letter spacing). Three waves per 4.7 s (1.567 s per wave).","Vertical offset of letter i = −28·sin(φ − 0.62i), with φ = 2π × 3 × time ÷ 4.7 (each letter lags the previous by 0.62 rad).","Rising letters stretch vertically (1 + 0.06·s) and shift from white towards yellow (s is the sine value, clamped to 0–1 for the colour).","A shadow ellipse under each letter shrinks as the letter rises."],"zh-Hans":["“WAVE TEXT”为 70 px 粗体、字距 4 px；每 4.7 秒三次波动，每次 1.567 秒。","第 i 字符纵向偏移 = −28·sin(φ − 0.62i)，φ = 2π × 3 × time ÷ 4.7；各字符比前一个延迟 0.62 rad。","上升字符纵向拉伸为 (1 + 0.06·s)，颜色由白趋黄；s 为正弦值，着色时限制在 0–1。","各字符下的椭圆阴影在字符升高时缩小。"]},"use":{"ja":"ロゴ・短い見出し・BGMに合わせたテロップに。楽しさやリズム感を出したいとき。","en":"Use it on a logo, a short heading or a caption timed to music, to add fun and rhythm.","zh-Hans":"适合标志、短标题或配乐字幕，增加趣味和节奏。"},"tags":["wave-text","wave","text","letters","stagger","bounce","kinetic-type"]},{"id":"131","pack":"motion2","no":"11","slug":"text-on-a-path","category":"text-shapes","width":539,"height":208,"cycle":4.7,"name":{"ja":"テキストオンパス","en":"Text on a path","zh-Hans":"沿路径文字"},"meaning":{"ja":"文字が線に沿って流れる","en":"Text flows along a line or curve","zh-Hans":"文字沿线条或曲线流动"},"ask":{"ja":"キャッチコピーをテキストオンパスで、波線に沿って左から右へ流して。1周5秒で。","en":"Run the tagline as text on a path along a wavy line, scrolling left to right, one full pass every 5 s.","zh-Hans":"标语沿波浪路径从左向右滚动，每五秒走完一轮。"},"summary":{"ja":"文字列が、波打つ線に沿って向きを変えながら流れていく。","en":"A line of text flows along a wavy line, each letter turning to follow it.","zh-Hans":"一行文字沿波浪曲线流动，每个字符随路径方向旋转。"},"spec":{"ja":["道: y = 118 + 42·sin(2πx ÷ 330 + 0.6)、x = −70〜609。紺の破線（14/10・線幅5）で6px下に見せる","「ALONG THE LINE • 」（42px・太字・字間2px）をくり返し並べる。1文字ずつ、道の上の長さ（弧長）の位置に置き、道の向きに回す","4.7秒で文字列1回分の長さだけ道に沿って進める（ループがつながる）","文字は白、「•」は黄"],"en":["Path: y = 118 + 42·sin(2πx ÷ 330 + 0.6) for x = −70 to 609, shown 6 px below as a navy dashed line (14/10, width 5).","\"ALONG THE LINE • \" (42 px, bold, 2 px letter spacing) is repeated. Each character is placed at its arc-length position on the path and rotated to the path direction.","The text moves along the path by the length of one copy of the string every 4.7 s, so the loop joins up.","Letters are white; the bullet is yellow."],"zh-Hans":["路径 y = 118 + 42·sin(2πx ÷ 330 + 0.6)，x = −70 至 609；下移 6 px 显示深蓝虚线，节距 14/10、线宽 5。","重复“ALONG THE LINE • ”，42 px 粗体、字距 2 px；各字符按路径弧长定位，并旋转至路径方向。","文字每 4.7 秒沿路径移动一个完整字符串的长度，保证无缝循环。","字母白色，圆点黄色。"]},"use":{"ja":"ロゴのまわり・道や川・波の上など、形に沿って文字を流したいとき。ループする帯の文字にも。","en":"Use it to run text along a shape: around a logo, along a road, river or wave, or as a looping band of text.","zh-Hans":"适合沿标志、道路、河流或波浪排字，也可做循环文字带。"},"tags":["text-on-path","path-text","curved-text","text","marquee","wave","scroll"]},{"id":"132","pack":"motion2","no":"12","slug":"variable-font-animation","category":"text-shapes","width":539,"height":208,"cycle":4.7,"name":{"ja":"可変フォントアニメーション","en":"Variable font animation","zh-Hans":"可变字重动画"},"meaning":{"ja":"文字の太さがなめらかに変わる","en":"The weight of the letters changes smoothly","zh-Hans":"字形粗细连续变化"},"ask":{"ja":"タイトルを可変フォントアニメーションで、細字から極太へ1秒で変えて。","en":"Use a variable font animation on the title: from Thin to Black (weight 100 to 900) in 1 s.","zh-Hans":"标题做可变字重动画，用一秒从 Thin 变到 Black，字重从 100 到 900。"},"summary":{"ja":"同じ単語の太さが、細→極太→細となめらかに変わり、下のつまみが太さを示す。","en":"The same word goes smoothly from thin to very bold and back, with a slider below showing the weight.","zh-Hans":"同一单词由细到极粗再变细，下方滑块显示当前字重。"},"spec":{"ja":["「MOTION」（112px・system-ui・字間2px）。太さを4.7秒に2往復: v = 0.5 − 0.5·cos(2π × 2 × 時間 ÷ 4.7)（cosなので両端でなめらかに止まる）","太さ = round(100 + 800v)（100〜900）をそのままフォントの太さに入れる","下にスライダー（x=112→427・y=180）。左に「細」、右に「太」。つまみ（黄・半径14）が v に合わせて動き、上に今の太さの数字を出す"],"en":["\"MOTION\" (112 px, system-ui, 2 px letter spacing). The weight goes back and forth twice per 4.7 s: v = 0.5 − 0.5·cos(2π × 2 × time ÷ 4.7), which eases at both ends.","Weight = round(100 + 800v), from 100 to 900, set directly as the font weight.","A slider below (x = 112→427, y = 180) labelled thin on the left and bold on the right. The knob (yellow, radius 14) follows v, with the current weight shown above it."],"zh-Hans":["“MOTION”为 112 px、system-ui、字距 2 px；每 4.7 秒字重往返两次，v = 0.5 − 0.5·cos(2π × 2 × time ÷ 4.7)，两端自然减速。","字重 = round(100 + 800v)，从 100 到 900，直接设置 font-weight。","下方滑轨 x = 112→427、y = 180，左标细、右标粗；黄色滑块半径 14，跟随 v，上方显示当前字重。"]},"use":{"ja":"タイトル・ロゴ・強調したい一語に。文字の形そのものを動かして、音や感情の強弱を見せたいとき。","en":"Use it on a title, a logo or a single word to show loudness or emotion through the letters themselves.","zh-Hans":"适合标题、标志或单词，用字体本身表达音量或情绪。"},"tags":["variable-font","font-weight","typography","text","weight","kinetic-type"]},{"id":"133","pack":"motion2","no":"13","slug":"text-mask","category":"text-shapes","width":539,"height":208,"cycle":4.7,"name":{"ja":"テキストマスク","en":"Text mask","zh-Hans":"文字遮罩"},"meaning":{"ja":"文字の形にくり抜いて中の柄を見せる","en":"Letters cut out to show a picture inside","zh-Hans":"用文字轮廓裁出内部图像"},"ask":{"ja":"「OCEAN」の文字をテキストマスクにして、中に波の映像を見せて。最後の1秒で外側も見せる。","en":"Use the word OCEAN as a text mask with ocean footage inside, and reveal the whole footage in the last second.","zh-Hans":"把 OCEAN 作为文字遮罩，内部播放海面素材，最后一秒显露完整画面。"},"summary":{"ja":"太い文字の形にくり抜いて、その中だけに動く海の景色が見える。周期の終わりに外側も見せる。","en":"Heavy letters are cut out so that a moving seascape shows only inside them; near the end of the cycle the whole picture appears.","zh-Hans":"粗体文字镂空，运动海景只显示在字内，周期接近结束时显露整幅画面。"},"spec":{"ja":["「OCEAN」（太さ900・system-ui・字間2px）。幅500px以下に収まるよう、172pxから2pxずつ小さくして文字の大きさを決める","中の景色（動き続ける）: コーラルの空、黄色い太陽（上下±6px）、y=116から下は青い海に白い波線4本（4.7秒で240pxずつ交互の向きに流れる）、ヨットが4.7秒で1回横切る、雲が60px流れる","作り方: 別のキャンバスに文字を描き、source-in で景色を重ねる（文字の形の中だけ景色が残る）。文字のふちに白い線（線幅4）","文字の外では景色を不透明度12%で見せ、3.45〜3.85秒に100%まで上げ、4.25〜4.65秒に12%へ戻す（smoothstep）"],"en":["\"OCEAN\" (weight 900, system-ui, 2 px letter spacing). The font size starts at 172 px and drops 2 px at a time until the word is at most 500 px wide.","The scene inside keeps moving: coral sky, a yellow sun bobbing ±6 px, blue sea below y = 116 with four white wavy lines drifting 240 px per 4.7 s in alternating directions, a sailboat crossing once per 4.7 s, clouds drifting 60 px.","Method: draw the word on an offscreen canvas, then composite the scene onto it with source-in, so the scene remains only inside the letters. A white 4 px outline around the letters.","Outside the letters the scene shows at 12% opacity; it rises to 100% at 3.45–3.85 s and returns to 12% at 4.25–4.65 s (smoothstep)."],"zh-Hans":["“OCEAN”使用字重 900、system-ui、字距 2 px；字号从 172 px 开始，每次减 2 px，直到词宽不超过 500 px。","字内场景持续运动：珊瑚色天空、上下 ±6 px 的黄色太阳、y = 116 以下的蓝海；四条白波纹交替反向，每 4.7 秒漂移 240 px；帆船每 4.7 秒穿过一次，云漂移 60 px。","在离屏画布绘制文字，再用 source-in 合成场景，只保留字内图像；文字外有白色 4 px 描边。","字外场景透明度为 12%，在 3.45–3.85 秒升至 100%，4.25–4.65 秒返回 12%，使用 smoothstep。"]},"use":{"ja":"タイトル・ブランド名の中に写真や映像を見せたいとき。言葉とイメージを1つにまとめたいとき。","en":"Use it to show a photo or footage inside a title or brand name, putting the word and the picture together.","zh-Hans":"适合把照片或视频放进标题、品牌名，让文字与图像结合。"},"tags":["text-mask","mask","clipping-mask","knockout","text","typography","title"],"aliases":{"zh-Hans":["文字蒙版","遮罩"]}},{"id":"134","pack":"motion2","no":"14","slug":"repeater","category":"text-shapes","width":539,"height":208,"cycle":4.7,"name":{"ja":"リピーター","en":"Repeater","zh-Hans":"图形重复器"},"meaning":{"ja":"図形を複製して並べて回す","en":"Duplicates a shape and turns the copies","zh-Hans":"复制图形，并对副本做旋转排列"},"ask":{"ja":"この花びらの形をリピーターで12枚、円に並べて、4秒で1回転させて。","en":"Use a repeater to make 12 copies of this petal in a circle, turning once every 4 s.","zh-Hans":"用重复器把花瓣复制十二份围成圆，每四秒转一圈。"},"summary":{"ja":"1つの図形が複製されて円に並び、少しずつずれながら回る。","en":"One shape is duplicated around a circle, and the copies turn and pulse slightly out of step.","zh-Hans":"图形沿圆周复制，各副本略微错开地旋转与脉动。"},"spec":{"ja":["角丸の棒（24×60・角丸12）を中央の半径58の円に最大12個並べる。それぞれ外向きに回す（角度 + 90°）","個数: 0.35〜1.7秒に1→12、3.6〜4.45秒に12→1（easeInOut・2乗）。新しい複製は前の位置から30°先の自分の位置へ滑って出る（easeOut・3乗）","全体を4.7秒で1回転。各複製の大きさを 1 ± 0.22 で4.7秒に2回脈打たせ、1つ先ほど0.55radずつ遅らせる（輪をまわる波になる）","色は青・コーラル・黄・ミントの順。元の1個には白いふち。右上に「×個数」"],"en":["A rounded bar (24 × 60, radius 12) is copied up to 12 times around a circle of radius 58 at the centre, each turned to face outward (angle + 90°).","Count: 1→12 at 0.35–1.7 s and 12→1 at 3.6–4.45 s (quadratic ease-in-out). Each new copy slides from the previous slot to its own, 30° further on (cubic ease-out).","The whole ring turns once per 4.7 s. Each copy pulses in size by 1 ± 0.22 twice per 4.7 s, each one 0.55 rad later than the last, so a ripple runs round the ring.","Colours go blue, coral, yellow, mint. The original copy has a white outline. A \"×N\" counter at the top right."],"zh-Hans":["24 × 60、圆角 12 的圆角条最多复制12 份，围绕中央半径 58 的圆排列，每份朝向外侧，即角度 + 90°。","数量在 0.35–1.7 秒从 1→12，3.6–4.45 秒从 12→1，二次缓入缓出；每个新副本从前一位置滑到自身位置，多转 30°，采用三次缓出。","整圈每 4.7 秒转一周；各副本每 4.7 秒脉动两次，尺寸为 1 ± 0.22，相邻错开 0.55 rad，形成环形波。","颜色依次蓝、珊瑚、黄、薄荷；原始副本带白色轮廓，右上角显示“×N”计数。"]},"use":{"ja":"ローディング・背景の模様・花や光の放射など、同じ形をくり返して並べたいとき。","en":"Use it for loaders, background patterns, flowers or rays: anything built from one shape repeated.","zh-Hans":"适合加载环、背景纹样、花朵、光线等重复图形。"},"tags":["repeater","duplicate","radial","array","clone","pattern","loader"]},{"id":"135","pack":"motion2","no":"15","slug":"kaleidoscope","category":"text-shapes","width":539,"height":208,"cycle":4.7,"name":{"ja":"カレイドスコープ","en":"Kaleidoscope","zh-Hans":"万花筒"},"meaning":{"ja":"万華鏡のように対称に広がる","en":"Mirrored patterns spread out symmetrically","zh-Hans":"镜像图案对称扩散"},"ask":{"ja":"ロゴの背景にカレイドスコープを入れて。8分割の対称で、ゆっくり回しながら広げて。","en":"Put a kaleidoscope behind the logo: 8-way mirror symmetry, turning slowly as it spreads out.","zh-Hans":"标志后加万花筒，八向镜像对称，缓慢转动并向外扩散。"},"summary":{"ja":"万華鏡のように、8分割の対称な模様が回りながら中心から広がる。","en":"An 8-way symmetrical pattern turns and spreads out from the centre, like a kaleidoscope.","zh-Hans":"八向对称图案从中心旋转扩散，像万花筒。"},"spec":{"ja":["中心のまわりを45°ずつ8つに分け、奇数番目は左右反転して描く（鏡の対称が8つ）","1区画の中に図形13個（丸・ひし形・三角、4色、乱数はシード固定）。中心から半径300まで外へ進み、4.7秒で半径1つ分（端まで行くと中心へ戻る）","図形は外へ行くほど大きく（(5 + 0.1r) × 0.7〜1.4）、進むほど回す（1pxあたり0.02rad）。最初の30pxで現れ、最後の70pxで消える。角度は4.7秒に1回 ±0.08rad 揺らす","模様全体は4.7秒で90°回す（区画2つ分なのでループがつながる）","中心に白い8角の星（半径20 ± 4・4.7秒に2回脈打つ）"],"en":["The area around the centre is split into eight 45° wedges; every other wedge is drawn mirrored, giving eight mirror-symmetric sections.","One wedge holds 13 shapes (circles, diamonds, triangles; four colours; fixed random seed). They travel outward from the centre to radius 300, one full radius per 4.7 s, wrapping back to the centre.","Shapes grow as they go out ((5 + 0.1r) × 0.7–1.4) and spin 0.02 rad per px. They fade in over the first 30 px and out over the last 70 px; each sways ±0.08 rad once per 4.7 s.","The whole pattern turns 90° per 4.7 s (two wedges, so the loop joins up).","A white eight-point star at the centre (radius 20 ± 4, pulsing twice per 4.7 s)."],"zh-Hans":["中心周围分为八个 45° 扇区，隔一个扇区做镜像，形成八向镜面对称。","每个扇区含13 个圆、菱形或三角，四色、固定随机种子；每 4.7 秒从中心走到半径 300，再回到中心循环。","图形向外时增大，尺寸 ((5 + 0.1r) × 0.7–1.4)，每 px 旋转 0.02 rad；前 30 px 淡入，后 70 px 淡出；每 4.7 秒左右摆动 ±0.08 rad 一次。","整幅图案每 4.7 秒转 90°，即两个扇区，使循环对齐。","中央为白色八角星，半径 20 ± 4，每 4.7 秒脉动两次。"]},"use":{"ja":"ミュージックビデオ・ライブの背景・幻想的な場面転換に。くり返し見ても飽きない模様がほしいとき。","en":"Use it for music videos, live backdrops or dreamy scene changes, wherever a pattern has to hold up on repeat.","zh-Hans":"适合音乐视频、现场背景或梦幻转场，可持续循环观看。"},"tags":["kaleidoscope","symmetry","mirror","mandala","pattern","radial","psychedelic"]},{"id":"136","pack":"motion2","no":"16","slug":"line-boil","category":"text-shapes","width":539,"height":208,"cycle":4.7,"name":{"ja":"ラインボイル","en":"Line boil","zh-Hans":"手绘线条抖动"},"meaning":{"ja":"手描きの線が小刻みに揺らぐ","en":"Hand-drawn lines wobble frame to frame","zh-Hans":"手绘轮廓在逐帧重画时轻微变化"},"ask":{"ja":"手描きのイラストにラインボイルを付けて。1秒10コマで、線を2〜3pxだけ揺らして。","en":"Add line boil to the hand-drawn illustration: 10 frames per second, with the lines shifting only 2–3 px.","zh-Hans":"手绘插画加线条抖动，每秒十帧，线条仅移动 2–3 px。"},"summary":{"ja":"手描き風の線の絵が、数コマごとに小刻みに揺らぐ。絵そのものは動かない。","en":"A hand-drawn line picture wobbles every few frames while the picture itself stays still.","zh-Hans":"画面本身静止，手绘轮廓每隔几帧轻微晃动。"},"spec":{"ja":["止まった線画（黄の星・白の雲・ミントのきらめき線・薄い地面の線）。線幅6〜8・端は丸","絵は動かさず、4.7秒に47回（約0.1秒ごと）全部の点を描き直す。各点を横・縦それぞれ±3.5pxの決め打ちの乱数でずらす","線はあらかじめ点の列にしておき（6〜13pxおき。雲は輪郭の96点）、隣の点の中点を通る2次曲線でつないで描く（手描きのコマのようにゆらぐ）","乱数はコマ番号と点の番号から作る（同じコマはいつも同じ形）"],"en":["A still line drawing (a yellow star, a white cloud, mint sparkle strokes, a faint ground line). Line widths 6–8, round caps.","The drawing does not move. 47 times per 4.7 s (about every 0.1 s) every point is redrawn with a fixed random offset of up to ±3.5 px in x and in y.","Each line is first turned into a row of points (every 6–13 px; 96 points round the cloud) and drawn as quadratic curves through the midpoints between them, so it wobbles like hand-drawn frames.","The offsets are a hash of the frame number and the point number, so the same frame always looks the same."],"zh-Hans":["静态线描包括黄色星形、白云、薄荷色闪光线和浅地面线，线宽 6–8、圆形端点。","画面不移动，每 4.7 秒重画47 次，约每 0.1 秒一次；各点使用固定随机偏移，x、y 最大均为 ±3.5 px。","各线先按每 6–13 px 取点，云轮廓96 点，再以相邻点中点构建二次曲线，形成逐帧手绘抖动。","偏移由帧号与点号的哈希决定，同一帧始终相同。"]},"use":{"ja":"手描き風のイラスト・アイコン・文字に。止まった絵にも、手で描いたような生きた感じを出したいとき。","en":"Use it on hand-drawn illustrations, icons or lettering to make even a still picture feel drawn by hand.","zh-Hans":"适合手绘插画、图标或字体，让静态画面仍有手绘生命感。"},"tags":["line-boil","boil","hand-drawn","wobble","jitter","sketch","frame-by-frame"]},{"id":"137","pack":"motion2","no":"17","slug":"push-transition","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"プッシュ","en":"Push transition","zh-Hans":"推移转场"},"meaning":{"ja":"次の画面が前の画面を押し出す","en":"The next scene pushes the current one out","zh-Hans":"下一场景滑入，同时把当前场景推出"},"ask":{"ja":"次のスライドへはプッシュで。右から0.8秒で押し出すように。","en":"Go to the next slide with a push transition from the right, 0.8 s.","zh-Hans":"下一页从右侧推入转场，持续 0.8 秒。"},"summary":{"ja":"次の画面が横から入ってきて、前の画面を一緒に押し出す。","en":"The next scene slides in from the side and pushes the current one out with it.","zh-Hans":"下一场景从侧面滑入，与当前场景一起运动并将其推出。"},"spec":{"ja":["海の画面 → 山の画面 → 海の画面を2.35秒ずつ。各区間の 0.45〜1.6秒（1.15秒）で切り替え、easeInOut（3乗）","2つの画面をつなげたまま、一緒に画面の幅（539px）だけ動かす。重ねたり薄くしたりしない","向き: 海→山は左へ（次の画面は右から）、山→海は右へ","2つの画面の境目に紺の線（幅6）"],"en":["Sea scene → mountain scene → sea scene, 2.35 s each. The change runs at 0.45–1.6 s of each half (1.15 s), cubic ease-in-out.","The two scenes stay joined and move together by the full frame width (539 px); no overlap and no fade.","Direction: sea→mountain moves left (the next scene enters from the right); mountain→sea moves right.","A navy line (width 6) marks the seam between the two scenes."],"zh-Hans":["海景→山景→海景，各占 2.35 秒；每半段的 0.45–1.6 秒转场，持续 1.15 秒，采用三次缓入缓出。","两场景保持相接，同时移动整个画面宽度 539 px，无重叠、无淡化。","海转山向左移动，下一场景从右侧进入；山转海向右移动。","两场景接缝用线宽 6 的深蓝线标记。"]},"use":{"ja":"スライド・写真・手順を順番に送るとき。続いている感じ、前へ進む感じを出したいとき。","en":"Use it to step through slides, photos or steps, when the change should feel continuous and moving forward.","zh-Hans":"适合连续前进的幻灯片、照片或步骤切换。"},"tags":["push","push-transition","slide","transition","scene-change","carousel"]},{"id":"138","pack":"motion2","no":"18","slug":"blinds-transition","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"ブラインド","en":"Blinds transition","zh-Hans":"百叶窗转场"},"meaning":{"ja":"細い帯の隙間から次の画面が開く","en":"The next scene opens through thin strips","zh-Hans":"通过多条窄带逐渐打开下一场景"},"ask":{"ja":"場面の切り替えをブラインドで。横の帯7本で、1秒かけて開くように。","en":"Change scenes with a blinds transition: seven horizontal strips that open over 1 s.","zh-Hans":"用七条横带做百叶窗转场，在一秒内展开。"},"summary":{"ja":"細い帯ごとのすき間がだんだん広がって、次の画面が開く。","en":"Gaps in a row of thin strips widen until the next scene is fully open.","zh-Hans":"一组窄条中的开口不断扩大，直到完整显露下一场景。"},"spec":{"ja":["昼の画面 → 夜の画面 → 昼を2.35秒ずつ。横の帯7本（1本 208÷7 ≒ 29.7px）","0.4〜1.65秒（1.25秒）、easeInOut（2乗）: どの帯でも、帯の上端から下へ次の画面が見える部分を広げ、0から帯の高さいっぱいまで同時に開く","前の画面は下に置いたまま動かさない。どちらの画面の絵も動かさない"],"en":["Day scene → night scene → day, 2.35 s each. Seven horizontal strips (208 ÷ 7 ≈ 29.7 px each).","0.4–1.65 s (1.25 s), quadratic ease-in-out: in every strip at once, the next scene is revealed from the strip's top edge downward, opening from 0 to the full strip height.","The previous scene stays underneath. Neither picture moves."],"zh-Hans":["日景→夜景→日景，各占 2.35 秒；七条横带，每条 208 ÷ 7 ≈ 29.7 px。","0.4–1.65 秒，持续 1.25 秒，二次缓入缓出；每条同时从顶部向下揭示下一场景，开口由 0 增至整条高度。","前场景保持在下层，两幅画面都不移动。"]},"use":{"ja":"昼夜・季節・前後など、2つの場面をはっきり切り替えたいとき。レトロな雰囲気を出したいときにも。","en":"Use it for a clear switch between two scenes, such as day and night or before and after, or for a retro feel.","zh-Hans":"适合日夜、前后对比等明确场景切换，也可营造复古感。"},"tags":["blinds","venetian-blinds","stripes","transition","wipe","scene-change"]},{"id":"139","pack":"motion2","no":"19","slug":"cube-transition","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"キューブ","en":"Cube transition","zh-Hans":"立方体转场"},"meaning":{"ja":"立方体が回るように面が替わる","en":"Changes scenes like a turning cube","zh-Hans":"像立方体转动一样切换场景"},"ask":{"ja":"商品写真の切り替えをキューブで。左へ90°回して、0.8秒で。","en":"Switch the product shots with a cube transition, turning 90° to the left in 0.8 s.","zh-Hans":"产品图片用立方体转场，用 0.8 秒向左转 90°。"},"summary":{"ja":"立方体が回るように、前の面が奥へ倒れて次の面が現れる。","en":"Like a turning cube, the front face swings away and the next face comes round.","zh-Hans":"像立方体旋转一样，正面转走，下一面转入。"},"spec":{"ja":["面A（コーラル地に「A」）と面B（ミント地に「B」）、各250×146。2.35秒ずつ A→B→A","0.45〜1.6秒（1.15秒）に0→90°回す、easeInOut（3乗）。回転の軸は立方体の中心を通る縦の線（奥行きは面の幅と同じ250）","遠近: カメラまでの距離820px。面を幅2pxの縦の帯に分け、帯ごとに遠近の倍率で高さと位置を決めて描く","奥へ行く面は最大55%まで暗く（0.55·sinφ）、出てくる面は55%の暗さから明るくする（0.55·cosφ）。床の影の幅は見えている幅に合わせる"],"en":["Face A (an \"A\" on coral) and face B (a \"B\" on mint), each 250 × 146. 2.35 s each, A→B→A.","Rotation 0→90° at 0.45–1.6 s (1.15 s), cubic ease-in-out, around a vertical axis through the centre of the cube (depth equal to the face width, 250).","Perspective: camera distance 820 px. Each face is drawn as 2 px vertical slices, each sized and placed by its perspective factor.","The face turning away darkens up to 55% (0.55·sinφ); the incoming face starts 55% dark and brightens (0.55·cosφ). The floor shadow follows the visible width."],"zh-Hans":["A 面为珊瑚色底字母 A，B 面为薄荷色底字母 B，各为 250 × 146；各占 2.35 秒，A→B→A。","0.45–1.6 秒旋转 0→90°，持续 1.15 秒，三次缓入缓出；绕立方体中心竖轴，深度等于面宽 250。","透视相机距离 820 px，各面按宽 2 px 的竖条绘制，根据透视系数设置尺寸和位置。","转出面最多变暗 55%，公式 0.55·sinφ；转入面从 55% 暗度逐渐变亮，公式 0.55·cosφ；地面阴影跟随可见宽度。"]},"use":{"ja":"商品・プラン・画面を次々に見せるとき。立体感を出して、横に並んでいる物を順に見せたいとき。","en":"Use it to show products, plans or screens one after another with a sense of depth.","zh-Hans":"适合有纵深感地依次展示产品、方案或界面。"},"tags":["cube","cube-transition","3d","rotate","transition","perspective"]},{"id":"140","pack":"motion2","no":"20","slug":"page-curl","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"ページめくり","en":"Page curl","zh-Hans":"卷页转场"},"meaning":{"ja":"紙のようにめくれて次へ","en":"Peels back like paper to show the next page","zh-Hans":"像纸张卷起一样显露下一页"},"ask":{"ja":"次の章へはページめくりで。右下の角から1.2秒でめくって。","en":"Go to the next chapter with a page curl from the bottom-right corner, 1.2 s.","zh-Hans":"从右下角卷页进入下一章节，持续 1.2 秒。"},"summary":{"ja":"角から紙がめくれて裏返り、下から次のページが現れる。","en":"A page peels back from its corner and folds over, revealing the next page beneath.","zh-Hans":"页面从角落揭起并翻折，露出下方下一页。"},"spec":{"ja":["ページ1（白）→ ページ2（クリーム）→ ページ1を2.35秒ずつ。右下の角から、0.35〜1.75秒（1.4秒）、easeInOut（2乗）","折り目の線を、角から向き（−1, −0.42）（長さ1にそろえる）へ 0→600px 動かす","折り目より角側の部分を折り目で鏡に映して、めくれた裏面にする（薄いグレーかベージュ）。影（ぼかし14・ずれ4, 4）と白いふち（線幅2）を付ける","めくれたところには次のページを見せ、折り目に沿って50pxの影のグラデーション"],"en":["Page 1 (white) → page 2 (cream) → page 1, 2.35 s each. The curl starts at the bottom-right corner, 0.35–1.75 s (1.4 s), quadratic ease-in-out.","The fold line moves from the corner in the direction (−1, −0.42), normalised, by 0→600 px.","The part beyond the fold line is mirrored across it to form the flap, the back of the page (light grey or beige), with a drop shadow (blur 14, offset 4, 4) and a white 2 px edge.","The next page shows where the paper has lifted, with a 50 px shadow gradient along the fold."],"zh-Hans":["白色第 1 页→奶油色第 2 页→第 1 页，各占 2.35 秒；从右下角开始，在 0.35–1.75 秒卷起，持续 1.4 秒，二次缓入缓出。","折线沿归一化方向 (−1, −0.42) 从角落移动 0→600 px。","折线外部分沿折线镜像，形成浅灰或米色纸背；投影模糊 14、偏移 4, 4，带白色 2 px 边缘。","纸张抬起处显露下一页，折线沿边有 50 px 的阴影渐变。"]},"use":{"ja":"本・カタログ・アルバム・章の切り替えに。紙の手ざわりや、物語を読み進める感じを出したいとき。","en":"Use it for books, catalogues, albums or chapter breaks, where a paper feel or reading on suits the content.","zh-Hans":"适合书籍、目录、相册和章节切换，强调纸张与阅读感。"},"tags":["page-curl","page-turn","page-peel","paper","book","transition"]},{"id":"141","pack":"motion2","no":"21","slug":"pixelate","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"ピクセレート","en":"Pixelate","zh-Hans":"像素化转场"},"meaning":{"ja":"モザイクが粗くなって切り替わる","en":"Turns into coarse blocks, then switches","zh-Hans":"画面变成粗方块，在最粗时切换"},"ask":{"ja":"ピクセレートで切り替えて。0.6秒でモザイクが粗くなり、いちばん粗いところで次の画面へ。","en":"Use a pixelate transition: the mosaic gets coarser over 0.6 s and the scene changes at the coarsest point.","zh-Hans":"做像素化转场，马赛克用 0.6 秒变粗，在最粗时切换场景。"},"summary":{"ja":"画面がだんだん粗いモザイクになり、いちばん粗いところで切り替わって細かく戻る。","en":"The picture turns into coarser and coarser blocks, switches at the coarsest point, then sharpens again.","zh-Hans":"画面逐渐变成更粗的像素块，在最粗时切换，再恢复清晰。"},"spec":{"ja":["野原の画面 → 街の画面 → 野原を2.35秒ずつ。0.2〜1.9秒（1.7秒）に、モザイクの1マスの大きさを 1・2・3・4・6・8・11・15・20・27・36px と段階で上げて下げる（中間の1.05秒がいちばん粗い）","前半は前の画面、後半は次の画面（いちばん粗いところで差し替える）","作り方: 画面を 幅÷マス の大きさに縮めて（なめらか補間あり）、補間を切って元の大きさに引き伸ばす"],"en":["Field scene → city scene → field, 2.35 s each. At 0.2–1.9 s (1.7 s) the block size steps up and back down through 1, 2, 3, 4, 6, 8, 11, 15, 20, 27 and 36 px (coarsest at the midpoint, 1.05 s).","The first half shows the old scene and the second half the new one; the swap happens at the coarsest step.","Method: shrink the frame to width ÷ block size with smoothing on, then scale it back up with smoothing off."],"zh-Hans":["田野→城市→田野，各占 2.35 秒；0.2–1.9 秒，持续 1.7 秒，块大小按 1, 2, 3, 4, 6, 8, 11, 15, 20, 27, 36 px 逐级增大再缩小，中点 1.05 秒最粗。","前半显示旧场景，后半显示新场景，在最粗一级交换。","先开启平滑，将画面缩至原宽 ÷ 块尺寸，再关闭平滑放大回原尺寸。"]},"use":{"ja":"ゲーム風・レトロ・デジタルな場面転換に。隠したい物をぼかして切り替えたいときにも。","en":"Use it for game-like, retro or digital scene changes, or to blur something out as the scene switches.","zh-Hans":"适合游戏、复古或数字风格转场，也可在切换时模糊内容。"},"tags":["pixelate","mosaic","pixel","transition","retro","8-bit","scene-change"]},{"id":"142","pack":"motion2","no":"22","slug":"shatter","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"ガラス割れ","en":"Shatter","zh-Hans":"碎裂转场"},"meaning":{"ja":"ガラスのように割れて破片が飛ぶ","en":"Breaks like glass and the shards fly off","zh-Hans":"像玻璃一样破碎，碎片飞散"},"ask":{"ja":"タイトルの登場前に、前の画面をガラス割れで砕いて。ひびが入ってから破片が1秒で落ちるように。","en":"Before the title appears, break the previous scene with a shatter: cracks first, then the shards fall away in about 1 s.","zh-Hans":"标题出现前让旧场景碎裂，先出现裂纹，再让碎片在约一秒内落走。"},"summary":{"ja":"画面がガラスのようにひび割れ、破片が飛び散って次の画面が現れる。","en":"The picture cracks like glass, the shards fly off and the next scene is revealed.","zh-Hans":"画面像玻璃一样开裂，碎片飞散，露出下一场景。"},"spec":{"ja":["山の画面 → 昼の画面 → 山を2.35秒ずつ。割れる中心は（304, 92）","ひび: 0.3〜0.65秒。中心から放射の線13本と、半径およそ40・98・175（各±15%）の輪が、中心からの距離順に伸びる（easeOut・3乗で420pxまで）。中心に白い光の星（0.6秒で消える）","0.82秒に割れる: 破片52枚（13本×4段）に前の画面を切り抜き、中心から外へ 220〜480px/s で飛ばす（縦は0.7倍、上向きに最大120を足す）。重力1300px/s²、回転±4rad/s、1秒で最大35%縮む","外側の段ほど遅れて飛ぶ（1段0.035秒＋乱数で最大0.03秒）。各破片は飛び始めて0.55〜1.0秒で消える","破片には白いふち（線幅2.5）。下には次の画面"],"en":["Mountain scene → day scene → mountain, 2.35 s each. The impact point is (304, 92).","Cracks: 0.3–0.65 s. Thirteen radial lines and rings at radii of about 40, 98 and 175 (each ±15%) appear in order of distance from the centre (cubic ease-out, out to 420 px). A white flash star at the centre fades by 0.6 s.","The glass breaks at 0.82 s: 52 shards (13 × 4 rings) cut from the old scene fly outward at 220–480 px/s (vertical speed × 0.7, plus up to 120 upward), with gravity 1300 px/s², spinning ±4 rad/s and shrinking up to 35% over 1 s.","Outer rings leave later (0.035 s per ring plus up to 0.03 s at random). Each shard fades out 0.55–1.0 s after it starts moving.","Shards have a white 2.5 px edge; the next scene is underneath."],"zh-Hans":["山景→日景→山景，各占 2.35 秒；撞击点为 (304, 92)。","0.3–0.65 秒出现裂纹：十三条放射线与半径约 40, 98, 175 的环，各扰动 ±15%；由中心按距离依次展开，三次缓出延伸至 420 px；中央白色闪光星在 0.6 秒前淡出。","0.82 秒碎裂：从旧场景裁出 52 片，即 13 × 4 环，向外速度 220–480 px/s；纵向速度 × 0.7 并额外最多向上 120，重力 1300 px/s²，旋转 ±4 rad/s，在 1 秒内最多缩小 35%。","外圈更晚飞离，每圈延迟 0.035 秒，另加最多 0.03 秒随机延迟；各碎片在开始移动后 0.55–1.0 秒淡出。","碎片带白色 2.5 px 边缘，下一场景位于下方。"]},"use":{"ja":"衝撃・破壊・どんでん返しの場面転換に。タイトルや結果を強く見せる直前に。","en":"Use it for an impact, a break or a twist, just before a title or a result that should hit hard.","zh-Hans":"适合在强烈标题或结果出现前制造冲击、破裂或转折。"},"tags":["shatter","glass-break","broken-glass","shards","crack","transition","impact"]},{"id":"143","pack":"motion2","no":"23","slug":"exploded-view","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"分解図","en":"Exploded view","zh-Hans":"爆炸分解图"},"meaning":{"ja":"部品がばらけて中の構造を見せる","en":"Parts separate to show the structure inside","zh-Hans":"将零件分离，展示内部结构"},"ask":{"ja":"製品の分解図を見せて。4つの部品が1秒でばらけて、名前のラベルを付けて。","en":"Show an exploded view of the product: four parts spread apart in 1 s, each with a name label.","zh-Hans":"产品做爆炸分解图，四个部件在一秒内分开，各带名称标签。"},"summary":{"ja":"スマホの部品が層ごとにばらけて中の構造を見せ、また組み上がる。","en":"A phone separates into its layers to show how it is built, then assembles again.","zh-Hans":"手机分成多个结构层展示内部构造，随后重新组装。"},"spec":{"ja":["アイソメトリックのスマホを4層（背面・電池・基板・画面）で作る。各層は平らな角丸の板を、0.85倍・左右30°に傾けた座標で描き、側面の厚み6px","ばらける: 0.45秒から各層0.75秒、上の層ほど0.08秒ずつ遅らせる。backOut(s=1.3)。下から i 段目（0〜3）の高さ = 7i + 30i × 進み具合（いちばん下の背面は動かない）","ばらけている間: 各層を ±3px で4.7秒に2回上下させ、角を結ぶ点線の補助線と、右へ引き出し線つきの名前ラベル（背面・電池・基板・画面）を出す","組み上がる: 3.25秒から各層0.7秒、いちばん上の層から0.07秒ずつ遅らせる。easeInOut（3乗）"],"en":["An isometric phone built from four layers (back cover, battery, circuit board, screen). Each layer is a flat rounded plate drawn on axes scaled by 0.85 and tilted 30° either way, with 6 px thick sides.","Separate: from 0.45 s, 0.75 s per layer, each layer 0.08 s after the one below, backOut (s = 1.3). Height of layer i (0–3 from the bottom) = 7i + 30i × progress, so the back cover stays put.","While apart, each layer bobs ±3 px twice per 4.7 s, dotted guide lines join the corners, and name labels with leader lines appear on the right (in Japanese in the demo).","Reassemble: from 3.25 s, 0.7 s per layer, starting with the top layer, 0.07 s apart, cubic ease-in-out."],"zh-Hans":["等距手机由后盖、电池、电路板、屏幕四层组成；各层为圆角平板，绘制轴缩放 0.85，分别倾斜 30°，侧面厚 6 px。","分离从 0.45 秒开始，每层 0.75 秒，比下层晚 0.08 秒，用 backOut（s = 1.3）；第 i 层高度 = 7i + 30i × progress，i 自底为 0–3，后盖保持原位。","分开时各层每 4.7 秒上下 ±3 px 两次，虚线连接各角，右侧出现带引线的名称标签，原演示为日文。","3.25 秒开始重组，每层 0.7 秒，从顶层开始，间隔 0.07 秒，三次缓入缓出。"]},"use":{"ja":"製品の中身・仕組み・構成要素を説明するとき。何でできているかを一目で見せたいとき。","en":"Use it to explain what is inside a product, how it works or what it is made of, at a glance.","zh-Hans":"适合直观说明产品内部、工作方式或材料组成。"},"tags":["exploded-view","explode","layers","isometric","product","breakdown","explainer"],"aliases":{"zh-Hans":["拆解","分解图"]}},{"id":"144","pack":"motion2","no":"24","slug":"split-screen","category":"transitions-highlights","width":539,"height":208,"cycle":4.7,"name":{"ja":"スプリットスクリーン","en":"Split screen","zh-Hans":"分屏"},"meaning":{"ja":"画面を分けて同時に見せる","en":"Divides the frame to show scenes side by side","zh-Hans":"分割画面，同时并列展示多个场景"},"ask":{"ja":"スプリットスクリーンで3つの場面を同時に見せて。1画面から2分割、3分割へ0.5秒ずつで。","en":"Show three scenes at once with a split screen: from one panel to two, then three, 0.5 s each.","zh-Hans":"同时显示三个场景，从一屏变两屏、再变三屏，每次 0.5 秒。"},"summary":{"ja":"1枚の画面が2つ、3つに分かれて、別々の場面が同時に動く。","en":"One full-frame scene splits into two panels, then three, each with its own scene moving.","zh-Hans":"全幅场景先分成两个面板，再分成三个，各面板中的场景持续运动。"},"spec":{"ja":["画面いっぱいの海の場面が、0.45〜0.95秒に2分割（境目 539→269.5）、1.4〜1.9秒に3分割（境目は 1/3 と 2/3）になる。3.75〜4.4秒に1画面へ戻る。どれも easeInOut（3乗）","3つの場面（海・街・野原）は、それぞれ自分の枠の中で中央に置き、枠で切り抜く。中は動き続ける（波とヨット、街の窓が4.7秒に8回点滅、風車が4.7秒に2回転）","枠の境目に白い線（幅6）"],"en":["A full-frame sea scene splits into two panels at 0.45–0.95 s (divider 539→269.5), then into three at 1.4–1.9 s (dividers at 1/3 and 2/3), and merges back into one at 3.75–4.4 s, all cubic ease-in-out.","The three scenes (sea, city, field) are each centred in and clipped to their own panel and keep moving inside it (waves and a sailboat, city windows switching 8 times per 4.7 s, a windmill turning twice per 4.7 s).","White dividers (width 6) between the panels."],"zh-Hans":["全幅海景在 0.45–0.95 秒分成两屏，分隔位置 539→269.5；1.4–1.9 秒变三屏，分隔在 1/3 和 2/3；3.75–4.4 秒合回一屏，均用三次缓入缓出。","海、城市、田野各自在面板内居中并裁剪，内部继续运动：海浪与帆船、城市窗户每 4.7 秒切换8 次、风车每 4.7 秒转两圈。","面板间为宽 6 的白色分隔线。"]},"use":{"ja":"比較・同時進行・複数の人や場所を並べて見せたいとき。ビフォーアフターや選択肢の紹介に。","en":"Use it to compare, to show things happening at once, or to line up several people or places, such as before and after or a set of options.","zh-Hans":"适合前后对比、同时发生的事件、多个人物或地点以及方案比较。"},"tags":["split-screen","multi-screen","panels","side-by-side","comparison","layout"]}]};
window.MP_PROMPT = function mpPrompt(el, packTitle, lang, site, apiBase) {
  lang = lang === 'zh' ? 'zh-Hans' : lang;
  var base = site || (typeof window !== 'undefined' && window.MP_SITE_CONFIG ? window.MP_SITE_CONFIG.site : '');
  var en = lang === 'en';
  var spec = (el.spec[lang] || el.spec.en).map(function (s) { return '- ' + s; }).join('\n');
  var api = apiBase || (typeof window !== 'undefined' && window.MP_SITE_CONFIG && window.MP_SITE_CONFIG.apiBase) || base + 'api/v1';
  api = api.replace(/\/+$/, '');
  var ref = api + '/' + lang + '/e/' + el.id + '.txt';
  var kit = api + '/kit/' + el.pack + '.js';
  var same = el.name.en === el.name.ja;
  var mean = el.meaning && (el.meaning[lang] || el.meaning.en);
  if (lang === 'zh-Hans') {
    return [
      '请使用“' + (el.name[lang] || el.name.en) + '（' + el.name.en + '）”，属于“' + packTitle + '”。',
      'Motion Prompt #' + el.id, '',
      '效果解释：' + mean,
      '动画表现：' + (el.summary[lang] || el.summary.en),
      '实现规格与关键运动参数：', spec,
      '适用场景：' + (el.use[lang] || el.use.en), '',
      '动画演示：' + base + '?lang=zh-Hans#' + el.id,
      '参考实现（Canvas 2D，画面仅由时间决定）：' + ref,
      '共享辅助代码：' + kit,
      '保留参考实现的形状、运动路径、时序、缓动和全部运动参数；按实际项目替换文字、颜色、图片、标志等素材，并接入项目现有实现方式。',
      '使用参考代码时保留 Shohei Ohtaki 的 MIT 版权标识。'
    ].join('\n');
  }
  if (en) {
    return [
      'Please use "' + el.name.en + '"' + (same ? '' : ' (' + el.name.ja + ')') + ', one of the names in "' + packTitle + '".',
      'Motion Prompt #' + el.id,
      ''
    ].concat(mean ? ['What it is: ' + mean] : [], [
      'What the sample shows: ' + el.summary.en,
      'Spec:',
      spec,
      'When to use it: ' + el.use.en,
      '',
      'Reference implementation (Canvas 2D, a function whose picture depends only on the time): ' + ref,
      'Shared helper code: ' + kit,
      'Keep the shapes, timing and easing values of the reference implementation as they are, and change only the text, colours and assets to fit what I am making.'
    ]).join('\n');
  }
  return [
    '「' + el.name.ja + (same ? '' : '（' + el.name.en + '）') + '」を使ってください。「' + packTitle + '」の名前の1つです。',
    'Motion Prompt #' + el.id,
    ''
  ].concat(mean ? ['どういうものか: ' + mean] : [], [
    '見本で起きること: ' + el.summary.ja,
    '仕様:',
    spec,
    '使いどころ: ' + el.use.ja,
    '',
    '参考実装（Canvas 2D・時刻だけで絵が決まる関数）: ' + ref,
    '共通の補助コード: ' + kit,
    '参考実装の形・タイミング・イージングの数値はそのまま使い、中の文字・色・素材だけ、いま作っている物に合わせてください。'
  ]).join('\n');
};
